INSERT INTO `gen_template` VALUES (1, 1, 329, 'java/Controller.ftl', '${classNameUpper}Controller.java', 1, 'Controller模板', 'package ${projectPackage}.${projectNameDot}.controller;\n\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.NotEmpty;\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport com.github.xiaoymin.knife4j.annotations.ApiOperationSupport;\nimport io.swagger.v3.oas.annotations.Operation;\nimport io.swagger.v3.oas.annotations.tags.Tag;\nimport io.swagger.v3.oas.annotations.Parameter;\n</#if>\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\nimport ${projectPackage}.${projectNameDot}.common.validation.group.InsertGroup;\nimport ${projectPackage}.${projectNameDot}.common.validation.group.UpdateGroup;\nimport ${projectPackage}.${projectNameDot}.service.${classNameUpper}Service;\nimport ${projectPackage}.${projectNameDot}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO;\nimport org.springframework.web.bind.annotation.*;\n<#if hasFunction(generatorFunction, 7)>\nimport org.springframework.http.ResponseEntity;\n</#if>\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.validation.annotation.Validated;\n<#if hasFunction(generatorFunction, 6)>\nimport org.springframework.web.multipart.MultipartFile;\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.enums.ParameterIn;\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\n</#if>\n\nimport java.util.List;\n\n/**\n * ${tableComment}管理\n */\n@Validated\n@RestController\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Tag(name = \"${tableComment}管理\")\n</#if>  \n@RequestMapping(\"/${functionName}\")\npublic class ${classNameUpper}Controller {\n\n    @Autowired\n    private ${classNameUpper}Service ${className}Service;\n\n<#-- 判断某个功能编号是否在 generatorFunction 列表中 -->\n<#function hasFunction generatorFunction target>\n    <#if generatorFunction?? && (generatorFunction?seq_contains(target))>\n        <#return true>\n    </#if>\n    <#return false>\n</#function>\n<#if hasFunction(generatorFunction, 0)>\n    /**\n     * 新增${tableComment}\n     */\n    @PostMapping(\"/add\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 1)\n    @Operation(summary = \"新增${tableComment}\")\n    </#if>\n    public void add(@RequestBody @Validated(InsertGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.add(dto);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 1)>\n    /**\n     * 修改${tableComment}\n     */\n    @PutMapping(\"/update\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 2)\n    @Operation(summary = \"修改${tableComment}\")\n    </#if>\n    public void update(@RequestBody @Validated(UpdateGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.update(dto);\n    }\n\n</#if>\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk == 1>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n<#if hasFunction(generatorFunction, 2)>\n    /**\n     * 删除${tableComment}\n     *\n     * @param id ${tableComment}ID\n     */\n    @DeleteMapping(\"/delete\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']> \n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 3)\n    @Operation(summary = \"删除${tableComment}\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    </#if>\n    public void delete(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        ${className}Service.delete(id);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 2)>\n    /**\n     * 批量删除${tableComment}\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @DeleteMapping(\"/deleteList\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 4)\n    @Operation(summary = \"批量删除${tableComment}\")\n    </#if>\n    public void deleteList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        ${className}Service.deleteList(idList);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 3)>\n    /**\n     * ${tableComment}详情\n     *\n     * @param id ${tableComment}ID\n     */\n    @GetMapping(\"/detail\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 5)\n    @Operation(summary = \"${tableComment}详情\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    </#if>  \n    public ${classNameUpper}VO detail(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        return ${className}Service.detail(id);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 3)>\n    /**\n     * ${tableComment}详情列表\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @PostMapping(\"/detailList\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 6)\n    @Operation(summary = \"${tableComment}详情列表\")\n    </#if>\n    public List<${classNameUpper}VO> detailList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        return ${className}Service.detailList(idList);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * ${tableComment}简单分页\n     */\n    @PostMapping(\"/entityPage\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>  \n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 7)\n    @Operation(summary = \"${tableComment}简单分页\")\n    </#if>  \n    public PageVO<${classNameUpper}VO> entityPage(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityPage(query);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * ${tableComment}简单列表\n     */\n    @PostMapping(\"/entityList\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']> \n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 8)\n    @Operation(summary = \"${tableComment}简单列表\")\n    </#if>\n    public List<${classNameUpper}VO> entityList(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityList(query);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * ${tableComment}复杂分页\n     */\n    @PostMapping(\"/voPage\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']> \n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 9)\n    @Operation(summary = \"${tableComment}复杂分页\")\n    </#if>\n    public PageVO<${classNameUpper}VO> voPage(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voPage(query);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * ${tableComment}复杂列表\n     */\n    @PostMapping(\"/voList\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']> \n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 10)\n    @Operation(summary = \"${tableComment}复杂列表\")\n    </#if>\n    public List<${classNameUpper}VO> voList(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voList(query);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 6)>\n    /**\n     * 导入${tableComment}\n     *\n     * @param file 文件\n    */\n    @PostMapping(\"/import\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']> \n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 11)\n    @Operation(summary = \"导入${tableComment}\")\n    @Parameter(name = \"file\", description = \"文件\", in = ParameterIn.DEFAULT, required = true,\n    schema = @Schema(name = \"file\", format = \"binary\"))\n    </#if>\n    public void importData(@RequestParam(\"file\") MultipartFile file) throws Exception {\n        ${className}Service.importData(file);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 7)>\n    /**\n     * 导出${tableComment}\n     *\n     * @param idList ${tableComment}ID列表\n    */\n    @GetMapping(\"/export\")\n    <#if projectTemplatePropertyData[\'enableKnife4j\']> \n    @ApiOperationSupport(<#if author!?length gt 0>author = \"${author}\", </#if>order = 11)\n    @Operation(summary = \"导出${tableComment}\")\n    @Parameter(name = \"idList\", description = \"${tableComment}ID列表\", required = true)\n    </#if>\n    public ResponseEntity<byte[]> export(@RequestParam(\"idList\") @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<Long> idList) {\n        return ${className}Service.export(idList);\n    }\n\n</#if>\n}\n', '', NULL, '2025-04-25 14:04:07', '2025-12-29 14:23:15', 0);
INSERT INTO `gen_template` VALUES (3, 1, 331, 'java/Service.ftl', '${classNameUpper}Service.java', 1, 'Service模板', 'package ${projectPackage}.${projectNameDot}.service;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\nimport ${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameDot}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameDot}.domain.entity.${classNameUpper}Entity;\nimport com.baomidou.mybatisplus.extension.service.IService;\n<#if hasFunction(generatorFunction, 6)>\nimport org.springframework.web.multipart.MultipartFile;\n</#if>\n<#if hasFunction(generatorFunction, 7)>\nimport org.springframework.http.ResponseEntity;\n</#if>\n\nimport java.util.List;\n\n/**\n * ${tableComment}服务层\n */\npublic interface ${classNameUpper}Service extends IService<${classNameUpper}Entity> {\n\n<#-- 判断某个功能编号是否在 generatorFunction 列表中 -->\n<#function hasFunction generatorFunction target>\n    <#if generatorFunction?? && (generatorFunction?seq_contains(target))>\n        <#return true>\n    </#if>\n    <#return false>\n</#function>\n<#if hasFunction(generatorFunction, 0)>\n    /**\n     * 新增\n     */\n    ${classNameUpper}Entity add(${classNameUpper}DTO dto);\n\n</#if>\n<#if hasFunction(generatorFunction, 1)>\n    /**\n     * 修改\n     */\n    void update(${classNameUpper}DTO dto);\n\n</#if>\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk == 1>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n<#if hasFunction(generatorFunction, 2)>\n    /**\n     * 删除\n     */\n    void delete(${primaryKeyType} id);\n\n    /**\n     * 批量删除\n     */\n    void deleteList(List<${primaryKeyType}> idList);\n\n</#if>\n<#if hasFunction(generatorFunction, 3)>\n    /**\n     * 详情\n     */\n    ${classNameUpper}VO detail(${primaryKeyType} id);\n\n    /**\n     * 详情列表\n     */\n    List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList);\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * 简单分页\n     */\n    PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query);\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * 简单列表\n     */\n    List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query);\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * 复杂分页\n     */\n    PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query);\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * 复杂列表\n     */\n    List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query);\n\n</#if>\n<#if hasFunction(generatorFunction, 6)>\n    /**\n     * 导入\n     */\n    void importData(MultipartFile file) throws Exception;\n\n</#if>\n<#if hasFunction(generatorFunction, 7)>\n    /**\n     * 导出\n     */\n    ResponseEntity<byte[]> export(List<${primaryKeyType}> idList);\n\n</#if>\n}', NULL, NULL, '2025-04-25 14:04:07', '2025-10-27 14:31:10', 0);
INSERT INTO `gen_template` VALUES (5, 1, 333, 'java/ServiceImpl.ftl', '${classNameUpper}ServiceImpl.java', 1, 'ServiceImpl模板', 'package ${projectPackage}.${projectNameDot}.service.impl;\n\n<#if hasFunction(generatorFunction, 6)>\nimport cn.hutool.v7.core.io.IoUtil;\nimport cn.hutool.v7.json.JSONUtil;\nimport cn.hutool.v7.core.text.StrUtil;\nimport cn.hutool.v7.core.util.CharsetUtil;\nimport cn.hutool.v7.core.collection.CollUtil;\n</#if>\n<#if hasFunction(generatorFunction, 7)>\nimport cn.hutool.v7.core.collection.CollUtil;\nimport cn.hutool.v7.core.date.DateUtil;\nimport cn.hutool.v7.core.util.CharsetUtil;\nimport cn.hutool.v7.http.meta.HttpHeaderUtil;\nimport cn.hutool.v7.json.JSONUtil;\nimport org.springframework.http.ResponseEntity;\n</#if>\nimport com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\nimport com.baomidou.mybatisplus.core.toolkit.Wrappers;\nimport com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\nimport ${projectPackage}.${projectNameDot}.common.exception.BusinessException;\nimport ${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil;\nimport ${projectPackage}.${projectNameDot}.mapstruct.${classNameUpper}Mapstruct;\nimport ${projectPackage}.${projectNameDot}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameDot}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameDot}.mapper.${classNameUpper}Mapper;\nimport ${projectPackage}.${projectNameDot}.service.${classNameUpper}Service;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.beans.factory.annotation.Autowired;\n<#if hasFunction(generatorFunction, 6)>\nimport org.springframework.web.multipart.MultipartFile;\n</#if>\n<#-- 判断某个功能编号是否在 generatorFunction 列表中 -->\n<#function hasFunction generatorFunction target>\n    <#if generatorFunction?? && (generatorFunction?seq_contains(target))>\n        <#return true>\n    </#if>\n    <#return false>\n</#function>\n\n<#if hasFunction(generatorFunction, 7)>\nimport java.util.Date;\n</#if>\nimport java.util.List;\nimport java.util.Objects;\n\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.DATA_NOT_EXIST;\n<#if hasFunction(generatorFunction, 7)>\nimport static cn.hutool.v7.core.date.DateFormatPool.PURE_DATETIME_PATTERN;\nimport static org.springframework.http.HttpHeaders.CONTENT_DISPOSITION;\nimport static org.springframework.http.MediaType.APPLICATION_OCTET_STREAM;\n</#if>\n\n/**\n * ${tableComment}Service实现类\n */\n@Service\npublic class ${classNameUpper}ServiceImpl extends ServiceImpl<${classNameUpper}Mapper, ${classNameUpper}Entity> implements ${classNameUpper}Service {\n\n    @Autowired\n    private ${classNameUpper}Mapper ${className}Mapper;\n\n    @Autowired\n    private ${classNameUpper}Mapstruct ${className}Mapstruct;\n<#function checkUnique fieldList>\n    <#list fieldList as field>\n        <#if field.uniqueField == 1>\n            <#return true>\n        </#if>\n    </#list>\n    <#return false>\n</#function>\n<#assign isUnique = checkUnique(fieldList)>\n\n<#if hasFunction(generatorFunction, 0)>\n    /**\n     * 新增\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public ${classNameUpper}Entity add(${classNameUpper}DTO dto) {\n        <#if isUnique>\n        //唯一性校验等\n        checkUnique(dto);\n        </#if>\n        ${classNameUpper}Entity entity = ${className}Mapstruct.dtoToEntity(dto);\n        ${className}Mapper.insert(entity);\n        return entity;\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 1)>\n    /**\n     * 修改\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void update(${classNameUpper}DTO dto) {\n        <#if isUnique>\n        //唯一性校验等\n        checkUnique(dto);\n        </#if>\n        ${classNameUpper}Entity formEntity = ${className}Mapstruct.dtoToEntity(dto);\n        ${classNameUpper}Entity dbEntity = selectById(dto.getId());\n        ${className}Mapper.updateById(formEntity);\n    }\n\n</#if>\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk == 1>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n<#if hasFunction(generatorFunction, 2)>\n    /**\n     * 删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void delete(${primaryKeyType} id) {\n        deleteList(List.of(id));\n    }\n\n    /**\n     * 批量删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void deleteList(List<${primaryKeyType}> idList) {\n        List<${classNameUpper}Entity> dbEntityList = ${className}Mapper.selectByIds(idList);\n        //删除校验\n        //checkReference(dbEntityList);\n        //关联删除\n        ${className}Mapper.deleteByIds(idList);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 3)>\n    /**\n     * 详情\n     */\n    @Override\n    public ${classNameUpper}VO detail(${primaryKeyType} id) {\n        ${classNameUpper}Entity dbEntity = selectById(id);\n        return ${className}Mapstruct.entityToVO(dbEntity);\n    }\n\n    /**\n     * 详情列表\n     */\n    @Override\n    public List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList) {\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectByIds(idList);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * 简单分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query) {\n        //简单sql使用QueryWrapper\n        ${className}Mapper.selectPage(query, buildQueryWrapper(query));\n        //较复杂sql，使用xml\n        //${className}Mapper.entityPage(query);\n        return ${className}Mapstruct.entityToPageVO(query);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * 简单列表\n     */\n    @Override\n    public List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query) {\n        query.setPageSize(-1L);\n        //简单sql使用QueryWrapper\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectList(buildQueryWrapper(query));\n        //复杂sql，使用xml\n        //List<${classNameUpper}Entity> entityList = ${className}Mapper.entityList(query);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * 复杂分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query) {\n        ${className}Mapper.voPage(query);\n        return ${className}Mapstruct.voToPageVO(query);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * 复杂列表\n     */\n    @Override\n    public List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query) {\n        //查询全部数据\n        query.setPageSize(-1L);\n        return ${className}Mapper.voList(query);\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 6)>\n    /**\n     * 导入\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void importData(MultipartFile file) throws Exception {\n        String data = IoUtil.read(file.getInputStream(), CharsetUtil.UTF_8);\n        if (StrUtil.isBlank(data)) {\n            throw new BusinessException(\"导入数据不能为空\");\n        }\n        List<${classNameUpper}DTO> dtoList = JSONUtil.toList(data, ${classNameUpper}DTO.class);\n        if (CollUtil.isEmpty(dtoList)) {\n            throw new BusinessException(\"导入数据不能为空\");\n        }\n        dtoList.forEach(dto -> {\n            add(dto);\n        });\n    }\n\n</#if>\n<#if hasFunction(generatorFunction, 7)>\n    /**\n     * 导出\n     */\n    @Override\n    public ResponseEntity<byte[]> export(List<${primaryKeyType}> idList) {\n        List<${classNameUpper}Entity> entityList = this.listByIds(idList);\n        if (CollUtil.isEmpty(entityList)) {\n            throw new BusinessException(\"导入数据不能为空\");\n        }\n\n        String jsonStr = JSONUtil.toJsonStr(entityList);\n\n        // 导出文件名\n        String fileName = \"${tableName}_\" + DateUtil.format(new Date(), PURE_DATETIME_PATTERN) + \".json\";\n\n        // 构建下载对象\n        return ResponseEntity.ok()\n            .header(CONTENT_DISPOSITION, HttpHeaderUtil.createAttachmentDisposition(fileName, CharsetUtil.UTF_8))\n            .contentType(APPLICATION_OCTET_STREAM)\n            .body(jsonStr.getBytes());\n    }\n\n</#if>\n\n    /**\n     * ID查询\n     */\n    private ${classNameUpper}Entity selectById(${primaryKeyType} id) {\n        ${classNameUpper}Entity entity = ${className}Mapper.selectById(id);\n        if (entity == null) {\n            throw new BusinessException(DATA_NOT_EXIST, \"${tableComment}\", id);\n        }\n        return entity;\n    }\n\n    <#if isUnique>\n    /**\n     * 唯一性校验\n     */\n    private void checkUnique(${classNameUpper}DTO dto) {\n        LambdaQueryWrapper<${classNameUpper}Entity> wrapper = Wrappers.lambdaQuery(${classNameUpper}Entity.class);\n\n        wrapper.ne(Objects.nonNull(dto.getId()), ${classNameUpper}Entity::getId, dto.getId());\n        <#list fieldList as field>\n            <#if field.uniqueField == 1>\n        wrapper.eq(${classNameUpper}Entity::get${field.attrName?cap_first}, dto.get${field.attrName?cap_first}());\n            </#if>\n        </#list>\n\n        boolean exists = ${className}Mapper.exists(wrapper);\n        if (exists) {\n            throw new BusinessException(\"${tableComment}已存在\");\n        }\n    }\n\n    </#if>\n    /**\n     * 校验能否被删除\n     */\n    private void checkReference(List<${classNameUpper}Entity> dbEntityList) {\n        //TODO 校验是否被引用\n        for (${classNameUpper}Entity dbEntity : dbEntityList) {\n\n        }\n    }\n\n    private LambdaQueryWrapper<${classNameUpper}Entity> buildQueryWrapper(${classNameUpper}EntityQuery query) {\n        LambdaQueryWrapper<${classNameUpper}Entity> wrapper = Wrappers.lambdaQuery(${classNameUpper}Entity.class);\n        <#if queryList?has_content>\n\n        //过滤字段\n        <#list queryList as field>\n            <#if field.queryType == \'=\'>\n        wrapper.eq(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'!=\'>\n        wrapper.ne(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'>\'>\n        wrapper.gt(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'>=\'>\n        wrapper.ge(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'<\'>\n        wrapper.lt(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'<=\'>\n        wrapper.le(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'like\'>\n        wrapper.like(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'left like\'>\n        wrapper.likeLeft(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'right like\'>\n        wrapper.likeRight(MybatisUtil.isNotEmpty(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n            <#elseif field.queryType == \'between\' && field.queryFormType == \'datetime\'>\n        wrapper.between(MybatisUtil.isNotEmpty(query.getStartTime()), ${classNameUpper}Entity::getCreateTime, query.getStartTime(), query.getEndTime());\n            <#elseif field.queryType == \'between\' && field.queryFormType == \'date\'>\n        wrapper.between(MybatisUtil.isNotEmpty(query.getStartDate()), ${classNameUpper}Entity::getCreateTime, query.getStartDate(), query.getEndDate());\n            <#else>\n            </#if>\n        </#list>\n        </#if>\n\n        //排序字段\n        MybatisUtil.orderBy(wrapper, query.getOrderItemList());\n        return wrapper;\n    }\n\n}\n', NULL, NULL, '2025-04-25 14:04:07', '2025-11-14 17:23:21', 0);
INSERT INTO `gen_template` VALUES (6, 1, 335, 'java/Mapper.ftl', '${classNameUpper}Mapper.java', 1, 'Mapper模板', 'package ${projectPackage}.${projectNameDot}.mapper;\n\nimport ${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus;\nimport com.baomidou.mybatisplus.core.metadata.IPage;\nimport ${projectPackage}.${projectNameDot}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameDot}.domain.query.${classNameUpper}VOQuery;\nimport org.apache.ibatis.annotations.Param;\nimport org.apache.ibatis.annotations.Mapper;\nimport org.springframework.stereotype.Repository;\n\nimport java.util.List;\n\n/**\n * ${tableComment}Mapper\n */\n@Mapper\n@Repository\npublic interface ${classNameUpper}Mapper extends BaseMapperPlus<${classNameUpper}Entity> {\n\n<#-- 判断某个功能编号是否在 generatorFunction 列表中 -->\n<#function hasFunction generatorFunction target>\n    <#if generatorFunction?? && (generatorFunction?seq_contains(target))>\n        <#return true>\n    </#if>\n    <#return false>\n</#function>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * Entity分页\n     */\n    IPage<${classNameUpper}Entity> entityPage(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * Entity列表\n     */\n    List<${classNameUpper}Entity> entityList(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    /**\n     * VO分页\n     */\n    IPage<${classNameUpper}VO> voPage(@Param(\"query\") ${classNameUpper}VOQuery query);\n                \n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    /**\n     * VO列表\n     */\n    List<${classNameUpper}VO> voList(@Param(\"query\") ${classNameUpper}VOQuery query);\n\n</#if>\n}\n', NULL, NULL, '2025-04-25 14:04:07', '2025-10-27 14:12:50', 0);
INSERT INTO `gen_template` VALUES (7, 1, 338, 'xml/Mapper.ftl', '${classNameUpper}Mapper.xml', 1, 'Mapper的XML模板', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE mapper PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\" \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n\n<mapper namespace=\"${projectPackage}.${projectNameDot}.mapper.${classNameUpper}Mapper\">\n\n    <!-- 所有字段 -->\n    <sql id=\"allColumns\">\n        <#list fieldList as field>\n        ${field.fieldName}<#if field_has_next>,</#if>\n        </#list>\n    </sql>\n\n    <!-- 过滤SQL -->\n    <sql id=\"whereSQL\">\n        <!-- 这里写过滤语句，过滤项需要加query前缀 -->\n        <#list queryList as field>\n        <if test=\"@${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil@isNotEmpty(query, \'${field.attrName}\')\">\n            <#if field.queryType == \'=\'>\n            AND ${field.fieldName} = <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n            <#elseif field.queryType == \'!=\'>\n            AND ${field.fieldName} != <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n            <#elseif field.queryType == \'>\'>\n            AND ${field.fieldName} &gt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n            <#elseif field.queryType == \'>=\'>\n            AND ${field.fieldName} &gt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n            <#elseif field.queryType == \'<\'>\n            AND ${field.fieldName} &lt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n            <#elseif field.queryType == \'<=\'>\n            AND ${field.fieldName} &lt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n            <#elseif field.queryType == \'like\'>\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n            <#elseif field.queryType == \'left like\'>\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>)\n            <#elseif field.queryType == \'right like\'>\n            AND ${field.fieldName} LIKE CONCAT(<#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n            <#elseif field.queryType == \'between\' && field.queryFormType == \'datetime\'>\n            AND ${field.fieldName} >= <#noparse>#</#noparse>{query.startTime} AND ${field.fieldName} &lt;= <#noparse>#</#noparse>{query.endTime}\n            <#elseif field.queryType == \'between\' && field.queryFormType == \'date\'>\n            AND ${field.fieldName} >= <#noparse>#</#noparse>{query.startDate} AND ${field.fieldName} &lt;= <#noparse>#</#noparse>{query.endDate}\n            <#else>\n            </#if>\n        </if>\n        </#list>\n    </sql>\n\n    <!-- Entity类字段映射 -->\n    <resultMap type=\"${projectPackage}.${projectNameDot}.domain.entity.${classNameUpper}Entity\" id=\"${className}Map\">\n        <#list fieldList as field>\n        <#if field.primaryPk == 1>\n        <id property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        <#else>\n        <result property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        </#if>\n        </#list>\n    </resultMap>\n<#function getLogicDeleteField fieldList >\n    <#list fieldList as field>\n        <#if field.logicDelete?? && field.logicDelete == 1>\n            <#return field.fieldName + \" = \" + field.logicNotDeleteValue>\n        </#if>\n    </#list>\n    <#return \"\">\n</#function>\n<#assign logicDeleteFlex = getLogicDeleteField(fieldList)>\n<#-- 判断某个功能编号是否在 generatorFunction 列表中 -->\n<#function hasFunction generatorFunction target>\n    <#if generatorFunction?? && (generatorFunction?seq_contains(target))>\n        <#return true>\n    </#if>\n    <#return false>\n</#function>\n\n<#if hasFunction(generatorFunction, 4)>\n    <!-- Entity分页 -->\n    <select id=\"entityPage\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus.orderBySQL\"/>\n    </select>\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    <!-- Entity列表 -->\n    <select id=\"entityList\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus.orderBySQL\"/>\n    </select>\n\n</#if>\n<#if hasFunction(generatorFunction, 4)>\n    <!-- VO分页 -->\n    <select id=\"voPage\" resultType=\"${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus.orderBySQL\"/>\n    </select>\n\n</#if>\n<#if hasFunction(generatorFunction, 5)>\n    <!-- VO列表 -->\n    <select id=\"voList\" resultType=\"${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus.orderBySQL\"/>\n    </select>\n\n</#if>\n\n</mapper>', NULL, NULL, '2025-04-25 14:04:07', '2025-10-27 14:13:29', 0);
INSERT INTO `gen_template` VALUES (8, 1, 340, 'java/Mapstruct.ftl', '${classNameUpper}Mapstruct.java', 1, 'Mapstruct模板', 'package ${projectPackage}.${projectNameDot}.mapstruct;\n\nimport ${projectPackage}.${projectNameDot}.common.mapstruct.BaseMapstruct;\nimport ${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameDot}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameDot}.domain.entity.${classNameUpper}Entity;\nimport org.mapstruct.Mapper;\nimport org.mapstruct.Named;\n\nimport static org.mapstruct.MappingConstants.ComponentModel.SPRING;\n\n/**\n * ${tableComment}Mapstruct\n */\n@Named(\"${className}Mapstruct\")\n@Mapper(componentModel = SPRING, implementationName = \"${projectNamePascal}${moduleNamePascal}${classNameUpper}MapstructImpl\")\npublic interface ${classNameUpper}Mapstruct extends BaseMapstruct<${classNameUpper}Entity, ${classNameUpper}VO, ${classNameUpper}DTO> {\n}', NULL, NULL, '2025-04-25 14:04:07', '2025-09-22 14:29:47', 0);
INSERT INTO `gen_template` VALUES (9, 1, 343, 'java/Entity.ftl', '${classNameUpper}Entity.java', 1, 'Entity实体类模板', 'package ${projectPackage}.${projectNameDot}.domain.entity;\n\nimport lombok.Data;\n<#if entityBaseClass??>\nimport lombok.EqualsAndHashCode;\n<#else></#if>\nimport com.baomidou.mybatisplus.annotation.*;\n<#if entityBaseClass??>\nimport ${entityBaseClass.packageName}.${entityBaseClass.className};\n</#if>\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity实体类\n */\n@Data\n@TableName(value = \"${tableName}\")\n<#if entityBaseClass??>\n@EqualsAndHashCode(callSuper = true)\n<#else></#if>\npublic class ${classNameUpper}Entity<#if entityBaseClass??> extends ${entityBaseClass.className}</#if> implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n<#if field.entityBaseField == 0>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	</#if>\n	<#if field.primaryPk == 1>\n	@TableId(value = \"${field.fieldName}\", type = IdType.AUTO)\n	<#else>\n		<#if field.autoFill == \"DEFAULT\">\n	@TableField(value = \"${field.fieldName}\")\n		</#if>\n		<#if field.autoFill == \"INSERT\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT)\n		</#if>\n		<#if field.autoFill == \"INSERT_UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT_UPDATE)\n		</#if>\n		<#if field.autoFill == \"UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.UPDATE)\n		</#if>\n	</#if>\n	<#if field.logicDelete == 1>\n	@TableLogic(value = \"${field.logicNotDeleteValue}\", delval = \"${field.logicDeleteValue}\")\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n</#if>\n</#list>\n}\n', NULL, NULL, '2025-04-25 14:04:07', '2025-09-19 14:31:37', 0);
INSERT INTO `gen_template` VALUES (10, 1, 345, 'java/DTO.ftl', '${classNameUpper}DTO.java', 1, 'DTO实体类模板', 'package ${projectPackage}.${projectNameDot}.domain.dto;\n\n<#function importEnumcode formList>\n	<#list formList as formField>\n		<#if formField.entityBaseField == 0 && formField.enumId??>\n			<#return true>\n		</#if>\n	</#list>\n	<#return false>\n</#function>\n<#assign importEnumcode = importEnumcode(formList)>\nimport ${projectPackage}.${projectNameDot}.common.validation.group.UpdateGroup;\n<#if importEnumcode>\nimport ${projectPackage}.${projectNameDot}.common.validation.code.EnumCode;\n</#if>\n<#list formList as formField >\n<#if formField.entityBaseField == 0 && formField.enumId??>\nimport ${projectPackage}.${projectNameDot}.enums.${formField.enumNamePascal}Enum;\n</#if>\n</#list>\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport jakarta.validation.constraints.*;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}DTO实体类\n */\n@Data\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\n@Schema(description = \"${tableComment}DTO实体类\")\n</#if>  \npublic class ${classNameUpper}DTO implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list formList as formField>\n<#if formField.entityBaseField == 0>\n	/**\n	 * ${formField.fieldComment}\n	 */\n  <#if projectTemplatePropertyData[\'enableKnife4j\']>\n	@Schema(description = \"${formField.fieldComment}\")\n  </#if>\n	<#if formField.primaryPk == 1>\n	@NotNull(message = \"${formField.fieldComment}不能为空\", groups = {UpdateGroup.class})\n	</#if>\n	<#if formField.formValidator?? && formField_has_next>\n	@${formField.formValidator}(message = \"${formField.fieldComment}不能为空\")\n	</#if>\n	<#if formField.enumId??>\n	@EnumCode(${formField.enumNamePascal}Enum.class)\n	</#if>\n	private ${formField.attrType} ${formField.attrName};\n\n</#if>\n</#list>\n}\n', NULL, NULL, '2025-04-25 14:04:07', '2025-12-29 14:24:38', 0);
INSERT INTO `gen_template` VALUES (11, 1, 347, 'java/VO.ftl', '${classNameUpper}VO.java', 1, 'VO实体类模板', 'package ${projectPackage}.${projectNameDot}.domain.vo;\n\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.Data;\n<#if voBaseClass??>\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.BaseVO;  \nimport lombok.EqualsAndHashCode;\n</#if>\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}VO实体类\n */\n@Data\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"${tableComment}VO实体类\")\n</#if>\n<#if voBaseClass??>\n@EqualsAndHashCode(callSuper = true)\n</#if>  \npublic class ${classNameUpper}VO<#if voBaseClass??> extends ${voBaseClass.className}</#if> implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n	<#if field.voBaseField == 0>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n  <#if projectTemplatePropertyData[\'enableKnife4j\']>\n	@Schema(description = \"${field.fieldComment}\")\n  </#if>\n	</#if>\n	<#if field.attrType == \'Date\'>\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n	</#if>\n</#list>\n}', NULL, NULL, '2025-04-25 14:04:07', '2025-12-29 14:54:40', 0);
INSERT INTO `gen_template` VALUES (12, 1, 349, 'java/EntityQuery.ftl', '${classNameUpper}EntityQuery.java', 1, 'EntityQuery查询实体类模板', 'package ${projectPackage}.${projectNameDot}.domain.query;\n\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.domain.entity.${classNameUpper}Entity;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity查询实体类\n */\n@Data\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"${tableComment}Entity查询实体类\")\n</#if>  \n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}EntityQuery extends PageQuery<${classNameUpper}Entity> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n<#list queryList as field>\n    <#if field.fieldComment!?length gt 0>\n    /**\n     * ${field.fieldComment}\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"${field.fieldComment}\")\n    </#if>\n    </#if>\n    <#if field.attrType == \'Date\'>\n    </#if>\n    private ${field.attrType} ${field.attrName};\n\n</#list>\n}\n', NULL, NULL, '2025-04-25 14:04:07', '2025-12-29 14:25:51', 0);
INSERT INTO `gen_template` VALUES (13, 1, 349, 'java/VOQuery.ftl', '${classNameUpper}VOQuery.java', 1, 'VOQuery查询实体类模板', 'package ${projectPackage}.${projectNameDot}.domain.query;\n\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.domain.vo.${classNameUpper}VO;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}VO查询实体类\n */\n@Data\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"${tableComment}VO查询实体类\")\n</#if>  \n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}VOQuery extends PageQuery<${classNameUpper}VO> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n<#list queryList as field>\n    <#if field.fieldComment!?length gt 0>\n    /**\n     * ${field.fieldComment}\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"${field.fieldComment}\")\n    </#if>\n    </#if>\n    <#if field.attrType == \'Date\'>\n    </#if>\n    private ${field.attrType} ${field.attrName};\n\n</#list>\n}\n', NULL, NULL, '2025-04-25 14:04:07', '2025-12-29 14:26:48', 0);
INSERT INTO `gen_template` VALUES (113, 22, 374, 'java/Controller.ftl', '${classNameUpper}Controller.java', 1, 'controller模板', 'package ${projectPackage}.${projectNameUnderline}.controller;\n\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.NotEmpty;\nimport com.github.xiaoymin.knife4j.annotations.ApiOperationSupport;\nimport io.swagger.v3.oas.annotations.Operation;\nimport io.swagger.v3.oas.annotations.tags.Tag;\nimport io.swagger.v3.oas.annotations.Parameter;\nimport com.yanggu.common.domain.vo.PageVO;\nimport com.yanggu.common.validation.group.InsertGroup;\nimport com.yanggu.common.validation.group.UpdateGroup;\nimport ${projectPackage}.${projectNameUnderline}.service.${classNameUpper}Service;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.validation.annotation.Validated;\n\nimport java.util.List;\n\n/**\n * ${tableComment}管理\n */\n@Validated\n@RestController\n@Tag(name = \"${tableComment}管理\")\n@RequestMapping(\"/${functionName}\")\npublic class ${classNameUpper}Controller {\n\n    @Autowired\n    private ${classNameUpper}Service ${className}Service;\n\n    /**\n     * 新增${tableComment}\n     */\n    @PostMapping(\"/add\")\n    @ApiOperationSupport(order = 1)\n    @Operation(summary = \"新增${tableComment}\")\n    public void add(@RequestBody @Validated(InsertGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.add(dto);\n    }\n\n    /**\n     * 修改${tableComment}\n     */\n    @PutMapping(\"/update\")\n    @ApiOperationSupport(order = 2)\n    @Operation(summary = \"修改${tableComment}\")\n    public void update(@RequestBody @Validated(UpdateGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.update(dto);\n    }\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除${tableComment}\n     *\n     * @param id ${tableComment}ID\n     */\n    @DeleteMapping(\"/delete\")\n    @ApiOperationSupport(order = 3)\n    @Operation(summary = \"删除${tableComment}\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    public void delete(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        ${className}Service.delete(id);\n    }\n\n    /**\n     * 批量删除${tableComment}\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @DeleteMapping(\"/deleteList\")\n    @ApiOperationSupport(order = 4)\n    @Operation(summary = \"批量删除${tableComment}\")\n    public void deleteList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        ${className}Service.deleteList(idList);\n    }\n\n    /**\n     * ${tableComment}详情\n     *\n     * @param id ${tableComment}ID\n     */\n    @GetMapping(\"/detail\")\n    @ApiOperationSupport(order = 5)\n    @Operation(summary = \"${tableComment}详情\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    public ${classNameUpper}VO detail(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        return ${className}Service.detail(id);\n    }\n\n    /**\n     * ${tableComment}批量查询\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @PostMapping(\"/detailList\")\n    @ApiOperationSupport(order = 6)\n    @Operation(summary = \"${tableComment}批量查询\")\n    public List<${classNameUpper}VO> detailList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        return ${className}Service.detailList(idList);\n    }\n\n    /**\n     * ${tableComment}简单分页\n     */\n    @PostMapping(\"/entityPage\")\n    @ApiOperationSupport(order = 7)\n    @Operation(summary = \"${tableComment}简单分页\")\n    public PageVO<${classNameUpper}VO> entityPage(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityPage(query);\n    }\n\n    /**\n     * ${tableComment}简单列表\n     */\n    @PostMapping(\"/entityList\")\n    @ApiOperationSupport(order = 8)\n    @Operation(summary = \"${tableComment}简单列表\")\n    public List<${classNameUpper}VO> entityList(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityList(query);\n    }\n\n    /**\n     * ${tableComment}复杂分页\n     */\n    @PostMapping(\"/voPage\")\n    @ApiOperationSupport(order = 9)\n    @Operation(summary = \"${tableComment}复杂分页\")\n    public PageVO<${classNameUpper}VO> voPage(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voPage(query);\n    }\n\n    /**\n     * ${tableComment}复杂列表\n     */\n    @PostMapping(\"/voList\")\n    @ApiOperationSupport(order = 10)\n    @Operation(summary = \"${tableComment}复杂列表\")\n    public List<${classNameUpper}VO> voList(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voList(query);\n    }\n\n}', NULL, NULL, '2025-05-13 18:08:30', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (114, 22, 376, 'java/Service.ftl', '${classNameUpper}Service.java', 1, 'Service模板', 'package ${projectPackage}.${projectNameUnderline}.service;\n\nimport com.yanggu.common.domain.vo.PageVO;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport com.baomidou.mybatisplus.extension.service.IService;\n\nimport java.util.List;\n\n/**\n * ${tableComment}服务层\n */\npublic interface ${classNameUpper}Service extends IService<${classNameUpper}Entity> {\n\n    /**\n     * 新增\n     */\n    void add(${classNameUpper}DTO dto);\n\n    /**\n     * 修改\n     */\n    void update(${classNameUpper}DTO dto);\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除\n     */\n    void delete(${primaryKeyType} id);\n\n    /**\n     * 批量删除\n     */\n    void deleteList(List<${primaryKeyType}> idList);\n\n    /**\n     * 详情\n     */\n    ${classNameUpper}VO detail(${primaryKeyType} id);\n\n    /**\n     * 批量查询\n     */\n    List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList);\n\n    /**\n     * 简单分页\n     */\n    PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query);\n\n    /**\n     * 简单列表\n     */\n    List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query);\n\n    /**\n     * 复杂分页\n     */\n    PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query);\n\n    /**\n     * 复杂列表\n     */\n    List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query);\n\n}', NULL, NULL, '2025-05-13 18:08:30', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (115, 22, 378, 'java/ServiceImpl.ftl', '${classNameUpper}ServiceImpl.java', 1, 'Service实现类模板', 'package ${projectPackage}.${projectNameUnderline}.service.impl;\n\nimport com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\nimport com.baomidou.mybatisplus.core.toolkit.Wrappers;\nimport com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;\n<#if queryList?has_content>\n    <#assign needStrUtil = false>\n    <#list queryList as field>\n        <#if field.queryType?matches(\"(like|left like|right like)\") || field.attrType?matches(\"(String)\")>\n            <#assign needStrUtil = true>\n        </#if>\n    </#list>\n    <#if needStrUtil>\nimport org.dromara.hutool.core.text.StrUtil;\n    </#if>\n</#if>\nimport com.yanggu.common.domain.vo.PageVO;\nimport com.yanggu.common.exception.BusinessException;\nimport com.yanggu.common.mybatis.util.MybatisUtil;\nimport ${projectPackage}.${projectNameUnderline}.mapstruct.${classNameUpper}Mapstruct;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.mapper.${classNameUpper}Mapper;\nimport ${projectPackage}.${projectNameUnderline}.service.${classNameUpper}Service;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.beans.factory.annotation.Autowired;\n\nimport java.util.List;\n<#if queryList?has_content>\n    <#assign needStrUtil = false>\n    <#list queryList as field>\n        <#if field.queryType?matches(\"(=|!=|>|<|>=|<=)\")>\n            <#assign needStrUtil = true>\n        </#if>\n    </#list>\n    <#if needStrUtil>\nimport java.util.Objects;\n    </#if>\n</#if>\n\nimport static com.yanggu.common.response.ResultEnum.DATA_NOT_EXIST;\n\n/**\n * ${tableComment}Service实现类\n */\n@Service\npublic class ${classNameUpper}ServiceImpl extends ServiceImpl<${classNameUpper}Mapper, ${classNameUpper}Entity> implements ${classNameUpper}Service {\n\n    @Autowired\n    private ${classNameUpper}Mapper ${className}Mapper;\n\n    @Autowired\n    private ${classNameUpper}Mapstruct ${className}Mapstruct;\n\n    /**\n     * 新增\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void add(${classNameUpper}DTO dto) {\n        ${classNameUpper}Entity entity = ${className}Mapstruct.dtoToEntity(dto);\n        //唯一性校验等\n        ${className}Mapper.insert(entity);\n    }\n\n    /**\n     * 修改\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void update(${classNameUpper}DTO dto) {\n        ${classNameUpper}Entity formEntity = ${className}Mapstruct.dtoToEntity(dto);\n        ${classNameUpper}Entity dbEntity = selectById(dto.getId());\n        //唯一性校验等\n        ${className}Mapper.updateById(formEntity);\n    }\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void delete(${primaryKeyType} id) {\n        ${classNameUpper}Entity dbEntity = selectById(id);\n        //删除校验和关联删除\n        ${className}Mapper.deleteById(id);\n    }\n\n    /**\n     * 批量删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void deleteList(List<${primaryKeyType}> idList) {\n        //删除校验和关联删除\n        ${className}Mapper.deleteByIds(idList);\n    }\n\n    /**\n     * 详情\n     */\n    @Override\n    public ${classNameUpper}VO detail(${primaryKeyType} id) {\n        ${classNameUpper}Entity dbEntity = selectById(id);\n        return ${className}Mapstruct.entityToVO(dbEntity);\n    }\n\n    /**\n     * 简单分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query) {\n        //简单sql使用QueryWrapper\n        ${className}Mapper.selectPage(query, buildQueryWrapper(query));\n        //较复杂sql，使用xml\n        //${className}Mapper.entityPage(query);\n        return ${className}Mapstruct.entityToPageVO(query);\n    }\n\n    /**\n     * 简单列表\n     */\n    @Override\n    public List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query) {\n        query.setPageSize(-1L);\n        //简单sql使用QueryWrapper\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectList(buildQueryWrapper(query));\n        //复杂sql，使用xml\n        //List<${classNameUpper}Entity> entityList = ${className}Mapper.entityList(query);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n    /**\n     * 复杂分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query) {\n        ${className}Mapper.voPage(query);\n        return ${className}Mapstruct.voToPageVO(query);\n    }\n\n    /**\n     * 复杂列表\n     */\n    @Override\n    public List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query) {\n        //查询全部数据\n        query.setPageSize(-1L);\n        return ${className}Mapper.voList(query);\n    }\n\n    /**\n     * 批量查询\n     */\n    @Override\n    public List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList) {\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectByIds(idList);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n    private ${classNameUpper}Entity selectById(${primaryKeyType} id) {\n        ${classNameUpper}Entity entity = ${className}Mapper.selectById(id);\n        if (entity == null) {\n            throw new BusinessException(DATA_NOT_EXIST, \"${tableComment}\", id);\n        }\n        return entity;\n    }\n\n    private LambdaQueryWrapper<${classNameUpper}Entity> buildQueryWrapper(${classNameUpper}EntityQuery query) {\n        LambdaQueryWrapper<${classNameUpper}Entity> wrapper = Wrappers.lambdaQuery(${classNameUpper}Entity.class);\n        <#if queryList?has_content>\n\n        //过滤字段\n        <#list queryList as field>\n            <#if field.queryType == \'=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.eq(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.eq(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'!=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.ne(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.ne(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'>\'>\n                <#if field.attrType == \'String\'>\n        wrapper.gt(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.gt(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'>=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.ge(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.ge(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'<\'>\n                <#if field.attrType == \'String\'>\n        wrapper.lt(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.lt(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'<=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.le(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.le(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.like(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.like(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'left like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.likeLeft(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.likeLeft(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'right like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.likeRight(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.likeRight(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            </#if>\n        </#list>\n        </#if>\n\n        //排序字段\n        MybatisUtil.orderBy(wrapper, query.getOrders());\n        return wrapper;\n    }\n\n}', NULL, NULL, '2025-05-13 18:08:30', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (116, 22, 380, 'java/Mapper.ftl', '${classNameUpper}Mapper.java', 1, 'Mapper模板', 'package ${projectPackage}.${projectNameUnderline}.mapper;\n\nimport com.yanggu.common.mybatis.mapper.BaseMapperPlus;\nimport com.baomidou.mybatisplus.core.metadata.IPage;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport org.apache.ibatis.annotations.Param;\nimport org.apache.ibatis.annotations.Mapper;\nimport org.springframework.stereotype.Repository;\n\nimport java.util.List;\n\n/**\n * ${tableComment}Mapper\n */\n@Mapper\n@Repository\npublic interface ${classNameUpper}Mapper extends BaseMapperPlus<${classNameUpper}Entity> {\n\n    /**\n     * Entity分页\n     */\n    IPage<${classNameUpper}Entity> entityPage(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n    /**\n     * Entity列表\n     */\n    List<${classNameUpper}Entity> entityList(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n    /**\n     * VO分页\n     */\n    IPage<${classNameUpper}VO> voPage(@Param(\"query\") ${classNameUpper}VOQuery query);\n\n    /**\n     * VO列表\n     */\n    List<${classNameUpper}VO> voList(@Param(\"query\") ${classNameUpper}VOQuery query);\n\n}', NULL, NULL, '2025-05-13 18:08:30', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (117, 22, 383, 'xml/Mapper.ftl', '${classNameUpper}Mapper.xml', 1, 'Mapper的XML模板', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE mapper PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\" \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n\n<mapper namespace=\"${projectPackage}.${projectNameUnderline}.mapper.${classNameUpper}Mapper\">\n\n    <!-- 所有字段 -->\n    <sql id=\"allColumns\">\n        <#list fieldList as field>\n        ${field.fieldName}<#if field_has_next>,</#if>\n        </#list>\n    </sql>\n\n    <!-- 过滤SQL -->\n    <sql id=\"whereSQL\">\n        <!-- 这里写过滤语句，过滤项需要加query前缀 -->\n        <#list queryList as field>\n            <#if field.queryType == \'=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} = <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'!=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} != <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'>\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &gt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'>=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &gt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'<\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &lt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'<=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &lt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n        </if>\n            <#elseif field.queryType == \'left like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>)\n        </if>\n            <#elseif field.queryType == \'right like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(<#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n        </if>\n            <#else>\n            </#if>\n        </#list>\n    </sql>\n\n    <!-- 排序SQL -->\n    <sql id=\"orderBySQL\">\n        <if test=\"query.orders != null and query.orders.size() > 0\">\n            ORDER BY\n            <foreach collection=\"query.orders\" item=\"order\" separator=\",\">\n                <#noparse>${order.column}</#noparse> <if test=\"order.isAsc\">ASC</if><if test=\"!order.isAsc\">DESC</if>\n            </foreach>\n        </if>\n    </sql>\n\n    <!-- Entity类字段映射 -->\n    <resultMap type=\"${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity\" id=\"${className}Map\">\n        <#list fieldList as field>\n        <#if field.primaryPk>\n        <id property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        <#else>\n        <result property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        </#if>\n        </#list>\n    </resultMap>\n<#function getLogicDeleteField fieldList >\n    <#list fieldList as field>\n        <#if field.logicDelete?? && field.logicDelete>\n            <#return field.fieldName + \" = \" + field.logicNotDeleteValue>\n        </#if>\n    </#list>\n    <#return \"\">\n</#function>\n<#assign logicDeleteFlex = getLogicDeleteField(fieldList)>\n\n    <!-- Entity分页 -->\n    <select id=\"entityPage\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- Entity列表 -->\n    <select id=\"entityList\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- VO分页 -->\n    <select id=\"voPage\" resultType=\"${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- VO列表 -->\n    <select id=\"voList\" resultType=\"${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n</mapper>', NULL, NULL, '2025-05-13 18:08:30', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (118, 22, 385, 'java/Mapstruct.ftl', '${classNameUpper}Mapstruct.java', 1, 'Mapstruct模板', 'package ${projectPackage}.${projectNameUnderline}.mapstruct;\n\nimport com.yanggu.common.mapstruct.BaseMapstruct;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport org.mapstruct.Mapper;\nimport org.mapstruct.Named;\n\nimport static org.mapstruct.MappingConstants.ComponentModel.SPRING;\n\n/**\n * ${tableComment}Mapstruct\n */\n@Named(\"${className}Mapstruct\")\n@Mapper(componentModel = SPRING, implementationName = \"${projectNamePascal}${classNameUpper}MapstructImpl\")\npublic interface ${classNameUpper}Mapstruct extends BaseMapstruct<${classNameUpper}Entity, ${classNameUpper}VO, ${classNameUpper}DTO> {\n}', NULL, NULL, '2025-05-13 18:08:30', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (119, 22, 388, 'java/Entity.ftl', '${classNameUpper}Entity.java', 1, 'Entity实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.entity;\n\nimport lombok.Data;\n<#if baseClass??>\nimport lombok.EqualsAndHashCode;\n<#else></#if>\nimport com.baomidou.mybatisplus.annotation.*;\n<#if baseClass??>\nimport ${baseClass.packageName}.${baseClass.code};\n</#if>\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity实体类\n */\n@Data\n@TableName(value = \"${tableName}\", schema = \"${databaseName}\")\n<#if baseClass??>\n@EqualsAndHashCode(callSuper = true)\n<#else></#if>\npublic class ${classNameUpper}Entity<#if baseClass??> extends ${baseClass.code}</#if> implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n<#if !field.baseField>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	</#if>\n	<#if field.primaryPk>\n	@TableId(value = \"${field.fieldName}\", type = IdType.AUTO)\n	<#else>\n		<#if field.autoFill == \"DEFAULT\">\n	@TableField(value = \"${field.fieldName}\")\n		</#if>\n		<#if field.autoFill == \"INSERT\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT)\n		</#if>\n		<#if field.autoFill == \"INSERT_UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT_UPDATE)\n		</#if>\n		<#if field.autoFill == \"UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.UPDATE)\n		</#if>\n	</#if>\n	<#if field.logicDelete>\n	@TableLogic(value = \"${field.logicNotDeleteValue}\", delval = \"${field.logicDeleteValue}\")\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n</#if>\n</#list>\n}', NULL, NULL, '2025-05-13 18:08:30', '2025-08-12 10:41:36', 0);
