INSERT INTO `gen_template` VALUES (157, 26, 490, 'java/Controller.ftl', '${classNameUpper}Controller.java', 1, 'controller模板', 'package ${projectPackage}.${projectNameUnderline}.controller;\n\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.NotEmpty;\nimport com.github.xiaoymin.knife4j.annotations.ApiOperationSupport;\nimport io.swagger.v3.oas.annotations.Operation;\nimport io.swagger.v3.oas.annotations.tags.Tag;\nimport io.swagger.v3.oas.annotations.Parameter;\nimport com.yanggu.common.domain.vo.PageVO;\nimport com.yanggu.common.validation.group.InsertGroup;\nimport com.yanggu.common.validation.group.UpdateGroup;\nimport ${projectPackage}.${projectNameUnderline}.service.${classNameUpper}Service;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.validation.annotation.Validated;\n\nimport java.util.List;\n\n/**\n * ${tableComment}管理\n */\n@Validated\n@RestController\n@Tag(name = \"${tableComment}管理\")\n@RequestMapping(\"/${functionName}\")\npublic class ${classNameUpper}Controller {\n\n    @Autowired\n    private ${classNameUpper}Service ${className}Service;\n\n    /**\n     * 新增${tableComment}\n     */\n    @PostMapping(\"/add\")\n    @ApiOperationSupport(order = 1)\n    @Operation(summary = \"新增${tableComment}\")\n    public void add(@RequestBody @Validated(InsertGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.add(dto);\n    }\n\n    /**\n     * 修改${tableComment}\n     */\n    @PutMapping(\"/update\")\n    @ApiOperationSupport(order = 2)\n    @Operation(summary = \"修改${tableComment}\")\n    public void update(@RequestBody @Validated(UpdateGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.update(dto);\n    }\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除${tableComment}\n     *\n     * @param id ${tableComment}ID\n     */\n    @DeleteMapping(\"/delete\")\n    @ApiOperationSupport(order = 3)\n    @Operation(summary = \"删除${tableComment}\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    public void delete(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        ${className}Service.delete(id);\n    }\n\n    /**\n     * 批量删除${tableComment}\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @DeleteMapping(\"/deleteList\")\n    @ApiOperationSupport(order = 4)\n    @Operation(summary = \"批量删除${tableComment}\")\n    public void deleteList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        ${className}Service.deleteList(idList);\n    }\n\n    /**\n     * ${tableComment}详情\n     *\n     * @param id ${tableComment}ID\n     */\n    @GetMapping(\"/detail\")\n    @ApiOperationSupport(order = 5)\n    @Operation(summary = \"${tableComment}详情\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    public ${classNameUpper}VO detail(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        return ${className}Service.detail(id);\n    }\n\n    /**\n     * ${tableComment}批量查询\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @PostMapping(\"/detailList\")\n    @ApiOperationSupport(order = 6)\n    @Operation(summary = \"${tableComment}批量查询\")\n    public List<${classNameUpper}VO> detailList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        return ${className}Service.detailList(idList);\n    }\n\n    /**\n     * ${tableComment}简单分页\n     */\n    @PostMapping(\"/entityPage\")\n    @ApiOperationSupport(order = 7)\n    @Operation(summary = \"${tableComment}简单分页\")\n    public PageVO<${classNameUpper}VO> entityPage(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityPage(query);\n    }\n\n    /**\n     * ${tableComment}简单列表\n     */\n    @PostMapping(\"/entityList\")\n    @ApiOperationSupport(order = 8)\n    @Operation(summary = \"${tableComment}简单列表\")\n    public List<${classNameUpper}VO> entityList(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityList(query);\n    }\n\n    /**\n     * ${tableComment}复杂分页\n     */\n    @PostMapping(\"/voPage\")\n    @ApiOperationSupport(order = 9)\n    @Operation(summary = \"${tableComment}复杂分页\")\n    public PageVO<${classNameUpper}VO> voPage(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voPage(query);\n    }\n\n    /**\n     * ${tableComment}复杂列表\n     */\n    @PostMapping(\"/voList\")\n    @ApiOperationSupport(order = 10)\n    @Operation(summary = \"${tableComment}复杂列表\")\n    public List<${classNameUpper}VO> voList(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voList(query);\n    }\n\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (158, 26, 492, 'java/Service.ftl', '${classNameUpper}Service.java', 1, 'Service模板', 'package ${projectPackage}.${projectNameUnderline}.service;\n\nimport com.yanggu.common.domain.vo.PageVO;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport com.baomidou.mybatisplus.extension.service.IService;\n\nimport java.util.List;\n\n/**\n * ${tableComment}服务层\n */\npublic interface ${classNameUpper}Service extends IService<${classNameUpper}Entity> {\n\n    /**\n     * 新增\n     */\n    void add(${classNameUpper}DTO dto);\n\n    /**\n     * 修改\n     */\n    void update(${classNameUpper}DTO dto);\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除\n     */\n    void delete(${primaryKeyType} id);\n\n    /**\n     * 批量删除\n     */\n    void deleteList(List<${primaryKeyType}> idList);\n\n    /**\n     * 详情\n     */\n    ${classNameUpper}VO detail(${primaryKeyType} id);\n\n    /**\n     * 批量查询\n     */\n    List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList);\n\n    /**\n     * 简单分页\n     */\n    PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query);\n\n    /**\n     * 简单列表\n     */\n    List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query);\n\n    /**\n     * 复杂分页\n     */\n    PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query);\n\n    /**\n     * 复杂列表\n     */\n    List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query);\n\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (159, 26, 494, 'java/ServiceImpl.ftl', '${classNameUpper}ServiceImpl.java', 1, 'Service实现类模板', 'package ${projectPackage}.${projectNameUnderline}.service.impl;\n\nimport com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\nimport com.baomidou.mybatisplus.core.toolkit.Wrappers;\nimport com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;\n<#if queryList?has_content>\n    <#assign needStrUtil = false>\n    <#list queryList as field>\n        <#if field.queryType?matches(\"(like|left like|right like)\") || field.attrType?matches(\"(String)\")>\n            <#assign needStrUtil = true>\n        </#if>\n    </#list>\n    <#if needStrUtil>\nimport org.dromara.hutool.core.text.StrUtil;\n    </#if>\n</#if>\nimport com.yanggu.common.domain.vo.PageVO;\nimport com.yanggu.common.exception.BusinessException;\nimport com.yanggu.common.mybatis.util.MybatisUtil;\nimport ${projectPackage}.${projectNameUnderline}.mapstruct.${classNameUpper}Mapstruct;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.mapper.${classNameUpper}Mapper;\nimport ${projectPackage}.${projectNameUnderline}.service.${classNameUpper}Service;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.beans.factory.annotation.Autowired;\n\nimport java.util.List;\n<#if queryList?has_content>\n    <#assign needStrUtil = false>\n    <#list queryList as field>\n        <#if field.queryType?matches(\"(=|!=|>|<|>=|<=)\")>\n            <#assign needStrUtil = true>\n        </#if>\n    </#list>\n    <#if needStrUtil>\nimport java.util.Objects;\n    </#if>\n</#if>\n\nimport static com.yanggu.common.response.ResultEnum.DATA_NOT_EXIST;\n\n/**\n * ${tableComment}Service实现类\n */\n@Service\npublic class ${classNameUpper}ServiceImpl extends ServiceImpl<${classNameUpper}Mapper, ${classNameUpper}Entity> implements ${classNameUpper}Service {\n\n    @Autowired\n    private ${classNameUpper}Mapper ${className}Mapper;\n\n    @Autowired\n    private ${classNameUpper}Mapstruct ${className}Mapstruct;\n\n    /**\n     * 新增\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void add(${classNameUpper}DTO dto) {\n        ${classNameUpper}Entity entity = ${className}Mapstruct.dtoToEntity(dto);\n        //唯一性校验等\n        ${className}Mapper.insert(entity);\n    }\n\n    /**\n     * 修改\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void update(${classNameUpper}DTO dto) {\n        ${classNameUpper}Entity formEntity = ${className}Mapstruct.dtoToEntity(dto);\n        ${classNameUpper}Entity dbEntity = selectById(dto.getId());\n        //唯一性校验等\n        ${className}Mapper.updateById(formEntity);\n    }\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void delete(${primaryKeyType} id) {\n        ${classNameUpper}Entity dbEntity = selectById(id);\n        //删除校验和关联删除\n        ${className}Mapper.deleteById(id);\n    }\n\n    /**\n     * 批量删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void deleteList(List<${primaryKeyType}> idList) {\n        //删除校验和关联删除\n        ${className}Mapper.deleteByIds(idList);\n    }\n\n    /**\n     * 详情\n     */\n    @Override\n    public ${classNameUpper}VO detail(${primaryKeyType} id) {\n        ${classNameUpper}Entity dbEntity = selectById(id);\n        return ${className}Mapstruct.entityToVO(dbEntity);\n    }\n\n    /**\n     * 简单分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query) {\n        //简单sql使用QueryWrapper\n        ${className}Mapper.selectPage(query, buildQueryWrapper(query));\n        //较复杂sql，使用xml\n        //${className}Mapper.entityPage(query);\n        return ${className}Mapstruct.entityToPageVO(query);\n    }\n\n    /**\n     * 简单列表\n     */\n    @Override\n    public List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query) {\n        query.setPageSize(-1L);\n        //简单sql使用QueryWrapper\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectList(buildQueryWrapper(query));\n        //复杂sql，使用xml\n        //List<${classNameUpper}Entity> entityList = ${className}Mapper.entityList(query);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n    /**\n     * 复杂分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query) {\n        ${className}Mapper.voPage(query);\n        return ${className}Mapstruct.voToPageVO(query);\n    }\n\n    /**\n     * 复杂列表\n     */\n    @Override\n    public List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query) {\n        //查询全部数据\n        query.setPageSize(-1L);\n        return ${className}Mapper.voList(query);\n    }\n\n    /**\n     * 批量查询\n     */\n    @Override\n    public List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList) {\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectByIds(idList);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n    private ${classNameUpper}Entity selectById(${primaryKeyType} id) {\n        ${classNameUpper}Entity entity = ${className}Mapper.selectById(id);\n        if (entity == null) {\n            throw new BusinessException(DATA_NOT_EXIST, \"${tableComment}\", id);\n        }\n        return entity;\n    }\n\n    private LambdaQueryWrapper<${classNameUpper}Entity> buildQueryWrapper(${classNameUpper}EntityQuery query) {\n        LambdaQueryWrapper<${classNameUpper}Entity> wrapper = Wrappers.lambdaQuery(${classNameUpper}Entity.class);\n        <#if queryList?has_content>\n\n        //过滤字段\n        <#list queryList as field>\n            <#if field.queryType == \'=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.eq(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.eq(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'!=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.ne(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.ne(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'>\'>\n                <#if field.attrType == \'String\'>\n        wrapper.gt(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.gt(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'>=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.ge(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.ge(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'<\'>\n                <#if field.attrType == \'String\'>\n        wrapper.lt(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.lt(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'<=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.le(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.le(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.like(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.like(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'left like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.likeLeft(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.likeLeft(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'right like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.likeRight(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.likeRight(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            </#if>\n        </#list>\n        </#if>\n\n        //排序字段\n        MybatisUtil.orderBy(wrapper, query.getOrders());\n        return wrapper;\n    }\n\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (160, 26, 496, 'java/Mapper.ftl', '${classNameUpper}Mapper.java', 1, 'Mapper模板', 'package ${projectPackage}.${projectNameUnderline}.mapper;\n\nimport com.yanggu.common.mybatis.mapper.BaseMapperPlus;\nimport com.baomidou.mybatisplus.core.metadata.IPage;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport org.apache.ibatis.annotations.Param;\nimport org.apache.ibatis.annotations.Mapper;\nimport org.springframework.stereotype.Repository;\n\nimport java.util.List;\n\n/**\n * ${tableComment}Mapper\n */\n@Mapper\n@Repository\npublic interface ${classNameUpper}Mapper extends BaseMapperPlus<${classNameUpper}Entity> {\n\n    /**\n     * Entity分页\n     */\n    IPage<${classNameUpper}Entity> entityPage(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n    /**\n     * Entity列表\n     */\n    List<${classNameUpper}Entity> entityList(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n    /**\n     * VO分页\n     */\n    IPage<${classNameUpper}VO> voPage(@Param(\"query\") ${classNameUpper}VOQuery query);\n\n    /**\n     * VO列表\n     */\n    List<${classNameUpper}VO> voList(@Param(\"query\") ${classNameUpper}VOQuery query);\n\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (161, 26, 499, 'xml/Mapper.ftl', '${classNameUpper}Mapper.xml', 1, 'Mapper的XML模板', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE mapper PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\" \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n\n<mapper namespace=\"${projectPackage}.${projectNameUnderline}.mapper.${classNameUpper}Mapper\">\n\n    <!-- 所有字段 -->\n    <sql id=\"allColumns\">\n        <#list fieldList as field>\n        ${field.fieldName}<#if field_has_next>,</#if>\n        </#list>\n    </sql>\n\n    <!-- 过滤SQL -->\n    <sql id=\"whereSQL\">\n        <!-- 这里写过滤语句，过滤项需要加query前缀 -->\n        <#list queryList as field>\n            <#if field.queryType == \'=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} = <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'!=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} != <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'>\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &gt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'>=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &gt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'<\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &lt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'<=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &lt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n        </if>\n            <#elseif field.queryType == \'left like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>)\n        </if>\n            <#elseif field.queryType == \'right like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(<#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n        </if>\n            <#else>\n            </#if>\n        </#list>\n    </sql>\n\n    <!-- 排序SQL -->\n    <sql id=\"orderBySQL\">\n        <if test=\"query.orders != null and query.orders.size() > 0\">\n            ORDER BY\n            <foreach collection=\"query.orders\" item=\"order\" separator=\",\">\n                <#noparse>${order.column}</#noparse> <if test=\"order.isAsc\">ASC</if><if test=\"!order.isAsc\">DESC</if>\n            </foreach>\n        </if>\n    </sql>\n\n    <!-- Entity类字段映射 -->\n    <resultMap type=\"${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity\" id=\"${className}Map\">\n        <#list fieldList as field>\n        <#if field.primaryPk>\n        <id property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        <#else>\n        <result property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        </#if>\n        </#list>\n    </resultMap>\n<#function getLogicDeleteField fieldList >\n    <#list fieldList as field>\n        <#if field.logicDelete?? && field.logicDelete>\n            <#return field.fieldName + \" = \" + field.logicNotDeleteValue>\n        </#if>\n    </#list>\n    <#return \"\">\n</#function>\n<#assign logicDeleteFlex = getLogicDeleteField(fieldList)>\n\n    <!-- Entity分页 -->\n    <select id=\"entityPage\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- Entity列表 -->\n    <select id=\"entityList\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- VO分页 -->\n    <select id=\"voPage\" resultType=\"${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- VO列表 -->\n    <select id=\"voList\" resultType=\"${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n</mapper>', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (162, 26, 501, 'java/Mapstruct.ftl', '${classNameUpper}Mapstruct.java', 1, 'Mapstruct模板', 'package ${projectPackage}.${projectNameUnderline}.mapstruct;\n\nimport com.yanggu.common.mapstruct.BaseMapstruct;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport org.mapstruct.Mapper;\nimport org.mapstruct.Named;\n\nimport static org.mapstruct.MappingConstants.ComponentModel.SPRING;\n\n/**\n * ${tableComment}Mapstruct\n */\n@Named(\"${className}Mapstruct\")\n@Mapper(componentModel = SPRING, implementationName = \"${projectNamePascal}${classNameUpper}MapstructImpl\")\npublic interface ${classNameUpper}Mapstruct extends BaseMapstruct<${classNameUpper}Entity, ${classNameUpper}VO, ${classNameUpper}DTO> {\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (163, 26, 504, 'java/Entity.ftl', '${classNameUpper}Entity.java', 1, 'Entity实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.entity;\n\nimport lombok.Data;\n<#if baseClass??>\nimport lombok.EqualsAndHashCode;\n<#else></#if>\nimport com.baomidou.mybatisplus.annotation.*;\n<#if baseClass??>\nimport ${baseClass.packageName}.${baseClass.code};\n</#if>\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity实体类\n */\n@Data\n@TableName(value = \"${tableName}\", schema = \"${databaseName}\")\n<#if baseClass??>\n@EqualsAndHashCode(callSuper = true)\n<#else></#if>\npublic class ${classNameUpper}Entity<#if baseClass??> extends ${baseClass.code}</#if> implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n<#if !field.baseField>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	</#if>\n	<#if field.primaryPk>\n	@TableId(value = \"${field.fieldName}\", type = IdType.AUTO)\n	<#else>\n		<#if field.autoFill == \"DEFAULT\">\n	@TableField(value = \"${field.fieldName}\")\n		</#if>\n		<#if field.autoFill == \"INSERT\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT)\n		</#if>\n		<#if field.autoFill == \"INSERT_UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT_UPDATE)\n		</#if>\n		<#if field.autoFill == \"UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.UPDATE)\n		</#if>\n	</#if>\n	<#if field.logicDelete>\n	@TableLogic(value = \"${field.logicNotDeleteValue}\", delval = \"${field.logicDeleteValue}\")\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n</#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (164, 26, 506, 'java/DTO.ftl', '${classNameUpper}DTO.java', 1, 'DTO实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.dto;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}DTO实体类\n */\n@Data\n@Schema(description = \"${tableComment}DTO实体类\")\npublic class ${classNameUpper}DTO implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n<#if !field.baseField>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	@Schema(description = \"${field.fieldComment}\")\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n</#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (165, 26, 508, 'java/VO.ftl', '${classNameUpper}VO.java', 1, 'VO实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.vo;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport com.yanggu.common.domain.vo.BaseVO;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}VO实体类\n */\n@Data\n@Schema(description = \"${tableComment}VO实体类\")\n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}VO extends BaseVO implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n	<#if !field.baseField>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	@Schema(description = \"${field.fieldComment}\")\n	</#if>\n	<#if field.attrType == \'Date\'>\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n	</#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (166, 26, 510, 'java/EntityQuery.ftl', '${classNameUpper}EntityQuery.java', 1, 'EntityQuery查询实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.query;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\nimport com.yanggu.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity查询实体类\n */\n@Data\n@Schema(description = \"${tableComment}Entity查询实体类\")\n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}EntityQuery extends PageQuery<${classNameUpper}Entity> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n<#list queryList as field>\n    <#if !field.baseField>\n    <#if field.fieldComment!?length gt 0>\n    /**\n     * ${field.fieldComment}\n     */\n    @Schema(description = \"${field.fieldComment}\")\n    </#if>\n    <#if field.attrType == \'Date\'>\n    </#if>\n    private ${field.attrType} ${field.attrName};\n\n    </#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (167, 26, 510, 'java/VOQuery.ftl', '${classNameUpper}VOQuery.java', 1, 'VOQuery查询实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.query;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\nimport com.yanggu.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}VO查询实体类\n */\n@Data\n@Schema(description = \"${tableComment}VO查询实体类\")\n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}VOQuery extends PageQuery<${classNameUpper}VO> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n<#list queryList as field>\n    <#if !field.baseField>\n    <#if field.fieldComment!?length gt 0>\n    /**\n     * ${field.fieldComment}\n     */\n    @Schema(description = \"${field.fieldComment}\")\n    </#if>\n    <#if field.attrType == \'Date\'>\n    </#if>\n    private ${field.attrType} ${field.attrName};\n\n    </#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:29', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (168, 27, 519, 'java/Controller.ftl', '${classNameUpper}Controller.java', 1, 'controller模板', 'package ${projectPackage}.${projectNameUnderline}.controller;\n\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.NotEmpty;\nimport com.github.xiaoymin.knife4j.annotations.ApiOperationSupport;\nimport io.swagger.v3.oas.annotations.Operation;\nimport io.swagger.v3.oas.annotations.tags.Tag;\nimport io.swagger.v3.oas.annotations.Parameter;\nimport com.yanggu.common.domain.vo.PageVO;\nimport com.yanggu.common.validation.group.InsertGroup;\nimport com.yanggu.common.validation.group.UpdateGroup;\nimport ${projectPackage}.${projectNameUnderline}.service.${classNameUpper}Service;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.validation.annotation.Validated;\n\nimport java.util.List;\n\n/**\n * ${tableComment}管理\n */\n@Validated\n@RestController\n@Tag(name = \"${tableComment}管理\")\n@RequestMapping(\"/${functionName}\")\npublic class ${classNameUpper}Controller {\n\n    @Autowired\n    private ${classNameUpper}Service ${className}Service;\n\n    /**\n     * 新增${tableComment}\n     */\n    @PostMapping(\"/add\")\n    @ApiOperationSupport(order = 1)\n    @Operation(summary = \"新增${tableComment}\")\n    public void add(@RequestBody @Validated(InsertGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.add(dto);\n    }\n\n    /**\n     * 修改${tableComment}\n     */\n    @PutMapping(\"/update\")\n    @ApiOperationSupport(order = 2)\n    @Operation(summary = \"修改${tableComment}\")\n    public void update(@RequestBody @Validated(UpdateGroup.class) ${classNameUpper}DTO dto) {\n        ${className}Service.update(dto);\n    }\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除${tableComment}\n     *\n     * @param id ${tableComment}ID\n     */\n    @DeleteMapping(\"/delete\")\n    @ApiOperationSupport(order = 3)\n    @Operation(summary = \"删除${tableComment}\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    public void delete(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        ${className}Service.delete(id);\n    }\n\n    /**\n     * 批量删除${tableComment}\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @DeleteMapping(\"/deleteList\")\n    @ApiOperationSupport(order = 4)\n    @Operation(summary = \"批量删除${tableComment}\")\n    public void deleteList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        ${className}Service.deleteList(idList);\n    }\n\n    /**\n     * ${tableComment}详情\n     *\n     * @param id ${tableComment}ID\n     */\n    @GetMapping(\"/detail\")\n    @ApiOperationSupport(order = 5)\n    @Operation(summary = \"${tableComment}详情\")\n    @Parameter(name = \"id\", description = \"${tableComment}ID\", required = true)\n    public ${classNameUpper}VO detail(@RequestParam(\"id\") @NotNull(message = \"${tableComment}ID不能为空\") ${primaryKeyType} id) {\n        return ${className}Service.detail(id);\n    }\n\n    /**\n     * ${tableComment}批量查询\n     *\n     * @param idList ${tableComment}ID列表\n     */\n    @PostMapping(\"/detailList\")\n    @ApiOperationSupport(order = 6)\n    @Operation(summary = \"${tableComment}批量查询\")\n    public List<${classNameUpper}VO> detailList(@RequestBody @NotEmpty(message = \"${tableComment}ID列表不能为空\") List<${primaryKeyType}> idList) {\n        return ${className}Service.detailList(idList);\n    }\n\n    /**\n     * ${tableComment}简单分页\n     */\n    @PostMapping(\"/entityPage\")\n    @ApiOperationSupport(order = 7)\n    @Operation(summary = \"${tableComment}简单分页\")\n    public PageVO<${classNameUpper}VO> entityPage(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityPage(query);\n    }\n\n    /**\n     * ${tableComment}简单列表\n     */\n    @PostMapping(\"/entityList\")\n    @ApiOperationSupport(order = 8)\n    @Operation(summary = \"${tableComment}简单列表\")\n    public List<${classNameUpper}VO> entityList(@RequestBody ${classNameUpper}EntityQuery query) {\n        return ${className}Service.entityList(query);\n    }\n\n    /**\n     * ${tableComment}复杂分页\n     */\n    @PostMapping(\"/voPage\")\n    @ApiOperationSupport(order = 9)\n    @Operation(summary = \"${tableComment}复杂分页\")\n    public PageVO<${classNameUpper}VO> voPage(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voPage(query);\n    }\n\n    /**\n     * ${tableComment}复杂列表\n     */\n    @PostMapping(\"/voList\")\n    @ApiOperationSupport(order = 10)\n    @Operation(summary = \"${tableComment}复杂列表\")\n    public List<${classNameUpper}VO> voList(@RequestBody ${classNameUpper}VOQuery query) {\n        return ${className}Service.voList(query);\n    }\n\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (169, 27, 521, 'java/Service.ftl', '${classNameUpper}Service.java', 1, 'Service模板', 'package ${projectPackage}.${projectNameUnderline}.service;\n\nimport com.yanggu.common.domain.vo.PageVO;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport com.baomidou.mybatisplus.extension.service.IService;\n\nimport java.util.List;\n\n/**\n * ${tableComment}服务层\n */\npublic interface ${classNameUpper}Service extends IService<${classNameUpper}Entity> {\n\n    /**\n     * 新增\n     */\n    void add(${classNameUpper}DTO dto);\n\n    /**\n     * 修改\n     */\n    void update(${classNameUpper}DTO dto);\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除\n     */\n    void delete(${primaryKeyType} id);\n\n    /**\n     * 批量删除\n     */\n    void deleteList(List<${primaryKeyType}> idList);\n\n    /**\n     * 详情\n     */\n    ${classNameUpper}VO detail(${primaryKeyType} id);\n\n    /**\n     * 批量查询\n     */\n    List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList);\n\n    /**\n     * 简单分页\n     */\n    PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query);\n\n    /**\n     * 简单列表\n     */\n    List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query);\n\n    /**\n     * 复杂分页\n     */\n    PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query);\n\n    /**\n     * 复杂列表\n     */\n    List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query);\n\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (170, 27, 523, 'java/ServiceImpl.ftl', '${classNameUpper}ServiceImpl.java', 1, 'Service实现类模板', 'package ${projectPackage}.${projectNameUnderline}.service.impl;\n\nimport com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\nimport com.baomidou.mybatisplus.core.toolkit.Wrappers;\nimport com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;\n<#if queryList?has_content>\n    <#assign needStrUtil = false>\n    <#list queryList as field>\n        <#if field.queryType?matches(\"(like|left like|right like)\") || field.attrType?matches(\"(String)\")>\n            <#assign needStrUtil = true>\n        </#if>\n    </#list>\n    <#if needStrUtil>\nimport org.dromara.hutool.core.text.StrUtil;\n    </#if>\n</#if>\nimport com.yanggu.common.domain.vo.PageVO;\nimport com.yanggu.common.exception.BusinessException;\nimport com.yanggu.common.mybatis.util.MybatisUtil;\nimport ${projectPackage}.${projectNameUnderline}.mapstruct.${classNameUpper}Mapstruct;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.mapper.${classNameUpper}Mapper;\nimport ${projectPackage}.${projectNameUnderline}.service.${classNameUpper}Service;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport org.springframework.beans.factory.annotation.Autowired;\n\nimport java.util.List;\n<#if queryList?has_content>\n    <#assign needStrUtil = false>\n    <#list queryList as field>\n        <#if field.queryType?matches(\"(=|!=|>|<|>=|<=)\")>\n            <#assign needStrUtil = true>\n        </#if>\n    </#list>\n    <#if needStrUtil>\nimport java.util.Objects;\n    </#if>\n</#if>\n\nimport static com.yanggu.common.response.ResultEnum.DATA_NOT_EXIST;\n\n/**\n * ${tableComment}Service实现类\n */\n@Service\npublic class ${classNameUpper}ServiceImpl extends ServiceImpl<${classNameUpper}Mapper, ${classNameUpper}Entity> implements ${classNameUpper}Service {\n\n    @Autowired\n    private ${classNameUpper}Mapper ${className}Mapper;\n\n    @Autowired\n    private ${classNameUpper}Mapstruct ${className}Mapstruct;\n\n    /**\n     * 新增\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void add(${classNameUpper}DTO dto) {\n        ${classNameUpper}Entity entity = ${className}Mapstruct.dtoToEntity(dto);\n        //唯一性校验等\n        ${className}Mapper.insert(entity);\n    }\n\n    /**\n     * 修改\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void update(${classNameUpper}DTO dto) {\n        ${classNameUpper}Entity formEntity = ${className}Mapstruct.dtoToEntity(dto);\n        ${classNameUpper}Entity dbEntity = selectById(dto.getId());\n        //唯一性校验等\n        ${className}Mapper.updateById(formEntity);\n    }\n<#function getPrimaryKeyType fieldList>\n    <#list fieldList as field>\n        <#if field.primaryPk>\n            <#return field.attrType>\n        </#if>\n    </#list>\n    <#return Long>\n</#function>\n<#assign primaryKeyType = getPrimaryKeyType(fieldList)>\n\n    /**\n     * 删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void delete(${primaryKeyType} id) {\n        ${classNameUpper}Entity dbEntity = selectById(id);\n        //删除校验和关联删除\n        ${className}Mapper.deleteById(id);\n    }\n\n    /**\n     * 批量删除\n     */\n    @Override\n    @Transactional(rollbackFor = RuntimeException.class)\n    public void deleteList(List<${primaryKeyType}> idList) {\n        //删除校验和关联删除\n        ${className}Mapper.deleteByIds(idList);\n    }\n\n    /**\n     * 详情\n     */\n    @Override\n    public ${classNameUpper}VO detail(${primaryKeyType} id) {\n        ${classNameUpper}Entity dbEntity = selectById(id);\n        return ${className}Mapstruct.entityToVO(dbEntity);\n    }\n\n    /**\n     * 简单分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> entityPage(${classNameUpper}EntityQuery query) {\n        //简单sql使用QueryWrapper\n        ${className}Mapper.selectPage(query, buildQueryWrapper(query));\n        //较复杂sql，使用xml\n        //${className}Mapper.entityPage(query);\n        return ${className}Mapstruct.entityToPageVO(query);\n    }\n\n    /**\n     * 简单列表\n     */\n    @Override\n    public List<${classNameUpper}VO> entityList(${classNameUpper}EntityQuery query) {\n        query.setPageSize(-1L);\n        //简单sql使用QueryWrapper\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectList(buildQueryWrapper(query));\n        //复杂sql，使用xml\n        //List<${classNameUpper}Entity> entityList = ${className}Mapper.entityList(query);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n    /**\n     * 复杂分页\n     */\n    @Override\n    public PageVO<${classNameUpper}VO> voPage(${classNameUpper}VOQuery query) {\n        ${className}Mapper.voPage(query);\n        return ${className}Mapstruct.voToPageVO(query);\n    }\n\n    /**\n     * 复杂列表\n     */\n    @Override\n    public List<${classNameUpper}VO> voList(${classNameUpper}VOQuery query) {\n        //查询全部数据\n        query.setPageSize(-1L);\n        return ${className}Mapper.voList(query);\n    }\n\n    /**\n     * 批量查询\n     */\n    @Override\n    public List<${classNameUpper}VO> detailList(List<${primaryKeyType}> idList) {\n        List<${classNameUpper}Entity> entityList = ${className}Mapper.selectByIds(idList);\n        return ${className}Mapstruct.entityToVO(entityList);\n    }\n\n    private ${classNameUpper}Entity selectById(${primaryKeyType} id) {\n        ${classNameUpper}Entity entity = ${className}Mapper.selectById(id);\n        if (entity == null) {\n            throw new BusinessException(DATA_NOT_EXIST, \"${tableComment}\", id);\n        }\n        return entity;\n    }\n\n    private LambdaQueryWrapper<${classNameUpper}Entity> buildQueryWrapper(${classNameUpper}EntityQuery query) {\n        LambdaQueryWrapper<${classNameUpper}Entity> wrapper = Wrappers.lambdaQuery(${classNameUpper}Entity.class);\n        <#if queryList?has_content>\n\n        //过滤字段\n        <#list queryList as field>\n            <#if field.queryType == \'=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.eq(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.eq(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'!=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.ne(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.ne(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'>\'>\n                <#if field.attrType == \'String\'>\n        wrapper.gt(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.gt(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'>=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.ge(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.ge(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'<\'>\n                <#if field.attrType == \'String\'>\n        wrapper.lt(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.lt(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'<=\'>\n                <#if field.attrType == \'String\'>\n        wrapper.le(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.le(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.like(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.like(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'left like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.likeLeft(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.likeLeft(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            <#elseif field.queryType == \'right like\'>\n                <#if field.attrType == \'String\'>\n        wrapper.likeRight(StrUtil.isNotBlank(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                <#else>\n        wrapper.likeRight(Objects.nonNull(query.get${field.attrName?cap_first}()), ${classNameUpper}Entity::get${field.attrName?cap_first}, query.get${field.attrName?cap_first}());\n                </#if>\n            </#if>\n        </#list>\n        </#if>\n\n        //排序字段\n        MybatisUtil.orderBy(wrapper, query.getOrders());\n        return wrapper;\n    }\n\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (171, 27, 525, 'java/Mapper.ftl', '${classNameUpper}Mapper.java', 1, 'Mapper模板', 'package ${projectPackage}.${projectNameUnderline}.mapper;\n\nimport com.yanggu.common.mybatis.mapper.BaseMapperPlus;\nimport com.baomidou.mybatisplus.core.metadata.IPage;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}EntityQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.query.${classNameUpper}VOQuery;\nimport org.apache.ibatis.annotations.Param;\nimport org.apache.ibatis.annotations.Mapper;\nimport org.springframework.stereotype.Repository;\n\nimport java.util.List;\n\n/**\n * ${tableComment}Mapper\n */\n@Mapper\n@Repository\npublic interface ${classNameUpper}Mapper extends BaseMapperPlus<${classNameUpper}Entity> {\n\n    /**\n     * Entity分页\n     */\n    IPage<${classNameUpper}Entity> entityPage(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n    /**\n     * Entity列表\n     */\n    List<${classNameUpper}Entity> entityList(@Param(\"query\") ${classNameUpper}EntityQuery query);\n\n    /**\n     * VO分页\n     */\n    IPage<${classNameUpper}VO> voPage(@Param(\"query\") ${classNameUpper}VOQuery query);\n\n    /**\n     * VO列表\n     */\n    List<${classNameUpper}VO> voList(@Param(\"query\") ${classNameUpper}VOQuery query);\n\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (172, 27, 528, 'xml/Mapper.ftl', '${classNameUpper}Mapper.xml', 1, 'Mapper的XML模板', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE mapper PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\" \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n\n<mapper namespace=\"${projectPackage}.${projectNameUnderline}.mapper.${classNameUpper}Mapper\">\n\n    <!-- 所有字段 -->\n    <sql id=\"allColumns\">\n        <#list fieldList as field>\n        ${field.fieldName}<#if field_has_next>,</#if>\n        </#list>\n    </sql>\n\n    <!-- 过滤SQL -->\n    <sql id=\"whereSQL\">\n        <!-- 这里写过滤语句，过滤项需要加query前缀 -->\n        <#list queryList as field>\n            <#if field.queryType == \'=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} = <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'!=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} != <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'>\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &gt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'>=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &gt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'<\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &lt; <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'<=\'>\n        <if test=\"query.${field.attrName} != null<#if field.attrType == \'String\'> and query.${field.attrName}.trim() != \'\'</#if>\">\n            AND ${field.fieldName} &lt;= <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>\n        </if>\n            <#elseif field.queryType == \'like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n        </if>\n            <#elseif field.queryType == \'left like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(\'%\', <#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>)\n        </if>\n            <#elseif field.queryType == \'right like\'>\n        <if test=\"query.${field.attrName} != null and query.${field.attrName}.trim() != \'\'\">\n            AND ${field.fieldName} LIKE CONCAT(<#noparse>#{query.</#noparse>${field.attrName}<#noparse>}</#noparse>, \'%\')\n        </if>\n            <#else>\n            </#if>\n        </#list>\n    </sql>\n\n    <!-- 排序SQL -->\n    <sql id=\"orderBySQL\">\n        <if test=\"query.orders != null and query.orders.size() > 0\">\n            ORDER BY\n            <foreach collection=\"query.orders\" item=\"order\" separator=\",\">\n                <#noparse>${order.column}</#noparse> <if test=\"order.isAsc\">ASC</if><if test=\"!order.isAsc\">DESC</if>\n            </foreach>\n        </if>\n    </sql>\n\n    <!-- Entity类字段映射 -->\n    <resultMap type=\"${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity\" id=\"${className}Map\">\n        <#list fieldList as field>\n        <#if field.primaryPk>\n        <id property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        <#else>\n        <result property=\"${field.attrName}\" column=\"${field.fieldName}\"/>\n        </#if>\n        </#list>\n    </resultMap>\n<#function getLogicDeleteField fieldList >\n    <#list fieldList as field>\n        <#if field.logicDelete?? && field.logicDelete>\n            <#return field.fieldName + \" = \" + field.logicNotDeleteValue>\n        </#if>\n    </#list>\n    <#return \"\">\n</#function>\n<#assign logicDeleteFlex = getLogicDeleteField(fieldList)>\n\n    <!-- Entity分页 -->\n    <select id=\"entityPage\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- Entity列表 -->\n    <select id=\"entityList\" resultMap=\"${className}Map\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- VO分页 -->\n    <select id=\"voPage\" resultType=\"${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n    <!-- VO列表 -->\n    <select id=\"voList\" resultType=\"${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO\">\n        SELECT\n            <include refid=\"allColumns\"/>\n        FROM\n            ${databaseName}.${tableName}\n        <where>\n            <#if logicDeleteFlex != \'\'>\n            ${logicDeleteFlex}\n            </#if>\n            <include refid=\"whereSQL\"/>\n        </where>\n        <include refid=\"orderBySQL\"/>\n    </select>\n\n</mapper>', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (173, 27, 530, 'java/Mapstruct.ftl', '${classNameUpper}Mapstruct.java', 1, 'Mapstruct模板', 'package ${projectPackage}.${projectNameUnderline}.mapstruct;\n\nimport com.yanggu.common.mapstruct.BaseMapstruct;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\nimport ${projectPackage}.${projectNameUnderline}.domain.dto.${classNameUpper}DTO;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\nimport org.mapstruct.Mapper;\nimport org.mapstruct.Named;\n\nimport static org.mapstruct.MappingConstants.ComponentModel.SPRING;\n\n/**\n * ${tableComment}Mapstruct\n */\n@Named(\"${className}Mapstruct\")\n@Mapper(componentModel = SPRING, implementationName = \"${projectNamePascal}${classNameUpper}MapstructImpl\")\npublic interface ${classNameUpper}Mapstruct extends BaseMapstruct<${classNameUpper}Entity, ${classNameUpper}VO, ${classNameUpper}DTO> {\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (174, 27, 533, 'java/Entity.ftl', '${classNameUpper}Entity.java', 1, 'Entity实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.entity;\n\nimport lombok.Data;\n<#if baseClass??>\nimport lombok.EqualsAndHashCode;\n<#else></#if>\nimport com.baomidou.mybatisplus.annotation.*;\n<#if baseClass??>\nimport ${baseClass.packageName}.${baseClass.code};\n</#if>\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity实体类\n */\n@Data\n@TableName(value = \"${tableName}\", schema = \"${databaseName}\")\n<#if baseClass??>\n@EqualsAndHashCode(callSuper = true)\n<#else></#if>\npublic class ${classNameUpper}Entity<#if baseClass??> extends ${baseClass.code}</#if> implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n<#if !field.baseField>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	</#if>\n	<#if field.primaryPk>\n	@TableId(value = \"${field.fieldName}\", type = IdType.AUTO)\n	<#else>\n		<#if field.autoFill == \"DEFAULT\">\n	@TableField(value = \"${field.fieldName}\")\n		</#if>\n		<#if field.autoFill == \"INSERT\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT)\n		</#if>\n		<#if field.autoFill == \"INSERT_UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT_UPDATE)\n		</#if>\n		<#if field.autoFill == \"UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.UPDATE)\n		</#if>\n	</#if>\n	<#if field.logicDelete>\n	@TableLogic(value = \"${field.logicNotDeleteValue}\", delval = \"${field.logicDeleteValue}\")\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n</#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (175, 27, 535, 'java/DTO.ftl', '${classNameUpper}DTO.java', 1, 'DTO实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.dto;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}DTO实体类\n */\n@Data\n@Schema(description = \"${tableComment}DTO实体类\")\npublic class ${classNameUpper}DTO implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n<#if !field.baseField>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	@Schema(description = \"${field.fieldComment}\")\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n</#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (176, 27, 537, 'java/VO.ftl', '${classNameUpper}VO.java', 1, 'VO实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.vo;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport com.yanggu.common.domain.vo.BaseVO;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}VO实体类\n */\n@Data\n@Schema(description = \"${tableComment}VO实体类\")\n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}VO extends BaseVO implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n	<#if !field.baseField>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	@Schema(description = \"${field.fieldComment}\")\n	</#if>\n	<#if field.attrType == \'Date\'>\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n	</#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (177, 27, 539, 'java/EntityQuery.ftl', '${classNameUpper}EntityQuery.java', 1, 'EntityQuery查询实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.query;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\nimport com.yanggu.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.entity.${classNameUpper}Entity;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity查询实体类\n */\n@Data\n@Schema(description = \"${tableComment}Entity查询实体类\")\n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}EntityQuery extends PageQuery<${classNameUpper}Entity> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n<#list queryList as field>\n    <#if !field.baseField>\n    <#if field.fieldComment!?length gt 0>\n    /**\n     * ${field.fieldComment}\n     */\n    @Schema(description = \"${field.fieldComment}\")\n    </#if>\n    <#if field.attrType == \'Date\'>\n    </#if>\n    private ${field.attrType} ${field.attrName};\n\n    </#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (178, 27, 539, 'java/VOQuery.ftl', '${classNameUpper}VOQuery.java', 1, 'VOQuery查询实体类模板', 'package ${projectPackage}.${projectNameUnderline}.domain.query;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\nimport com.yanggu.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameUnderline}.domain.vo.${classNameUpper}VO;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}VO查询实体类\n */\n@Data\n@Schema(description = \"${tableComment}VO查询实体类\")\n@EqualsAndHashCode(callSuper = true)\npublic class ${classNameUpper}VOQuery extends PageQuery<${classNameUpper}VO> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n<#list queryList as field>\n    <#if !field.baseField>\n    <#if field.fieldComment!?length gt 0>\n    /**\n     * ${field.fieldComment}\n     */\n    @Schema(description = \"${field.fieldComment}\")\n    </#if>\n    <#if field.attrType == \'Date\'>\n    </#if>\n    private ${field.attrType} ${field.attrName};\n\n    </#if>\n</#list>\n}', NULL, NULL, '2025-05-14 09:33:58', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (179, 28, 1652, 'vue/api.ts.ftl', '${functionNameKebabCase}.ts', 1, '后端接口api', 'import { createCrudApi, EnabledCrudApi } from \'@/api/common\'\nimport { ${moduleNamePascal}${functionNamePascal}Entity, ${moduleNamePascal}${functionNamePascal}Query } from \'@/types\'\n\n\n// 特定api\ninterface CustomApi {\n  \n}\n\n// 禁用的api\nconst disabled = [\n  \n] as const\n\nexport type ${moduleNamePascal}${functionNamePascal}ApiType = EnabledCrudApi<${moduleNamePascal}${functionNamePascal}Entity, ${moduleNamePascal}${functionNamePascal}Query, typeof disabled> & CustomApi\n\nconst baseUrl: string = \'/${moduleNameCase}/${functionName}\'\n\n// ${tableComment}API\nexport const ${moduleNameCase}${functionNamePascal}Api: ${moduleNamePascal}${functionNamePascal}ApiType = {\n	// 通用CRUD接口\n	...createCrudApi<${moduleNamePascal}${functionNamePascal}Entity, ${moduleNamePascal}${functionNamePascal}Query, typeof disabled>(baseUrl, disabled)\n}', NULL, NULL, '2025-05-14 17:55:56', '2025-11-24 16:49:50', 0);
INSERT INTO `gen_template` VALUES (180, 28, 547, 'form.vue.ftl', 'form.vue', 1, '表单页面', '<template>\n<#function getPopupType>\n    <#if popupType == 0>\n        <#return \'dialog\'>\n    <#else>\n        <#return \'drawer\'>\n    </#if>\n</#function>\n    <el-${getPopupType()}\n        v-model=\"visible\"\n        :title=\"!state.dataForm.id ? \'新增\' : \'修改\'\"\n        :close-on-click-modal=\"false\"\n    >\n        <el-form\n            ref=\"dataFormRef\"\n            :model=\"state.dataForm\"\n            :rules=\"dataRules\"\n            label-width=\"100px\"\n            @keyup.enter=\"submitHandle()\"\n        >\n            <#macro formItem field>\n                <el-form-item label=\"${field.fieldComment!}\" prop=\"${field.attrName}\">\n                    <#if field.formType == \'text\'>\n                        <el-input\n                            v-model=\"state.dataForm.${field.attrName}\"\n                            clearable\n                            placeholder=\"请输入${field.fieldComment!}\"\n                        ></el-input>\n                    <#elseif field.formType == \'textarea\'>\n                        <el-input\n                            type=\"textarea\"\n                            v-model=\"state.dataForm.${field.attrName}\"\n                        ></el-input>\n                    <#elseif field.formType == \'editor\'>\n                        <el-input\n                            type=\"textarea\"\n                            v-model=\"state.dataForm.${field.attrName}\"\n                        ></el-input>\n                    <#elseif field.formType == \'select\'>\n                        <el-select\n                            v-model=\"state.dataForm.${field.attrName}\"\n                            :options=\"${field.enumNameAllUpper}_ENUM\"\n                            clearable\n                            filterable\n                            placeholder=\"请选择${field.fieldComment!}\"\n                        ></el-select>\n                    <#elseif field.formType == \'radio\'>\n                        <el-radio-group\n                            v-model=\"state.dataForm.${field.attrName}\"\n                            :options=\"${field.enumNameAllUpper}_ENUM\"\n                        ></el-radio-group>\n                    <#elseif field.formType == \'checkbox\'>\n                        <el-checkbox-group\n                            v-model=\"state.dataForm.${field.attrName}\"\n                            :options=\"${field.enumNameAllUpper}_ENUM\"\n                        ></el-checkbox-group>\n                    <#elseif field.formType == \'date\'>\n                        <el-date-picker\n                            type=\"date\"\n                            placeholder=\"请选择${field.fieldComment!}\"\n                            v-model=\"state.dataForm.${field.attrName}\"\n                        ></el-date-picker>\n                    <#elseif field.formType == \'datetime\'>\n                        <el-date-picker\n                            type=\"datetime\"\n                            placeholder=\"请选择${field.fieldComment!}\"\n                            v-model=\"state.dataForm.${field.attrName}\"\n                        ></el-date-picker>\n                    <#elseif field.formType == \'number\'>\n                        <el-input-number\n                            v-model=\"state.dataForm.${field.attrName}\"\n                            size=\"small\"\n                        ></el-input-number>\n                    <#else>\n                        <el-input\n                            v-model=\"state.dataForm.${field.attrName}\"\n                            clearable\n                            placeholder=\"请输入${field.fieldComment!}\"\n                        ></el-input>\n                    </#if>\n                </el-form-item>\n            </#macro>\n\n            <#if formLayout == 2>\n                <#list formList?chunk(2) as row>\n                    <#if row?size == 2>\n                        <el-row :gutter=\"20\">\n                            <el-col :span=\"12\">\n                                <@formItem field=row[0] />\n                            </el-col>\n                            <el-col :span=\"12\">\n                                <@formItem field=row[1] />\n                            </el-col>\n                        </el-row>\n                    <#else>\n                        <!-- 单个时不使用 el-row -->\n                        <@formItem field=row[0] />\n                    </#if>\n                </#list>\n            <#else>\n                <#list formList as field>\n                    <@formItem field=field />\n                </#list>\n            </#if>\n        </el-form>\n\n        <template #footer>\n            <el-button\n                type=\"primary\"\n                :icon=\"Check\"\n                :loading=\"submitLoading\"\n                @click=\"submitHandle()\"\n            >\n                确定\n            </el-button>\n            <el-button :icon=\"Close\" @click=\"visible = false\">取消</el-button>\n        </template>\n    </el-${getPopupType()}>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive } from \'vue\'\nimport { ${moduleNameCase}${functionNamePascal}Api } from \'@/api\'\nimport { FormOptions, ${moduleNamePascal}${functionNamePascal}Entity } from \'@/types\'\nimport { useSubmitForm } from \'@/hooks\'\nimport { Check, Close } from \'@element-plus/icons-vue\'\n\n<#list formList as field>\n    <#if field.formType == \'select\' || field.formType == \'checkbox\' || field.formType == \'radio\'>\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/constant/enum\'\n    </#if>\n</#list>\n\nconst emit = defineEmits([\'refreshDataList\'])\n\nconst state = reactive({\n    // 提交API\n    submitApi: ${moduleNameCase}${functionNamePascal}Api.submit,\n    // 详情API\n    detailApi: ${moduleNameCase}${functionNamePascal}Api.detail,\n    // 表单数据\n    dataForm: {\n        <#list fieldList as field>\n            <#if field.entityBaseField == 0>\n        ${field.attrName}: \'\'<#if field_has_next>,</#if>\n            </#if>\n        </#list>\n    },\n    emit\n} as FormOptions<${moduleNamePascal}${functionNamePascal}Entity>)\n\nconst dataRules = reactive({\n    <#list formList as field>\n        <#if field.formRequired == 1>\n    ${field.attrName}: [\n        { required: true, message: \'${field.fieldComment!}不能为空\', trigger: \'blur\' }\n    ]<#if field_has_next>,</#if>\n        </#if>\n    </#list>\n})\n\nconst {\n    visible,\n    dataFormRef,\n    init,\n    submitHandle,\n    submitLoading\n} = useSubmitForm(state)\n\ndefineExpose({ init })\n</script>\n', '', NULL, '2025-05-14 17:55:56', '2025-12-03 14:37:52', 0);
INSERT INTO `gen_template` VALUES (181, 28, 547, 'vue/index.vue.ftl', 'index.vue', 1, '列表页面', '<template>\n	<div>\n		<el-card v-if=\"queryShow\" class=\"layout-query-card\" shadow=\"hover\">\n			<el-form ref=\"queryRef\" :inline=\"true\" :model=\"state.queryForm\" @keyup.enter=\"getDataList()\">\n			<#list queryList as field>\n				<#if field.queryFormType == \'date\'>\n				<el-form-item label=\"${field.fieldComment}\" prop=\"dateRange\" style=\"width: 350px\">\n				<#elseif field.queryFormType == \'datetime\'>\n				<el-form-item label=\"${field.fieldComment}\" prop=\"dateTimeRange\" style=\"width: 350px\">\n				<#else>\n				<el-form-item label=\"${field.fieldComment}\" prop=\"${field.attrName}\">\n				</#if>\n				<#if field.queryFormType == \'text\' || field.queryFormType == \'textarea\' || field.queryFormType == \'editor\'>\n					<el-input v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请输入${field.fieldComment}\"></el-input>\n				<#elseif field.queryFormType == \'select\'>\n					<el-select v-model=\"state.queryForm.${field.attrName}\" :options=\"${field.enumNameAllUpper}_ENUM\" clearable placeholder=\"请选择${field.fieldComment}\"></el-select>\n				<#elseif field.queryFormType == \'radio\'>\n					<el-radio-group v-model=\"state.queryForm.${field.attrName}\" :options=\"${field.enumNameAllUpper}_ENUM\"></el-radio-group>\n				<#elseif field.queryFormType == \'checkbox\'>\n					<el-checkbox-group v-model=\"state.queryForm.${field.attrName}\" :options=\"${field.enumNameAllUpper}_ENUM\"></el-checkbox-group>\n				<#elseif field.queryFormType == \'date\'>\n					<el-date-picker\n							v-model=\"state.queryForm.dateRange\"\n							type=\"daterange\"\n							format=\"YYYY-MM-DD\"\n							value-format=\"YYYY-MM-DD\"\n							clearable\n							start-placeholder=\"开始日期\"\n							end-placeholder=\"结束日期\"\n							:default-time=\"[new Date(2000, 1, 1, 0, 0, 0), new Date(2000, 1, 1, 23, 59, 59)]\"\n					>\n					</el-date-picker>\n				<#elseif field.queryFormType == \'datetime\'>\n					<el-date-picker\n							v-model=\"state.queryForm.dateTimeRange\"\n							type=\"datetimerange\"\n							format=\"YYYY-MM-DD HH:mm:ss\"\n							value-format=\"YYYY-MM-DD HH:mm:ss\"\n							clearable\n							start-placeholder=\"开始时间\"\n							end-placeholder=\"结束时间\"\n							:default-time=\"[new Date(2000, 1, 1, 0, 0, 0), new Date(2000, 1, 1, 23, 59, 59)]\"\n					>\n					</el-date-picker>\n				<#else>\n					<el-input v-model=\"state.queryForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment}\"></el-input>\n				</#if>\n				</el-form-item>\n			</#list>\n				<el-form-item>\n					<el-button type=\"primary\" :loading=\"state.dataListLoading\" :icon=\"Search\" @click=\"getDataList()\">查询</el-button>\n				</el-form-item>\n				<el-form-item>\n					<el-button :icon=\"Refresh\" @click=\"resetQueryHandle()\">重置</el-button>\n				</el-form-item>\n			</el-form>\n		</el-card>\n\n		<el-card ref=\"tableCardRef\" class=\"layout-table-card\" shadow=\"hover\">\n			<!-- 表格工具栏 -->\n			<template #header>\n				<table-tool-bar\n					v-if=\"tableCardRef\"\n					v-model:show-search=\"queryShow\"\n					v-model:query-loading=\"state.dataListLoading\"\n					:table-card-ref=\"tableCardRef\"\n					@get-data-list=\"getDataList()\"\n				>\n					<template #left>\n						<el-space>\n							<el-button type=\"primary\" :icon=\"Plus\" @click=\"formInitHandle()\">新增</el-button>\n							<el-button type=\"danger\" :loading=\"state.deleteLoading\" :icon=\"Delete\" @click=\"deleteBatchHandle()\">删除</el-button>\n						</el-space>\n					</template>\n				</table-tool-bar>\n			</template>\n      <!-- 表格数据 -->\n			<el-table\n				ref=\"tableRef\"\n				v-loading=\"state.dataListLoading\"\n				:data=\"state.dataList\"\n				border\n				row-key=\"id\"\n				max-height=\"60vh\"\n				class=\"layout-table\"\n        header-cell-class-name=\"layout-table-header\"\n				@selection-change=\"selectionChangeHandle\"\n				@sort-change=\"sortChangeHandle\"\n			>\n				<el-table-column type=\"selection\" header-align=\"center\" align=\"center\" width=\"50\"></el-table-column>\n				<el-table-column type=\"index\" :index=\"tableIndex\" label=\"序号\" header-align=\"center\" align=\"center\" width=\"60\"></el-table-column>\n			<#list gridList as field>\n				<el-table-column prop=\"${field.attrName}\" label=\"${field.fieldComment!}\" show-overflow-tooltip header-align=\"center\" align=\"center\" <#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>:formatter=\"getLabel(${field.enumNameAllUpper}_ENUM)\"</#if> <#if field.gridSort == 1>sortable=\"custom\"</#if>></el-table-column>\n			</#list>\n				<el-table-column label=\"操作\" fixed=\"right\" header-align=\"center\" align=\"center\" width=\"150\">\n					<template #default=\"scope\">\n						<el-button type=\"primary\" link :icon=\"Edit\" @click=\"formInitHandle(scope.row.id)\">修改</el-button>\n						<el-button type=\"primary\" link :icon=\"Delete\" @click=\"deleteBatchHandle(scope.row.id)\">删除</el-button>\n					</template>\n				</el-table-column>\n			</el-table>\n      <!-- 分页操作栏 -->\n			<el-pagination\n				:current-page=\"state.pageNum\"\n				:page-sizes=\"state.pageSizes\"\n				:page-size=\"state.pageSize\"\n				:total=\"state.total\"\n				background\n				layout=\"total, sizes, prev, pager, next, jumper\"\n				@size-change=\"sizeChangeHandle\"\n				@current-change=\"currentChangeHandle\"\n			></el-pagination>\n\n			<!-- 弹窗表单 -->\n			<${moduleName}-${functionNameKebabCase}-form ref=\"formRef\" @refresh-data-list=\"getDataList()\"></${moduleName}-${functionNameKebabCase}-form>\n		</el-card>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive } from \'vue\'\nimport ${moduleNamePascal}${functionNamePascal}Form from \'@/views/${moduleName}/${functionNameKebabCase}/form.vue\'\nimport TableToolBar from \'@/components/table/tool-bar/index.vue\'\nimport { Delete, Edit, Plus, Refresh, Search } from \'@element-plus/icons-vue\'\nimport { useTableAction, useInitForm } from \'@/hooks\'\nimport { ${moduleNameCase}${functionNamePascal}Api } from \'@/api\'\nimport { IHooksOptions, ${moduleNamePascal}${functionNamePascal}Entity, ${moduleNamePascal}${functionNamePascal}Query } from \'@/types\'\n<#list queryList as field>\n<#if field.queryFormType == \'select\' || field.queryFormType == \'radio\' || field.queryFormType == \'checkbox\'>\nimport { getLabel } from \'@/utils/enum\'\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/constant/enum\'\n</#if>\n</#list>\n<#list gridList as field>\n	<#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>\nimport { getLabel } from \'@/utils/enum\'\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/constant/enum\'\n	</#if>\n</#list>\n\ndefineOptions({\n	name: \'${moduleNamePascal}${functionNamePascal}\'\n})\n\nconst state = reactive({\n    dataListApi: ${moduleNameCase}${functionNamePascal}Api.entityPage,\n    deleteListApi: ${moduleNameCase}${functionNamePascal}Api.deleteList,\n    queryForm: {\n        <#list queryList as field>\n        	<#if field.queryFormType == \'date\'>\n        dateRange: []<#sep>, </#sep>\n        	<#elseif field.queryFormType == \'datetime\'>\n		    dateTimeRange: []<#sep>, </#sep>\n        	<#else>\n        ${field.attrName}: \'\'<#sep>, </#sep>\n        	</#if>\n        </#list>\n    }\n} as IHooksOptions<${moduleNamePascal}${functionNamePascal}Query, ${moduleNamePascal}${functionNamePascal}Entity>)\n\nconst {\n	getDataList,\n	selectionChangeHandle,\n	sizeChangeHandle,\n	currentChangeHandle,\n	deleteBatchHandle,\n	sortChangeHandle,\n	queryRef,\n  queryShow,\n	tableCardRef,\n  tableRef,\n	resetQueryHandle,\n	tableIndex\n} = useTableAction(state)\n\nconst { formRef, formInitHandle } = useInitForm()\n</script>\n', NULL, NULL, '2025-05-14 17:55:56', '2025-11-24 17:51:15', 0);
INSERT INTO `gen_template` VALUES (182, 29, 550, 'pom.xml.ftl', 'pom.xml', 1, 'pom文件模板', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<project xmlns=\"http://maven.apache.org/POM/4.0.0\"\n         xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n         xsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd\">\n    <modelVersion>4.0.0</modelVersion>\n\n    <groupId>${projectPackage}</groupId>\n    <artifactId>${projectName}</artifactId>\n    <version>${projectVersion}</version>\n    <description>${projectDesc}</description>\n    <packaging>${projectTemplatePropertyData[\'packageType\']}</packaging>\n\n    <properties>\n        <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>\n        <project.reporting.outputEncoding>UTF-8</project.reporting.outputEncoding>\n        <java.version>${projectTemplatePropertyData[\'jdkVersion\']}</java.version>\n        <maven.compiler.source>${projectTemplatePropertyData[\'jdkVersion\']}</maven.compiler.source>\n        <maven.compiler.target>${projectTemplatePropertyData[\'jdkVersion\']}</maven.compiler.target>\n        <spring-boot.version>3.3.1</spring-boot.version>\n        <hutool.version>7.0.0-M2</hutool.version>\n        <lombok.version>1.18.36</lombok.version>\n        <mapstruct.version>1.6.3</mapstruct.version>\n        <mybatis-plus.version>3.5.14</mybatis-plus.version>\n        <#if projectTemplatePropertyData[\'enableKnife4j\']>   \n        <knife4j-openapi3-jakarta.version>4.5.0</knife4j-openapi3-jakarta.version>\n        </#if>\n        <#if projectTemplatePropertyData[\'enableSaToken\']>\n        <sa-token.version>1.39.0</sa-token.version>\n        </#if>   \n    </properties>\n\n    <!-- 依赖版本管理 -->\n    <dependencyManagement>\n        <dependencies>\n            <dependency>\n                <groupId>org.springframework.boot</groupId>\n                <artifactId>spring-boot-dependencies</artifactId>\n                <version><#noparse>${spring-boot.version}</#noparse></version>\n                <type>pom</type>\n                <scope>import</scope>\n            </dependency>\n            <dependency>\n                <groupId>org.projectlombok</groupId>\n                <artifactId>lombok</artifactId>\n                <version><#noparse>${lombok.version}</#noparse></version>\n            </dependency>\n            <dependency>\n                <groupId>cn.hutool.v7</groupId>\n                <artifactId>hutool-all</artifactId>\n                <version><#noparse>${hutool.version}</#noparse></version>\n            </dependency>\n            <!--对象转换-->\n            <dependency>\n                <groupId>org.mapstruct</groupId>\n                <artifactId>mapstruct</artifactId>\n                <version><#noparse>${mapstruct.version}</#noparse></version>\n            </dependency>\n            <dependency>\n                <groupId>org.mapstruct</groupId>\n                <artifactId>mapstruct-processor</artifactId>\n                <version><#noparse>${mapstruct.version}</#noparse></version>\n            </dependency>\n            <#if projectTemplatePropertyData[\'enableKnife4j\']>  \n            <dependency>\n                <groupId>com.github.xiaoymin</groupId>\n                <artifactId>knife4j-openapi3-jakarta-spring-boot-starter</artifactId>\n                <version><#noparse>${knife4j-openapi3-jakarta.version}</#noparse></version>\n            </dependency>\n           </#if>\n            <dependency>\n                <groupId>com.baomidou</groupId>\n                <artifactId>mybatis-plus-jsqlparser</artifactId>\n                <version><#noparse>${mybatis-plus.version}</#noparse></version>\n            </dependency>\n            <dependency>\n                <groupId>com.baomidou</groupId>\n                <artifactId>mybatis-plus-spring-boot3-starter</artifactId>\n                <version><#noparse>${mybatis-plus.version}</#noparse></version>\n            </dependency>\n            <#if projectTemplatePropertyData[\'enableSaToken\']> \n            <dependency>\n                <groupId>cn.dev33</groupId>\n                <artifactId>sa-token-spring-boot3-starter</artifactId>\n                <version><#noparse>${sa-token.version}</#noparse></version>\n            </dependency>  \n            <!-- Sa-Token 整合 RedisTemplate -->\n            <dependency>\n                <groupId>cn.dev33</groupId>\n                <artifactId>sa-token-redis-jackson</artifactId>\n                <version><#noparse>${sa-token.version}</#noparse></version>\n            </dependency>\n            </#if>\n        </dependencies>\n    </dependencyManagement>\n\n    <dependencies>\n        <dependency>\n            <groupId>org.projectlombok</groupId>\n            <artifactId>lombok</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>cn.hutool.v7</groupId>\n            <artifactId>hutool-all</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-validation</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-web</artifactId>\n        </dependency>\n        <#if projectTemplatePropertyData[\'enableKnife4j\']>    \n        <dependency>\n            <groupId>com.github.xiaoymin</groupId>\n            <artifactId>knife4j-openapi3-jakarta-spring-boot-starter</artifactId>\n        </dependency>\n        </#if>   \n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-aop</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>jakarta.validation</groupId>\n            <artifactId>jakarta.validation-api</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-test</artifactId>\n            <scope>test</scope>\n        </dependency>\n        <dependency>\n            <groupId>com.mysql</groupId>\n            <artifactId>mysql-connector-j</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>com.baomidou</groupId>\n            <artifactId>mybatis-plus-jsqlparser</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>com.baomidou</groupId>\n            <artifactId>mybatis-plus-spring-boot3-starter</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.mapstruct</groupId>\n            <artifactId>mapstruct</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.mapstruct</groupId>\n            <artifactId>mapstruct-processor</artifactId>\n        </dependency>\n        <#if projectTemplatePropertyData[\'enableSaToken\']>      \n        <dependency>\n            <groupId>cn.dev33</groupId>\n            <artifactId>sa-token-spring-boot3-starter</artifactId>\n        </dependency>\n        <!-- Sa-Token 整合 RedisTemplate -->\n        <dependency>\n            <groupId>cn.dev33</groupId>\n            <artifactId>sa-token-redis-jackson</artifactId>\n        </dependency>\n        <!-- 提供 Redis 连接池 -->\n        <dependency>\n            <groupId>org.apache.commons</groupId>\n            <artifactId>commons-pool2</artifactId>\n        </dependency>\n        </#if>   \n    </dependencies>\n\n    <build>\n        <finalName><#noparse>${project.artifactId}</#noparse></finalName>\n        <plugins>\n            <plugin>\n                <groupId>org.springframework.boot</groupId>\n                <artifactId>spring-boot-maven-plugin</artifactId>\n                <version><#noparse>${spring-boot.version}</#noparse></version>\n                <executions>\n                    <execution>\n                        <id>repackage</id>\n                        <goals>\n                            <goal>repackage</goal>\n                        </goals>\n                    </execution>\n                </executions>\n            </plugin>\n        </plugins>\n    </build>\n\n</project>', NULL, NULL, '2025-05-14 17:56:37', '2025-12-29 16:01:32', 0);
INSERT INTO `gen_template` VALUES (183, 29, 550, '.gitignore.ftl', '.gitignore', 1, 'gitignore配置文件', '!.mvn/wrapper/maven-wrapper.jar\n!**/src/main/**/target/\n!**/src/test/**/target/\n\n### IntelliJ IDEA ###\n.idea/**\n*.iws\n*.iml\n*.ipr\n\n### Eclipse ###\n.apt_generated\n.classpath\n.factorypath\n.project\n.settings\n.springBeans\n.sts4-cache\n\n### NetBeans ###\n/nbproject/private/\n/nbbuild/\n/dist/\n/nbdist/\n/.nb-gradle/\nbuild/\n!**/src/main/**/build/\n!**/src/test/**/build/\n\n### VS Code ###\n.vscode/\n\n### Mac OS ###\n.DS_Store\n\n/**/target/**\n/**/logs/**\n/**/log/**', NULL, NULL, '2025-05-14 17:56:37', '2025-09-11 10:20:40', 0);
INSERT INTO `gen_template` VALUES (184, 29, 555, 'application.ftl', 'application.yaml', 1, 'springboot项目配置文件', 'server:\n  port: ${projectPort}\n<#if projectTemplatePropertyData[\'serverServletContextPath\']>\n  servlet:  \n    context-path: /${projectName}\n</#if>\n\nspring:\n  # 项目名配置\n  application:\n    name: ${projectName}\n    version: \'${projectVersion}\'\n    description: \'${projectDesc}\'\n\n  main:\n    # 允许循环依赖\n    allow-circular-references: true\n\n  # 配置策略\n  mvc:\n    pathmatch:\n      matching-strategy: ANT_PATH_MATCHER\n\n  # jackson配置\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8\n\n<#if databaseDriverClassName??>\n  # 数据源配置\n  datasource:\n    driver-class-name: ${databaseDriverClassName}\n    url: ${databaseUrl}\n    username: ${databaseUsername}\n    password: ${databasePassword}\n</#if>\n\n<#if projectTemplatePropertyData[\'enableSaToken\']>\n  data:\n    # redis配置\n    redis:\n      database: 0\n      # Redis数据库索引（默认为0）\n      # Redis服务器地址\n      host: 127.0.0.1\n      # Redis服务器连接端口\n      port: 6379\n      # Redis服务器连接密码（默认为空）\n      # password: \'123456\'\n      # 连接超时时间\n      timeout: 10s\n      lettuce:\n        pool:\n          # 连接池最大连接数\n          max-active: 200\n          # 连接池最大阻塞等待时间（使用负值表示没有限制）\n          max-wait: -1ms\n          # 连接池中的最大空闲连接\n          max-idle: 10\n          # 连接池中的最小空闲连接\n          min-idle: 0\n\n# Sa-Token 配置 (文档: https://sa-token.cc)\nsa-token:\n  # token 名称（同时也是 cookie 名称）\n  token-name: satoken\n  # token 有效期（单位：秒） 默认30天，-1 代表永久有效\n  timeout: 2592000\n  # token 最低活跃频率（单位：秒），如果 token 超过此时间没有访问系统就会被冻结，默认-1 代表不限制，永不冻结\n  active-timeout: -1\n  # 是否允许同一账号多地同时登录 （为 true 时允许一起登录, 为 false 时新登录挤掉旧登录）\n  is-concurrent: true\n  # 在多人登录同一账号时，是否共用一个 token （为 true 时所有登录共用一个 token, 为 false 时每次登录新建一个 token）\n  is-share: false\n  # token 风格（默认可取值：uuid、simple-uuid、random-32、random-64、random-128、tik）\n  token-style: simple-uuid\n  # 是否输出操作日志\n  is-log: true\n</#if>\n\n# mybatis-plus配置\nmybatis-plus:\n  # mapper配置文件\n  mapper-locations: classpath*:mapper/**/*.xml\n  configuration:\n    # 日志配置\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\n# knife4j配置\nknife4j:\n  enable: true\n  setting:\n    enable-dynamic-parameter: true\n</#if>', '', NULL, '2025-05-14 17:56:37', '2025-12-29 15:32:47', 0);
INSERT INTO `gen_template` VALUES (185, 29, 185, 'Application.ftl', '${projectNamePascal}Application.java', 1, '主启动类', 'package ${projectPackage}.${projectNameDot};\n\nimport org.mybatis.spring.annotation.MapperScan;\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\n\n/**\n * ${projectNamePascal}主启动类\n */\n@MapperScan(\"${projectPackage}.${projectNameDot}.mapper\")\n@SpringBootApplication(scanBasePackages = \"${projectPackage}.${projectNameDot}.*\")\npublic class ${projectNamePascal}Application {\n\n    public static void main(String[] args) {\n        SpringApplication.run(${projectNamePascal}Application.class, args);\n    }\n\n}', NULL, NULL, '2025-05-14 17:56:37', '2025-08-13 15:09:22', 0);
INSERT INTO `gen_template` VALUES (187, 29, 562, 'CorsConfig.ftl', 'CorsConfig.java', 1, '跨域文件配置类', 'package ${projectPackage}.${projectNameDot}.common.config;\n\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.web.cors.CorsConfiguration;\nimport org.springframework.web.cors.UrlBasedCorsConfigurationSource;\nimport org.springframework.web.filter.CorsFilter;\n\nimport java.util.List;\n\n/**\n * 跨域配置\n */\n@Configuration\n@ConditionalOnProperty(name = \"web.cors.enable\", havingValue = \"true\", matchIfMissing = true)\npublic class CorsConfig {\n\n    /**\n     * 跨域过期时间。单位：秒\n     */\n    @Value(\"<#noparse>${web.cors.max-age:3600}</#noparse>\")\n    private Long maxAge;\n\n    /**\n     * 跨域是否传递cookie\n     */\n    @Value(\"<#noparse>${web.cors.allow-credentials:true}</#noparse>\")\n    private Boolean allowCredentials;\n\n    /**\n     * 允许跨域的请求头\n     */\n    @Value(\"<#noparse>#{\'${web.cors.allowed-headers:*}\'.split(\',\')}</#noparse>\")\n    private List<String> allowedHeaders;\n\n    /**\n     * 允许跨域的方法\n     */\n    @Value(\"<#noparse>#{\'${web.cors.allowed-methods:*}\'.split(\',\')}</#noparse>\")\n    private List<String> allowedMethods;\n\n    /**\n     * 允许跨域的源\n     */\n    @Value(\"<#noparse>#{\'${web.cors.allowed-origins:*}\'.split(\',\')}</#noparse>\")\n    private List<String> allowedOrigins;\n\n    /**\n     * 允许跨域的响应头\n     */\n    @Value(\"<#noparse>#{\'${web.cors.expose-headers:Content-Disposition,Authorization,token,Cookie}\'.split(\',\')}</#noparse>\")\n    private List<String> exposedHeaders;\n\n    @Bean\n    public CorsFilter corsFilter() {\n        final UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();\n        final CorsConfiguration corsConfiguration = new CorsConfiguration();\n        corsConfiguration.setMaxAge(maxAge);\n        corsConfiguration.setAllowCredentials(allowCredentials);\n        corsConfiguration.setAllowedHeaders(allowedHeaders);\n        corsConfiguration.setAllowedMethods(allowedMethods);\n        corsConfiguration.setAllowedOriginPatterns(allowedOrigins);\n        corsConfiguration.setExposedHeaders(exposedHeaders);\n        source.registerCorsConfiguration(\"/**\", corsConfiguration);\n        return new CorsFilter(source);\n    }\n\n}\n', '', NULL, '2025-05-16 16:11:20', '2025-08-21 14:36:50', 0);
INSERT INTO `gen_template` VALUES (188, 29, 562, 'Knife4jConfig.ftl', 'Knife4jConfig.java', 1, 'Knife4j配置类', 'package ${projectPackage}.${projectNameDot}.common.config;\n\nimport com.github.xiaoymin.knife4j.spring.annotations.EnableKnife4j;\nimport io.swagger.v3.oas.models.OpenAPI;\nimport io.swagger.v3.oas.models.info.Info;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/**\n * 创建Knife4j配置\n */\n@Configuration\n@EnableKnife4j\npublic class Knife4jConfig {\n\n    @Value(\"<#noparse>${spring.application.name:}</#noparse>\")\n    private String applicationName;\n\n    @Value(\"<#noparse>${spring.application.version:}</#noparse>\")\n    private String version;\n\n    @Value(\"<#noparse>${spring.application.description:}</#noparse>\")\n    private String description;\n\n    @Bean\n    public OpenAPI customOpenAPI() {\n        return new OpenAPI()\n                .info(new Info()\n                        .title(applicationName)\n                        .version(version)\n                        .description(description)\n                );\n    }\n\n}\n', '', 'projectTemplatePropertyData[\'enableKnife4j\']', '2025-05-16 16:12:47', '2025-12-29 10:10:47', 0);
INSERT INTO `gen_template` VALUES (189, 29, 566, 'BaseEntity.ftl', 'BaseEntity.java', 1, 'Entity基类', 'package ${projectPackage}.${projectNameDot}.common.domain.entity;\n\nimport com.baomidou.mybatisplus.annotation.FieldFill;\nimport com.baomidou.mybatisplus.annotation.TableField;\nimport com.baomidou.mybatisplus.annotation.TableLogic;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * 数据库实体基类\n * <p>包含创建时间、修改时间、删除标识三个字段</p>\n */\n@Data\npublic abstract class BaseEntity implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 4784400802803080438L;\n\n    /**\n     * 创建时间\n     */\n    @TableField(value = \"create_time\", fill = FieldFill.INSERT)\n    private Date createTime;\n\n    /**\n     * 修改时间\n     */\n    @TableField(value = \"update_time\", fill = FieldFill.INSERT_UPDATE)\n    private Date updateTime;\n\n    /**\n     * 是否删除（0未删除, 1删除）\n     */\n    @TableField(\"is_delete\")\n    @TableLogic(value = \"0\", delval = \"1\")\n    private Integer isDelete;\n\n}', NULL, NULL, '2025-05-16 16:14:43', '2025-10-30 11:10:52', 0);
INSERT INTO `gen_template` VALUES (190, 29, 566, 'BaseUserEntity.ftl', 'BaseUserEntity.java', 1, 'Entity用户基类', 'package ${projectPackage}.${projectNameDot}.common.domain.entity;\n\nimport com.baomidou.mybatisplus.annotation.FieldFill;\nimport com.baomidou.mybatisplus.annotation.TableField;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\n/**\n * 数据库实体类基类，适用于用户操作的数据表、增删改查\n */\n@Data\n@EqualsAndHashCode(callSuper = true)\npublic abstract class BaseUserEntity extends BaseEntity implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = -3534460034686573788L;\n\n    /**\n     * 创建人\n     */\n    @TableField(value = \"create_user_id\", fill = FieldFill.INSERT)\n    private Long createUserId;\n\n    /**\n     * 修改人\n     */\n    @TableField(value = \"update_user_id\", fill = FieldFill.INSERT_UPDATE)\n    private Long updateUserId;\n\n}\n', '', NULL, '2025-05-16 16:16:05', '2025-08-14 17:16:22', 0);
INSERT INTO `gen_template` VALUES (191, 29, 569, 'PageQuery.ftl', 'PageQuery.java', 1, '分页查询参数', 'package ${projectPackage}.${projectNameDot}.common.domain.query;\n\nimport com.baomidou.mybatisplus.core.metadata.IPage;\nimport com.baomidou.mybatisplus.core.metadata.OrderItem;\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.AccessLevel;\nimport lombok.Data;\nimport lombok.Getter;\nimport lombok.Setter;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.List;\n\n/**\n * 分页查询参数基类，分页查询入参和返回基类\n *\n * @param <T> 必须是Entity或者是VO\n */\n@Data\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"分页查询参数基类\")\n</#if>  \npublic class PageQuery<T> implements IPage<T>, Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 2101820826443930585L;\n\n    /**\n     * 当前页码\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"当前页码\", defaultValue = \"1\")\n    </#if>  \n    private Long pageNum = 1L;\n\n    /**\n     * 每页大小\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"每页大小\", defaultValue = \"10\")\n    </#if>  \n    private Long pageSize = 10L;\n\n    /**\n     * 排序字段列表\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"排序字段列表\")\n    </#if>  \n    private List<OrderItemQuery> orderItemList = OrderItemQuery.descs(\"updateTime\", \"id\");\n\n    /**\n     * 分页数据\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"分页数据\", hidden = true)\n    </#if>  \n    private List<T> records;\n\n    /**\n     * 记录总数\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"记录总数\", hidden = true)\n    </#if>  \n    private long total;\n\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(hidden = true)\n    </#if>  \n    private Long size;\n\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(hidden = true)\n    </#if>  \n    private Long current;\n\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(hidden = true)\n    </#if>  \n    @Getter(AccessLevel.NONE)\n    @Setter(AccessLevel.NONE)\n    private Long pages;\n\n    @Override\n    public long getSize() {\n        return this.pageSize;\n    }\n\n    @Override\n    public IPage<T> setSize(long size) {\n        this.pageSize = size;\n        return this;\n    }\n\n    @Override\n    public long getCurrent() {\n        return pageNum;\n    }\n\n    @Override\n    public IPage<T> setCurrent(long current) {\n        this.pageSize = current;\n        return this;\n    }\n\n    @Override\n    public List<T> getRecords() {\n        return this.records;\n    }\n\n    @Override\n    public PageQuery<T> setRecords(List<T> records) {\n        this.records = records;\n        return this;\n    }\n\n    @Override\n    public long getTotal() {\n        return this.total;\n    }\n\n    @Override\n    public PageQuery<T> setTotal(long total) {\n        this.total = total;\n        return this;\n    }\n\n    @Override\n    public List<OrderItem> orders() {\n        //返回空数组，让框架不做排序处理\n        return List.of();\n    }\n\n}\n', '', NULL, '2025-05-16 16:17:35', '2025-12-29 14:31:18', 0);
INSERT INTO `gen_template` VALUES (192, 29, 571, 'BaseUserVO.ftl', 'BaseUserVO.java', 1, '响应基类（包含用户信息）', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\n/**\n * Controller返回值数据基类（包含用户相关信息）\n * <p>自定义VO类继承该类即可</p>\n */\n@Data\n@EqualsAndHashCode(callSuper = true)\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"数据VO基类（包含用户相关信息）\")\n</#if>  \npublic abstract class BaseUserVO extends BaseVO implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = -5814569213714989166L;\n\n    /**\n     * 创建人ID\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"创建人ID\")\n    </#if>  \n    private Long createUserId;\n\n    /**\n     * 创建人\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"创建人\")\n    </#if>  \n    private String createUser;\n\n    /**\n     * 修改人ID\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"修改人ID\")\n    </#if>  \n    private Long updateUserId;\n\n    /**\n     * 修改人\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"修改人\")\n    </#if>  \n    private String updateUser;\n\n}', '', NULL, '2025-05-16 16:21:17', '2025-12-29 14:32:27', 0);
INSERT INTO `gen_template` VALUES (193, 29, 571, 'BaseVO.ftl', 'BaseVO.java', 1, '响应基类', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * Controller返回值数据基类\n * <p>自定义VO类继承该类即可</p>\n */\n@Data\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"数据VO基类\")\n</#if>  \npublic abstract class BaseVO implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = -5814569213714989166L;\n\n    /**\n     * 创建时间\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"创建时间\")\n    </#if>    \n    private Date createTime;\n\n    /**\n     * 修改时间\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"修改时间\")\n    </#if>\n    private Date updateTime;\n\n    /**\n     * 是否删除（0正常, 1删除）\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"是否删除（0正常, 1删除）\")\n    </#if>  \n    private Integer isDelete;\n\n}', '', NULL, '2025-05-16 16:22:09', '2025-12-29 14:33:29', 0);
INSERT INTO `gen_template` VALUES (194, 29, 571, 'PageVO.ftl', 'PageVO.java', 1, '分页响应参数', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.Data;\nimport lombok.NoArgsConstructor;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.List;\n\n/**\n * 分页数据封装\n *\n * @param <T> 必须是VO\n */\n@Data\n@NoArgsConstructor\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"分页数据封装\")\n</#if>  \npublic class PageVO<T> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 3563028771440196184L;\n\n    /**\n     * 当前页码\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"当前页码\")\n    </#if>  \n    private Long pageNum;\n\n    /**\n     * 每页显示条数\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"每页显示条数\")\n    </#if>  \n    private Long pageSize;\n\n    /**\n     * 分页数据\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"分页数据\")\n    </#if>  \n    private List<T> records;\n\n    /**\n     * 总记录数\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"总记录数\")\n    </#if>  \n    private Long total;\n\n    /**\n     * 将其余VO分页数据转换成PageVO分页数据\n     */\n    public PageVO(PageQuery<T> pageQuery) {\n        this.pageNum = pageQuery.getPageNum();\n        this.pageSize = pageQuery.getPageSize();\n        this.records = pageQuery.getRecords();\n        this.total = pageQuery.getTotal();\n    }\n\n    /**\n     * 转成成分页数据通过全量参数\n     *\n     * @param records 已经分页后的list\n     */\n    public PageVO(Long pageNum, Long pageSize, Long total, List<T> records) {\n        this.pageNum = pageNum;\n        this.pageSize = pageSize;\n        this.total = total;\n        this.records = records;\n    }\n\n    /**\n     * 转换成分页数据，手动分页\n     *\n     * @param records 分页前的数据\n     */\n    public PageVO(Long pageNum, Long pageSize, List<T> records) {\n        this.pageNum = pageNum;\n        this.pageSize = pageSize;\n        this.total = (long) records.size();\n        this.records = records.stream()\n                .skip((pageNum - 1) * pageSize)\n                .limit(pageSize)\n                .toList();\n    }\n\n}\n', '', NULL, '2025-05-16 16:23:22', '2025-12-29 14:34:58', 0);
INSERT INTO `gen_template` VALUES (195, 29, 575, 'BusinessException.ftl', 'BusinessException.java', 1, '异常类', 'package ${projectPackage}.${projectNameDot}.common.exception;\n\nimport ${projectPackage}.${projectNameDot}.common.response.IResultError;\nimport cn.hutool.v7.core.text.StrUtil;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\nimport java.io.Serial;\n\n/**\n * 自定义业务异常\n */\n@Data\n@EqualsAndHashCode(callSuper = true)\npublic class BusinessException extends RuntimeException implements IException {\n\n    @Serial\n    private static final long serialVersionUID = -2779970368178204678L;\n\n    /**\n     * 错误码\n     */\n    private final Integer code;\n\n    /**\n     * 错误信息\n     */\n    private final String message;\n\n    public BusinessException(IResultError resultError, Object... objects) {\n        super(StrUtil.format(resultError.getMessage(), objects));\n        this.code = resultError.getCode();\n        this.message = StrUtil.format(resultError.getMessage(), objects);\n    }\n\n    public BusinessException(IResultError resultError, Throwable cause, Object... objects) {\n        super(StrUtil.format(resultError.getMessage(), objects), cause);\n        this.code = resultError.getCode();\n        this.message = StrUtil.format(resultError.getMessage(), objects);\n    }\n\n    public BusinessException(String msg, Object... objects) {\n        super(StrUtil.format(msg, objects));\n        this.code = 500;\n        this.message = StrUtil.format(msg, objects);\n    }\n\n    public BusinessException(Integer code, String msg, Object... objects) {\n        super(StrUtil.format(msg, objects));\n        this.code = code;\n        this.message = StrUtil.format(msg, objects);\n    }\n\n    public BusinessException(Integer code, String msg, Throwable cause, Object... objects) {\n        super(StrUtil.format(msg, objects), cause);\n        this.code = code;\n        this.message = StrUtil.format(msg, objects);\n    }\n\n}\n', '', NULL, '2025-05-16 16:25:10', '2025-10-30 11:15:02', 0);
INSERT INTO `gen_template` VALUES (196, 29, 575, 'GlobalExceptionHandler.ftl', 'GlobalExceptionHandler.java', 1, '通用异常处理器', 'package ${projectPackage}.${projectNameDot}.common.exception;\n\nimport ${projectPackage}.${projectNameDot}.common.response.Result;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.validation.ConstraintViolation;\nimport jakarta.validation.ConstraintViolationException;\nimport jakarta.validation.ValidationException;\nimport lombok.extern.slf4j.Slf4j;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.http.converter.HttpMessageNotReadableException;\nimport org.springframework.validation.BindException;\nimport org.springframework.web.HttpRequestMethodNotSupportedException;\nimport org.springframework.web.bind.*;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\nimport org.springframework.web.method.HandlerMethod;\nimport org.springframework.web.multipart.MaxUploadSizeExceededException;\nimport org.springframework.web.servlet.resource.NoResourceFoundException;\n\nimport java.util.Set;\nimport java.util.StringJoiner;\n\nimport static ${projectPackage}.${projectNameDot}.common.response.Result.fail;\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.*;\n\n/**\n * 通用异常处理\n */\n@Slf4j\n@RestControllerAdvice\n@ConditionalOnProperty(name = \"web.exception.enable\", havingValue = \"true\", matchIfMissing = true)\npublic class GlobalExceptionHandler {\n\n    @Autowired\n    private HttpServletRequest request;\n\n    /**\n     * 获取业务异常\n     */\n    @ExceptionHandler(BusinessException.class)\n    public Result<Void> businessException(BusinessException exception,\n                                          HandlerMethod handlerMethod) {\n        log.error(\"业务处理不成功, 请求方式: {}, 请求uri: {}, 请求方法: {}, 异常code: {}, 异常message: {}\",\n                request.getMethod(), request.getRequestURI(), handlerMethod.getMethod().getName(), exception.getCode(), exception.getMessage(), exception);\n        return fail(exception);\n    }\n\n    /**\n     * 捕获异常\n     */\n    @ExceptionHandler(Exception.class)\n    public Result<Void> serverException(Exception exception) {\n        log.error(\"服务处理不成功, 请求方式: {}, 请求uri: {}, 异常message: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(INTERNAL_SERVER_ERROR);\n    }\n\n    /**\n     * 捕获运行时异常\n     */\n    @ExceptionHandler(RuntimeException.class)\n    public Result<Void> runtimeException(RuntimeException exception) {\n        log.error(\"服务处理不成功, 请求方式: {}, 请求uri: {}, 发生运行时异常, 异常message: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(INTERNAL_SERVER_ERROR);\n    }\n\n    /**\n     * 捕获字段校验异常\n     */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    public Result<Void> methodArgumentNotValidException(MethodArgumentNotValidException exception) {\n        StringJoiner stringJoiner = new StringJoiner(\";\");\n        exception.getBindingResult().getFieldErrors().forEach(fieldError -> stringJoiner.add(fieldError.getDefaultMessage()));\n        log.error(\"字段校验不通过, 请求方式: {}, 请求uri: {}, 字段校验异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), stringJoiner, exception);\n        return fail(PARAM_ERR);\n    }\n\n    /**\n     * 捕获参数校验异常\n     */\n    @ExceptionHandler(ValidationException.class)\n    public Result<Void> validationException(ValidationException exception) {\n        log.error(\"参数校验不通过, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(PARAM_ERR);\n    }\n\n    /**\n     * 捕获字段校验异常\n     */\n    @ExceptionHandler(ConstraintViolationException.class)\n    public Result<Void> constraintViolationException(ConstraintViolationException exception) {\n        Set<ConstraintViolation<?>> constraintViolations = exception.getConstraintViolations();\n        StringJoiner stringJoiner = new StringJoiner(\";\");\n        constraintViolations.forEach(temp -> stringJoiner.add(temp.getMessage()));\n        log.error(\"参数校验不通过, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), stringJoiner, exception);\n        return fail(PARAM_ERR);\n    }\n\n    /**\n     * 捕获参数绑定异常\n     */\n    @ExceptionHandler(BindException.class)\n    public Result<Void> bindException(BindException exception) {\n        StringJoiner stringJoiner = new StringJoiner(\";\");\n        exception.getBindingResult().getFieldErrors().forEach(fieldError -> stringJoiner.add(fieldError.getDefaultMessage()));\n        log.error(\"参数绑定不通过, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), stringJoiner, exception);\n        return fail(PARAM_ERR);\n    }\n\n    /**\n     * 捕获请求方式不支持异常\n     */\n    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)\n    public Result<Void> httpRequestMethodNotSupportedException(HttpRequestMethodNotSupportedException exception) {\n        log.error(\"请求方法不支持, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(METHOD_NOT_ALLOWED);\n    }\n\n    /**\n     * 捕获cookie参数丢失\n     */\n    @ExceptionHandler(MissingRequestCookieException.class)\n    public Result<Void> handleMissingRequestCookieException(MissingRequestCookieException exception) {\n        log.error(\"请求cookie缺失, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(COOKIE_LOST);\n    }\n\n    /**\n     * 捕获缺失请求头异常\n     */\n    @ExceptionHandler(MissingRequestHeaderException.class)\n    public Result<Void> handleMissingRequestHeaderException(MissingRequestHeaderException exception) {\n        log.error(\"请求头缺失, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(HEADER_LOST);\n    }\n\n    /**\n     * 捕获路径参数丢失异常\n     */\n    @ExceptionHandler(MissingPathVariableException.class)\n    public Result<Void> handleMissingPathVariableException(MissingPathVariableException exception) {\n        log.error(\"路径参数缺失, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(PATH_LOST);\n    }\n\n    /**\n     * 捕获参数缺失异常\n     */\n    @ExceptionHandler(MissingServletRequestParameterException.class)\n    public Result<Void> handleMissingServletRequestParameterException(MissingServletRequestParameterException exception) {\n        log.error(\"请求参数缺失, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(PARAM_LOST);\n    }\n\n    /**\n     * 捕获文件太大异常\n     */\n    @ExceptionHandler(MaxUploadSizeExceededException.class)\n    public Result<Void> handleMaxUploadSizeExceededException(MaxUploadSizeExceededException exception) {\n        log.error(\"上传文件大小超出限制, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(FILE_TOO_LARGE);\n    }\n\n    /**\n     * 捕获资源不存在异常\n     */\n    @ExceptionHandler(NoResourceFoundException.class)\n    public Result<Void> noResourceFoundException(NoResourceFoundException exception) {\n        log.error(\"请求资源不存在, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(NOT_FOUND);\n    }\n\n    /**\n     * 捕获请求参数解析异常\n     */\n    @ExceptionHandler(HttpMessageNotReadableException.class)\n    public Result<Void> handleHttpMessageNotReadableException(HttpMessageNotReadableException exception) {\n        log.error(\"请求参数解析失败, 请求方式: {}, 请求uri: {}, 异常信息: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(REQUEST_ERR.getCode(), exception.getMessage());\n    }\n\n}\n', '', NULL, '2025-05-16 16:26:18', '2025-08-14 15:15:36', 0);
INSERT INTO `gen_template` VALUES (197, 29, 575, 'IException.ftl', 'IException.java', 1, '异常接口', 'package ${projectPackage}.${projectNameDot}.common.exception;\n\n/**\n * 异常信息接口，设置CODE和异常信息\n */\npublic interface IException {\n\n    /**\n     * 获取异常码\n     */\n    Integer getCode();\n\n    /**\n     * 获取异常信息\n     */\n    String getMessage();\n\n}\n', NULL, NULL, '2025-05-16 16:27:15', '2025-12-25 16:11:05', 0);
INSERT INTO `gen_template` VALUES (198, 29, 579, 'BaseMapstruct.ftl', 'BaseMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\n/**\n * Mapstruct转换基类，提供Entity、VO、DTO之间基本的转换\n * <p>适用于Entity、VO、DTO都存在的情况</p>\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n */\npublic interface BaseMapstruct<E, V, D> extends DTOToEntityMapstruct<D, E>, PageEntityMapstruct<E, V>, PageVOMapstruct<V> {\n}\n', NULL, NULL, '2025-05-16 16:35:10', '2025-10-30 11:13:19', 0);
INSERT INTO `gen_template` VALUES (199, 29, 579, 'BaseNoDTOMapstruct.ftl', 'BaseNoDTOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\n/**\n * Mapstruct转换基类，提供Entity和VO之间基本的转换\n * <p>适用于DTO不存在的情况，但是有分页的情况</p>\n * <p>例如系统日志表，它的数据是程序内部自己生成的，并不是外界传入</p>\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface BaseNoDTOMapstruct<E, V> extends PageEntityMapstruct<E, V>, PageVOMapstruct<V> {\n}\n', NULL, NULL, '2025-05-16 16:35:57', '2025-10-30 11:15:28', 0);
INSERT INTO `gen_template` VALUES (200, 29, 579, 'BaseNoPageMapstruct.ftl', 'BaseNoPageMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\n/**\n * Mapstruct转换基类，提供Entity、VO、DTO之间基本的转换\n * <p>适用于Entity、VO、DTO都存在的情况，但是不需要分页</p>\n * <p>例如系统内置字典表。可能就10条数据</p>\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n */\npublic interface BaseNoPageMapstruct<E, V, D> extends DTOToEntityMapstruct<D, E>, EntityToVOMapstruct<E, V> {\n}\n', NULL, NULL, '2025-05-16 16:36:46', '2025-10-30 11:15:28', 0);
INSERT INTO `gen_template` VALUES (201, 29, 579, 'DTOToEntityMapstruct.ftl', 'DTOToEntityMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport cn.hutool.v7.core.collection.CollUtil;\n\nimport java.util.List;\n\n/**\n * 将DTO转换成Entity的通用接口\n *\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n * @param <E> entity实体类泛型（数据库实体类）\n */\npublic interface DTOToEntityMapstruct<D, E> {\n\n    /**\n     * 将DTO转换成Entity\n     */\n    E dtoToEntity(D dto);\n\n    /**\n     * 将DTO列表转换为Entity列表\n     */\n    default List<E> dtoToEntity(List<D> dtoList) {\n        if (CollUtil.isEmpty(dtoList)) {\n            return List.of();\n        }\n        return dtoList.stream().map(this::dtoToEntity).toList();\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:37:38', '2025-10-30 11:17:50', 0);
INSERT INTO `gen_template` VALUES (202, 29, 579, 'EntityToDTOMapstruct.ftl', 'EntityToDTOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport cn.hutool.v7.core.collection.CollUtil;\n\nimport java.util.List;\n\n/**\n * 将Entity转换成DTO的通用接口\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n */\npublic interface EntityToDTOMapstruct<E, D> {\n\n    /**\n     * 将Entity转换成DTO\n     */\n    D entityToDTO(E entity);\n\n    /**\n     * 将DTO列表转换为Entity列表\n     */\n    default List<D> entityToDTO(List<E> entityList) {\n        if (CollUtil.isEmpty(entityList)) {\n            return List.of();\n        }\n        return entityList.stream().map(this::entityToDTO).toList();\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:38:36', '2025-10-30 11:17:51', 0);
INSERT INTO `gen_template` VALUES (203, 29, 579, 'EntityToVOMapstruct.ftl', 'EntityToVOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport cn.hutool.v7.core.collection.CollUtil;\n\nimport java.util.List;\n\n/**\n * 将Entity转换成VO的通用接口\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface EntityToVOMapstruct<E, V> {\n\n    /**\n     * 将Entity转换成VO\n     */\n    V entityToVO(E entity);\n\n    /**\n     * 将Entity列表转换成VO列表\n     */\n    default List<V> entityToVO(List<E> entityList) {\n        if (CollUtil.isEmpty(entityList)) {\n            return List.of();\n        }\n        return entityList.stream().map(this::entityToVO).toList();\n    }\n\n}', NULL, NULL, '2025-05-16 16:39:19', '2025-10-30 11:17:51', 0);
INSERT INTO `gen_template` VALUES (204, 29, 579, 'PageEntityMapstruct.ftl', 'PageEntityMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\n\nimport java.util.List;\n\n/**\n * 将Entity分页数据转换为VO分页数据的通用接口\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface PageEntityMapstruct<E, V> extends EntityToVOMapstruct<E, V> {\n\n    /**\n     * 将Entity分页数据转换为VO分页数据\n     */\n    default PageVO<V> entityToPageVO(PageQuery<E> entityPageQuery) {\n        Long pageNum = entityPageQuery.getPageNum();\n        Long pageSize = entityPageQuery.getPageSize();\n        long total = entityPageQuery.getTotal();\n        List<V> voList = this.entityToVO(entityPageQuery.getRecords());\n        return new PageVO<>(pageNum, pageSize, total, voList);\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:39:59', '2025-10-30 11:17:51', 0);
INSERT INTO `gen_template` VALUES (205, 29, 579, 'PageVOMapstruct.ftl', 'PageVOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\n\n/**\n * 将VO分页数据转换为VO分页数据的通用接口\n *\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface PageVOMapstruct<V> extends PageVOOtherMapstruct {\n\n    /**\n     * 将VO分页数据转换成PageVO分页数据\n     */\n    default PageVO<V> voToPageVO(PageQuery<V> voPageQuery) {\n        return toPageVO(voPageQuery);\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:40:45', '2025-10-30 11:17:51', 0);
INSERT INTO `gen_template` VALUES (206, 29, 579, 'PageVOOtherMapstruct.ftl', 'PageVOOtherMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\n\nimport java.util.List;\n\n/**\n * 其余情况下的分页数据转换\n */\npublic interface PageVOOtherMapstruct {\n\n    /**\n     * 将其余VO分页数据转换成PageVO分页数据\n     *\n     * @param <T> 其余VO对象\n     */\n    default <T> PageVO<T> toPageVO(PageQuery<T> voPageQuery) {\n        return new PageVO<>(voPageQuery);\n    }\n\n    /**\n     * 转成成分页数据通过全量参数\n     *\n     * @param records 已经分页后的list\n     */\n    default <T> PageVO<T> toPageVOWithFullParams(Long pageNum, Long pageSize, Long total, List<T> records) {\n        return new PageVO<>(pageNum, pageSize, total, records);\n    }\n\n    /**\n     * 转换成分页数据，手动分页\n     *\n     * @param records 分页前的数据\n     */\n    default <T> PageVO<T> toPageVOWithPagination(Long pageNum, Long pageSize, List<T> records) {\n        return new PageVO<>(pageNum, pageSize, records);\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:41:30', '2025-10-30 11:17:51', 0);
INSERT INTO `gen_template` VALUES (207, 29, 579, 'VOToEntityMapstruct.ftl', 'VOToEntityMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport cn.hutool.v7.core.collection.CollUtil;\n\nimport java.util.List;\n\n/**\n * 将VO转换成Entity的通用接口\n *\n * @param <V> vo实体类泛型（controller返回参数）\n * @param <E> entity实体类泛型（数据库实体类）\n */\npublic interface VOToEntityMapstruct<V, E> {\n\n    /**\n     * 将VO转换成Entity\n     */\n    E voToEntity(V vo);\n\n    /**\n     * 将Entity列表转换成VO列表\n     */\n    default List<E> voToEntity(List<V> voList) {\n        if (CollUtil.isEmpty(voList)) {\n            return List.of();\n        }\n        return voList.stream().map(this::voToEntity).toList();\n    }\n\n}', NULL, NULL, '2025-05-16 16:42:18', '2025-10-30 11:17:51', 0);
INSERT INTO `gen_template` VALUES (208, 29, 591, 'CommonMetaObjectHandler.ftl', 'CommonMetaObjectHandler.java', 1, 'mybatis-plus数据填充配置类', 'package ${projectPackage}.${projectNameDot}.common.mybatis.config;\n\nimport com.baomidou.mybatisplus.core.handlers.MetaObjectHandler;\nimport org.apache.ibatis.reflection.MetaObject;\n\nimport java.util.Date;\n\n/**\n * 填充公共字段\n */\npublic class CommonMetaObjectHandler implements MetaObjectHandler {\n\n    @Override\n    public void insertFill(MetaObject metaObject) {\n        //插入的时候设置添加和修改时间的值\n        this.setFieldValByName(\"createTime\", new Date(), metaObject);\n        this.setFieldValByName(\"updateTime\", new Date(), metaObject);\n        this.setFieldValByName(\"isDelete\", 0, metaObject);\n    }\n\n    @Override\n    public void updateFill(MetaObject metaObject) {\n        //更新的时候设置修改时间的值\n        this.setFieldValByName(\"updateTime\", new Date(), metaObject);\n    }\n\n}\n', '', NULL, '2025-05-16 16:44:04', '2025-09-22 14:55:00', 0);
INSERT INTO `gen_template` VALUES (209, 29, 591, 'MybatisPlusConfig.ftl', 'MybatisPlusConfig.java', 1, 'mybatis-plus配置类', 'package ${projectPackage}.${projectNameDot}.common.mybatis.config;\n\nimport com.baomidou.mybatisplus.annotation.DbType;\nimport com.baomidou.mybatisplus.core.handlers.MetaObjectHandler;\nimport com.baomidou.mybatisplus.extension.plugins.MybatisPlusInterceptor;\nimport com.baomidou.mybatisplus.extension.plugins.inner.PaginationInnerInterceptor;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/**\n * mybatis-plus配置类\n */\n@Configuration\npublic class MybatisPlusConfig {\n\n    /**\n     * 添加分页插件\n     */\n    @Bean\n    public MybatisPlusInterceptor mybatisPlusInterceptor() {\n        MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor();\n        //如果配置多个插件, 切记分页最后添加\n        interceptor.addInnerInterceptor(new PaginationInnerInterceptor(DbType.MYSQL));\n        return interceptor;\n    }\n\n    /**\n     * 自动填充部分数据（createTime、updateTime、isDelete）\n     */\n    @Bean\n    public MetaObjectHandler metaObjectHandler() {\n        return new CommonMetaObjectHandler();\n    }\n\n}\n', '', NULL, '2025-05-16 16:45:02', '2025-08-14 15:16:11', 0);
INSERT INTO `gen_template` VALUES (210, 29, 594, 'BaseMapperPlus.ftl', 'BaseMapperPlus.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mybatis.mapper;\n\nimport com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;\nimport com.baomidou.mybatisplus.core.mapper.BaseMapper;\nimport com.baomidou.mybatisplus.extension.toolkit.Db;\n\nimport java.util.Collection;\nimport java.util.List;\n\n/**\n * 自定义Mapper接口, 实现自定义扩展\n *\n * @param <T> Entity泛型\n */\npublic interface BaseMapperPlus<T> extends BaseMapper<T> {\n\n    /**\n     * 使用默认的查询条件查询并返回结果列表\n     *\n     * @return 返回查询结果的列表\n     */\n    default List<T> selectList() {\n        return this.selectList(new QueryWrapper<>());\n    }\n\n    /**\n     * 批量插入实体对象集合\n     *\n     * @param entityList 实体对象集合\n     * @return 插入操作是否成功的布尔值\n     */\n    default boolean insertBatch(Collection<T> entityList) {\n        return Db.saveBatch(entityList);\n    }\n\n    /**\n     * 批量插入实体对象集合并指定批处理大小\n     *\n     * @param entityList 实体对象集合\n     * @param batchSize  批处理大小\n     * @return 插入操作是否成功的布尔值\n     */\n    default boolean insertBatch(Collection<T> entityList, int batchSize) {\n        return Db.saveBatch(entityList, batchSize);\n    }\n\n    /**\n     * 批量根据ID更新实体对象集合\n     *\n     * @param entityList 实体对象集合\n     * @return 更新操作是否成功的布尔值\n     */\n    default boolean updateBatchById(Collection<T> entityList) {\n        return Db.updateBatchById(entityList);\n    }\n\n    /**\n     * 批量根据ID更新实体对象集合并指定批处理大小\n     *\n     * @param entityList 实体对象集合\n     * @param batchSize  批处理大小\n     * @return 更新操作是否成功的布尔值\n     */\n    default boolean updateBatchById(Collection<T> entityList, int batchSize) {\n        return Db.updateBatchById(entityList, batchSize);\n    }\n\n    /**\n     * 批量插入或更新实体对象集合\n     *\n     * @param entityList 实体对象集合\n     * @return 插入或更新操作是否成功的布尔值\n     */\n    default boolean insertOrUpdateBatch(Collection<T> entityList) {\n        return Db.saveOrUpdateBatch(entityList);\n    }\n\n    /**\n     * 批量插入或更新实体对象集合并指定批处理大小\n     *\n     * @param entityList 实体对象集合\n     * @param batchSize  批处理大小\n     * @return 插入或更新操作是否成功的布尔值\n     */\n    default boolean insertOrUpdateBatch(Collection<T> entityList, int batchSize) {\n        return Db.saveOrUpdateBatch(entityList, batchSize);\n    }\n\n}', NULL, NULL, '2025-05-16 16:46:08', '2025-08-13 15:50:23', 0);
INSERT INTO `gen_template` VALUES (211, 29, 596, 'MybatisUtil.ftl', 'MybatisUtil.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mybatis.util;\n\nimport cn.hutool.v7.core.bean.BeanUtil;\nimport cn.hutool.v7.core.collection.CollUtil;\nimport cn.hutool.v7.core.func.LambdaFactory;\nimport cn.hutool.v7.core.reflect.FieldUtil;\nimport cn.hutool.v7.core.reflect.method.MethodInvoker;\nimport cn.hutool.v7.core.text.NamingCase;\nimport cn.hutool.v7.core.text.StrUtil;\nimport cn.hutool.v7.core.util.ObjUtil;\nimport com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;\nimport com.baomidou.mybatisplus.core.toolkit.support.SFunction;\nimport ${projectPackage}.${projectNameDot}.common.domain.query.OrderItemQuery;\nimport lombok.experimental.UtilityClass;\nimport lombok.extern.slf4j.Slf4j;\n\nimport java.util.List;\n\n/**\n * mybatis工具类\n */\n@Slf4j\n@UtilityClass\npublic class MybatisUtil {\n\n    /**\n     * 设置排序字段\n     */\n    public static <T> void orderBy(LambdaQueryWrapper<T> wrapper, List<OrderItemQuery> orderItemList) {\n        if (CollUtil.isEmpty(orderItemList)) {\n            return;\n        }\n        if (wrapper == null) {\n            throw new IllegalArgumentException(\"wrapper is null\");\n        }\n        Class<T> entityClass = wrapper.getEntityClass();\n        if (entityClass == null) {\n            throw new IllegalArgumentException(\"entityClass is null\");\n        }\n        orderItemList.forEach(orderItem -> {\n            SFunction<T, ?> column = buildGetter(entityClass, orderItem.getColumn());\n            if (orderItem.getAsc()) {\n                wrapper.orderByAsc(column);\n            } else {\n                wrapper.orderByDesc(column);\n            }\n        });\n    }\n\n    /**\n     * 获取getter方法的lambda表达式\n     */\n    public static <T> SFunction<T, ?> buildGetter(Class<T> clazz, String column) {\n        if (clazz == null) {\n            throw new IllegalArgumentException(\"clazz is null\");\n        }\n        if (StrUtil.isBlank(column)) {\n            throw new IllegalArgumentException(\"column is blank\");\n        }\n        //获取字段对应的getter方法\n        MethodInvoker getter = (MethodInvoker) BeanUtil.getBeanDesc(clazz).getGetter(column);\n        if (getter == null) {\n            throw new IllegalArgumentException(StrUtil.format(\"column: {} is not exist\", column));\n        }\n        return LambdaFactory.build(SFunction.class, getter.getMethod());\n    }\n\n    /**\n     * 判断对象不为空\n     */\n    public static boolean isNotEmpty(Object object) {\n        // 如果是字符串，则去除首尾空格\n        if (object instanceof CharSequence) {\n            object = StrUtil.trim((CharSequence) object);\n        }\n\n        return ObjUtil.isNotEmpty(object);\n    }\n\n    /**\n     * 判断对象中某个字段不为空\n     */\n    public static boolean isNotEmpty(Object object, String propertyName) {\n        if (object == null) {\n            log.warn(\"object is null\");\n            return false;\n        }\n        if (StrUtil.isBlank(propertyName)) {\n            log.warn(\"propertyName is null or blank\");\n            return false;\n        }\n        boolean hasField = FieldUtil.hasField(object.getClass(), propertyName);\n        if (!hasField) {\n            return false;\n        }\n        Object fieldValue = FieldUtil.getFieldValue(object, propertyName);\n\n        return isNotEmpty(fieldValue);\n    }\n\n    /**\n     * 小驼峰转下划线\n     */\n    public static String toUnderlineCase(String str) {\n        return NamingCase.toUnderlineCase(str);\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:47:01', '2025-10-30 11:19:47', 0);
INSERT INTO `gen_template` VALUES (212, 29, 598, 'IgnoreResult.ftl', 'IgnoreResult.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport java.lang.annotation.*;\n\n/**\n * 方法加上这个注解代表无需自动封装 {@link Result} 返回值\n */\n@Documented\n@Target({ElementType.METHOD, ElementType.TYPE})\n@Retention(RetentionPolicy.RUNTIME)\npublic @interface IgnoreResult {\n}\n', NULL, NULL, '2025-05-16 16:48:12', '2025-10-30 13:52:16', 0);
INSERT INTO `gen_template` VALUES (213, 29, 598, 'IResultError.ftl', 'IResultError.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\n/**\n * 自定义枚举继承该接口\n */\npublic interface IResultError {\n\n    /**\n     * 错误码\n     */\n    Integer getCode();\n\n    /**\n     * 错误信息\n     */\n    String getMessage();\n\n}\n', NULL, NULL, '2025-05-16 16:48:57', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (214, 29, 598, 'Result.ftl', 'Result.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport ${projectPackage}.${projectNameDot}.common.exception.BusinessException;\nimport ${projectPackage}.${projectNameDot}.common.exception.IException;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.INTERNAL_SERVER_ERROR;\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.SUCCESS;\n\n/**\n * 统一返回的响应封装结果\n */\n@Data\npublic class Result<T> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 3782047511903624813L;\n\n    /**\n     * 返回状态码\n     */\n    private Integer code;\n\n    /**\n     * 返回信息\n     */\n    private String message;\n\n    /**\n     * 返回的数据\n     */\n    private T data;\n\n    /**\n     * 无参\n     */\n    public static <T> Result<T> success() {\n        Result<T> result = new Result<>();\n        result.setCode(SUCCESS.getCode());\n        result.setMessage(SUCCESS.getMessage());\n        return result;\n    }\n\n    /**\n     * 一个参数\n     */\n    public static <T> Result<T> success(T data) {\n        Result<T> result = success();\n        result.setData(data);\n        return result;\n    }\n\n    /**\n     * 两个参数\n     *\n     * @param message\n     * @param data\n     * @param <T>\n     * @return\n     */\n    public static <T> Result<T> success(String message, T data) {\n        Result<T> result = success(data);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 服务稳定-两个参数\n     *\n     * @param code\n     * @param message\n     * @param <T>\n     * @return\n     */\n    public static <T> Result<T> build(Integer code, String message) {\n        Result<T> result = new Result<>();\n        result.setCode(code);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 三个参数\n     *\n     * @param code\n     * @param message\n     * @param data\n     * @param <T>\n     * @return\n     */\n    public static <T> Result<T> build(Integer code, String message, T data) {\n        Result<T> result = build(code, message);\n        result.setData(data);\n        return result;\n    }\n\n\n    /**\n     * 服务异常时的响应 -无参\n     */\n    public static <T> Result<T> fail() {\n        Result<T> result = new Result<>();\n        result.setCode(INTERNAL_SERVER_ERROR.getCode());\n        result.setMessage(INTERNAL_SERVER_ERROR.getMessage());\n        return result;\n    }\n\n    /**\n     * 服务异常时的响应 -一个参数\n     */\n    public static <T> Result<T> fail(T data) {\n        Result<T> result = fail();\n        result.setData(data);\n        return result;\n    }\n\n    /**\n     * 服务异常时的响应 -两个参数\n     */\n    public static <T> Result<T> fail(String message, T data) {\n        Result<T> result = fail(data);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 异常信息处理\n     */\n    public static <T> Result<T> fail(String message) {\n        Result<T> result = fail();\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 服务异常时的响应 -两个参数\n     */\n    public static <T> Result<T> fail(Integer code, String message) {\n        Result<T> result = fail();\n        result.setCode(code);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 返回异常\n     */\n    public static <T> Result<T> fail(BusinessException businessException) {\n        return fail(businessException.getCode(), businessException.getMessage());\n    }\n\n    /**\n     * 返回异常\n     */\n    public static <T> Result<T> fail(IException exception) {\n        Result<T> result = new Result<>();\n        result.setCode(exception.getCode());\n        result.setMessage(exception.getMessage());\n        return result;\n    }\n\n    /**\n     * 返回异常枚举\n     */\n    public static <T> Result<T> fail(IResultError error) {\n        return fail(error.getCode(), error.getMessage());\n    }\n\n    /**\n     * 服务异常时的响应 -三个参数\n     */\n    public static <T> Result<T> fail(Integer code, String message, T data) {\n        Result<T> result = fail(message, data);\n        result.setCode(code);\n        return result;\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:49:43', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (215, 29, 598, 'ResultAdvice.ftl', 'ResultAdvice.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport cn.hutool.v7.core.collection.CollUtil;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport lombok.SneakyThrows;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.core.MethodParameter;\nimport org.springframework.core.annotation.AnnotationUtils;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.converter.HttpMessageConverter;\nimport org.springframework.http.server.ServerHttpRequest;\nimport org.springframework.http.server.ServerHttpResponse;\nimport org.springframework.web.bind.annotation.RestController;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\nimport org.springframework.web.servlet.mvc.method.annotation.ResponseBodyAdvice;\n\nimport java.lang.reflect.Method;\nimport java.util.List;\n\n/**\n * 对RestController返回值统一处理\n */\n@RestControllerAdvice(annotations = RestController.class)\n@ConditionalOnProperty(name = \"web.response.enable\", havingValue = \"true\", matchIfMissing = true)\npublic class ResultAdvice implements ResponseBodyAdvice<Object> {\n\n    @Autowired\n    private ObjectMapper objectMapper;\n\n    /**\n     * 不需要增强的类名，有默认值，主要是swagger等的类\n     */\n    @Value(\"<#noparse>#{\'${web.response.exclude-list:swagger,springfox,springdoc}\'.split(\',\')}</#noparse>\")\n    private List<String> excludeNameList;\n\n    @Override\n    public boolean supports(MethodParameter returnType, Class<? extends HttpMessageConverter<?>> converterType) {\n        //类上有IgnoreResult注解的，不增强\n        IgnoreResult annotation = AnnotationUtils.findAnnotation(returnType.getDeclaringClass(), IgnoreResult.class);\n        if (annotation != null) {\n            return false;\n        }\n\n        //方法上有IgnoreResult注解的，不增强\n        annotation = AnnotationUtils.findAnnotation(returnType.getAnnotatedElement(), IgnoreResult.class);\n        if (annotation != null) {\n            return false;\n        }\n        Method method = returnType.getMethod();\n        //如果类名包含swagger等，不处理\n        if (method != null && CollUtil.isNotEmpty(excludeNameList)) {\n            String name = method.getDeclaringClass().getName();\n            for (String excludeName : excludeNameList) {\n                if (name.contains(excludeName)) {\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n\n    @Override\n    @SneakyThrows\n    public Object beforeBodyWrite(Object body,\n                                  MethodParameter returnType,\n                                  MediaType selectedContentType,\n                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,\n                                  ServerHttpRequest request,\n                                  ServerHttpResponse response) {\n        //如果返回类型已经是Result则直接返回，否则需要用Result进行返回值包装\n        if (body instanceof Result) {\n            return body;\n        } else if (body instanceof byte[]) {\n            return body;\n        } else {\n            Result<Object> result = Result.success(body);\n            //如果返回值是字符串, 需要特殊处理, 手动变成JSON字符串\n            if (returnType.getParameterType().equals(String.class)) {\n                return objectMapper.writeValueAsString(result);\n            }\n            return result;\n        }\n    }\n\n}\n', NULL, NULL, '2025-05-16 16:50:24', '2025-10-30 13:53:06', 0);
INSERT INTO `gen_template` VALUES (216, 29, 598, 'ResultEnum.ftl', 'ResultEnum.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport lombok.AllArgsConstructor;\nimport lombok.Getter;\n\n/**\n * 响应结果枚举\n */\n@Getter\n@AllArgsConstructor\npublic enum ResultEnum implements IResultError {\n\n    /**\n     * 请求成功\n     */\n    SUCCESS(200, \"success\"),\n\n    /**\n     * 请求参数错误\n     */\n    PARAM_ERR(300, \"request param error\"),\n\n    /**\n     * 请求参数丢失\n     */\n    PARAM_LOST(301, \"request param lost\"),\n\n    /**\n     * 请求头参数丢失\n     */\n    HEADER_LOST(302, \"request header lost\"),\n\n    /**\n     * 路径参数丢失\n     */\n    PATH_LOST(303, \"request path lost\"),\n\n    /**\n     * cookie值丢失\n     */\n    COOKIE_LOST(304, \"request cookie lost\"),\n\n    /**\n     * 客户端错误\n     */\n    REQUEST_ERR(400, \"request error\"),\n\n    /**\n     * 未认证\n     */\n    UNAUTHORIZED(401, \"unauthorized\"),\n\n    /**\n     * 未授权\n     */\n    FORBIDDEN(403, \"forbidden\"),  \n\n    /**\n     * 资源不存在\n     */\n    NOT_FOUND(404, \"not found\"),\n\n    /**\n     * 请求方法不支持\n     */\n    METHOD_NOT_ALLOWED(405, \"this method is not supported\"),\n\n    /**\n     * 服务器错误\n     */\n    INTERNAL_SERVER_ERROR(500, \"internal server error\"),\n\n    /**\n     * 文件太大\n     */\n    FILE_TOO_LARGE(501, \"file too large\"),\n\n    /**\n     * 数据不存在\n     */\n    DATA_NOT_EXIST(1000, \"{}数据{}字段的值已存在\"),\n\n    /**\n     * 数据已经存在\n     */\n    DATA_ALREADY_EXIST(1001, \"{}数据{}字段的值已存在\"),\n\n    /**\n     * 数据不能为空\n     */\n    DATA_NOT_NULL(1002, \"数据不能为空\"),\n    ;\n\n    /**\n     * 请求结果状态码\n     */\n    private final Integer code;\n\n    /**\n     * 请求结果描述信息\n     */\n    private final String message;\n\n}\n', '', NULL, '2025-05-16 16:51:03', '2025-11-14 14:15:13', 0);
