INSERT INTO `gen_template` VALUES (220, 29, 605, 'UpdateGroup.ftl', 'UpdateGroup.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.validation.group;\n\nimport jakarta.validation.groups.Default;\n\n/**\n * 表单校验修改分组\n * <p>默认包含Default</p>\n */\npublic interface UpdateGroup extends Default {\n}\n', NULL, NULL, '2025-05-16 16:54:54', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (221, 31, 700, 'Enum.ftl', '${enumNamePascal}Enum.java', 1, 'java枚举模板', 'package ${projectPackage}.${projectNameDot}.enums;\n\nimport com.baomidou.mybatisplus.annotation.EnumValue;\nimport com.fasterxml.jackson.annotation.JsonValue;\nimport lombok.AllArgsConstructor;\nimport lombok.Getter;\n\n\n/**\n * ${enumDesc}枚举\n */\n@Getter\n@AllArgsConstructor\npublic enum ${enumNamePascal}Enum {\n\n    <#list enumItemList as item >\n    /**\n     * ${item.enumItemDesc}\n     */\n    ${item.enumItemNameAllUpper}(<#if item.enumItemCode?is_string>\"${item.enumItemCode}\"<#else>${item.enumItemCode}</#if>, \"${item.enumItemDesc}\"),\n    <#if item_has_next>\n\n    </#if>\n    </#list>\n    ;\n\n    /**\n     * code值\n     */\n    @JsonValue\n    @EnumValue\n    private final ${enumCodeType} code;\n\n    /**\n     * 描述\n     */\n    private final String description;\n\n}\n', NULL, NULL, '2025-05-19 14:09:42', '2025-09-23 10:15:46', 0);
INSERT INTO `gen_template` VALUES (222, 32, 313, 'enum.ftl', '${enumName}-enum.ts', 1, '枚举模板', 'import { EnumItem } from \'@/utils/enum\'\n\n//${enumDesc}枚举\nconst ${enumNameAllUpper}_ENUM: EnumItem[] = [\n<#list enumItemList as item >\n    {  label: \'${item.enumItemDesc}\', value: <#if item.enumItemCode?is_string>\'${item.enumItemCode}\'<#else>${item.enumItemCode}</#if> }<#if item_has_next>,</#if>\n</#list>\n]\n', NULL, NULL, '2025-05-20 10:23:49', '2025-09-23 09:52:12', 0);
INSERT INTO `gen_template` VALUES (223, 29, 555, 'logback-spring.ftl', 'logback-spring.xml', 1, 'logback文件日志配置', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<configuration>\n\n    <!-- 服务名称 -->\n    <springProperty name=\"APP_NAME\" source=\"spring.application.name\" defaultValue=\"app\" />\n    <!-- 日志格式 -->\n    <springProperty name=\"LOG_PATTERN\" source=\"logging.pattern.console\"\n                    defaultValue=\"%d{yyyy-MM-dd HH:mm:ss.SSS} [%thread] %-5level %logger{36}:%line - %msg%n\"/>\n    <!-- 指定日志输出路径 -->\n    <springProperty name=\"LOG_PATH\" source=\"logging.file.path\" defaultValue=\"./logs\" />\n    <!-- 日志文件最大大小 -->\n    <springProperty name=\"MAX_FILE_SIZE\" source=\"logging.max-file-size\" defaultValue=\"200MB\" />\n    <!-- 日志保留天数 -->\n    <springProperty name=\"MAX_HISTORY\" source=\"logging.max-history\" defaultValue=\"30\" />\n\n    <!-- 输出到控制台 -->\n    <appender name=\"CONSOLE\" class=\"ch.qos.logback.core.ConsoleAppender\">\n        <encoder>\n            <Pattern><#noparse>${LOG_PATTERN}</#noparse></Pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n    </appender>\n\n    <!-- 所有日志级别 -->\n    <appender name=\"ALL_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <!-- 正在记录的日志文档的路径及文档名 -->\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-all.log</#noparse></file>\n        <!--日志文档输出格式-->\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-all-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n    </appender>\n\n    <!-- DEBUG日志级别 -->\n    <appender name=\"DEBUG_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <!-- 正在记录的日志文档的路径及文档名 -->\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-debug.log</#noparse></file>\n        <!--日志文档输出格式-->\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-debug-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <!-- 此日志文档只记录debug级别的 -->\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>DEBUG</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- INFO日志级别 -->\n    <appender name=\"INFO_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-info.log</#noparse></file>\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-info-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>INFO</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- WARN日志级别 -->\n    <appender name=\"WARN_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-warn.log</#noparse></file>\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-warn-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>WARN</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- ERROR日志级别 -->\n    <appender name=\"ERROR_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-error.log</#noparse></file>\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-error-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>ERROR</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- mapper接口日志配置 -->\n    <logger name=\"${projectPackage}.${projectNameDot}.mapper\" level=\"DEBUG\" />\n\n    <root level=\"INFO\">\n        <appender-ref ref=\"CONSOLE\" />\n        <appender-ref ref=\"DEBUG_FILE\" />\n        <appender-ref ref=\"ERROR_FILE\" />\n        <appender-ref ref=\"WARN_FILE\" />\n        <appender-ref ref=\"INFO_FILE\" />\n        <appender-ref ref=\"ALL_FILE\" />\n    </root>\n\n</configuration>', '', NULL, '2025-06-05 11:12:12', '2025-08-14 10:39:07', 0);
INSERT INTO `gen_template` VALUES (224, 29, 569, 'OrderItemQuery.ftl', 'OrderItemQuery.java', 1, '排序参数', 'package ${projectPackage}.${projectNameDot}.common.domain.query;\n\nimport com.baomidou.mybatisplus.core.toolkit.StringUtils;\n<#if projectTemplatePropertyData[\'enableKnife4j\']>\nimport io.swagger.v3.oas.annotations.media.Schema;\n</#if>\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.stream.Collectors;\n\n/**\n * 排序字段查询参数\n */\n@Data\n<#if projectTemplatePropertyData[\'enableKnife4j\']>  \n@Schema(description = \"排序字段查询参数\")\n</#if>  \npublic class OrderItemQuery implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    /**\n     * 需要进行排序的字段\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"需要进行排序的字段\")\n    </#if>    \n    private String column;\n\n    /**\n     * 是否正序排列，默认 true\n     */\n    <#if projectTemplatePropertyData[\'enableKnife4j\']>\n    @Schema(description = \"是否正序排列，默认 true\")\n    </#if>    \n    private Boolean asc = true;\n\n    public static OrderItemQuery asc(String column) {\n        return build(column, true);\n    }\n\n    public static OrderItemQuery desc(String column) {\n        return build(column, false);\n    }\n\n    public static List<OrderItemQuery> ascs(String... columns) {\n        return Arrays.stream(columns).map(OrderItemQuery::asc).collect(Collectors.toList());\n    }\n\n    public static List<OrderItemQuery> descs(String... columns) {\n        return Arrays.stream(columns).map(OrderItemQuery::desc).collect(Collectors.toList());\n    }\n\n    private static OrderItemQuery build(String column, boolean asc) {\n        return new OrderItemQuery().setColumn(column).setAsc(asc);\n    }\n\n    public OrderItemQuery setColumn(String column) {\n        this.column = StringUtils.replaceAllBlank(column);\n        return this;\n    }\n\n    public OrderItemQuery setAsc(boolean asc) {\n        this.asc = asc;\n        return this;\n    }\n\n}\n', '', NULL, '2025-06-10 10:42:05', '2025-12-29 14:29:22', 0);
INSERT INTO `gen_template` VALUES (225, 29, 612, 'BaseMapperPlus.xml.ftl', 'BaseMapperPlus.xml', 1, '通用mybatis的mapper的xml文件', '<?xml version=\"1.0\" encoding=\"UTF-8\" ?>\n<!DOCTYPE mapper\n        PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\"\n        \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n<mapper namespace=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus\">\n\n    <!-- 排序SQL -->\n    <sql id=\"orderBySQL\">\n        <bind name=\"columnPrefix\" value=\"\'\'\"/>\n        <include refid=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus.prefixOrderBySQL\"/>\n    </sql>\n\n    <!-- 排序SQL（带前缀） -->\n    <sql id=\"prefixOrderBySQL\">\n        <if test=\"@${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil@isNotEmpty(query, \'orderItemList\')\">\n            ORDER BY\n            <foreach collection=\"query.orderItemList\" item=\"order\" separator=\",\">\n                <if test=\"@${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil@isNotEmpty(columnPrefix)\">\n                    <#noparse>${columnPrefix}</#noparse>.\n                </if>\n                <#noparse>${columnPrefix}.${@</#noparse>${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil@toUnderlineCase(order.column)} <if test=\"order.asc\">ASC</if><if test=\"!order.asc\">DESC</if>\n            </foreach>\n        </if>\n    </sql>\n\n</mapper>\n', '', NULL, '2025-06-10 11:05:57', '2025-08-14 10:32:41', 0);
INSERT INTO `gen_template` VALUES (226, 29, 614, 'AbstractEnumCodeValidator.ftl', 'AbstractEnumCodeValidator.java', 1, NULL, 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\nimport cn.hutool.v7.core.array.ArrayUtil;\nimport cn.hutool.v7.core.convert.ConvertUtil;\nimport cn.hutool.v7.core.reflect.FieldUtil;\nimport cn.hutool.v7.core.util.EnumUtil;\nimport jakarta.validation.ConstraintValidator;\nimport jakarta.validation.ConstraintValidatorContext;\nimport lombok.SneakyThrows;\n\nimport java.lang.reflect.Field;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Objects;\n\npublic abstract class AbstractEnumCodeValidator<T> implements ConstraintValidator<EnumCode, T> {\n\n    protected String enumName;\n\n    protected String enumFieldName;\n\n    protected List<?> values;\n\n    @Override\n    @SneakyThrows\n    public void initialize(EnumCode annotation) {\n        Class<? extends Enum<?>> value = annotation.value();\n        this.enumName = value.getName();\n        this.enumFieldName = annotation.fieldName();\n        if (!FieldUtil.hasField(value, this.enumFieldName)) {\n            throw new IllegalArgumentException(\"枚举属性名称: \" + enumName + \", 枚举属性名称: \" + enumFieldName + \" 不存在\");\n        }\n        List<Object> fieldValues = EnumUtil.getFieldValues((Class) value, this.enumFieldName);\n        String[] valueList = annotation.valueList();\n        if (ArrayUtil.isNotEmpty(valueList)) {\n            Field declaredField = value.getDeclaredField(this.enumFieldName);\n            List<?> list = ConvertUtil.toList(declaredField.getType(), valueList);\n            //判断是否包含所有值\n            if (new HashSet<>(fieldValues).containsAll(list)) {\n                this.values = list;\n            } else {\n                throw new IllegalArgumentException(\"枚举属性名称: \" + enumName + \", 属性名称: \" + enumFieldName + \", 值: \"\n                        + list + \" 不在枚举属性值范围内: \" + fieldValues);\n            }\n        } else {\n            this.values = fieldValues;\n        }\n    }\n\n    /**\n     * 子类实现校验逻辑\n     */\n    public abstract boolean isValid(T value);\n\n    @Override\n    public boolean isValid(T value, ConstraintValidatorContext context) {\n        //进行校验\n        boolean valid = isValid(value);\n        //如果校验不通过，则设置错误提示语句\n        if (!valid) {\n            setMessageTemplate(value, context);\n        }\n        return valid;\n    }\n\n    protected void setMessageTemplate(Object value, ConstraintValidatorContext context) {\n        //校验不通过，自定义提示语句\n        context.disableDefaultConstraintViolation();\n        //禁用默认的message 的值\n        String messageTemplate = context.getDefaultConstraintMessageTemplate()\n                //重新添加错误提示语句\n                .replace(\"{enumName}\", enumName)\n                .replace(\"{enumFieldName}\", enumFieldName)\n                .replace(\"{enumValue}\", Objects.toString(value))\n                .replace(\"{valueList}\", values.toString());\n        context.buildConstraintViolationWithTemplate(messageTemplate)\n                .addConstraintViolation();\n    }\n\n}\n', NULL, NULL, '2025-06-12 10:10:04', '2025-10-30 13:59:16', 0);
INSERT INTO `gen_template` VALUES (227, 29, 614, 'EnumCode.ftl', 'EnumCode.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\nimport jakarta.validation.Constraint;\nimport jakarta.validation.Payload;\n\nimport java.lang.annotation.Documented;\nimport java.lang.annotation.Retention;\nimport java.lang.annotation.RetentionPolicy;\nimport java.lang.annotation.Target;\n\nimport static java.lang.annotation.ElementType.*;\n\n/**\n * 枚举校验注解。字段的值需要在枚举的指定字段的指定值范围内\n */\n@Documented\n@Retention(RetentionPolicy.RUNTIME)\n@Target({METHOD, FIELD, ANNOTATION_TYPE, CONSTRUCTOR, PARAMETER, TYPE_USE})\n@Constraint(validatedBy = {EnumCodeValidator.class, EnumCodeCollectionValidator.class})\npublic @interface EnumCode {\n\n    /**\n     * 需要校验的枚举类型\n     */\n    Class<? extends Enum<?>> value();\n\n    /**\n     * 枚举类型校验值字段名称\n     */\n    String fieldName() default \"code\";\n\n    /**\n     * 枚举类型校验值列表。为空代表全部\n     */\n    String[] valueList() default {};\n\n    /**\n     * 异常信息，支持{enumName}、{enumFieldName}、{enumValue}和{valueList}占位替换\n     */\n    String message() default \"枚举属性名称: {enumName}.{enumFieldName}, 传入的枚举属性枚举值: {enumValue}, 必须在指定范围: {valueList}\";\n\n    Class<?>[] groups() default {};\n\n    Class<? extends Payload>[] payload() default {};\n\n}\n', NULL, NULL, '2025-06-12 10:10:35', '2025-10-30 13:59:23', 0);
INSERT INTO `gen_template` VALUES (228, 29, 614, 'EnumCodeCollectionValidator.ftl', 'EnumCodeCollectionValidator.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\nimport cn.hutool.v7.core.collection.CollUtil;\n\nimport java.util.Collection;\n\npublic class EnumCodeCollectionValidator extends AbstractEnumCodeValidator<Collection<?>> {\n\n    @Override\n    public boolean isValid(Collection<?> value) {\n        return CollUtil.containsAll(values, value);\n    }\n\n}\n', NULL, NULL, '2025-06-12 10:11:02', '2025-10-30 13:59:44', 0);
INSERT INTO `gen_template` VALUES (229, 29, 614, 'EnumCodeValidator.ftl', 'EnumCodeValidator.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\npublic class EnumCodeValidator extends AbstractEnumCodeValidator<Object> {\n\n    @Override\n    public boolean isValid(Object value) {\n        //为空时，默认不校验，即认为通过\n        if (value == null) {\n            return true;\n        }\n        for (Object item : values) {\n            if (item.equals(value)) {\n                return true;\n            }\n        }\n        return false;\n    }\n\n}\n', NULL, NULL, '2025-06-12 10:11:27', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (230, 33, 317, 'vue/api.ts.ftl', '${functionName}.ts', 1, '后端接口api', 'import service from \'@/utils/request\'\n\n//提交表单\nexport const ${functionName}SubmitApi = (dataForm: any) => {\n    if (dataForm.id) {\n        //修改接口\n        return service.put(\'/${functionName}/update\', dataForm)\n    } else {\n        //新增接口\n        return service.post(\'/${functionName}/add\', dataForm)\n    }\n}\n\n//删除接口\nexport const ${functionName}DeleteApi = (id: number) => {\n    return service.delete(\'/${functionName}/delete?id=\' + id)\n}\n\n//批量删除\nexport const ${functionName}DeleteListApi = (idList: Array<number>) => {\n    return service.delete(\'/${functionName}/deleteList\', { data: idList })\n}\n\n//详情\nexport const ${functionName}DetailApi = (id: number) => {\n    return service.get(\'/${functionName}/detail?id=\' + id)\n}\n\n//详情列表\nexport const ${functionName}DetailListApi = (idList: Array<number>) => {\n    return service.post(\'/${functionName}/detailList\', idList)\n}\n\n//简单分页\nexport const ${functionName}EntityPageApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/entityPage\', queryForm)\n}\n\n//简单列表\nexport const ${functionName}EntityListApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/entityList\', queryForm)\n}\n\n//复杂分页\nexport const ${functionName}VOPageApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/voPage\', queryForm)\n}\n\n//复杂列表\nexport const ${functionName}VOListApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/voList\', queryForm)\n}', NULL, NULL, '2025-06-16 15:24:15', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (231, 33, 320, 'vue/add-or-update.vue.ftl', 'add-or-update.vue', 1, '新增或者修改页面', '<template>\n	<el-dialog v-model=\"visible\" :title=\"!dataForm.id ? \'新增\' : \'修改\'\" :close-on-click-modal=\"false\">\n		<el-form ref=\"dataFormRef\" :model=\"dataForm\" :rules=\"dataRules\" label-width=\"100px\" @keyup.enter=\"submitHandle()\">\n	    <#list formList as field>\n            <el-form-item label=\"${field.fieldComment!}\" prop=\"${field.attrName}\">\n			<#if field.formType == \'text\'>\n                <el-input v-model=\"dataForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			<#elseif field.formType == \'textarea\'>\n                <el-input type=\"textarea\" v-model=\"dataForm.${field.attrName}\"></el-input>\n			<#elseif field.formType == \'editor\'>\n                <el-input type=\"textarea\" v-model=\"dataForm.${field.attrName}\"></el-input>\n			<#elseif field.formType == \'select\'>\n                <el-select v-model=\"dataForm.${field.attrName}\" clearable placeholder=\"请选择${field.fieldComment!}\">\n                    <el-option v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n                </el-select>\n			<#elseif field.formType == \'radio\'>\n                <el-radio-group v-model=\"dataForm.${field.attrName}\">\n                    <el-radio v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.value\">{{ item.label }}</el-radio>\n                </el-radio-group>\n			<#elseif field.formType == \'checkbox\'>\n                <el-checkbox-group v-model=\"dataForm.${field.attrName}\">\n                    <el-checkbox v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n                </el-checkbox-group>\n			<#elseif field.formType == \'date\'>\n                <el-date-picker type=\"date\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"dataForm.${field.attrName}\"></el-date-picker>\n			<#elseif field.formType == \'datetime\'>\n                <el-date-picker type=\"datetime\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"dataForm.${field.attrName}\"></el-date-picker>\n			<#else>\n                <el-input v-model=\"dataForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			</#if>\n            </el-form-item>\n	    </#list>\n		</el-form>\n		<template #footer>\n			<el-button @click=\"visible = false\">取消</el-button>\n			<el-button type=\"primary\" @click=\"submitHandle()\">确定</el-button>\n		</template>\n	</el-dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive, ref } from \'vue\'\nimport { ElMessage } from \'element-plus/es\'\nimport { ${functionName}DetailApi, ${functionName}SubmitApi } from \'@/api/${functionName}\'\n<#list formList as field>\n    <#if field.formType == \'select\' || field.formType == \'checkbox\' || field.formType == \'radio\'>\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/enums/${field.enumName}-enum\'\n    </#if>\n</#list>\n\nconst emit = defineEmits([\'refreshDataList\'])\n\nconst visible = ref(false)\nconst dataFormRef = ref()\n\nconst dataForm = reactive({\n	<#list fieldList as field>\n	    <#if field.baseField == 0>\n	${field.attrName}: \'\'<#sep>,\n	    </#if>\n	</#list>\n})\n\nconst init = (id?: number) => {\n	visible.value = true\n	dataForm.id = null\n\n	// 重置表单数据\n	if (dataFormRef.value) {\n		dataFormRef.value.resetFields()\n	}\n\n	if (id) {\n		get${functionNamePascal}(id)\n	}\n}\n\nconst get${functionNamePascal} = (id: number) => {\n	${functionName}DetailApi(id).then(res => {\n		Object.assign(dataForm, res.data)\n	})\n}\n\nconst dataRules = ref({\n	<#list formList as field>\n	<#if field.formRequired == 1>\n	${field.attrName}: [{ required: true, message: \'必填项不能为空\', trigger: \'blur\' }]<#sep>,\n	</#if>\n	</#list>\n})\n\n// 表单提交\nconst submitHandle = () => {\n	dataFormRef.value.validate((valid: boolean) => {\n		if (!valid) {\n			return false\n		}\n\n		${functionName}SubmitApi(dataForm).then(() => {\n			ElMessage.success({\n				message: \'操作成功\',\n				duration: 500,\n				onClose: () => {\n					visible.value = false\n					emit(\'refreshDataList\')\n				}\n			})\n		})\n	})\n}\n\ndefineExpose({\n	init\n})\n</script>\n', NULL, NULL, '2025-06-16 15:24:15', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (232, 33, 320, 'vue/index.vue.ftl', 'index.vue', 1, '列表页面', '<template>\n	<el-card class=\"layout-query\">\n		<el-form ref=\"queryRef\" :inline=\"true\" :model=\"state.queryForm\" @keyup.enter=\"getDataList()\">\n		<#list queryList as field>\n			<el-form-item prop=\"${field.attrName}\">\n			<#if field.queryFormType == \'text\' || field.queryFormType == \'textarea\' || field.queryFormType == \'editor\'>\n                <el-input v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请输入${field.fieldComment}\"></el-input>\n			<#elseif field.formType == \'select\'>\n                <el-select v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请选择${field.fieldComment}\">\n                    <el-option v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n                </el-select>\n			<#elseif field.formType == \'radio\'>\n                <el-radio-group v-model=\"state.queryForm.${field.attrName}\">\n                    <el-radio v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.value\">{{ item.label }}</el-radio>\n                </el-radio-group>\n			<#elseif field.formType == \'checkbox\'>\n                <el-checkbox-group v-model=\"state.queryForm.${field.attrName}\">\n                    <el-checkbox v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n                </el-checkbox-group>\n			<#elseif field.queryFormType == \'date\'>\n                <el-date-picker\n                        v-model=\"state.queryForm.${field.attrName}\"\n                        type=\"daterange\"\n                        format=\"YYYY-MM-DD\"\n                        value-format=\"YYYY-MM-DD\"\n                        clearable\n                >\n                </el-date-picker>\n            <#elseif field.queryFormType == \'datetime\'>\n                <el-date-picker\n                        v-model=\"state.queryForm.${field.attrName}\"\n                        type=\"datetimerange\"\n                        format=\"YYYY-MM-DD HH:mm:ss\"\n                        value-format=\"YYYY-MM-DD HH:mm:ss\"\n                        clearable\n                >\n                </el-date-picker>\n			<#else>\n                <el-input v-model=\"state.queryForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			</#if>\n			</el-form-item>\n        </#list>\n			<el-form-item>\n				<el-button type=\"primary\" @click=\"getDataList()\">查询</el-button>\n			</el-form-item>\n			<el-form-item>\n				<el-button @click=\"resetQueryRef()\">重置</el-button>\n			</el-form-item>\n            <el-form-item>\n                <el-button type=\"primary\" @click=\"addOrUpdateHandle()\">新增</el-button>\n            </el-form-item>\n            <el-form-item>\n                <el-button type=\"danger\" @click=\"deleteBatchHandle()\">删除</el-button>\n            </el-form-item>\n		</el-form>\n	</el-card>\n\n	<el-card>\n		<el-table v-loading=\"state.dataListLoading\" :data=\"state.dataList\" border class=\"layout-table\" @selection-change=\"selectionChangeHandle\">\n			<el-table-column type=\"selection\" header-align=\"center\" align=\"center\" width=\"50\"></el-table-column>\n			<el-table-column type=\"index\" label=\"序号\" header-align=\"center\" align=\"center\" width=\"60\"></el-table-column>\n	    <#list gridList as field>\n		  <#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>\n        	<el-table-column prop=\"${field.attrName}\" label=\"${field.fieldComment!}\" show-overflow-tooltip header-align=\"center\" align=\"center\" :formatter=\"(_: any, __: any, value: any) => getLabel(value, ${field.enumNameAllUpper}_ENUM)\"></el-table-column>\n		  <#else>\n			<el-table-column prop=\"${field.attrName}\" label=\"${field.fieldComment!}\" show-overflow-tooltip header-align=\"center\" align=\"center\"></el-table-column>\n		  </#if>\n        </#list>\n			<el-table-column label=\"操作\" fixed=\"right\" header-align=\"center\" align=\"center\" width=\"150\">\n				<template #default=\"scope\">\n					<el-button type=\"primary\" link @click=\"addOrUpdateHandle(scope.row.id)\">修改</el-button>\n					<el-button type=\"primary\" link @click=\"deleteBatchHandle(scope.row.id)\">删除</el-button>\n				</template>\n			</el-table-column>\n		</el-table>\n		<el-pagination\n			:current-page=\"state.pageNum\"\n			:page-sizes=\"state.pageSizes\"\n			:page-size=\"state.pageSize\"\n			:total=\"state.total\"\n			layout=\"total, sizes, prev, pager, next, jumper\"\n			@size-change=\"sizeChangeHandle\"\n			@current-change=\"currentChangeHandle\"\n		>\n		</el-pagination>\n\n		<!-- 弹窗, 新增 / 修改 -->\n		<add-or-update ref=\"addOrUpdateRef\" @refresh-data-list=\"getDataList\"></add-or-update>\n	</el-card>\n</template>\n\n<script setup lang=\"ts\">\nimport { useCrud } from \'@/hooks\'\nimport { reactive, ref } from \'vue\'\nimport { IHooksOptions } from \'@/hooks/interface\'\nimport AddOrUpdate from \'./add-or-update.vue\'\n<#list gridList as field>\n	<#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>\nimport { getLabel } from \'@/utils/enum\'\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/enums/${field.enumName}-enum\'\n	</#if>\n</#list>\n\nconst state: IHooksOptions = reactive({\n    dataListUrl: \'/${functionName}/entityPage\',\n    deleteUrl: \'/${functionName}/deleteList\',\n    queryForm: {\n        <#list queryList as field>\n        <#if field.formType == \'date\'>\n        startDate: \'\',\n        endDate: \'\'<#sep>, </#sep>\n        <#elseif field.formType == \'datetime\'>\n        startDateTime: \'\',\n        endDateTime: \'\'<#sep>, </#sep>\n        <#else>\n        ${field.attrName}: \'\'<#sep>, </#sep>\n        </#if>\n        </#list>\n    }\n})\n\nconst queryRef = ref()\nconst addOrUpdateRef = ref()\nconst addOrUpdateHandle = (id: number) => {\n	addOrUpdateRef.value.init(id)\n}\nconst resetQueryRef = () => {\n  queryRef.value.resetFields()\n}\n\nconst { getDataList, selectionChangeHandle, sizeChangeHandle, currentChangeHandle, deleteBatchHandle } = useCrud(state)\n</script>\n', NULL, NULL, '2025-06-16 15:24:15', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (233, 34, 354, 'vue/api.ts.ftl', '${functionName}.ts', 1, '后端接口api', 'import service from \'@/utils/request\'\n\n//提交表单\nexport const ${functionName}SubmitApi = (dataForm: any) => {\n    if (dataForm.id) {\n        //修改接口\n        return service.put(\'/${functionName}/update\', dataForm)\n    } else {\n        //新增接口\n        return service.post(\'/${functionName}/add\', dataForm)\n    }\n}\n\n//删除接口\nexport const ${functionName}DeleteApi = (id: number) => {\n    return service.delete(\'/${functionName}/delete?id=\' + id)\n}\n\n//批量删除\nexport const ${functionName}DeleteListApi = (idList: Array<number>) => {\n    return service.delete(\'/${functionName}/deleteList\', { data: idList })\n}\n\n//详情\nexport const ${functionName}DetailApi = (id: number) => {\n    return service.get(\'/${functionName}/detail?id=\' + id)\n}\n\n//详情列表\nexport const ${functionName}DetailListApi = (idList: Array<number>) => {\n    return service.post(\'/${functionName}/detailList\', idList)\n}\n\n//简单分页\nexport const ${functionName}EntityPageApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/entityPage\', queryForm)\n}\n\n//简单列表\nexport const ${functionName}EntityListApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/entityList\', queryForm)\n}\n\n//复杂分页\nexport const ${functionName}VOPageApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/voPage\', queryForm)\n}\n\n//复杂列表\nexport const ${functionName}VOListApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/voList\', queryForm)\n}', NULL, NULL, '2025-06-16 15:25:05', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (234, 34, 357, 'vue/add-or-update.vue.ftl', 'add-or-update.vue', 1, '新增或者修改页面', '<template>\n	<el-dialog v-model=\"visible\" :title=\"!dataForm.id ? \'新增\' : \'修改\'\" :close-on-click-modal=\"false\">\n		<el-form ref=\"dataFormRef\" :model=\"dataForm\" :rules=\"dataRules\" label-width=\"100px\" @keyup.enter=\"submitHandle()\">\n	    <#list formList as field>\n            <el-form-item label=\"${field.fieldComment!}\" prop=\"${field.attrName}\">\n			<#if field.formType == \'text\'>\n                <el-input v-model=\"dataForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			<#elseif field.formType == \'textarea\'>\n                <el-input type=\"textarea\" v-model=\"dataForm.${field.attrName}\"></el-input>\n			<#elseif field.formType == \'editor\'>\n                <el-input type=\"textarea\" v-model=\"dataForm.${field.attrName}\"></el-input>\n			<#elseif field.formType == \'select\'>\n                <el-select v-model=\"dataForm.${field.attrName}\" clearable placeholder=\"请选择${field.fieldComment!}\">\n                    <el-option v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n                </el-select>\n			<#elseif field.formType == \'radio\'>\n                <el-radio-group v-model=\"dataForm.${field.attrName}\">\n                    <el-radio v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.value\">{{ item.label }}</el-radio>\n                </el-radio-group>\n			<#elseif field.formType == \'checkbox\'>\n                <el-checkbox-group v-model=\"dataForm.${field.attrName}\">\n                    <el-checkbox v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n                </el-checkbox-group>\n			<#elseif field.formType == \'date\'>\n                <el-date-picker type=\"date\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"dataForm.${field.attrName}\"></el-date-picker>\n			<#elseif field.formType == \'datetime\'>\n                <el-date-picker type=\"datetime\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"dataForm.${field.attrName}\"></el-date-picker>\n			<#else>\n                <el-input v-model=\"dataForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			</#if>\n            </el-form-item>\n	    </#list>\n		</el-form>\n		<template #footer>\n			<el-button @click=\"visible = false\">取消</el-button>\n			<el-button type=\"primary\" @click=\"submitHandle()\">确定</el-button>\n		</template>\n	</el-dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive, ref } from \'vue\'\nimport { ElMessage } from \'element-plus/es\'\nimport { ${functionName}DetailApi, ${functionName}SubmitApi } from \'@/api/${functionName}\'\n<#list formList as field>\n    <#if field.formType == \'select\' || field.formType == \'checkbox\' || field.formType == \'radio\'>\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/enums/${field.enumName}-enum\'\n    </#if>\n</#list>\n\nconst emit = defineEmits([\'refreshDataList\'])\n\nconst visible = ref(false)\nconst dataFormRef = ref()\n\nconst dataForm = reactive({\n	<#list fieldList as field>\n	    <#if field.baseField == 0>\n	${field.attrName}: \'\'<#sep>,\n	    </#if>\n	</#list>\n})\n\nconst init = (id?: number) => {\n	visible.value = true\n	dataForm.id = null\n\n	// 重置表单数据\n	if (dataFormRef.value) {\n		dataFormRef.value.resetFields()\n	}\n\n	if (id) {\n		get${functionNamePascal}(id)\n	}\n}\n\nconst get${functionNamePascal} = (id: number) => {\n	${functionName}DetailApi(id).then(res => {\n		Object.assign(dataForm, res.data)\n	})\n}\n\nconst dataRules = ref({\n	<#list formList as field>\n	<#if field.formRequired == 1>\n	${field.attrName}: [{ required: true, message: \'必填项不能为空\', trigger: \'blur\' }]<#sep>,\n	</#if>\n	</#list>\n})\n\n// 表单提交\nconst submitHandle = () => {\n	dataFormRef.value.validate((valid: boolean) => {\n		if (!valid) {\n			return false\n		}\n\n		${functionName}SubmitApi(dataForm).then(() => {\n			ElMessage.success({\n				message: \'操作成功\',\n				duration: 500,\n				onClose: () => {\n					visible.value = false\n					emit(\'refreshDataList\')\n				}\n			})\n		})\n	})\n}\n\ndefineExpose({\n	init\n})\n</script>\n', NULL, NULL, '2025-06-16 15:25:05', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (235, 34, 357, 'vue/index.vue.ftl', 'index.vue', 1, '列表页面', '<template>\n	<el-card class=\"layout-query\">\n		<el-form ref=\"queryRef\" :inline=\"true\" :model=\"state.queryForm\" @keyup.enter=\"getDataList()\">\n		<#list queryList as field>\n			<el-form-item prop=\"${field.attrName}\">\n			<#if field.queryFormType == \'text\' || field.queryFormType == \'textarea\' || field.queryFormType == \'editor\'>\n                <el-input v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请输入${field.fieldComment}\"></el-input>\n			<#elseif field.formType == \'select\'>\n                <el-select v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请选择${field.fieldComment}\">\n                    <el-option v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n                </el-select>\n			<#elseif field.formType == \'radio\'>\n                <el-radio-group v-model=\"state.queryForm.${field.attrName}\">\n                    <el-radio v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.value\">{{ item.label }}</el-radio>\n                </el-radio-group>\n			<#elseif field.formType == \'checkbox\'>\n                <el-checkbox-group v-model=\"state.queryForm.${field.attrName}\">\n                    <el-checkbox v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n                </el-checkbox-group>\n			<#elseif field.queryFormType == \'date\'>\n                <el-date-picker\n                        v-model=\"state.queryForm.${field.attrName}\"\n                        type=\"daterange\"\n                        format=\"YYYY-MM-DD\"\n                        value-format=\"YYYY-MM-DD\"\n                        clearable\n                >\n                </el-date-picker>\n            <#elseif field.queryFormType == \'datetime\'>\n                <el-date-picker\n                        v-model=\"state.queryForm.${field.attrName}\"\n                        type=\"datetimerange\"\n                        format=\"YYYY-MM-DD HH:mm:ss\"\n                        value-format=\"YYYY-MM-DD HH:mm:ss\"\n                        clearable\n                >\n                </el-date-picker>\n			<#else>\n                <el-input v-model=\"state.queryForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			</#if>\n			</el-form-item>\n        </#list>\n			<el-form-item>\n				<el-button type=\"primary\" @click=\"getDataList()\">查询</el-button>\n			</el-form-item>\n			<el-form-item>\n				<el-button @click=\"resetQueryRef()\">重置</el-button>\n			</el-form-item>\n            <el-form-item>\n                <el-button type=\"primary\" @click=\"addOrUpdateHandle()\">新增</el-button>\n            </el-form-item>\n            <el-form-item>\n                <el-button type=\"danger\" @click=\"deleteBatchHandle()\">删除</el-button>\n            </el-form-item>\n		</el-form>\n	</el-card>\n\n	<el-card>\n		<el-table v-loading=\"state.dataListLoading\" :data=\"state.dataList\" border class=\"layout-table\" @selection-change=\"selectionChangeHandle\">\n			<el-table-column type=\"selection\" header-align=\"center\" align=\"center\" width=\"50\"></el-table-column>\n			<el-table-column type=\"index\" label=\"序号\" header-align=\"center\" align=\"center\" width=\"60\"></el-table-column>\n	    <#list gridList as field>\n		  <#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>\n        	<el-table-column prop=\"${field.attrName}\" label=\"${field.fieldComment!}\" show-overflow-tooltip header-align=\"center\" align=\"center\" :formatter=\"(_: any, __: any, value: any) => getLabel(value, ${field.enumNameAllUpper}_ENUM)\"></el-table-column>\n		  <#else>\n			<el-table-column prop=\"${field.attrName}\" label=\"${field.fieldComment!}\" show-overflow-tooltip header-align=\"center\" align=\"center\"></el-table-column>\n		  </#if>\n        </#list>\n			<el-table-column label=\"操作\" fixed=\"right\" header-align=\"center\" align=\"center\" width=\"150\">\n				<template #default=\"scope\">\n					<el-button type=\"primary\" link @click=\"addOrUpdateHandle(scope.row.id)\">修改</el-button>\n					<el-button type=\"primary\" link @click=\"deleteBatchHandle(scope.row.id)\">删除</el-button>\n				</template>\n			</el-table-column>\n		</el-table>\n		<el-pagination\n			:current-page=\"state.pageNum\"\n			:page-sizes=\"state.pageSizes\"\n			:page-size=\"state.pageSize\"\n			:total=\"state.total\"\n			layout=\"total, sizes, prev, pager, next, jumper\"\n			@size-change=\"sizeChangeHandle\"\n			@current-change=\"currentChangeHandle\"\n		>\n		</el-pagination>\n\n		<!-- 弹窗, 新增 / 修改 -->\n		<add-or-update ref=\"addOrUpdateRef\" @refresh-data-list=\"getDataList\"></add-or-update>\n	</el-card>\n</template>\n\n<script setup lang=\"ts\">\nimport { useCrud } from \'@/hooks\'\nimport { reactive, ref } from \'vue\'\nimport { IHooksOptions } from \'@/hooks/interface\'\nimport AddOrUpdate from \'./add-or-update.vue\'\n<#list gridList as field>\n	<#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>\nimport { getLabel } from \'@/utils/enum\'\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/enums/${field.enumName}-enum\'\n	</#if>\n</#list>\n\nconst state: IHooksOptions = reactive({\n    dataListUrl: \'/${functionName}/entityPage\',\n    deleteUrl: \'/${functionName}/deleteList\',\n    queryForm: {\n        <#list queryList as field>\n        <#if field.formType == \'date\'>\n        startDate: \'\',\n        endDate: \'\'<#sep>, </#sep>\n        <#elseif field.formType == \'datetime\'>\n        startDateTime: \'\',\n        endDateTime: \'\'<#sep>, </#sep>\n        <#else>\n        ${field.attrName}: \'\'<#sep>, </#sep>\n        </#if>\n        </#list>\n    }\n})\n\nconst queryRef = ref()\nconst addOrUpdateRef = ref()\nconst addOrUpdateHandle = (id: number) => {\n	addOrUpdateRef.value.init(id)\n}\nconst resetQueryRef = () => {\n  queryRef.value.resetFields()\n}\n\nconst { getDataList, selectionChangeHandle, sizeChangeHandle, currentChangeHandle, deleteBatchHandle } = useCrud(state)\n</script>\n', NULL, NULL, '2025-06-16 15:25:05', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (236, 35, 362, 'vue/api.ts.ftl', '${functionName}.ts', 1, '后端接口api', 'import service from \'@/utils/request\'\n\n//提交表单\nexport const ${functionName}SubmitApi = (dataForm: any) => {\n    if (dataForm.id) {\n        //修改接口\n        return service.put(\'/${functionName}/update\', dataForm)\n    } else {\n        //新增接口\n        return service.post(\'/${functionName}/add\', dataForm)\n    }\n}\n\n//删除接口\nexport const ${functionName}DeleteApi = (id: number) => {\n    return service.delete(\'/${functionName}/delete?id=\' + id)\n}\n\n//批量删除\nexport const ${functionName}DeleteListApi = (idList: Array<number>) => {\n    return service.delete(\'/${functionName}/deleteList\', { data: idList })\n}\n\n//详情\nexport const ${functionName}DetailApi = (id: number) => {\n    return service.get(\'/${functionName}/detail?id=\' + id)\n}\n\n//详情列表\nexport const ${functionName}DetailListApi = (idList: Array<number>) => {\n    return service.post(\'/${functionName}/detailList\', idList)\n}\n\n//简单分页\nexport const ${functionName}EntityPageApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/entityPage\', queryForm)\n}\n\n//简单列表\nexport const ${functionName}EntityListApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/entityList\', queryForm)\n}\n\n//复杂分页\nexport const ${functionName}VOPageApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/voPage\', queryForm)\n}\n\n//复杂列表\nexport const ${functionName}VOListApi = (queryForm: any) => {\n    return service.post(\'/${functionName}/voList\', queryForm)\n}', NULL, NULL, '2025-06-16 15:25:54', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (237, 35, 365, 'vue/add-or-update.vue.ftl', 'add-or-update.vue', 1, '新增或者修改页面', '<template>\n	<el-dialog v-model=\"visible\" :title=\"!dataForm.id ? \'新增\' : \'修改\'\" :close-on-click-modal=\"false\">\n		<el-form ref=\"dataFormRef\" :model=\"dataForm\" :rules=\"dataRules\" label-width=\"100px\" @keyup.enter=\"submitHandle()\">\n	    <#list formList as field>\n            <el-form-item label=\"${field.fieldComment!}\" prop=\"${field.attrName}\">\n			<#if field.formType == \'text\'>\n                <el-input v-model=\"dataForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			<#elseif field.formType == \'textarea\'>\n                <el-input type=\"textarea\" v-model=\"dataForm.${field.attrName}\"></el-input>\n			<#elseif field.formType == \'editor\'>\n                <el-input type=\"textarea\" v-model=\"dataForm.${field.attrName}\"></el-input>\n			<#elseif field.formType == \'select\'>\n                <el-select v-model=\"dataForm.${field.attrName}\" clearable placeholder=\"请选择${field.fieldComment!}\">\n                    <el-option v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n                </el-select>\n			<#elseif field.formType == \'radio\'>\n                <el-radio-group v-model=\"dataForm.${field.attrName}\">\n                    <el-radio v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.value\">{{ item.label }}</el-radio>\n                </el-radio-group>\n			<#elseif field.formType == \'checkbox\'>\n                <el-checkbox-group v-model=\"dataForm.${field.attrName}\">\n                    <el-checkbox v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n                </el-checkbox-group>\n			<#elseif field.formType == \'date\'>\n                <el-date-picker type=\"date\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"dataForm.${field.attrName}\"></el-date-picker>\n			<#elseif field.formType == \'datetime\'>\n                <el-date-picker type=\"datetime\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"dataForm.${field.attrName}\"></el-date-picker>\n			<#else>\n                <el-input v-model=\"dataForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment!}\"></el-input>\n			</#if>\n            </el-form-item>\n	    </#list>\n		</el-form>\n		<template #footer>\n			<el-button @click=\"visible = false\">取消</el-button>\n			<el-button type=\"primary\" @click=\"submitHandle()\">确定</el-button>\n		</template>\n	</el-dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive, ref } from \'vue\'\nimport { ElMessage } from \'element-plus/es\'\nimport { ${functionName}DetailApi, ${functionName}SubmitApi } from \'@/api/${functionName}\'\n<#list formList as field>\n    <#if field.formType == \'select\' || field.formType == \'checkbox\' || field.formType == \'radio\'>\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/enums/${field.enumName}-enum\'\n    </#if>\n</#list>\n\nconst emit = defineEmits([\'refreshDataList\'])\n\nconst visible = ref(false)\nconst dataFormRef = ref()\n\nconst dataForm = reactive({\n	<#list fieldList as field>\n	    <#if field.baseField == 0>\n	${field.attrName}: \'\'<#sep>,\n	    </#if>\n	</#list>\n})\n\nconst init = (id?: number) => {\n	visible.value = true\n	dataForm.id = null\n\n	// 重置表单数据\n	if (dataFormRef.value) {\n		dataFormRef.value.resetFields()\n	}\n\n	if (id) {\n		get${functionNamePascal}(id)\n	}\n}\n\nconst get${functionNamePascal} = (id: number) => {\n	${functionName}DetailApi(id).then(res => {\n		Object.assign(dataForm, res.data)\n	})\n}\n\nconst dataRules = ref({\n	<#list formList as field>\n	<#if field.formRequired == 1>\n	${field.attrName}: [{ required: true, message: \'必填项不能为空\', trigger: \'blur\' }]<#sep>,\n	</#if>\n	</#list>\n})\n\n// 表单提交\nconst submitHandle = () => {\n	dataFormRef.value.validate((valid: boolean) => {\n		if (!valid) {\n			return false\n		}\n\n		${functionName}SubmitApi(dataForm).then(() => {\n			ElMessage.success({\n				message: \'操作成功\',\n				duration: 500,\n				onClose: () => {\n					visible.value = false\n					emit(\'refreshDataList\')\n				}\n			})\n		})\n	})\n}\n\ndefineExpose({\n	init\n})\n</script>\n', NULL, NULL, '2025-06-16 15:25:54', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (238, 35, 365, 'vue/index.vue.ftl', 'index.vue', 1, '列表页面', '<template>\n	<el-card class=\"layout-query\">\n		<el-form ref=\"queryRef\" :inline=\"true\" :model=\"state.queryForm\" @keyup.enter=\"getDataList()\">\n		<#list queryList as field>\n			<el-form-item prop=\"${field.attrName}\">\n			<#if field.queryFormType == \'text\' || field.queryFormType == \'textarea\' || field.queryFormType == \'editor\'>\n                <el-input v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请输入${field.fieldComment}\"></el-input>\n			<#elseif field.formType == \'select\'>\n                <el-select v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请选择${field.fieldComment}\">\n                    <el-option v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n                </el-select>\n			<#elseif field.formType == \'radio\'>\n                <el-radio-group v-model=\"state.queryForm.${field.attrName}\">\n                    <el-radio v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.value\">{{ item.label }}</el-radio>\n                </el-radio-group>\n			<#elseif field.formType == \'checkbox\'>\n                <el-checkbox-group v-model=\"state.queryForm.${field.attrName}\">\n                    <el-checkbox v-for=\"item in ${enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n                </el-checkbox-group>\n			<#elseif field.queryFormType == \'date\'>\n                <el-date-picker\n                        v-model=\"state.queryForm.${field.attrName}\"\n                        type=\"daterange\"\n                        format=\"YYYY-MM-DD\"\n                        value-format=\"YYYY-MM-DD\"\n                        clearable\n                >\n                </el-date-picker>\n            <#elseif field.queryFormType == \'date