INSERT INTO `gen_template` VALUES (267, 30, 631, 'main.ts.ftl', 'main.ts', 1, '主启动文件', 'import { createApp } from \'vue\'\nimport { createPinia } from \'pinia\'\nimport piniaPluginPersistedstate from \'pinia-plugin-persistedstate\'\nimport { dynamicPersistPlugin } from \'@/plugins/dynamic-persist-plugin\'\nimport ElementPlus from \'element-plus\'\nimport App from \'@/App.vue\'\nimport { router } from \'@/router\'\nimport \'virtual:svg-icons-register\'\nimport SvgIcon from \'@/components/svg-icon\'\nimport \'@/icons/iconfont/iconfont\'\nimport \'element-plus/dist/index.css\'\nimport \'element-plus/theme-chalk/dark/css-vars.css\' // ✅ 引入暗黑模式 css\nimport \'@/styles/index.scss\'\nimport * as ElementPlusIconsVue from \'@element-plus/icons-vue\'\nimport directive from \'@/directive\'\n\nconst app = createApp(App)\nconst pinia = createPinia()\npinia.use(piniaPluginPersistedstate)\npinia.use(dynamicPersistPlugin)\n//使用element-plus图标\nfor (const [key, component] of Object.entries(ElementPlusIconsVue)) {\n	app.component(key, component)\n}\n// 自定义指令\ndirective(app)\n\napp.use(router)\napp.use(SvgIcon)\napp.use(pinia)\napp.use(ElementPlus)\napp.mount(\'#app\')\n', NULL, NULL, '2025-08-07 10:11:07', '2025-09-25 14:56:42', 0);
INSERT INTO `gen_template` VALUES (268, 30, 631, 'App.vue.ftl', 'App.vue', 1, '主页面文件', '<template>\n	<el-config-provider :locale=\"zhCn\" :size=\"appStore.layoutSize\">\n		<router-view></router-view>\n	</el-config-provider>\n</template>\n\n<script setup lang=\"ts\">\nimport { RouterView } from \'vue-router\'\nimport zhCn from \'element-plus/dist/locale/zh-cn.mjs\'\nimport dayjs from \'dayjs\'\nimport \'dayjs/locale/zh-cn\'\nimport { useAppStore } from \'@/store/app-store\'\n\ndayjs.locale(\'zh-cn\')\n\nconst appStore = useAppStore()\n</script>\n', NULL, NULL, '2025-08-07 10:11:56', '2025-09-25 14:56:34', 0);
INSERT INTO `gen_template` VALUES (269, 30, 634, 'tool.ts.ftl', 'tool.ts', 1, '工具类', 'import type { App, Component, Plugin } from \'vue\' // 添加 Component 类型\nimport { useClipboard, useTitle } from \'@vueuse/core\'\nimport { ElMessage } from \'element-plus/es\'\nimport { cloneDeep } from \'lodash-unified\'\n\nconst { copy, isSupported } = useClipboard()\n\n// 复制到剪切板\nexport const copyToClipboard = (text: string): Promise<void> => {\n	return new Promise((resolve, reject) => {\n		if (isSupported) {\n			copy(text)\n				.then(() => {\n					resolve()\n				})\n				.catch(err => {\n					console.error(\'复制失败:\', err)\n					ElMessage.error(\'复制失败\')\n					reject()\n				})\n		} else {\n			// ⚙️ 降级处理：使用 document.execCommand(\'copy\')\n			try {\n				// 创建隐藏的 textarea\n				const textarea = document.createElement(\'textarea\')\n				textarea.value = text\n				textarea.style.position = \'fixed\'\n				textarea.style.top = \'-9999px\'\n				textarea.style.left = \'-9999px\'\n				document.body.appendChild(textarea)\n\n				// 选中并执行复制命令\n				textarea.select()\n				const successful = document.execCommand(\'copy\')\n				document.body.removeChild(textarea)\n\n				if (successful) {\n					resolve()\n				} else {\n					ElMessage.warning(\'浏览器不支持自动复制，请手动复制\')\n					reject(new Error(\'execCommand copy failed\'))\n				}\n			} catch (err) {\n				console.error(\'复制失败（降级模式）:\', err)\n				ElMessage.warning(\'浏览器不支持自动复制，请手动复制\')\n				reject(err)\n			}\n		}\n	})\n}\n\n// 克隆对象\nexport const cloneObject = <T extends object>(obj: T): T => {\n	return cloneDeep(obj) as T\n}\n\n// 重置对象\nexport const resetReactiveObject = <T extends object>(target: T, source: T): void => {\n	Object.assign(target, cloneObject(source))\n}\n\nconst title = useTitle()\n\n// 默认标题\nconst originalTitle = import.meta.env.VITE_APP_TITLE\ntitle.value = originalTitle\n\n// 设置标题\nexport const setTitle = (newTitle: string) => {\n	title.value = newTitle + \' - \' + originalTitle\n}\n\n// 设置原始标题\nexport const setDefaultTitle = () => {\n	title.value = originalTitle\n}\n\n// 修改泛型约束为 Component\nexport const withInstall = <T extends Component>(component: T, alias?: string) => {\n	const comp = component as any\n	comp.install = (app: App) => {\n		app.component(comp.__name || comp.displayName, component)\n		if (alias) {\n			app.config.globalProperties[alias] = component\n		}\n	}\n	return component as T & Plugin\n}\n', NULL, NULL, '2025-08-07 10:12:27', '2025-11-05 14:49:43', 0);
INSERT INTO `gen_template` VALUES (270, 30, 651, 'router-guard.ts.ftl', 'guard.ts', 1, '路由守卫', 'import { useAppStore, useSystemSettingStore, useUserStore } from \'@/store\'\nimport { Router, RouteRecordRaw } from \'vue-router\'\nimport \'nprogress/nprogress.css\'\nimport NProgress from \'nprogress\'\nimport { setTitle } from \'@/utils/tool\'\nimport { MenuInfo, RouteMetaData } from \'@/types\'\n\nNProgress.configure({ showSpinner: false })\n\n// 路由白名单名称列表\nconst whiteLists: string[] = [\'AuthLogin\']\n\nexport const routeGuard = (router: Router) => {\n	// 路由前置拦截\n	router.beforeEach((to, from, next) => {\n		const systemSettingStore = useSystemSettingStore()\n\n		if (systemSettingStore.isOpenProgress) {\n			NProgress.start()\n		}\n		const routeMetaData: RouteMetaData = {\n			name: to.name as string,\n			path: to.path,\n			fullPath: to.fullPath,\n			title: to.meta?.title as string,\n			icon: to.meta?.icon as string,\n			cache: to.meta?.cache as boolean,\n			type: to.meta?.type as number,\n			hidden: to.meta?.hidden as boolean,\n			externalUrl: to.meta?.externalUrl as string\n		}\n\n		// console.log(to, from, routeMetaData)\n\n		// 如果包含白名单，直接放行\n		if (whiteLists.includes(routeMetaData.name)) {\n			next()\n			return\n		}\n\n		const userStore = useUserStore()\n		// 是否登录\n		// if (!userStore.isLogin) {\n		// 	// 未登录，跳转登录页面\n		// 	next({\n		// 		name: \'Login\',\n		// 		query: {\n		// 			redirect: encodeURIComponent(to.fullPath || \'/\')\n		// 		}\n		// 	})\n		// 	NProgress.done()\n		// 	return\n		// }\n		// 是否添加路由\n		if (!userStore.isAddRoutes) {\n			// 1. 添加路由\n			const routeList = buildRouteList(userStore.menuList)\n			routeList.forEach((item: RouteRecordRaw) => {\n				// console.log(\'item\', item)\n				router.addRoute(\'Layout\', item)\n			})\n\n			// 3. 设置添加路由标记\n			userStore.setAddRouteFlag()\n			// 添加完路由需要重新执行一次路由跳转，否则会出现空白页面\n			next({ ...to, replace: true })\n			return\n		}\n\n		// 动态设置默认跳转\n		if (to.path === \'/\') {\n			return next(systemSettingStore.menuDefault ?? \'/index\')\n		}\n\n		const appStore = useAppStore()\n\n		// 不是新窗口,添加tag标签\n		if (routeMetaData.type !== 4 && systemSettingStore.isOpenTag) {\n			// 添加标签\n			appStore.addTag({\n				...routeMetaData\n			})\n		}\n\n		// 添加缓存路由 - 有名称和是菜单时才添加缓存\n		if (routeMetaData.cache && routeMetaData.name && routeMetaData.type === 1 && systemSettingStore.isOpenPageCache) {\n			appStore.addCacheComponent(routeMetaData.name)\n		}\n\n		next()\n	})\n\n	// 路由后置拦截\n	router.afterEach(to => {\n		const systemSettingStore = useSystemSettingStore()\n		// 设置动态标题\n		if (systemSettingStore.isOpenDynamicTitle) {\n			setTitle(to.meta.title as string)\n		}\n\n		// 关闭进度条\n		if (systemSettingStore.isOpenProgress && NProgress.isStarted()) {\n			NProgress.done()\n		}\n	})\n}\n\n// 匹配views里面所有的.vue文件\nconst modules = import.meta.glob(\'@/views/**/*.vue\')\nconst loadView = (component: string | undefined) => {\n	let res\n	for (const path in modules) {\n		const dir = path.split(\'/src/views/\')[1].split(\'.vue\')[0]\n		if (dir === component) {\n			res = () => modules[path]()\n			return res\n		}\n	}\n	if (!res) {\n		console.warn(<#noparse>`未找到组件: ${component}`</#noparse>)\n		res = () => import(\'@/views/error/404.vue\')\n		return res\n	}\n}\n\n// 构建路由\nconst buildRouteList = (menuList: MenuInfo[]): RouteRecordRaw[] => {\n	return menuList\n		.map((item: MenuInfo) => {\n			// 处理外链菜单\n			if (item.meta.type === 3) {\n				// iframe内嵌方式\n				return {\n					path: item.path,\n					name: item.name,\n					component: loadIframeComponent(item),\n					props: { iframeSrc: item.meta.externalUrl, cache: item.meta.cache },\n					meta: {\n						...item.meta\n					}\n				} as RouteRecordRaw\n			} else if (item.meta.type === 4) {\n				// 新窗口打开方式，创建一个跳转页面\n				return null\n			}\n\n			const menu = {\n				...item\n			} as RouteRecordRaw\n\n			// 如果是目录，则需要构建子路由\n			if (item.meta.type === 0 && item.children && item.children.length > 0) {\n				menu.children = buildRouteList(item.children)\n			}\n			// 如果是菜单，则需要构建组件\n			if (item.meta.type === 1) {\n				menu.component = loadView(item.component)\n			}\n			return menu\n		})\n		.filter(Boolean) as RouteRecordRaw[]\n}\n\n// 处理iframe菜单对应的组件\nconst loadIframeComponent = (item: MenuInfo) => {\n	// 如果有组件，则直接加载组件\n	if (item.component) {\n		return loadView(item.component)\n	} else {\n		// 否则使用公共的组件，并且重新设置组件名称\n		return () =>\n			import(\'@/components/router/iframe-page.vue\').then(comp => {\n				// 给组件动态设置 name\n				comp.default.name = item.name\n				return comp\n			})\n	}\n}\n', '', NULL, '2025-08-07 10:13:06', '2025-11-24 16:37:33', 0);
INSERT INTO `gen_template` VALUES (271, 30, 634, 'request.ts.ftl', 'request.ts', 1, '请求工具类', 'import axios from \'axios\'\nimport qs from \'qs\'\nimport { ElMessage, ElMessageBox } from \'element-plus\'\nimport { useUserStore } from \'@/store\'\nimport { router } from \'@/router\'\nimport { Result } from \'@/types/api/common\'\nimport { useRoute } from \'vue-router\'\n\n// axios实例\nexport const service = axios.create({\n	baseURL: import.meta.env.VITE_API_URL,\n	timeout: 60000,\n	headers: { \'Content-Type\': \'application/json;charset=UTF-8\' },\n	paramsSerializer: params => qs.stringify(params, { indices: false }), // 使用qs.stringify进行序列化\n	withCredentials: true // 允许携带cookie\n})\n\n// 请求拦截器\nservice.interceptors.request.use(\n	config => {\n		// 追加时间戳，防止GET请求缓存\n		if (config.method?.toUpperCase() === \'GET\') {\n			config.params = { ...config.params, t: new Date().getTime() }\n		}\n\n		// 处理表单数据\n		if (config.headers[\'Content-Type\'] === \'application/x-www-form-urlencoded\') {\n			config.data = qs.stringify(config.data)\n		}\n\n		// 添加token\n		const userStore = useUserStore()\n		if (userStore.tokenInfo) {\n			config.headers[userStore.tokenInfo.tokenName] = userStore.tokenInfo.accessToken\n		}\n\n		return config\n	},\n	error => {\n		return Promise.reject(error)\n	}\n)\n\n// 响应拦截器\nservice.interceptors.response.use(\n	response => {\n		const { config, status, statusText, data } = response\n\n		// 处理 HTTP 状态码错误\n		if (status !== 200) {\n			return handleHttpStatusError(status, statusText, config)\n		}\n\n		// 文件下载直接返回\n		if (config.responseType === \'blob\') {\n			return response\n		}\n\n		const result = data as Result\n\n		// 响应成功\n		if (result.code === 200) {\n			return config.rawResponse === false ? result : result.data\n		}\n\n		// 处理业务逻辑错误\n		return handleBusinessError(result, config)\n	},\n	error => {\n		const config = error.config || {}\n		return handleNetworkError(error, config)\n	}\n)\n\n/**\n * 处理HTTP状态码错误\n */\nconst handleHttpStatusError = (status: number, statusText: string, config: any) => {\n	if (!config.noErrorMessage) {\n		ElMessage.error(statusText || \'网络错误\')\n	}\n	return Promise.reject(new Error(statusText || \'网络错误\'))\n}\n\n/**\n * 处理业务逻辑错误\n */\nconst handleBusinessError = (result: Result, config: any) => {\n	// 未认证\n	if (result.code === 401) {\n		// 重定向到登录页面\n		ElMessageBox.confirm(\'登录状态已过期，您可以继续留在该页面，或者重新登录\', \'系统提示\', {\n			confirmButtonText: \'重新登录\',\n			cancelButtonText: \'取消\',\n			type: \'warning\'\n		}).then(() => {\n			const userStore = useUserStore()\n			userStore.clearAll()\n			// 使用 useRoute 获取当前路由信息，保持与其他组件一致\n			const route = useRoute()\n			router.replace({\n				path: \'/auth/login\',\n				query: {\n					redirect: encodeURIComponent(route.fullPath || \'/\')\n				}\n			})\n		})\n		return Promise.reject(\'无效的会话，或者会话已过期，请重新登录。\')\n	} else if (result.code === 403) {\n		// 未授权\n		if (!config.noErrorMessage) {\n			ElMessage.error(\'您没有权限访问该资源\')\n		}\n		return Promise.reject(\'您没有权限访问该资源\')\n	} else {\n		// 业务错误提示：只有没有设置 noErrorMessage 才提示\n		if (!config.noErrorMessage) {\n			ElMessage.error(result.message || \'请求错误\')\n		}\n		return Promise.reject(new Error(result.message || \'请求错误\'))\n	}\n}\n\n/**\n * 处理网络请求错误\n */\nconst handleNetworkError = (error: any, config: any) => {\n	if (!config.noErrorMessage) {\n		// 根据错误类型提供更具体的错误信息\n		let errorMessage = \'请求失败\'\n		if (error.code === \'ECONNABORTED\') {\n			errorMessage = \'请求超时，请稍后重试\'\n		} else if (error.message === \'Network Error\') {\n			errorMessage = \'网络连接失败，请检查网络设置\'\n		} else if (error.response) {\n			switch (error.response.status) {\n				case 400:\n					errorMessage = \'请求参数错误\'\n					break\n				case 401:\n					errorMessage = \'未授权，请重新登录\'\n					break\n				case 403:\n					errorMessage = \'拒绝访问\'\n					break\n				case 404:\n					errorMessage = \'请求资源不存在\'\n					break\n				case 408:\n					errorMessage = \'请求超时\'\n					break\n				case 500:\n					errorMessage = \'服务器内部错误\'\n					break\n				case 501:\n					errorMessage = \'服务未实现\'\n					break\n				case 502:\n					errorMessage = \'网关错误\'\n					break\n				case 503:\n					errorMessage = \'服务不可用\'\n					break\n				case 504:\n					errorMessage = \'网关超时\'\n					break\n				default:\n					errorMessage = <#noparse>`连接错误${error.response.status}</#noparse>`\n			}\n		} else if (error.request) {\n			errorMessage = \'服务器无响应，请稍后重试\'\n		}\n		ElMessage.error(errorMessage)\n	}\n	return Promise.reject(error)\n}\n\n/**\n * 统一文件下载工具（适用于小文件）\n *\n * @param url 请求地址\n * @param params 请求参数\n * @param noErrorMessage 是否不显示错误提示\n */\nexport const downloadFile = (url: string, params?: any, noErrorMessage = false): Promise<void> => {\n	return new Promise((resolve, reject) => {\n		service\n			.get(url, {\n				responseType: \'blob\',\n				params,\n				noErrorMessage\n			})\n			.then(response => {\n				const contentDisposition = response.headers[\'content-disposition\']\n				let filename = \'download\'\n\n				// 获取下载的文件名\n				if (contentDisposition) {\n					const filenameStarMatch = contentDisposition.match(/filename\\*=[\'\"]?(?:UTF-8[\'\"]?)?\'\'?([^;]+)/i)\n					const filenameMatch = contentDisposition.match(/filename=[\'\"]?([^;]+)[\'\"]?/i)\n					filename = filenameStarMatch?.[1]\n						? decodeURIComponent(filenameStarMatch[1])\n						: filenameMatch?.[1]\n							? decodeURIComponent(filenameMatch[1].replace(/\\+/g, \'%20\'))\n							: filename\n				}\n\n				const downloadUrl = URL.createObjectURL(new Blob([response.data]))\n				const a = document.createElement(\'a\')\n				a.href = downloadUrl\n				a.download = filename\n				document.body.appendChild(a)\n				a.click()\n				window.URL.revokeObjectURL(downloadUrl)\n				document.body.removeChild(a)\n\n				resolve()\n			})\n			.catch(error => {\n				if (!noErrorMessage) {\n					let errorMessage = \'导出失败，请稍后重试或联系管理员\'\n					if (error.response) {\n						errorMessage = `导出失败，服务器返回状态码：<#noparse>${error.response.status}</#noparse>`\n					} else if (error.request) {\n						errorMessage = \'导出失败，请检查网络连接或稍后重试\'\n					}\n					ElMessage.error(errorMessage)\n				}\n				reject(error)\n			})\n	})\n}\n\n/**\n * 下载大文件（通过 a 标签 + token 拼接）\n * @param url 请求地址\n * @param params 请求参数\n */\nexport const downloadBigFile = (url: string, params?: Record<string, any>) => {\n	return new Promise<void>(resolve => {\n		const userStore = useUserStore()\n		const tokenName = userStore.tokenInfo.tokenName\n		const tokenValue = userStore.tokenInfo.accessToken\n		const requestParam = { ...(params ?? {}), [tokenName]: tokenValue }\n\n		// 拼接完整 URL\n		const baseURL = import.meta.env.VITE_API_URL as string\n		const downloadUrl = <#noparse>`${baseURL}${url}?${qs.stringify(requestParam, { indices: false })}`</#noparse>\n\n		// 创建隐藏的 a 标签\n		const a = document.createElement(\'a\')\n		a.href = downloadUrl\n		a.style.display = \'none\'\n		document.body.appendChild(a)\n		a.click()\n		document.body.removeChild(a)\n		resolve()\n	})\n}\n\n/**\n * 加载blob数据\n *\n * @param url 请求地址\n * @param type blob类型\n * @param params 请求参数\n * @param noErrorMessage 是否不显示错误提示\n */\nexport const loadBlob = (url: string, type: string, params?: any, noErrorMessage = false) => {\n	return service\n		.get(url, {\n			responseType: \'blob\',\n			params,\n			noErrorMessage\n		})\n		.then(resp => {\n			// 进行一下非空判断，有些组件当没有数据时，会报错\n			if (resp.data.size === 0) {\n				return Promise.reject(new Error(\'Blob 内容为空\'))\n			}\n			const blob = new Blob([resp.data], { type })\n			return URL.createObjectURL(blob)\n		})\n		.catch(error => {\n			let errorMessage = \'加载blob数据失败，请稍后重试或联系管理员\'\n			if (!noErrorMessage) {\n				if (error.response) {\n					errorMessage = <#noparse>`加载blob数据失败，服务器返回状态码：${error.response.status}`</#noparse>\n				} else if (error.request) {\n					errorMessage = \'加载blob数据失败，请检查网络连接或稍后重试\'\n				}\n				ElMessage.error(errorMessage)\n			}\n			return Promise.reject(new Error(errorMessage))\n		})\n}\n', NULL, NULL, '2025-08-07 10:13:43', '2025-11-24 16:39:46', 0);
INSERT INTO `gen_template` VALUES (272, 30, 634, 'enum.ts.ftl', 'enum.ts', 1, '枚举工具类', 'import { EnumItem, EnumTagTypeValue, EnumValueType } from \'@/types\'\n\n/**\n * 获取表格枚举标签（单独给el-table-column的formatter属性使用）\n */\nexport const getLabel = (enumList: EnumItem[]) => {\n	return (_: any, __: any, value: EnumValueType): string => {\n		return <string>getLabelData(value, enumList)\n	}\n}\n\n/**\n * 获取枚举标签label\n */\nexport const getLabelData = (value: EnumValueType, enumList: EnumItem[], defaultValue = \'\') => {\n	const byValue = getByValue(value, enumList)\n	if (!byValue) {\n		return defaultValue\n	} else {\n		return <string>byValue.label\n	}\n}\n\n/**\n * 根据枚举值获取枚举项\n */\nexport const getByValue = (value: EnumValueType, enumList: EnumItem[]) => {\n	return enumList.find(item => item.value === value)\n}\n\nexport type { EnumValueType, EnumTagTypeValue, EnumItem }\n', NULL, NULL, '2025-08-07 10:14:21', '2025-11-24 16:19:40', 0);
INSERT INTO `gen_template` VALUES (273, 30, 634, 'download.ts.ftl', 'download.ts', 1, '文件下载工具类', 'import { ElMessage } from \'element-plus\'\nimport service from \'@/utils/request\'\n\n/**\n * 统一文件下载工具\n *\n * @param url 请求地址\n * @param params 请求参数\n */\nexport const downloadFile = (url: string, params?: any): Promise<void> => {\n	return new Promise((resolve, reject) => {\n		service\n			.get(url, {\n				responseType: \'blob\',\n				params\n			})\n			.then((response: any) => {\n				// 提取文件名\n				const contentDisposition = response.headers[\'content-disposition\']\n				let filename = \'\'\n\n				//attachment;filename=\"GenEnumItemServiceImpl.java\";filename*=UTF-8\'\'GenEnumItemServiceImpl.java\n				if (contentDisposition) {\n					// 正则匹配 filename* 或 filename（支持带引号或不带引号的格式）\n					const filenameStarMatch = contentDisposition.match(/filename\\*=[\'\"]?(?:UTF-8[\'\"]?)?\'\'?([^;]+)/i)\n					const filenameMatch = contentDisposition.match(/filename=[\'\"]?([^;]+)[\'\"]?/i)\n\n					// 优先使用 filename*\n					if (filenameStarMatch && filenameStarMatch[1]) {\n						filename = decodeURIComponent(filenameStarMatch[1].trim())\n					}\n					// 回退到 filename（需解码 URL 编码）\n					else if (filenameMatch && filenameMatch[1]) {\n						filename = decodeURIComponent(filenameMatch[1].trim().replace(/\\+/g, \'%20\')) // 替换 + 为 %20（兼容 URLEncoder 格式）\n					}\n				}\n\n				// 创建下载链接并触发下载\n				const downloadUrl = window.URL.createObjectURL(new Blob([response.data]))\n				const a = document.createElement(\'a\')\n				a.href = downloadUrl\n				a.download = filename\n				document.body.appendChild(a)\n				a.click()\n				window.URL.revokeObjectURL(downloadUrl)\n				document.body.removeChild(a)\n\n				// 成功时直接resolve，不返回true\n				resolve()\n			})\n			.catch((error: any) => {\n				console.error(\'导出失败:\', error)\n				let errorMessage = \'导出失败，请稍后重试或联系管理员\'\n\n				if (error.response) {\n					errorMessage = `导出失败，服务器返回状态码：<#noparse>${error.response.status}</#noparse>`\n				} else if (error.request) {\n					errorMessage = \'导出失败，请检查网络连接或稍后重试\'\n				}\n\n				ElMessage.error(errorMessage)\n				// 失败时reject错误信息\n				reject(new Error(errorMessage))\n			})\n	})\n}\n', NULL, NULL, '2025-08-07 10:14:51', '2025-11-05 14:49:13', 1);
INSERT INTO `gen_template` VALUES (274, 30, 640, 'shims.d.ts.ftl', 'shims.d.ts', 1, '类型约束文件', 'declare module \'*.svg\'\ndeclare module \'*.png\'\ndeclare module \'*.jpg\'\ndeclare module \'*.gif\'\ndeclare module \'*.scss\'\ndeclare module \'*.ts\'\ndeclare module \'*.js\'\n\ndeclare module \'*.vue\' {\n	import type { DefineComponent } from \'vue\'\n	const component: DefineComponent<{}, {}, any>\n	export default component\n}\n', NULL, NULL, '2025-08-07 10:15:23', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (275, 30, 640, 'element-plus.d.ts.ftl', 'element-plus.d.ts', 1, 'element类型约束文件', '// src/types/element-plus.d.ts\ndeclare module \'element-plus/dist/locale/zh-cn.mjs\' {\n	import { Locale } from \'element-plus\'\n	const locale: Locale\n	export default locale\n}\n', NULL, NULL, '2025-08-07 10:16:14', '2025-11-05 14:48:33', 1);
INSERT INTO `gen_template` VALUES (276, 30, 643, 'variables.scss.ftl', 'variables.scss', 1, 'css变量文件', ':root {\n  --el-color-primary: #1e97f8;\n\n  /* 菜单颜色 */\n  --theme-menu-text-color: #333333;\n  --theme-menu-bg-color: #ffffff;\n  --theme-menu-border-color: var(--el-color-primary);\n  --theme-menu-hover-color: var(--el-color-primary);\n  --theme-menu-hover-bg-color: var(--el-color-primary-light-9);\n\n  /* 默认 header 配置，会被 theme.scss 覆盖 */\n  --theme-header-bg-color: var(--el-color-primary);\n  --theme-header-text-color: #ffffff;\n\n  --theme-main-bg-color: #f0f2f5;\n}\n', NULL, NULL, '2025-08-07 10:16:48', '2025-11-24 16:18:51', 0);
INSERT INTO `gen_template` VALUES (277, 30, 643, 'layout.scss.ftl', 'layout.scss', 1, '布局css文件', '* {\n  margin: 0;\n  padding: 0;\n  outline: none !important;\n}\n\nhtml,\nbody,\n#app {\n  margin: 0;\n  padding: 0;\n  width: 100%;\n  height: 100%;\n  font-family: \'Helvetica Neue\', Helvetica, \'PingFang SC\', \'Hiragino Sans GB\', \'Microsoft YaHei\', \'微软雅黑\', Arial, sans-serif;\n  font-weight: 400;\n  -webkit-font-smoothing: antialiased;\n  -webkit-tap-highlight-color: transparent;\n  font-size: 14px;\n  overflow: hidden;\n  position: relative;\n}\n\na,\na:focus,\na:hover {\n  cursor: pointer;\n  color: inherit;\n  text-decoration: none;\n}\n\n.layout-container {\n  height: 100vh;\n  display: flex;\n\n  .layout-sidebar {\n    background: var(--theme-menu-bg-color);\n    position: relative;\n    transition: width 0.3s ease;\n    overflow: hidden;\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n    overflow-x: auto;\n    overflow-y: auto;\n    border-right: 1px solid var(--el-border-color);\n  }\n\n  .layout-header {\n    background-color: var(--theme-header-bg-color) !important;\n    color: var(--theme-header-text-color) !important;\n    display: flex;\n    flex-direction: column;\n    padding: 0;\n    width: 100%;\n    height: auto !important;\n  }\n\n  .layout-main {\n    padding: 0 !important;\n    overflow: hidden;\n    flex: 1;\n    background-color: var(--theme-main-bg-color);\n\n    .layout-scrollbar {\n      flex: 1;\n      padding: 15px;\n\n      .layout-card {\n\n        .layout-query-card {\n        }\n\n        .layout-table-card {\n\n          .layout-table {\n            .layout-table-header {\n              background: var(--el-fill-color-light);\n              color: var(--el-text-color-regular);\n            }\n          }\n        }\n      }\n    }\n  }\n}\n\n/* fade 过渡动画样式 */\n.fade-enter-active,\n.fade-leave-active {\n  transition: opacity 0.3s ease;\n}\n\n.fade-enter-from,\n.fade-leave-to {\n  opacity: 0;\n}\n\n/* 可选：slide 过渡动画样式 */\n.slide-enter-active,\n.slide-leave-active {\n  transition: all 0.15s ease;\n}\n\n.slide-enter-from {\n  transform: translateX(20px);\n  opacity: 0;\n}\n\n.slide-leave-to {\n  transform: translateX(-20px);\n  opacity: 0;\n}\n\n/* 可选：zoom 过渡动画样式 */\n.zoom-enter-active,\n.zoom-leave-active {\n  transition: all 0.3s ease;\n}\n\n.zoom-enter-from {\n  transform: scale(0.95);\n  opacity: 0;\n}\n\n.zoom-leave-to {\n  transform: scale(1.05);\n  opacity: 0;\n}\n', NULL, NULL, '2025-08-07 10:17:29', '2025-11-24 16:18:29', 0);
INSERT INTO `gen_template` VALUES (278, 30, 643, 'index.scss.ftl', 'index.scss', 1, 'css初始化文件', '@import \'./variables.scss\';\n@import \'./layout.scss\';\n@import \'./element.scss\';\n@import \'./theme.scss\';\n', NULL, NULL, '2025-08-07 10:18:01', '2025-09-25 14:51:58', 0);
INSERT INTO `gen_template` VALUES (279, 30, 643, 'element.scss.ftl', 'element.scss', 1, 'element组件css文件', '// 覆盖 element-plus 样式\n/* 基础菜单样式 */\n.el-menu {\n  border-right: none !important;\n}\n\n.el-menu-item,\n.el-sub-menu__title {\n  display: flex;\n  align-items: center; /* 图标+文字垂直居中 */\n  color: var(--theme-menu-text-color) !important;\n  height: 48px !important;\n  line-height: 48px !important;\n  overflow: hidden;\n  transition: color 0.3s, background-color 0.3s;\n}\n\n.el-menu.el-menu--horizontal {\n  border-bottom: none !important;\n}\n\n/* 图标样式 */\n.el-menu-item .svg-icon,\n.el-sub-menu__title .svg-icon {\n  font-size: 16px !important;\n  display: inline-block;\n  width: 20px; /* 固定宽度，保证对齐 */\n  margin-right: 8px;\n  flex-shrink: 0;\n  text-align: center;\n  color: var(--theme-menu-text-color) !important;\n  transition: color 0.3s; /* 添加过渡效果 */\n}\n\n/* 折叠时隐藏文字 */\n.el-menu--collapse .menu-title {\n  width: 0;\n  overflow: hidden;\n}\n\n/* 选中状态：文字和图标都高亮 */\n.el-menu-item.is-active {\n  box-shadow: inset 3px 0 0 var(--theme-menu-border-color), inset -3px 0 0 var(--theme-menu-border-color);\n  background-color: var(--theme-menu-hover-bg-color) !important;\n}\n\n/* 文字高亮 */\n.el-menu-item.is-active .menu-title {\n  color: var(--theme-menu-hover-color) !important;\n}\n\n/* 图标高亮 */\n.el-menu-item.is-active .svg-icon {\n  color: var(--theme-menu-hover-color) !important;\n}\n\n/* 子菜单选中状态：只高亮文字和图标，不添加背景色 */\n.el-sub-menu.is-active > .el-sub-menu__title .menu-title {\n  color: var(--theme-menu-hover-color) !important;\n}\n\n.el-sub-menu.is-active > .el-sub-menu__title .svg-icon {\n  color: var(--theme-menu-hover-color) !important;\n}\n\n/* 悬浮状态：只高亮文字和图标，不更改背景颜色 */\n.el-menu-item:hover {\n  background-color: transparent !important; /* 移除背景色 */\n}\n\n.el-menu-item:hover .menu-title,\n.el-sub-menu__title:hover .menu-title {\n  color: var(--theme-menu-hover-color) !important;\n}\n\n.el-menu-item:hover .svg-icon,\n.el-sub-menu__title:hover .svg-icon {\n  color: var(--theme-menu-hover-color) !important;\n}\n\n/* 子菜单悬浮状态：不添加背景色 */\n.el-sub-menu__title:hover {\n  background-color: transparent !important; /* 移除背景色 */\n}\n\n// 分页\n.el-pagination {\n  margin-top: 15px;\n  justify-content: flex-end;\n}\n\n// 表单\n.el-form .el-form-item__label {\n  font-weight: 700;\n}\n\n.el-form--inline .el-form-item {\n  margin-right: 16px !important;\n}\n\n// 对话框\n.el-dialog {\n  padding: 0;\n}\n\n.el-dialog__header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 10px 30px 5px;\n  border-bottom: 1px solid var(--el-border-color);\n}\n\n.el-dialog__headerbtn {\n  position: relative !important;\n}\n\n.el-dialog__header.show-close {\n  padding-right: 0;\n}\n\n.el-dialog__body {\n  padding: 20px 20px 15px;\n}\n\n.el-dialog__footer {\n  padding: 15px 25px 15px 15px;\n  border-top: 1px solid var(--el-border-color);\n}\n\n// 抽屉\n.el-drawer .el-drawer__header {\n  display: flex;\n  align-items: center;\n  height: 50px;\n  padding: 0 15px;\n  margin-bottom: 0 !important;\n  font-size: 15px;\n  border-bottom: 1px solid var(--el-border-color);\n  color: var(--el-text-color-primary);\n}\n\n// 卡片\n.el-card {\n  &:not(:first-child) {\n    margin-top: 10px;\n  }\n}\n\n.el-card.is-always-shadow {\n  box-shadow: none !important;\n}\n\n// 消息弹出框，确定在前，取消在后\n.el-message-box__btns {\n  display: flex;\n  justify-content: flex-end;\n  gap: 12px;\n}\n\n.el-message-box__btns .el-button--primary {\n  order: -1; /* 让“是(Y)”排到最前 */\n}\n\n.el-message-box__btns .el-button + .el-button {\n  margin-left: 0 !important;\n}\n\n/* el-space 默认改成 default (12px) */\n.el-space {\n  gap: 12px !important; /* default 对应 12px */\n}\n', NULL, NULL, '2025-08-07 10:18:41', '2025-11-24 16:18:14', 0);
INSERT INTO `gen_template` VALUES (280, 30, 648, 'user-store.ts.ftl', 'user-store.ts', 1, '用户store文件', 'import { defineStore } from \'pinia\'\nimport { computed, reactive, ref } from \'vue\'\nimport { cloneObject, resetReactiveObject } from \'@/utils/tool\'\nimport { PersistenceOptions } from \'pinia-plugin-persistedstate\'\nimport { MenuInfo, TokenInfo, UserInfo } from \'@/types\'\n\nconst INITIAL_USER_INFO: UserInfo = {\n	username: \'admin\',\n	nickname: \'张三\',\n	avatar: \'\',\n	email: \'admin@qq.com\',\n	mobile: \'18888888888\'\n}\n\nconst INITIAL_TOKEN_INFO: TokenInfo = {\n	tokenName: \'satoken\',\n	accessToken: \'\',\n	refreshToken: \'\',\n	expire: 0\n}\n\n// 定义需要在侧边栏显示的常量菜单\nconst sidebarConstantMenuInfoList: MenuInfo[] = [\n	{\n		path: \'/index\',\n		component: \'index/index\',\n		name: \'Index\',\n		meta: {\n			title: \'首页\',\n			icon: \'icon-home\',\n			cache: true,\n			type: 1\n		}\n	}\n	// 可以添加其他需要在侧边栏显示的常量菜单\n]\n\n// 业务菜单\nconst businessMenuInfoList: MenuInfo[] = [\n	// {\n	// 	path: \'/index2\',\n	// 	component: \'index/index\',\n	// 	name: \'Index2\',\n	// 	meta: {\n	// 		title: \'首页2\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index3\',\n	// 	component: \'index/index\',\n	// 	name: \'Index3\',\n	// 	meta: {\n	// 		title: \'首页3\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index4\',\n	// 	component: \'index/index\',\n	// 	name: \'Index4\',\n	// 	meta: {\n	// 		title: \'首页4\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index5\',\n	// 	component: \'index/index\',\n	// 	name: \'Index5\',\n	// 	meta: {\n	// 		title: \'首页5\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index6\',\n	// 	component: \'index/index\',\n	// 	name: \'Index6\',\n	// 	meta: {\n	// 		title: \'首页6\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index7\',\n	// 	component: \'index/index\',\n	// 	name: \'Index7\',\n	// 	meta: {\n	// 		title: \'首页7\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index8\',\n	// 	component: \'index/index\',\n	// 	name: \'Index8\',\n	// 	meta: {\n	// 		title: \'首页8\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index9\',\n	// 	component: \'index/index\',\n	// 	name: \'Index9\',\n	// 	meta: {\n	// 		title: \'首页9\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index10\',\n	// 	component: \'index/index\',\n	// 	name: \'Index10\',\n	// 	meta: {\n	// 		title: \'首页10\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index11\',\n	// 	component: \'index/index\',\n	// 	name: \'Index11\',\n	// 	meta: {\n	// 		title: \'首页11\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index12\',\n	// 	component: \'index/index\',\n	// 	name: \'Index12\',\n	// 	meta: {\n	// 		title: \'首页12\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index13\',\n	// 	component: \'index/index\',\n	// 	name: \'Index13\',\n	// 	meta: {\n	// 		title: \'首页13\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index14\',\n	// 	component: \'index/index\',\n	// 	name: \'Index14\',\n	// 	meta: {\n	// 		title: \'首页14\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/index15\',\n	// 	component: \'index/index\',\n	// 	name: \'Index15\',\n	// 	meta: {\n	// 		title: \'首页15\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		cache: true,\n	// 		type: 1,\n	// 	}\n	// },\n	// {\n	// 	path: \'/dir1\',\n	// 	name: \'Dir1\',\n	// 	meta: {\n	// 		title: \'目录1\',\n	// 		icon: \'icon-dashboard-fill\',\n	// 		type: 0\n	// 	},\n	// 	children: [\n	// 		{\n	// 			path: \'/dir1/dir2\',\n	// 			name: \'Dir2\',\n	// 			meta: {\n	// 				title: \'目录2\',\n	// 				icon: \'icon-dashboard-fill\',\n	// 				type: 0\n	// 			},\n	// 			children: [\n	// 				{\n	// 					path: \'/dir1/dir2/index1\',\n	// 					component: \'index/index\',\n	// 					name: \'Dir1Index1\',\n	// 					meta: {\n	// 						title: \'目录1-目录2-首页\',\n	// 						icon: \'icon-dashboard-fill\',\n	// 						cache: true,\n	// 						type: 1,\n	// 					}\n	// 				}\n	// 			]\n	// 		}\n	// 	]\n	// },\n	{\n		path: \'/icon-search\',\n		component: \'icon-search/index\',\n		name: \'IconSearch\',\n		meta: {\n			title: \'图标搜索\',\n			icon: \'icon-search\',\n			type: 1,\n			cache: true\n		}\n	},\n	{\n		path: \'/test-external\',\n		name: \'TestExternal\',\n		meta: {\n			title: \'外链测试\',\n			icon: \'icon-link\',\n			type: 0\n		},\n		children: [\n			{\n				path: \'/test-external/iframe\',\n				name: \'TestExternalIframeJava\',\n				meta: {\n					title: \'java官网（iframe）\',\n					icon: \'icon-java\',\n					type: 3,\n					externalUrl: \'https://www.java.com\',\n					cache: true\n				}\n			},\n			{\n				path: \'/test-external/iframe2\',\n				name: \'TestExternalIframeVite\',\n				meta: {\n					title: \'vite官网（iframe）（不缓存）\',\n					icon: \'icon-Batchfolding\',\n					type: 3,\n					externalUrl: \'https://cn.vitejs.dev/\',\n					cache: false\n				}\n			},\n			{\n				path: \'/test-external/iframe3\',\n				name: \'TestExternalIframeElementPlus\',\n				meta: {\n					title: \'element-plus\',\n					icon: \'icon-java\',\n					type: 3,\n					externalUrl: \'https://cn.element-plus.org/zh-CN/guide/design.html\',\n					cache: true\n				}\n			},\n			{\n				path: \'/test-external/new-window\',\n				name: \'TestExternalNewWindow\',\n				meta: {\n					title: \'阿里巴巴（新窗口）\',\n					icon: \'icon-alibaba\',\n					type: 4,\n					externalUrl: \'https://www.alibaba.com\'\n				}\n			}\n		]\n	},\n  <#list tableModelList as tableModel>\n    {\n        path: \'/${tableModel.moduleName}/${tableModel.functionNameKebabCase}\',\n        component: \'${tableModel.moduleName}/${tableModel.functionNameKebabCase}/index\',\n        name: \'${tableModel.moduleNamePascal}${tableModel.functionNamePascal}\',\n        meta: {\n            title: \'${tableModel.tableComment}管理\',\n            icon: \'icon-icon-test\',\n            cache: true,\n            type: 1,\n            hidden: false\n        }\n    }<#if tableModel_has_next>,</#if>\n  </#list>\n]\n\n// 持久化配置\nconst getPersistConfig = () => {\n	const key = \'userStore\'\n	if (import.meta.env.PROD) {\n		return {\n			key,\n			omit: [\'isAddRoutes\'],\n			storage: localStorage\n		} as PersistenceOptions\n	} else {\n		return {\n			key,\n			pick: [\'userInfo\', \'tokenInfo\', \'permissionList\', \'roleList\'],\n			storage: localStorage\n		} as PersistenceOptions\n	}\n}\n\nexport const useUserStore = defineStore(\n	\'user\',\n	() => {\n		// 状态\n		// 是否添加路由\n		const isAddRoutes = ref(false)\n		// 菜单列表\n		const menuList = ref<MenuInfo[]>([...sidebarConstantMenuInfoList, ...businessMenuInfoList])\n		// 激活菜单\n		const activeMenuPath = ref<string>(\'\')\n		// 权限列表\n		const permissionList = ref<string[]>([])\n		// 角色列表\n		const roleList = ref<string[]>([])\n		// 登录用户信息\n		// reactive每次初始化，必须传入一个全新的对象\n		const userInfo = reactive<UserInfo>(cloneObject(INITIAL_USER_INFO))\n		// token信息\n		const tokenInfo = reactive<TokenInfo>(cloneObject(INITIAL_TOKEN_INFO))\n\n		// 计算属性\n		const isLogin = computed(() => {\n			return tokenInfo.accessToken !== \'\'\n		})\n\n		// actions\n		// 设置添加路由的标志\n		const setAddRouteFlag = () => {\n			isAddRoutes.value = true\n		}\n\n		// 清空数据\n		const clearAll = () => {\n			menuList.value = []\n			roleList.value = []\n			permissionList.value = []\n			// 完全清空 userInfo\n			resetReactiveObject(userInfo, INITIAL_USER_INFO)\n\n			// 完全清空 tokenInfo\n			resetReactiveObject(tokenInfo, INITIAL_TOKEN_INFO)\n		}\n\n		// 设置登录后的数据\n		const setData = (loginVO: any) => {\n			Object.assign(userInfo, loginVO.userInfo)\n			Object.assign(tokenInfo, loginVO.tokenInfo)\n			menuList.value = loginVO.menuList\n			permissionList.value = loginVO.permissionList\n			roleList.value = loginVO.roleList\n		}\n\n		// 设置激活的菜单\n		const setActiveMenuPath = (path: string) => {\n			activeMenuPath.value = path\n		}\n\n		return {\n			isLogin,\n			isAddRoutes,\n			menuList,\n			activeMenuPath,\n			permissionList,\n			userInfo,\n			tokenInfo,\n			clearAll,\n			setData,\n			setAddRouteFlag,\n			setActiveMenuPath\n		}\n	},\n	{\n		persist: getPersistConfig()\n	}\n)\n', NULL, NULL, '2025-08-07 10:19:30', '2025-11-24 18:01:43', 0);
INSERT INTO `gen_template` VALUES (281, 30, 648, 'app-store.ts.ftl', 'app-store.ts', 1, '应用store文件', 'import { defineStore } from \'pinia\'\nimport { computed, ref } from \'vue\'\nimport { useSystemSettingStore } from \'@/store\'\nimport { useDark, useFullscreen, useToggle } from \'@vueuse/core\'\nimport { PersistenceOptions } from \'pinia-plugin-persistedstate\'\nimport { IframeInfo, LayOutSize, NavbarTag } from \'@/types\'\n\n// 持久化配置\nconst getPersistConfig = () => {\n	const key = \'appStore\'\n	// 忽略字段\n	const originOmitList = [\'layoutMainRef\']\n	// 根据环境设置持久化配置\n	// if (import.meta.env.PROD) {\n	//\n	// }\n	return {\n		key,\n		storage: localStorage,\n		// 支持动态配置忽略字段\n		omit: (_: never) => {\n			const systemSettingStore = useSystemSettingStore()\n			if (!systemSettingStore.isOpenTagCache) {\n				originOmitList.push(\'tagList\')\n			}\n			return originOmitList\n		}\n	} as unknown as PersistenceOptions\n}\n\nexport const useAppStore = defineStore(\n	\'app\',\n	() => {\n		// 状态\n		// 折叠状态\n		const isCollapse = ref(false)\n		// 标签列表\n		const tagList = ref<NavbarTag[]>([])\n		// 缓存组件列表\n		const cacheList = ref<string[]>([])\n		// 布局大小\n		const layoutSize = ref<LayOutSize>(\'default\')\n		// iframe缓存列表\n		const iframeCacheList = ref<IframeInfo[]>([])\n		// 主题模式\n		const isDark = useDark({\n			selector: \'html\',\n			attribute: \'class\',\n			valueDark: \'dark\',\n			valueLight: \'light\'\n		})\n		// Layout Main Ref\n		const layoutMainRef = ref()\n\n		// 计算属性\n		// 标签数量\n		const tagLength = computed(() => tagList.value.length)\n\n		// actions\n		// 切换折叠状态\n		const toggleCollapse = () => {\n			isCollapse.value = !isCollapse.value\n		}\n\n		const { toggle: toolFullscreen } = useFullscreen(layoutMainRef)\n\n		// 添加标签\n		const addTag = (tag: NavbarTag) => {\n			const isExist = tagList.value.find(item => item.fullPath === tag.fullPath)\n			const includes = tag.fullPath.includes(\'redirect\')\n			if (!isExist && !includes) {\n				tagList.value.push(tag)\n			}\n		}\n\n		// 删除标签\n		const removeTag = (tag: NavbarTag) => {\n			tagList.value = tagList.value.filter(item => item.fullPath !== tag.fullPath)\n		}\n\n		// 批量删除标签\n		const removeTags = (removeTagList: NavbarTag[]) => {\n			tagList.value = tagList.value.filter(item => !removeTagList.some(tag => tag.fullPath === item.fullPath))\n		}\n\n		// 添加所有标签\n		const addAllTags = (addTagList: NavbarTag[]) => {\n			tagList.value = addTagList\n		}\n\n		// 删除所有标签\n		const removeAllTags = () => {\n			tagList.value = []\n		}\n\n		// 添加缓存路由\n		const addCacheComponent = (name: string) => {\n			if (!cacheList.value.includes(name)) {\n				cacheList.value.push(name)\n			}\n		}\n\n		// 删除缓存路由\n		const removeCacheComponent = (name: string) => {\n			const indexOf = cacheList.value.indexOf(name)\n			if (indexOf > -1) {\n				cacheList.value.splice(indexOf, 1)\n			}\n		}\n\n		// 批量删除缓存路由\n		const removeCacheComponentList = (nameList: string[]) => {\n			if (!nameList || nameList.length === 0) {\n				return\n			}\n			for (const name of nameList) {\n				removeCacheComponent(name)\n			}\n		}\n\n		// 删除所有缓存\n		const removeAllCache = () => {\n			cacheList.value = []\n		}\n\n		// 添加iframe路由\n		const addIframeCache = (iframeInfo: IframeInfo) => {\n			if (iframeCacheList.value.some(item => item.fullPath === iframeInfo.fullPath)) {\n				return\n			}\n			iframeCacheList.value.push(iframeInfo)\n		}\n\n		// 删除iframe路由\n		const removeIframeCache = (name: string) => {\n			iframeCacheList.value = iframeCacheList.value.filter(item => item.name !== name)\n		}\n\n		// 批量删除iframe路由\n		const removeIframeCacheList = (nameList: string[]) => {\n			if (!nameList || nameList.length === 0) {\n				return\n			}\n			for (const name of nameList) {\n				removeIframeCache(name)\n			}\n		}\n\n		// 删除全部iframe路由\n		const removeAllIframeCache = () => {\n			iframeCacheList.value = []\n		}\n\n		// 设置布局大小\n		const setLayoutSize = (size: LayOutSize) => {\n			layoutSize.value = size\n		}\n\n		// 切换主题模式\n		const toggleDark = useToggle(isDark)\n\n		return {\n			isCollapse,\n			tagList,\n			layoutSize,\n			cacheList,\n			iframeCacheList,\n			isDark,\n			layoutMainRef,\n			tagLength,\n			toggleCollapse,\n			toolFullscreen,\n			addTag,\n			removeTag,\n			addAllTags,\n			removeAllTags,\n			removeTags,\n			addCacheComponent,\n			removeCacheComponent,\n			removeCacheComponentList,\n			removeAllCache,\n			addIframeCache,\n			removeIframeCache,\n			removeIframeCacheList,\n			removeAllIframeCache,\n			setLayoutSize,\n			toggleDark\n		}\n	},\n	{\n		persist: getPersistConfig()\n	}\n)\n', NULL, NULL, '2025-08-07 10:20:05', '2025-11-24 16:17:09', 0);
INSERT INTO `gen_template` VALUES (282, 30, 651, 'router.ts.ftl', 'index.ts', 1, '全局路由文件', 'import { createRouter, createWebHashHistory } from \'vue-router\'\nimport { routeGuard } from \'@/router/guard\'\nimport { constantRoutes } from \'@/router/constant\'\n\n// 创建路由实例\nexport const router = createRouter({\n	history: createWebHashHistory(),\n	scrollBehavior(_to, _from, savedPosition) {\n		if (savedPosition) {\n			return savedPosition\n		} else {\n			return { top: 0 }\n		}\n	},\n	// 常量路由\n	routes: constantRoutes\n})\n\n// 路由拦截\nrouteGuard(router)\n', NULL, NULL, '2025-08-07 10:20:42', '2025-11-05 14:46:23', 0);
INSERT INTO `gen_template` VALUES (283, 30, 1909, '404.vue.ftl', '404.vue', 1, '404页面', '<template>\n	<div class=\"layout-error\">\n		<img src=\"@/assets/404.png\" alt=\"404\" />\n		<div>\n			<el-button type=\"primary\" @click=\"onBack\">返回</el-button>\n			<el-button type=\"success\" @click=\"onToHome\">主页</el-button>\n		</div>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useRouter } from \'vue-router\'\n\nconst router = useRouter()\n\nconst onBack = () => {\n	router.back()\n}\nconst onToHome = () => {\n	router.replace(\'/\')\n}\n</script>\n\n<style lang=\"scss\" scoped>\n.layout-error {\n	img {\n		width: 800px;\n	}\n	display: flex;\n	flex-direction: column;\n	align-items: center;\n}\n</style>\n', NULL, NULL, '2025-08-07 10:21:16', '2025-09-25 14:54:54', 0);
INSERT INTO `gen_template` VALUES (284, 30, 655, 'redirect.vue.ftl', 'redirect.vue', 1, '重定向页面', '<template>\n	<div></div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useRoute, useRouter } from \'vue-router\'\n\nconst route = useRoute()\nconst router = useRouter()\nconst { params, query } = route\nconst { path } = params\n\ndefineOptions({\n	name: \'Redirect\'\n})\nrouter.replace({ path: \'/\' + path, query })\n</script>\n', NULL, NULL, '2025-08-07 10:21:45', '2025-11-24 16:23:06', 1);
INSERT INTO `gen_template` VALUES (285, 30, 657, 'index.vue.ftl', 'index.vue', 1, '首页页面', '<template>\n	<h1>首页</h1>\n</template>\n\n<script setup lang=\"ts\">\n</script>\n<style scoped></style>\n', NULL, NULL, '2025-08-07 10:22:17', '2025-08-12 10:41:36', 0);
INSERT INTO `gen_template` VALUES (286, 30, 659, 'layout-index.vue.ftl', 'index.vue', 1, '布局首页页面', '<template>\n	<el-container class=\"layout-container\">\n		<!-- 侧边栏 -->\n		<el-aside class=\"layout-sidebar\" :style=\"{ width: calculateLayoutSidebarWidth }\">\n			<layout-sidebar></layout-sidebar>\n		</el-aside>\n		<el-container direction=\"vertical\">\n			<!-- 顶栏 -->\n			<el-header class=\"layout-header\">\n				<layout-navbar></layout-navbar>\n			</el-header>\n			<!-- 内容 -->\n			<el-main ref=\"layoutMainRef\" class=\"layout-main\">\n				<layout-main></layout-main>\n			</el-main>\n		</el-container>\n	</el-container>\n</template>\n\n<script setup lang=\"ts\">\nimport LayoutSidebar from \'@/layout/sidebar/index.vue\'\nimport LayoutNavbar from \'@/layout/navbar/index.vue\'\nimport LayoutMain from \'@/layout/main/index.vue\'\nimport { useAppStore, useSystemSettingStore } from \'@/store\'\nimport { computed } from \'vue\'\nimport { storeToRefs } from \'pinia\'\n\ndefineOptions({\n	name: \'Layout\'\n})\n\nconst appStore = useAppStore()\nconst systemSettingStore = useSystemSettingStore()\nconst { layoutMainRef } = storeToRefs(appStore)\n\n// 计算布局宽度\nconst calculateLayoutSidebarWidth = computed(() => {\n	return (appStore.isCollapse ? systemSettingStore.menuFoldWidth : systemSettingStore.menuExpandWidth) + \'px\'\n})\n</script>\n', NULL, NULL, '2025-08-07 10:23:05', '2025-11-24 16:15:25', 0);
INSERT INTO `gen_template` VALUES (287, 30, 661, 'layout-navbar-index.vue.ftl', 'index.vue', 1, '布局顶栏页面', '<template>\n	<div>\n		<!-- 工具栏 -->\n		<div class=\"navbar-toolbar\">\n			<!-- 左侧区域：折叠按钮 + 面包屑 -->\n			<div class=\"navbar-toolbar-left\">\n				<!-- 折叠按钮 -->\n				<el-icon v-if=\"systemSettingStore.isOpenMenuCollapseButton\" :size=\"18\" class=\"collapse-icon\" @click=\"appStore.toggleCollapse()\">\n					<Expand v-if=\"appStore.isCollapse\"></Expand>\n					<Fold v-else></Fold>\n				</el-icon>\n				<!-- 面包屑 -->\n				<breadcrumb v-if=\"systemSettingStore.isOpenBreadcrumb\"></breadcrumb>\n			</div>\n\n			<!-- 右侧区域 -->\n			<div class=\"navbar-toolbar-right\">\n				<!-- 菜单搜索 -->\n				<menu-search v-if=\"systemSettingStore.isOpenMenuSearch\"></menu-search>\n				<!-- 刷新当前页 -->\n				<refresh-current-page v-if=\"systemSettingStore.isOpenRefreshPage\"></refresh-current-page>\n				<!-- 切换布局大小	-->\n				<layout-size v-if=\"systemSettingStore.isOpenLayoutSetting\"></layout-size>\n				<!-- 全屏按钮 -->\n				<el-tooltip v-if=\"systemSettingStore.isOpenFullscreen\" :content=\"isFullscreen ? \'退出全屏\' : \'开启全屏\'\" effect=\"dark\" placement=\"bottom\">\n					<svg-icon :icon=\"isFullscreen ? \'icon-fullscreen-exit\' : \'icon-fullscreen\'\" size=\"18px\" is-pointer @click=\"toggle()\"></svg-icon>\n				</el-tooltip>\n				<!-- 日间/夜间模式切换  -->\n				<theme-switch v-if=\"systemSettingStore.isOpenThemeSwitch\"></theme-switch>\n				<!-- 用户下拉菜单 -->\n				<user-dropdown></user-dropdown>\n				<!-- 系统设置 -->\n				<system-setting></system-setting>\n			</div>\n		</div>\n		<!-- 标签栏 -->\n		<tag-bar v-if=\"systemSettingStore.isOpenTag\"></tag-bar>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { Expand, Fold } from \'@element-plus/icons-vue\'\nimport TagBar from \'@/layout/navbar/components/tag-bar.vue\'\nimport Breadcrumb from \'@/layout/navbar/components/breadcrumb.vue\'\nimport MenuSearch from \'@/layout/navbar/components/menu-search.vue\'\nimport SvgIcon from \'@/components/svg-icon/index.vue\'\nimport SystemSetting from \'@/layout/navbar/components/system-setting.vue\'\nimport RefreshCurrentPage from \'@/layout/navbar/components/refresh-current-page.vue\'\nimport LayoutSize from \'@/layout/navbar/components/layout-size.vue\'\nimport ThemeSwitch from \'@/layout/navbar/components/theme-switch.vue\'\nimport UserDropdown from \'@/layout/navbar/components/user-dropdown.vue\'\nimport { useFullscreen } from \'@vueuse/core\'\nimport { useAppStore, useSystemSettingStore } from \'@/store\'\n\ndefineOptions({\n	name: \'LayoutNavbar\'\n})\n\nconst { isFullscreen, toggle } = useFullscreen()\nconst appStore = useAppStore()\nconst systemSettingStore = useSystemSettingStore()\n</script>\n\n<style scoped>\n.navbar-toolbar {\n	height: 35px;\n	display: flex;\n	justify-content: space-between;\n	align-items: center;\n	padding: 0 10px;\n	margin-top: 6px;\n	border-bottom: 1px solid var(--el-border-color);\n}\n\n.navbar-toolbar-left {\n	display: flex;\n	align-items: center;\n	gap: 15px;\n}\n\n.navbar-toolbar-right {\n	display: flex;\n	align-items: center;\n	gap: 15px;\n}\n\n.collapse-icon {\n	cursor: pointer;\n}\n</style>\n', NULL, NULL, '2025-08-07 10:23:48', '2025-11-24 16:14:11', 0);
INSERT INTO `gen_template` VALUES (288, 30, 663, 'breadcrumb.vue.ftl', 'breadcrumb.vue', 1, '面包屑页面', '<template>\n	<el-breadcrumb separator=\"/\">\n		<el-breadcrumb-item v-for=\"item in breadcrumbList\" :key=\"item.title\">\n			<template #default>\n				<icon-text-tooltip\n					:enable-icon=\"systemSettingStore.isOpenBreadcrumbIcon\"\n					:icon=\"item.icon\"\n					:title=\"item.title\"\n					:placement=\"\'bottom\'\"\n				></icon-text-tooltip>\n			</template>\n		</el-breadcrumb-item>\n	</el-breadcrumb>\n</template>\n\n<script setup lang=\"ts\">\nimport IconTextTooltip from \'@/components/icon-text-tooltip/index.vue\'\nimport { useSystemSettingStore } from \'@/store\'\nimport { onMounted, ref, watch } from \'vue\'\nimport { useRoute, useRouter } from \'vue-router\'\n\ndefineOptions({\n	name: \'Breadcrumb\'\n})\n\n// 面包屑\ninterface Breadcrumb {\n	// 标题\n	title: string\n	// 图标\n	icon: string\n}\n\nconst route = useRoute()\nconst router = useRouter()\nconst systemSettingStore = useSystemSettingStore()\n\n// 面包屑列表\nconst breadcrumbList = ref<Breadcrumb[]>([])\n\n// 挂载时设置面包屑\nonMounted(() => {\n	setBreadcrumb(route.fullPath)\n})\n\n// 动态设置面包屑\nwatch(\n	() => route.fullPath,\n	newPath => {\n		if (newPath.startsWith(\'/redirect\')) {\n			return\n		}\n		setBreadcrumb(newPath)\n	}\n)\n\n// 设置面包屑\nconst setBreadcrumb = (fullPath: string) => {\n	const matched: Breadcrumb[] = []\n	const paths = fullPath.split(\'/\').filter(p => p)\n\n	let currentPath = \'\'\n	for (const path of paths) {\n		<#noparse>currentPath += `/${path}`</#noparse>\n		const breadcrumb = findRouteByPath(currentPath)\n		if (breadcrumb.title) {\n			matched.push(breadcrumb)\n		}\n	}\n	breadcrumbList.value = matched\n}\n\n/**\n * 查找路径对应的 meta.title\n */\nconst findRouteByPath = (targetPath: string): Breadcrumb => {\n	// 使用 Vue Router 的路径匹配算法\n	const matchedRoute = router.resolve(targetPath)\n\n	if (matchedRoute?.meta?.title) {\n		return {\n			title: matchedRoute.meta.title as string,\n			icon: matchedRoute.meta.icon as string\n		}\n	} else {\n		return { title: \'\', icon: \'\' }\n	}\n}\n</script>\n<style scoped>\n:deep(.el-breadcrumb__inner),\n:deep(.el-breadcrumb__inner.is-link),\n:deep(.el-breadcrumb__separator) {\n	color: var(--el-text-color-primary) !important;\n}\n</style>\n', NULL, NULL, '2025-08-07 10:24:19', '2025-11-24 16:40:25', 0);
INSERT INTO `gen_template` VALUES (289, 30, 663, 'menu-search.vue.ftl', 'menu-search.vue', 1, '菜单搜索页面', '<template>\n	<div class=\"search-container\">\n		<el-tooltip content=\"菜单搜索\" effect=\"dark\" placement=\"bottom\">\n			<el-icon :size=\"18\" class=\"search-icon\" @click=\"openSearch\">\n				<Search></Search>\n			</el-icon>\n		</el-tooltip>\n\n		<!-- 搜索框 -->\n		<el-dialog v-model=\"searchState.visible\" title=\"菜单搜索\" width=\"45%\" destroy-on-close @opened=\"onDialogOpened\">\n			<el-input\n				ref=\"searchInputRef\"\n				v-model=\"searchState.keyword\"\n				placeholder=\"请输入菜单名称\"\n				clearable\n				:prefix-icon=\"Search\"\n				class=\"search-input\"\n				@input=\"querySearch\"\n			></el-input>\n\n			<!-- 树形结构展示 -->\n			<el-scrollbar ref=\"scrollbarRef\" max-height=\"400px\" class=\"search-results\">\n				<MenuTreeNode v-for=\"node in searchState.matchItemList\" :key=\"node.title\" :node=\"node\" :level=\"0\" :on-select=\"handleSelect\"></MenuTreeNode>\n				<div v-if=\"!searchState.matchItemList.length\" class=\"no-results\">\n					<el-text>无匹配结果</el-text>\n				</div>\n			</el-scrollbar>\n			<template #footer></template>\n		</el-dialog>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { Search } from \'@element-plus/icons-vue\'\nimport { nextTick, reactive, ref } from \'vue\'\nimport { useUserStore } from \'@/store\'\nimport { MenuInfo } from \'@/types\'\nimport { useRoute, useRouter } from \'vue-router\'\nimport { useDebounceFn } from \'@vueuse/core\'\nimport { cloneObject, resetReactiveObject } from \'@/utils/tool\'\nimport MenuTreeNode, { TreeNode } from \'@/layout/navbar/components/menu-tree-node.vue\'\n\ndefineOptions({\n	name: \'MenuSearch\'\n})\n\nconst INIT_STATE = {\n	visible: false,\n	keyword: \'\',\n	searchItemList: [] as TreeNode[],\n	matchItemList: [] as TreeNode[]\n}\n\nconst searchState = reactive(cloneObject(INIT_STATE))\n\nconst searchInputRef = ref()\nconst scrollbarRef = ref()\nconst userStore = useUserStore()\nconst route = useRoute()\nconst router = useRouter()\n\n// 构建树结构\nconst buildMenuTree = (menuList: MenuInfo[]): TreeNode[] => {\n	const build = (items: MenuInfo[]): TreeNode[] => {\n		return items\n			.filter(item => !item.meta.hidden && item.meta.type !== 2)\n			.map(item => {\n				const node: TreeNode = {\n					title: item.meta.title,\n					icon: item.meta.icon,\n					type: item.meta.type,\n					path: item.path,\n					externalUrl: item.meta.externalUrl\n				}\n				if (item.children?.length) {\n					node.children = build(item.children)\n				}\n				return node\n			})\n	}\n	return build(menuList)\n}\n\n// 打开搜索框\nconst openSearch = () => {\n	resetReactiveObject(searchState, INIT_STATE)\n	searchState.visible = true\n	searchState.searchItemList = buildMenuTree(userStore.menuList)\n	searchState.matchItemList = searchState.searchItemList\n}\n\n// 搜索逻辑（防抖）\nconst debouncedQuerySearch = useDebounceFn((queryString?: string) => {\n	const raw = queryString !== undefined ? queryString : searchState.keyword\n	if (!raw || !raw.trim()) {\n		searchState.matchItemList = searchState.searchItemList\n		return\n	}\n\n	const keyword = raw.toLowerCase()\n\n	const filterTree = (nodes: TreeNode[]): TreeNode[] => {\n		return nodes\n			.map(node => {\n				const children = node.children ? filterTree(node.children) : []\n				if (node.title.toLowerCase().includes(keyword) || children.length > 0) {\n					return { ...node, children }\n				}\n				return null\n			})\n			.filter(Boolean) as TreeNode[]\n	}\n\n	searchState.matchItemList = filterTree(searchState.searchItemList)\n}, 150)\n\nconst querySearch = (queryString?: string) => debouncedQuerySearch(queryString)\n\n// 事件\nconst onDialogOpened = async () => {\n	await nextTick()\n	searchInputRef.value?.focus()\n	scrollbarRef.value?.setScrollTop(0)\n}\n\n// 选择树节点\nconst handleSelect = (node: TreeNode) => {\n	searchState.visible = false\n	// 如果是菜单或者iframe，则路由跳转\n	if ([1, 3].includes(node.type)) {\n		if (node.path != route.path) {\n			router.push(node.path!)\n		}\n	} else {\n		// 如果是外链\n		window.open(node.externalUrl!)\n	}\n	if (node.path != userStore.activeMenuPath) {\n		userStore.setActiveMenuPath(node.path!)\n	}\n}\n</script>\n\n<style scoped>\n.search-container {\n	display: flex;\n	align-items: center;\n}\n.search-icon {\n	cursor: pointer;\n}\n.search-results {\n	margin-top: 8px;\n	padding-left: 8px;\n}\n.search-input {\n	margin-bottom: 6px;\n}\n.no-results {\n	padding: 16px 0;\n	text-align: center;\n	color: #8c8c8c;\n}\n</style>\n', NULL, NULL, '2025-08-07 10:25:01', '2025-11-24 16:11:55', 0);
INSERT INTO `gen_template` VALUES (290, 30, 663, 'refresh-current-page.vue.ftl', 'refresh-current-page.vue', 1, '刷新当前页页面', '<template>\n	<div class=\"refresh-container\">\n		<el-tooltip :content=\"\'刷新页面\'\" effect=\"dark\" placement=\"bottom\">\n			<el-icon :size=\"18\" class=\"refresh-icon\" @click=\"refreshPage()\">\n				<Refresh></Refresh>\n			</el-icon>\n		</el-tooltip>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { Refresh } from \'@element-plus/icons-vue\'\nimport { usePageRefresher } from \'@/hooks\'\n\ndefineOptions({\n	name: \'RefreshCurrentPage\'\n})\nconst { refreshPage } = usePageRefresher()\n</script>\n<style scoped>\n.refresh-icon {\n	cursor: pointer;\n}\n.refresh-container {\n	display: flex;\n	align-items: center;\n}\n</style>\n', NULL, NULL, '2025-08-07 10:25:29', '2025-11-24 16:12:52', 0);
INSERT INTO `gen_template` VALUES (291, 30, 663, 'tag-bar.vue.ftl', 'tag-bar.vue', 1, '标签页页面', '<template>\n	<el-tabs ref=\"tagWrapperRef\" v-model=\"userStore.activeMenuPath\" type=\"card\" @tab-click=\"handleTabClick\" @tab-remove=\"handleTabRemove\">\n		<!-- 标签 -->\n		<el-tab-pane\n			v-for=\"tag in appStore.tagList\"\n			:key=\"tag.fullPath\"\n			:name=\"tag.fullPath\"\n			:closable=\"tag.fullPath != defaultMenu || appStore.tagLength > 1\"\n		>\n			<template #label>\n				<icon-text-tooltip :enable-icon=\"systemSettingStore.isOpenTagIcon\" :icon=\"tag.icon\" is-pointer :title=\"tag.title\"></icon-text-tooltip>\n			</template>\n		</el-tab-pane>\n	</el-tabs>\n\n	<!-- 右键菜单 -->\n	<div v-if=\"tagMenuVisible\" class=\"tag-context-menu\" :style=\"menuPosition\">\n		<tag-menu\n			:default-menu=\"defaultMenu\"\n			:current-menu-tag=\"currentMenuTag\"\n			:current-menu-tag-index=\"currentMenuTagIndex\"\n			@close-current-tag=\"closeCurrentTag()\"\n			@refresh-current-tag=\"refreshCurrentTag()\"\n			@close-other-tags=\"closeOtherTags()\"\n			@close-left-tag=\"closeLeftTag()\"\n			@close-right-tag=\"closeRightTag()\"\n			@close-all-tags=\"closeAllTags()\"\n			@open-new-window=\"openNewWindow()\"\n			@full-screen=\"fullScreen()\"\n		></tag-menu>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useRoute, useRouter } from \'vue-router\'\nimport { computed, nextTick, onMounted, onUnmounted, reactive, ref } from \'vue\'\nimport TagMenu from \'@/layout/navbar/components/tag-menu.vue\'\nimport Sortable from \'sortablejs\'\nimport { usePageRefresher } from \'@/hooks\'\nimport { useAppStore, useSystemSettingStore, useUserStore } from \'@/store\'\nimport { NavbarTag } from \'@/types\'\nimport IconTextTooltip from \'@/components/icon-text-tooltip/index.vue\'\nimport { TabsPaneContext } from \'element-plus\'\n\ndefineOptions({\n	name: \'TagBar\'\n})\n\nconst route = useRoute()\nconst router = useRouter()\nconst tagMenuVisible = ref(false)\nconst menuPosition = reactive({\n	left: \'0px\',\n	top: \'0px\'\n})\nconst currentMenuTag = reactive({} as NavbarTag)\nconst currentMenuTagIndex = ref(0)\nconst appStore = useAppStore()\nconst systemSettingStore = useSystemSettingStore()\nconst userStore = useUserStore()\nconst tagWrapperRef = ref()\n\nonMounted(() => {\n	// 点击页面任意位置关闭右键菜单\n	document.addEventListener(\'click\', closeTagMenu)\n})\n\n// 默认菜单\nconst defaultMenu = computed(() => systemSettingStore.menuDefault)\n\n// 实现标签页的拖拽效果\nonMounted(() => {\n	nextTick(() => {\n		const tabsWrapper = tagWrapperRef.value.$el.querySelector(\'.el-tabs__nav\') as HTMLElement\n		if (!tabsWrapper) {\n			return\n		}\n		new Sortable(tabsWrapper, {\n			animation: 200,\n			handle: \'.el-tabs__item\', // 拖拽手柄\n			onEnd: evt => {\n				// el-tab会有一个高亮的样式需要排除掉\n				const oldIndex = evt.oldIndex! - 1\n				const newIndex = evt.newIndex! - 1\n				if (oldIndex !== null && newIndex !== null && oldIndex !== newIndex) {\n					const newTags = [...appStore.tagList]\n					const movedTag = newTags.splice(oldIndex!, 1)[0]\n					newTags.splice(newIndex!, 0, movedTag)\n					appStore.addAllTags(newTags)\n					// 激活被移动的标签\n					if (systemSettingStore.isOpenTagDragActivated) {\n						if (route.fullPath != movedTag.fullPath) {\n							router.push(movedTag.fullPath)\n						}\n					}\n				}\n			}\n		})\n	})\n})\n\nonMounted(() => {\n	nextTick(() => {\n		const nav = tagWrapperRef.value.$el.querySelector(\'.el-tabs__nav\')\n		if (!nav) {\n			return\n		}\n\n		nav.addEventListener(\'contextmenu\', (e: MouseEvent) => {\n			const item = (e.target as HTMLElement).closest(\'.el-tabs__item\')\n			if (!item) {\n				return\n			}\n\n			const index = Array.from(nav.children).indexOf(item)\n			const tag = appStore.tagList[index]\n\n			showTagMenu(e, tag, index)\n		})\n	})\n})\n\n// 组件卸载时移除事件监听\nonUnmounted(() => {\n	document.removeEventListener(\'click\', closeTagMenu)\n})\n\n// 处理点击标签\nconst handleTabClick = (tab: TabsPaneContext, _: Event) => {\n	const fullPath = tab.paneName as string\n	if (fullPath != route.fullPath) {\n		router.push(fullPath)\n	}\n}\n\n// 处理标签删除\nconst handleTabRemove = (fullPath: string) => {\n	const index = appStore.tagList.findIndex(tag => tag.fullPath === fullPath)\n	handleClose(index, appStore.tagList[index])\n}\n\n// 处理关闭单个标签\nconst handleClose = (index: number, tag: NavbarTag) => {\n	// 新增：首页保护逻辑（当只有一个标签且是首页时不允许关闭）\n	if (appStore.tagLength === 1 && tag.fullPath === defaultMenu.value) {\n		return // 直接返回，不执行关闭操作\n	}\n\n	// 删除对应的缓存组件和标签\n	deleteCacheAndTag([tag])\n\n	// 判断当前标签页是否为当前路由\n	if (tag.fullPath === route.fullPath) {\n		let to = defaultMenu.value // 默认跳转首页\n\n		// 关闭后如果还有标签页\n		if (appStore.tagLength > 0) {\n			// 优先尝试右侧标签\n			if (index < appStore.tagLength) {\n				to = appStore.tagList[index].fullPath\n			} else if (index > 0) {\n				// 右侧无标签时选择左侧\n				to = appStore.tagList[index - 1].fullPath\n			}\n		}\n		// 跳转到对应路由\n		router.push(to)\n	}\n}\n\n// 显示标签右键菜单\nconst showTagMenu = (e: MouseEvent, tag: NavbarTag, index: number) => {\n	e.preventDefault()\n	Object.assign(currentMenuTag, tag)\n	currentMenuTagIndex.value = index\n\n	const x = e.clientX\n	const y = e.clientY\n\n	const menuWidth = 80\n	const menuHeight = 200\n	const windowWidth = window.innerWidth\n	const windowHeight = window.innerHeight\n\n	Object.assign(menuPosition, {\n		<#noparse>left: `${Math.min(x, windowWidth - menuWidth)}px`,\n		top: `${Math.min(y, windowHeight - menuHeight)}px`</#noparse>\n	})\n\n	tagMenuVisible.value = true\n}\n\n// 关闭标签菜单\nconst closeTagMenu = () => {\n	tagMenuVisible.value = false\n}\n\n// 刷新当前标签页\nconst refreshCurrentTag = () => {\n	if (route.fullPath != currentMenuTag.fullPath) {\n		router.push(currentMenuTag.fullPath)\n		setTimeout(() => refreshPage(), 10)\n	} else {\n		refreshPage()\n	}\n	closeTagMenu()\n}\n\n// 关闭当前标签\nconst closeCurrentTag = () => {\n	handleClose(currentMenuTagIndex.value, currentMenuTag)\n	closeTagMenu()\n}\n\n// 关闭其他标签\nconst closeOtherTags = () => {\n	const currentPath = currentMenuTag.fullPath\n	// 保留当前标签，关闭其他所有标签\n	const deleteTagList = appStore.tagList.filter(tag => tag.fullPath !== currentPath)\n	deleteCacheAndTag(deleteTagList)\n	router.push(currentPath)\n	closeTagMenu()\n}\n\n// 关闭所有标签\nconst closeAllTags = () => {\n	deleteCacheAndTag(appStore.tagList.filter(item => item.fullPath !== defaultMenu.value))\n	closeTagMenu()\n	// 回到首页\n	if (route.fullPath !== defaultMenu.value) {\n		router.push(defaultMenu.value)\n	}\n}\n\n// 关闭左侧标签\nconst closeLeftTag = () => {\n	// 激活的标签索引\n	const activeTagIndex = appStore.tagList.findIndex(tag => tag.fullPath === route.fullPath)\n	const deleteTagList = appStore.tagList.filter((_, index) => index < currentMenuTagIndex.value)\n	deleteCacheAndTag(deleteTagList)\n	// 检查当前激活的标签是否在被关闭的标签中\n	if (activeTagIndex < currentMenuTagIndex.value) {\n		// 当前激活标签在被关闭范围内，切换到右键点击的标签\n		router.push(currentMenuTag.fullPath)\n	}\n	closeTagMenu()\n}\n\n// 关闭右侧标签\nconst closeRightTag = () => {\n	// 激活的标签索引\n	const activeTagIndex = appStore.tagList.findIndex(tag => tag.fullPath === route.fullPath)\n	// 保留当前标签及其左侧所有标签\n	const deleteTagList = appStore.tagList.filter((_, index) => index > currentMenuTagIndex.value)\n	deleteCacheAndTag(deleteTagList)\n	// 检查当前激活的标签是否在被关闭的标签中\n	if (activeTagIndex > currentMenuTagIndex.value) {\n		// 当前激活标签在被关闭范围内，切换到右键点击的标签\n		router.push(currentMenuTag.fullPath)\n	}\n	closeTagMenu()\n}\n\n// 删除缓存和标签\nconst deleteCacheAndTag = (tagList: NavbarTag[]) => {\n	if (!tagList || tagList.length === 0) {\n		return\n	}\n	const nameList = tagList.map(item => item.name)\n\n	// 删除缓存\n	appStore.removeCacheComponentList(nameList)\n	appStore.removeIframeCacheList(nameList)\n\n	// 删除标签\n	appStore.removeTags(tagList)\n}\n\n// 打开新窗口\nconst openNewWindow = () => {\n	const resolve = router.resolve(currentMenuTag.fullPath)\n	// 构造完整 URL\n	const fullUrl = window.location.origin + resolve.href\n	window.open(fullUrl, \'_blank\')\n}\n\n// 窗口最大化\nconst fullScreen = () => {\n	appStore.toolFullscreen()\n}\n\nconst { refreshPage } = usePageRefresher()\n</script>\n\n<style scoped>\n:deep(.el-tabs__header) {\n	margin-bottom: 0;\n}\n\n.tag-context-menu {\n	position: fixed;\n	align-items: center;\n	background: var(--el-tag-bg-color);\n	border: 1px solid var(--el-border-color);\n	z-index: 1000;\n	min-width: 100px;\n}\n</style>\n', '', NULL, '2025-08-07 10:26:33', '2025-11-24 16:41:59', 0);
INSERT INTO `gen_template` VALUES (292, 30, 663, 'tag-menu.vue.ftl', 'tag-menu.vue', 1, '标签菜单页面', '<template>\n	<div class=\"icon-list\">\n		<div class=\"icon-item\" @click=\"emits(\'refreshCurrentTag\')\">\n			<el-icon size=\"10\"><Refresh></Refresh></el-icon>\n			<span>刷新当前</span>\n		</div>\n		<div class=\"icon-item\" @click=\"emits(\'openNewWindow\')\">\n			<svg-icon icon=\"icon-new-window\" size=\"10px\"></svg-icon>\n			<span>打开窗口</span>\n		</div>\n		<div class=\"icon-item\" @click=\"emits(\'fullScreen\')\">\n			<svg-icon icon=\"icon-fullscreen\" size=\"10px\"></svg-icon>\n			<span>内容全屏</span>\n		</div>\n		<div v-if=\"props.currentMenuTag.fullPath != defaultMenu || appStore.tagLength > 1\" class=\"icon-item\" @click=\"emits(\'closeCurrentTag\')\">\n			<el-icon size=\"10\"><CloseBold></CloseBold></el-icon>\n			<span>关闭当前</span>\n		</div>\n		<div v-if=\"props.currentMenuTagIndex > 0\" class=\"icon-item\" @click=\"emits(\'closeLeftTag\')\">\n			<el-icon size=\"10\"><Back></Back></el-icon>\n			<span>关闭左侧</span>\n		</div>\n		<div v-if=\"props.currentMenuTagIndex < appStore.tagLength - 1\" class=\"icon-item\" @click=\"emits(\'closeRightTag\')\">\n			<el-icon size=\"10\"><Right></Right></el-icon>\n			<span>关闭右侧</span>\n		</div>\n		<div v-if=\"appStore.tagLength > 1\" class=\"icon-item\" @click=\"emits(\'closeOtherTags\')\">\n			<svg-icon icon=\"icon-close-others\" size=\"10px\"></svg-icon>\n			<span>关闭其他</span>\n		</div>\n		<div v-if=\"appStore.tagLength > 1\" class=\"icon-item\" @click=\"emits(\'closeAllTags\')\">\n			<svg-icon icon=\"icon-close-all\" size=\"10px\"></svg-icon>\n			<span>关闭全部</span>\n		</div>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { Back, CloseBold, Refresh, Right } from \'@element-plus/icons-vue\'\nimport { useAppStore } from \'@/store\'\nimport { NavbarTag } from \'@/types\'\nimport { defineEmits, defineProps, PropType } from \'vue\'\nimport SvgIcon from \'@/components/svg-icon/index.vue\'\n\ndefineOptions({\n	name: \'TagMenu\'\n})\n\nconst appStore = useAppStore()\n\nconst props = defineProps({\n	defaultMenu: {\n		type: String,\n		required: true\n	},\n	currentMenuTag: {\n		type: Object as PropType<NavbarTag>,\n		required: true\n	},\n	currentMenuTagIndex: {\n		type: Number,\n		required: true\n	}\n})\n\nconst emits = defineEmits([\n	\'refreshCurrentTag\',\n	\'closeCurrentTag\',\n	\'closeAllTags\',\n	\'closeOtherTags\',\n	\'closeLeftTag\',\n	\'closeRightTag\',\n	\'openNewWindow\',\n	\'fullScreen\'\n])\n</script>\n\n<style scoped>\n.icon-list {\n	display: flex;\n	flex-direction: column;\n	gap: 10px;\n	padding: 5px;\n	width: 70px;\n}\n\n.icon-item {\n	display: flex;\n	align-items: center;\n	gap: 5px;\n	font-size: 12px;\n	width: 100%;\n	cursor: pointer;\n	padding: 5px 10px;\n	text-align: left;\n	transition:\n		background-color 0.2s ease,\n		color 0.2s ease;\n}\n\n/* 悬停效果 - 亮色模式 */\n.icon-item:hover {\n	background-color: #f0f0f0;\n	color: #333;\n}\n\n/* 暗黑模式样式 */\nhtml.dark .icon-item:hover {\n	background-color: #3a3a3a;\n	color: #e0e0e0;\n}\n</style>\n', NULL, NULL, '2025-08-07 10:29:04', '2025-11-24 16:13:36', 0);
INSERT INTO `gen_template` VALUES (293, 30, 669, 'layout-sidebar-index.vue.ftl', 'index.vue', 1, '侧边首页', '<template>\n	<!-- 项目logo和文字 -->\n	<logo v-if=\"systemSettingStore.isOpenLogo\"></logo>\n	<!-- 菜单 -->\n	<menu-index></menu-index>\n</template>\n\n<script setup lang=\"ts\">\nimport Logo from \'@/layout/sidebar/components/logo.vue\'\nimport MenuIndex from \'@/layout/sidebar/components/menu/menu-index.vue\'\nimport { useSystemSettingStore } from \'@/store\'\n\ndefineOptions({\n	name: \'LayoutSidebar\'\n})\n\nconst systemSettingStore = useSystemSettingStore()\n</script>\n', NULL, NULL, '2025-08-07 10:29:44', '2025-11-24 16:15:16', 0);
INSERT INTO `gen_template` VALUES (294, 30, 671, 'logo.vue.ftl', 'logo.vue', 1, 'logo页面', '<template>\n	<div class=\"logo-container\">\n		<el-avatar src=\"./favicon.ico\" size=\"small\" class=\"logo-avatar\"></el-avatar>\n		<el-text v-if=\"!appStore.isCollapse\" tag=\"b\">{{ appTitle }}</el-text>\n	</div>\n</template>\n<script setup lang=\"ts\">\nimport { useAppStore } from \'@/store\'\n\ndefineOptions({\n	name: \'Logo\'\n})\n\nconst appTitle = import.meta.env.VITE_APP_TITLE\nconst appStore = useAppStore()\n</script>\n\n<style scoped>\n.logo-container {\n	margin-left: 7px;\n	display: flex;\n	align-items: center;\n	padding: 8px;\n	margin-top: 5px;\n}\n\n.logo-avatar {\n	margin-right: 9px;\n	color: #2c3e50;\n	font-size: 18px;\n	font-weight: 550;\n}\n</style>\n', NULL, NULL, '2025-08-07 10:30:34', '2025-11-24 16:15:05', 0);
