INSERT INTO `gen_template` VALUES (1631, 67, 1630, 'java/Entity.ftl', '${classNameUpper}Entity.java', 1, 'Entity实体类模板', 'package ${projectPackage}.${projectNameDot}.domain.entity;\n\nimport lombok.Data;\n<#if entityBaseClass??>\nimport lombok.EqualsAndHashCode;\n<#else></#if>\nimport com.baomidou.mybatisplus.annotation.*;\n<#if entityBaseClass??>\nimport ${entityBaseClass.packageName}.${entityBaseClass.className};\n</#if>\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}Entity实体类\n */\n@Data\n@TableName(value = \"${tableName}\")\n<#if entityBaseClass??>\n@EqualsAndHashCode(callSuper = true)\n<#else></#if>\npublic class ${classNameUpper}Entity<#if entityBaseClass??> extends ${entityBaseClass.className}</#if> implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list fieldList as field>\n<#if field.entityBaseField == 0>\n	<#if field.fieldComment!?length gt 0>\n	/**\n	 * ${field.fieldComment}\n	 */\n	</#if>\n	<#if field.primaryPk == 1>\n	@TableId(value = \"${field.fieldName}\", type = IdType.AUTO)\n	<#else>\n		<#if field.autoFill == \"DEFAULT\">\n	@TableField(value = \"${field.fieldName}\")\n		</#if>\n		<#if field.autoFill == \"INSERT\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT)\n		</#if>\n		<#if field.autoFill == \"INSERT_UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.INSERT_UPDATE)\n		</#if>\n		<#if field.autoFill == \"UPDATE\">\n	@TableField(value = \"${field.fieldName}\", fill = FieldFill.UPDATE)\n		</#if>\n	</#if>\n	<#if field.logicDelete == 1>\n	@TableLogic(value = \"${field.logicNotDeleteValue}\", delval = \"${field.logicDeleteValue}\")\n	</#if>\n	private ${field.attrType} ${field.attrName};\n\n</#if>\n</#list>\n}\n', NULL, NULL, '2025-09-16 15:15:16', '2025-09-18 10:29:40', 0);
INSERT INTO `gen_template` VALUES (1632, 67, 1629, 'dto', 'dto', 0, NULL, NULL, NULL, NULL, '2025-09-16 15:15:16', '2025-09-16 15:15:16', 0);
INSERT INTO `gen_template` VALUES (1633, 67, 1632, 'java/DTO.ftl', '${classNameUpper}DTO.java', 1, 'DTO实体类模板', 'package ${projectPackage}.${projectNameDot}.domain.dto;\n\n<#function importEnumcode formList>\n	<#list formList as formField>\n		<#if formField.entityBaseField == 0 && formField.enumId??>\n			<#return true>\n		</#if>\n	</#list>\n	<#return false>\n</#function>\n<#assign importEnumcode = importEnumcode(formList)>\nimport ${projectPackage}.${projectNameDot}.common.validation.group.UpdateGroup;\n<#if importEnumcode>\nimport ${projectPackage}.${projectNameDot}.common.validation.code.EnumCode;\n</#if>\n<#list formList as formField >\n<#if formField.entityBaseField == 0 && formField.enumId??>\nimport ${projectPackage}.${projectNameDot}.enums.${formField.enumNamePascal}Enum;\n</#if>\n</#list>\nimport jakarta.validation.constraints.*;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n<#list importList as i>\nimport ${i!};\n</#list>\n\n/**\n * ${tableComment}DTO实体类\n */\n@Data\npublic class ${classNameUpper}DTO implements Serializable {\n\n	@Serial\n	private static final long serialVersionUID = 1L;\n\n<#list formList as formField>\n<#if formField.entityBaseField == 0>\n	/**\n	 * ${formField.fieldComment}\n	 */\n	<#if formField.primaryPk == 1>\n	@NotNull(message = \"${formField.fieldComment}不能为空\", groups = {UpdateGroup.class})\n	</#if>\n	<#if formField.formValidator?? && formField_has_next>\n	@${formField.formValidator}(message = \"${formField.fieldComment}不能为空\")\n	</#if>\n	<#if formField.enumId??>\n	@EnumCode(${formField.enumNamePascal}Enum.class)\n	</#if>\n	private ${formField.attrType} ${formField.attrName};\n\n</#if>\n</#list>\n}\n', NULL, NULL, '2025-09-16 15:15:16', '2025-09-16 15:18:00', 0);
