INSERT INTO `gen_template` VALUES (1645, 68, 1650, 'vue/api.ts.ftl', '${functionNameKebabCase}.ts', 1, '后端接口api', 'import service from \'@/utils/request\'\n\nconst baseUrl: string = \'/${moduleNameCase}/${functionName}\'\n\n// 提交表单\nexport const ${functionName}SubmitApi = (dataForm: any) => {\n    if (dataForm.id) {\n        // 修改接口\n        return service.post(baseUrl + \'/update\', dataForm)\n    } else {\n        // 新增接口\n        return service.post(baseUrl + \'/add\', dataForm)\n    }\n}\n\n// 删除接口\nexport const ${functionName}DeleteApi = (id: number) => {\n    return service.post(baseUrl + \'/delete?id=\' + id)\n}\n\n// 批量删除\nexport const ${functionName}DeleteListApi = (idList: number[]) => {\n    return service.post(baseUrl + \'/deleteList\', idList)\n}\n\n// 详情\nexport const ${functionName}DetailApi = (id: number) => {\n    return service.get(baseUrl + \'/detail?id=\' + id)\n}\n\n// 详情列表\nexport const ${functionName}DetailListApi = (idList: number[]) => {\n    return service.post(baseUrl + \'/detailList\', idList)\n}\n\n// 简单分页\nexport const ${functionName}EntityPageApi = (queryForm?: any) => {\n    return service.post(baseUrl + \'/entityPage\', queryForm ? queryForm : {})\n}\n\n// 简单列表\nexport const ${functionName}EntityListApi = (queryForm?: any) => {\n    return service.post(baseUrl + \'/entityList\', queryForm ? queryForm : {})\n}\n\n// 复杂分页\nexport const ${functionName}VOPageApi = (queryForm?: any) => {\n    return service.post(baseUrl + \'/voPage\', queryForm ? queryForm : {})\n}\n\n// 复杂列表\nexport const ${functionName}VOListApi = (queryForm?: any) => {\n    return service.post(baseUrl + \'/voList\', queryForm ? queryForm : {})\n}\n', NULL, NULL, '2025-09-16 15:19:38', '2025-09-17 13:58:41', 0);
INSERT INTO `gen_template` VALUES (1646, 68, 1643, 'views', 'views', 0, NULL, NULL, NULL, NULL, '2025-09-16 15:19:38', '2025-09-16 15:19:38', 0);
INSERT INTO `gen_template` VALUES (1647, 68, 1651, '${functionNameKebabCase}', '${functionNameKebabCase}', 0, NULL, NULL, NULL, NULL, '2025-09-16 15:19:38', '2025-09-17 10:23:01', 0);
INSERT INTO `gen_template` VALUES (1648, 68, 1647, 'vue/add-or-update.vue.ftl', 'add-or-update.vue', 1, '新增或者修改页面', '<template>\n    <el-dialog v-model=\"visible\" :title=\"!state.dataForm.id ? \'新增\' : \'修改\'\" :close-on-click-modal=\"false\">\n        <el-form ref=\"dataFormRef\" :model=\"state.dataForm\" :rules=\"dataRules\" label-width=\"100px\" @keyup.enter=\"submitHandle()\">\n            <#list formList as field>\n                <el-form-item label=\"${field.fieldComment!}\" prop=\"${field.attrName}\">\n                    <#if field.formType == \'text\'>\n                        <el-input v-model=\"state.dataForm.${field.attrName}\" clearable placeholder=\"请输入${field.fieldComment!}\"></el-input>\n                    <#elseif field.formType == \'textarea\'>\n                        <el-input type=\"textarea\" v-model=\"state.dataForm.${field.attrName}\"></el-input>\n                    <#elseif field.formType == \'editor\'>\n                        <el-input type=\"textarea\" v-model=\"state.dataForm.${field.attrName}\"></el-input>\n                    <#elseif field.formType == \'select\'>\n                        <el-select v-model=\"state.dataForm.${field.attrName}\" clearable filterable placeholder=\"请选择${field.fieldComment!}\">\n                            <el-option v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n                        </el-select>\n                    <#elseif field.formType == \'radio\'>\n                        <el-radio-group v-model=\"state.dataForm.${field.attrName}\">\n                            <el-radio v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :value=\"item.value\">{{ item.label }}</el-radio>\n                        </el-radio-group>\n                    <#elseif field.formType == \'checkbox\'>\n                        <el-checkbox-group v-model=\"state.dataForm.${field.attrName}\">\n                            <el-checkbox v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n                        </el-checkbox-group>\n                    <#elseif field.formType == \'date\'>\n                        <el-date-picker type=\"date\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"state.dataForm.${field.attrName}\"></el-date-picker>\n                    <#elseif field.formType == \'datetime\'>\n                        <el-date-picker type=\"datetime\" placeholder=\"请选择${field.fieldComment!}\" v-model=\"state.dataForm.${field.attrName}\"></el-date-picker>\n                    <#elseif field.formType == \'number\'>\n                        <el-input-number v-model=\"state.dataForm.${field.attrName}\" size=\"small\"></el-input-number>\n                    <#else>\n                        <el-input v-model=\"state.dataForm.${field.attrName}\" clearable placeholder=\"请输入${field.fieldComment!}\"></el-input>\n                    </#if>\n                </el-form-item>\n            </#list>\n        </el-form>\n        <template #footer>\n            <el-button type=\"primary\" :loading=\"submitLoading\" @click=\"submitHandle()\">确定</el-button>\n            <el-button @click=\"visible = false\">取消</el-button>\n        </template>\n    </el-dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive } from \'vue\'\nimport { ${functionName}DetailApi, ${functionName}SubmitApi } from \'@/api/${moduleName}/${functionNameKebabCase}\'\nimport { FormOptions, useSubmitForm } from \'@/hooks/use-submit-form\'\n<#list formList as field>\n<#if field.formType == \'select\' || field.formType == \'checkbox\' || field.formType == \'radio\'>\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/constant/enum\'\n</#if>\n</#list>\n\nconst emit = defineEmits([\'refreshDataList\'])\n\nconst state: FormOptions = reactive({\n    // 提交API\n    submitApi: ${functionName}SubmitApi,\n    // 详情API\n    detailApi: ${functionName}DetailApi,\n    // 表单数据\n    dataForm: {\n        <#list fieldList as field>\n        <#if field.entityBaseField == 0>\n        ${field.attrName}: \'\'<#if field_has_next>,</#if>\n        </#if>\n        </#list>\n    },\n    emit\n})\n\nconst dataRules = reactive({\n    <#list formList as field>\n    <#if field.formRequired == 1>\n    ${field.attrName}: [{ required: true, message: \'必填项不能为空\', trigger: \'blur\' }]<#if field_has_next>,</#if>\n    </#if>\n    </#list>\n})\n\nconst { visible, dataFormRef, init, submitHandle, submitLoading } = useSubmitForm(state)\n\ndefineExpose({\n    init\n})\n</script>\n', NULL, NULL, '2025-09-16 15:19:38', '2025-09-17 11:15:34', 0);
INSERT INTO `gen_template` VALUES (1649, 68, 1647, 'vue/index.vue.ftl', 'index.vue', 1, '列表页面', '<template>\n	<div>\n      <div class=\"app-breadcrumb\">{{ route.meta.title }}</div>\n			<el-form ref=\"queryRef\" :inline=\"true\" :model=\"state.queryForm\" class=\"app-search\" @keyup.enter=\"getDataList()\">\n			<#list queryList as field>\n				<#if field.queryFormType == \'date\'>\n				<el-form-item prop=\"dateRange\" style=\"width: 350px\">\n				<#elseif field.queryFormType == \'datetime\'>\n				<el-form-item prop=\"dateTimeRange\" style=\"width: 350px\">\n				<#else>\n				<el-form-item prop=\"${field.attrName}\">\n				</#if>\n				<#if field.queryFormType == \'text\' || field.queryFormType == \'textarea\' || field.queryFormType == \'editor\'>\n					<el-input v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请输入${field.fieldComment}\"></el-input>\n				<#elseif field.queryFormType == \'select\'>\n					<el-select v-model=\"state.queryForm.${field.attrName}\" clearable placeholder=\"请选择${field.fieldComment}\">\n						<el-option v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\"></el-option>\n					</el-select>\n				<#elseif field.queryFormType == \'radio\'>\n					<el-radio-group v-model=\"state.queryForm.${field.attrName}\">\n						<el-radio v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :value=\"item.value\">{{ item.label }}</el-radio>\n					</el-radio-group>\n				<#elseif field.queryFormType == \'checkbox\'>\n					<el-checkbox-group v-model=\"state.queryForm.${field.attrName}\">\n						<el-checkbox v-for=\"item in ${field.enumNameAllUpper}_ENUM\" :key=\"item.value\" :label=\"item.label\" :value=\"item.value\">{{ item.label }}</el-checkbox>\n					</el-checkbox-group>\n				<#elseif field.queryFormType == \'date\'>\n					<el-date-picker\n							v-model=\"state.queryForm.dateRange\"\n							type=\"daterange\"\n							format=\"YYYY-MM-DD\"\n							value-format=\"YYYY-MM-DD\"\n							clearable\n							start-placeholder=\"开始日期\"\n							end-placeholder=\"结束日期\"\n							:default-time=\"[new Date(2000, 1, 1, 0, 0, 0), new Date(2000, 1, 1, 23, 59, 59)]\"\n					>\n					</el-date-picker>\n				<#elseif field.queryFormType == \'datetime\'>\n					<el-date-picker\n							v-model=\"state.queryForm.dateTimeRange\"\n							type=\"datetimerange\"\n							format=\"YYYY-MM-DD HH:mm:ss\"\n							value-format=\"YYYY-MM-DD HH:mm:ss\"\n							clearable\n							start-placeholder=\"开始时间\"\n							end-placeholder=\"结束时间\"\n							:default-time=\"[new Date(2000, 1, 1, 0, 0, 0), new Date(2000, 1, 1, 23, 59, 59)]\"\n					>\n					</el-date-picker>\n				<#else>\n					<el-input v-model=\"state.queryForm.${field.attrName}\" placeholder=\"请输入${field.fieldComment}\"></el-input>\n				</#if>\n				</el-form-item>\n			</#list>\n				<el-form-item>\n					<el-button type=\"primary\" :loading=\"state.dataListLoading\" @click=\"getDataList()\">查询</el-button>\n				</el-form-item>\n        <el-form-item>\n  				<el-button type=\"primary\" @click=\"addOrUpdateHandle()\">新增</el-button>\n  			</el-form-item>\n			</el-form>\n\n			<el-table\n				v-loading=\"state.dataListLoading\"\n				:data=\"state.dataList\"\n				border\n  			row-key=\"id\"\n			  class=\"layout-table\"\n			  header-cell-class-name=\"layout-table-header\"\n				@selection-change=\"selectionChangeHandle\"\n				@sort-change=\"sortChangeHandle\"\n			>\n				<el-table-column type=\"selection\" header-align=\"center\" align=\"center\" width=\"50\"></el-table-column>\n				<el-table-column type=\"index\" :index=\"tableIndex\" label=\"序号\" header-align=\"center\" align=\"center\" width=\"60\"></el-table-column>\n			<#list gridList as field>\n				<el-table-column prop=\"${field.attrName}\" label=\"${field.fieldComment!}\" show-overflow-tooltip header-align=\"center\" align=\"center\" <#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>:formatter=\"getLabel(${field.enumNameAllUpper}_ENUM)\"</#if> <#if field.gridSort == 1>sortable=\"custom\"</#if>></el-table-column>\n			</#list>\n				<el-table-column label=\"操作\" fixed=\"right\" header-align=\"center\" align=\"center\" width=\"150\">\n					<template #default=\"scope\">\n						<el-button type=\"primary\" link @click=\"addOrUpdateHandle(scope.row.id)\">修改</el-button>\n						<el-button type=\"primary\" link @click=\"deleteBatchHandle(scope.row.id)\">删除</el-button>\n					</template>\n				</el-table-column>\n			</el-table>\n			<el-pagination\n				:current-page=\"state.pageNum\"\n				:page-sizes=\"state.pageSizes\"\n				:page-size=\"state.pageSize\"\n				:total=\"state.total\"\n				layout=\"total, prev, pager, next, sizes\"\n				@size-change=\"sizeChangeHandle\"\n				@current-change=\"currentChangeHandle\"\n			>\n			</el-pagination>\n\n			<!-- 弹窗, 新增 / 修改 -->\n			<add-or-update ref=\"addOrUpdateRef\" @refresh-data-list=\"getDataList\"></add-or-update>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { IHooksOptions, useIndexQuery } from \'@/hooks/use-index-query\'\nimport { useInitForm } from \'@/hooks/use-init-form\'\nimport { reactive } from \'vue\'\nimport { useRoute } from \'vue-router\'\nimport AddOrUpdate from \'@/views/${moduleName}/${functionNameKebabCase}/add-or-update.vue\'\nimport { ${functionName}EntityPageApi, ${functionName}DeleteListApi } from \'@/api/${moduleName}/${functionNameKebabCase}\'\n<#list queryList as field>\n<#if field.queryFormType == \'select\' || field.queryFormType == \'radio\' || field.queryFormType == \'checkbox\'>\nimport { getLabel } from \'@/utils/enum\'\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/constant/enum\'\n</#if>\n</#list>\n<#list gridList as field>\n	<#if field.formType == \'select\' || field.formType == \'radio\' || field.formType == \'checkbox\'>\nimport { getLabel } from \'@/utils/enum\'\nimport { ${field.enumNameAllUpper}_ENUM } from \'@/constant/enum\'\n	</#if>\n</#list>\n\ndefineOptions({\n	name: \'${moduleNamePascal}${functionNamePascal}\'\n})\n\nconst route = useRoute()\n\nconst state: IHooksOptions = reactive({\n    dataListApi: ${functionName}EntityPageApi,\n    deleteListApi: ${functionName}DeleteListApi,\n    queryForm: {\n        <#list queryList as field>\n        	<#if field.queryFormType == \'date\'>\n        dateRange: []<#sep>, </#sep>\n        	<#elseif field.queryFormType == \'datetime\'>\n		dateTimeRange: []<#sep>, </#sep>\n        	<#else>\n        ${field.attrName}: \'\'<#sep>, </#sep>\n        	</#if>\n        </#list>\n    }\n})\n\nconst {\n	getDataList,\n	selectionChangeHandle,\n	sizeChangeHandle,\n	currentChangeHandle,\n	deleteBatchHandle,\n	sortChangeHandle,\n	queryRef,\n	resetQueryHandle,\n	tableIndex\n} = useIndexQuery(state)\n\nconst { addOrUpdateRef, addOrUpdateHandle } = useInitForm()\n</script>\n', NULL, NULL, '2025-09-16 15:19:38', '2025-09-28 17:13:42', 0);
