INSERT INTO `gen_template` VALUES (1891, 30, 678, 'refresh-hook.ftl', 'use-refresh-current-page.ts', 1, '刷新页面的hook（支持缓存和非缓存、iframe和非iframe）', 'import { useAppStore, useSystemSettingStore } from \'@/store\'\nimport { useRoute, useRouter } from \'vue-router\'\n\n// 刷新当前页面\nexport const usePageRefresher = () => {\n	const appStore = useAppStore()\n	const systemSettingStore = useSystemSettingStore()\n	const route = useRoute()\n	const router = useRouter()\n\n	const refreshPage = () => {\n		const { type, cache } = route.meta\n		const name = route.name as string\n\n		// 关闭了全局页面缓存，使用路由跳转实现刷新\n		if (!systemSettingStore.isOpenPageCache) {\n			// 使用路由跳转实现刷新\n			router.push({\n				path: \'/redirect\' + route.fullPath,\n				query: route.query\n			})\n		} else {\n			// 开启了全局页面缓存，使用组件缓存实现刷新\n			// 业务菜单\n			if (type === 1) {\n				// 如果是缓存，删除缓存\n				if (cache) {\n					appStore.removeCacheComponent(name)\n				}\n\n				// 使用路由跳转实现刷新\n				router.push({\n					path: \'/redirect\' + route.fullPath,\n					query: route.query\n				})\n			} else if (type === 3 && cache === false) {\n				// iframe菜单，非缓存\n				// 使用路由跳转实现刷新\n				router.push({\n					path: \'/redirect\' + route.fullPath,\n					query: route.query\n				})\n			} else {\n				// iframe菜单，缓存\n				const idx = appStore.iframeCacheList.findIndex(i => i.fullPath === route.fullPath)\n				if (idx !== -1) {\n					const old = appStore.iframeCacheList[idx]\n					// 修改src的值，会触发刷新\n					old.src = <#noparse>`${old.src.split(\'?\')[0]}?t=${Date.now()}`</#noparse>\n				}\n			}\n		}\n	}\n	return { refreshPage }\n}\n', '', NULL, '2025-09-25 14:29:30', '2025-11-24 16:07:29', 0);
INSERT INTO `gen_template` VALUES (1892, 30, 659, '', 'main', 0, '', '', '', NULL, '2025-09-25 14:30:40', '2025-09-25 14:30:40', 0);
INSERT INTO `gen_template` VALUES (1893, 30, 1892, 'LayoutMain.ftl', 'index.vue', 1, '主页面组件', '<template>\n	<el-scrollbar ref=\"layoutScrollbarRef\" class=\"layout-scrollbar\">\n		<div class=\"layout-card\">\n			<!-- 开启了全局缓存 -->\n			<template v-if=\"systemSettingStore.isOpenPageCache\">\n				<router-view v-slot=\"{ Component }\">\n					<transition name=\"slide\" mode=\"out-in\">\n						<!-- 内置|业务菜单和非缓存的iframe页面 -->\n						<keep-alive :include=\"appStore.cacheList\" :exclude=\"[\'RouterRedirect\']\">\n							<component\n								:is=\"Component\"\n								v-if=\"route.meta.type === 1 || (route.meta.type === 3 && !route.meta.cache)\"\n								:key=\"route.fullPath\"\n							></component>\n						</keep-alive>\n					</transition>\n				</router-view>\n				<!-- 缓存的iframe页面 -->\n				<iframe-container></iframe-container>\n			</template>\n			<!-- 关闭全局缓存，只用component -->\n			<template v-else>\n				<router-view v-slot=\"{ Component }\">\n					<transition name=\"slide\" mode=\"out-in\">\n						<component :is=\"Component\" :key=\"route.fullPath\"></component>\n					</transition>\n				</router-view>\n			</template>\n		</div>\n	</el-scrollbar>\n</template>\n\n<script setup lang=\"ts\">\nimport IframeContainer from \'@/layout/main/components/iframe-container.vue\'\nimport { useRoute } from \'vue-router\'\nimport { useAppStore, useSystemSettingStore } from \'@/store\'\nimport { ref, watch } from \'vue\'\n\ndefineOptions({\n	name: \'LayoutMain\'\n})\n\nconst route = useRoute()\nconst appStore = useAppStore()\nconst systemSettingStore = useSystemSettingStore()\nconst layoutScrollbarRef = ref()\n\n// 路由切换时滚动到顶部\nwatch(\n	() => route.fullPath,\n	() => {\n		// 滚动到顶部和左侧\n		layoutScrollbarRef.value.scrollTo({ top: 0, left: 0 })\n	}\n)\n</script>\n', '', NULL, '2025-09-25 14:37:16', '2025-11-24 16:11:26', 0);
INSERT INTO `gen_template` VALUES (1894, 30, 1892, '', 'components', 0, '', '', '', NULL, '2025-09-25 14:37:43', '2025-09-25 14:37:43', 0);
INSERT INTO `gen_template` VALUES (1895, 30, 1894, 'iframe-container.ftl', 'iframe-container.vue', 1, 'iframe缓存容器组件', '<template>\n	<!-- 缓存池化（v-show控制展示和隐藏） -->\n	<transition-group name=\"slide\" tag=\"div\">\n		<div v-for=\"item in appStore.iframeCacheList\" v-show=\"route.fullPath === item.fullPath\" <#noparse>:key=\"`iframe-${item.fullPath}`\"></#noparse>\n			<router-view v-slot=\"{ Component }\">\n				<component :is=\"Component\" :iframe-src=\"item.src\" :cache=\"true\"></component>\n			</router-view>\n		</div>\n	</transition-group>\n</template>\n\n<script setup lang=\"ts\">\nimport { useAppStore } from \'@/store\'\nimport { useRoute } from \'vue-router\'\nimport { watch } from \'vue\'\n\nconst appStore = useAppStore()\nconst route = useRoute()\n\ndefineOptions({\n	name: \'IframeContainer\'\n})\n\n// 监听路由切换\nwatch(\n	() => [route.fullPath, route.meta.type, route.meta.cache],\n	([newFullPath, newType, newCache]) => {\n		// 只处理 iframe 类型的路由 (type === 3)\n		const externalUrl = route.meta.externalUrl as string\n		if (newType !== 3 || newCache === false || !externalUrl) {\n			return\n		}\n\n		const newRouteName = route.name as string\n\n		// 缓存模式：加入池子\n		appStore.addIframeCache({ name: newRouteName, src: externalUrl, fullPath: newFullPath as string })\n	},\n	{ immediate: true }\n)\n</script>\n', '', NULL, '2025-09-25 14:38:02', '2025-11-24 16:44:44', 0);
INSERT INTO `gen_template` VALUES (1896, 30, 663, 'LayoutSize.ftl', 'layout-size.vue', 1, '布局大小组件', '<template>\n	<div class=\"layout-size\">\n		<el-tooltip content=\"布局大小\" effect=\"dark\" placement=\"bottom\">\n			<el-dropdown trigger=\"click\" @command=\"(size: LayOutSize) => appStore.setLayoutSize(size)\">\n				<svg-icon icon=\"icon-font-size\" size=\"18px\" is-pointer></svg-icon>\n				<template #dropdown>\n					<el-dropdown-menu>\n						<el-dropdown-item v-for=\"item of sizeOptions\" :key=\"item.value\" :disabled=\"appStore.layoutSize === item.value\" :command=\"item.value\">\n							{{ item.label }}\n						</el-dropdown-item>\n					</el-dropdown-menu>\n				</template>\n			</el-dropdown>\n		</el-tooltip>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport SvgIcon from \'@/components/svg-icon/index\'\nimport { ref } from \'vue\'\nimport { useAppStore } from \'@/store\'\nimport { LayOutSize } from \'@/types\'\n\ndefineOptions({\n	name: \'LayoutSize\'\n})\n\nconst appStore = useAppStore()\n\nconst sizeOptions = ref([\n	{ label: \'较大\', value: \'large\' },\n	{ label: \'默认\', value: \'default\' },\n	{ label: \'稍小\', value: \'small\' }\n])\n</script>\n\n<style scoped>\n.layout-size {\n	display: flex;\n	align-items: center;\n	cursor: pointer;\n}\n</style>\n', '', NULL, '2025-09-25 14:40:10', '2025-11-24 16:11:49', 0);
INSERT INTO `gen_template` VALUES (1897, 30, 663, 'system-setting.ftl', 'system-setting.vue', 1, '系统设置组件', '<template>\n	<el-tooltip content=\"系统设置\" effect=\"dark\" placement=\"bottom\">\n		<el-icon size=\"18px\" class=\"setting-icon\" @click=\"visible = true\">\n			<Setting></Setting>\n		</el-icon>\n	</el-tooltip>\n	<el-drawer\n		v-model=\"visible\"\n		title=\"系统设置\"\n		size=\"30%\"\n		body-class=\"system-setting-drawer-body\"\n		footer-class=\"system-setting-drawer-footer\"\n		destroy-on-close\n	>\n		<el-scrollbar>\n			<div class=\"drawer-content\">\n				<div>\n					<el-divider>菜单设置</el-divider>\n					<setting-item v-model=\"systemSettingStore.isOpenLogo\" label=\"展示logo\"></setting-item>\n					<el-row class=\"setting-row\">\n						<el-text style=\"margin-right: 5px\">折叠宽度</el-text>\n						<div style=\"display: flex; align-items: center\">\n							<!-- 下拉推荐值 -->\n							<el-select v-model=\"systemSettingStore.menuFoldWidth\" size=\"small\" clearable style=\"width: 90px\">\n								<el-option\n									v-for=\"value in menuFoldWidthList\"\n									:key=\"value\"\n									<#noparse>:label=\"`${value}px`\"</#noparse>\n									:value=\"value\"\n									:disabled=\"systemSettingStore.menuFoldWidth === value\"\n								></el-option>\n							</el-select>\n						</div>\n					</el-row>\n					<el-row class=\"setting-row\">\n						<el-text style=\"margin-right: 5px\">展开宽度</el-text>\n						<div style=\"display: flex; align-items: center\">\n							<!-- 下拉推荐值 -->\n							<el-select v-model=\"systemSettingStore.menuExpandWidth\" size=\"small\" clearable style=\"width: 90px\">\n								<el-option\n									v-for=\"value in menuExpandWidthList\"\n									:key=\"value\"\n									<#noparse>:label=\"`${value}px`\"</#noparse>\n									:value=\"value\"\n									:disabled=\"systemSettingStore.menuExpandWidth === value\"\n								></el-option>\n							</el-select>\n						</div>\n					</el-row>\n					<setting-item\n						v-model=\"systemSettingStore.isOpenMenuCollapseAnimation\"\n						label=\"展开收起动画\"\n						tooltip=\"开启后菜单展开和收起时会有平滑过渡动画效果\"\n					></setting-item>\n					<setting-item\n						v-model=\"systemSettingStore.isOpenMenuUniqueOpened\"\n						label=\"手风琴模式\"\n						tooltip=\"开启后同一时间只允许一个子菜单展开，打开新子菜单时其他子菜单自动收起\"\n					></setting-item>\n					<el-row class=\"setting-row\">\n						<el-text style=\"margin-right: 5px\">默认菜单</el-text>\n						<div style=\"display: flex; align-items: center\">\n							<el-tree-select\n								v-model=\"systemSettingStore.menuDefault\"\n								:data=\"userStore.menuList\"\n								:props=\"{ label: (data: MenuInfo) => data.meta.title, value: \'path\' }\"\n								node-key=\"id\"\n								filterable\n								default-expand-all\n								placeholder=\"请选择默认菜单\"\n								style=\"width: 180px\"\n							>\n								<template #default=\"{ data }\">\n									<icon-text-tooltip :icon=\"data.meta.icon\" :title=\"data.meta.title\"></icon-text-tooltip>\n								</template>\n							</el-tree-select>\n						</div>\n					</el-row>\n				</div>\n				<div>\n					<el-divider>工具栏设置</el-divider>\n					<setting-item v-model=\"systemSettingStore.isOpenMenuCollapseButton\" label=\"菜单展开/折叠按钮\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenBreadcrumb\" label=\"面包屑\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenBreadcrumbIcon\" label=\"面包屑图标\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenMenuSearch\" label=\"菜单搜索\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenRefreshPage\" label=\"刷新页面\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenLayoutSetting\" label=\"布局大小\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenFullscreen\" label=\"开启/退出全屏\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenThemeSwitch\" label=\"日间/夜间主题切换\"></setting-item>\n				</div>\n				<div>\n					<el-divider>标签页设置</el-divider>\n					<setting-item v-model=\"systemSettingStore.isOpenTag\" label=\"启用\"></setting-item>\n					<setting-item v-model=\"systemSettingStore.isOpenTagIcon\" label=\"图标\"></setting-item>\n					<setting-item\n						v-model=\"systemSettingStore.isOpenTagDragActivated\"\n						label=\"拖拽后激活标签\"\n						tooltip=\"开启后拖拽标签页位置时会自动激活被拖拽的标签页\"\n					></setting-item>\n					<setting-item\n						v-model=\"systemSettingStore.isOpenTagCache\"\n						label=\"持久化\"\n						tooltip=\"开启后即使刷新页面或重启浏览器已打开的标签页仍将保留\"\n					></setting-item>\n				</div>\n				<div>\n					<el-divider>其他设置</el-divider>\n					<setting-item\n						v-model=\"systemSettingStore.isOpenPageCache\"\n						label=\"页面缓存\"\n						tooltip=\"开启后切换菜单时页面数据保留，避免重复加载\"\n					></setting-item>\n					<setting-item\n						v-model=\"systemSettingStore.isOpenDynamicTitle\"\n						label=\"动态标题\"\n						tooltip=\"开启后页面标题会根据当前菜单动态显示\"\n					></setting-item>\n					<setting-item\n						v-model=\"systemSettingStore.isOpenProgress\"\n						label=\"载入进度条\"\n						tooltip=\"开启后切换菜单或者刷新页面时会看到页面顶部有进度条\"\n					></setting-item>\n				</div>\n			</div>\n		</el-scrollbar>\n		<template #footer>\n			<el-button :icon=\"CopyDocument\" type=\"primary\" size=\"small\" @click=\"copySystemSetting()\">复制设置</el-button>\n			<el-button :icon=\"Refresh\" size=\"small\" style=\"margin-right: 5px\" @click=\"handlerResetSystemSetting()\">重置设置</el-button>\n		</template>\n	</el-drawer>\n</template>\n\n<script setup lang=\"ts\">\nimport { CopyDocument, Refresh, Setting } from \'@element-plus/icons-vue\'\nimport { ref, watch } from \'vue\'\nimport { copyToClipboard, setDefaultTitle, setTitle } from \'@/utils/tool\'\nimport { useRoute } from \'vue-router\'\nimport { menuExpandWidthList, menuFoldWidthList, useAppStore, useSystemSettingStore, useUserStore } from \'@/store\'\nimport { MenuInfo, NavbarTag } from \'@/types\'\nimport { ElMessage, ElTreeSelect } from \'element-plus\'\nimport SettingItem from \'@/layout/navbar/components/system-setting-item.vue\'\nimport IconTextTooltip from \'@/components/icon-text-tooltip/index.vue\'\n\ndefineOptions({\n	name: \'SystemSetting\'\n})\n\nconst appStore = useAppStore()\nconst userStore = useUserStore()\nconst systemSettingStore = useSystemSettingStore()\n\nconst visible = ref(false)\nconst route = useRoute()\n\n// 标签是否开启\nwatch(\n	() => systemSettingStore.isOpenTag,\n	newValue => {\n		// 为false的情况\n		if (!newValue) {\n			appStore.removeAllTags()\n		} else {\n			const tag = {\n				fullPath: route.fullPath,\n				name: route.name as string,\n				title: route.meta.title as string,\n				icon: route.meta.icon as string\n			} as NavbarTag\n			appStore.addTag(tag)\n		}\n	}\n)\n\n// 页面缓存\nwatch(\n	() => systemSettingStore.isOpenPageCache,\n	newValue => {\n		// 为false的情况\n		if (!newValue) {\n			appStore.removeAllCache()\n			appStore.removeAllIframeCache()\n		}\n	}\n)\n\n// 动态标题\nwatch(\n	() => systemSettingStore.isOpenDynamicTitle,\n	newValue => {\n		// 为false的情况\n		if (!newValue) {\n			setDefaultTitle()\n		} else {\n			setTitle(route.meta.title as string)\n		}\n	}\n)\n\n// 复制系统设置到剪切板\nconst copySystemSetting = () => {\n	const stateData = { ...systemSettingStore.$state }\n	copyToClipboard(JSON.stringify(stateData, null, 2)).then(() => {\n		ElMessage.success(\'系统设置已复制到剪贴板\')\n	})\n}\n\n// 重置系统设置\nconst handlerResetSystemSetting = () => {\n	systemSettingStore.resetSettings()\n	ElMessage.success(\'系统设置重置成功\')\n}\n</script>\n\n<style lang=\"scss\">\n.system-setting-drawer-body {\n	padding: 10px 5px 10px 10px;\n}\n.system-setting-drawer-footer {\n	border-top: 1px solid var(--el-border-color);\n	padding: 10px 10px 10px 15px;\n}\n</style>\n<style scoped lang=\"scss\">\n.setting-icon {\n	cursor: pointer;\n}\n\n.setting-row {\n	display: flex;\n	justify-content: space-between;\n	align-items: center;\n	margin-bottom: 10px;\n}\n\n.drawer-content {\n	padding: 0 15px 15px 15px;\n}\n</style>\n', '', NULL, '2025-09-25 14:41:39', '2025-11-24 16:45:43', 0);
INSERT INTO `gen_template` VALUES (1898, 30, 663, 'system-setting-item.ftl', 'system-setting-item.vue', 1, '系统设置项组件', '<template>\n	<el-row class=\"setting-row\">\n		<div class=\"setting-label\">\n			<el-text style=\"margin-right: 5px\">{{ label }}</el-text>\n			<el-tooltip v-if=\"tooltip\" :content=\"tooltip\" effect=\"dark\" placement=\"top\">\n				<el-icon class=\"setting-icon\"><InfoFilled></InfoFilled></el-icon>\n			</el-tooltip>\n		</div>\n		<el-switch v-model=\"localValue\" inline-prompt active-text=\"开\" inactive-text=\"关\"></el-switch>\n	</el-row>\n</template>\n\n<script setup lang=\"ts\">\nimport { InfoFilled } from \'@element-plus/icons-vue\'\nimport { computed } from \'vue\'\n\ndefineOptions({\n	name: \'SystemSettingItem\'\n})\n\nconst props = defineProps<{\n	label: string\n	tooltip?: string\n	modelValue: boolean\n}>()\n\nconst emit = defineEmits<{\n	(e: \'update:modelValue\', value: boolean): void\n}>()\n\n// 通过 computed 做双向绑定\nconst localValue = computed({\n	get: () => props.modelValue,\n	set: (val: boolean) => emit(\'update:modelValue\', val)\n})\n</script>\n\n<style scoped>\n.setting-row {\n	display: flex;\n	justify-content: space-between;\n	align-items: center;\n	margin-bottom: 10px;\n}\n.setting-label {\n	display: flex;\n	align-items: center;\n}\n.setting-icon {\n	cursor: pointer;\n}\n</style>\n', '', NULL, '2025-09-25 14:42:37', '2025-09-25 14:42:53', 0);
INSERT INTO `gen_template` VALUES (1899, 30, 663, 'theme-switch.ftl', 'theme-switch.vue', 1, '主题切换组件', '<template>\n	<el-tooltip :content=\"appStore.isDark ? \'日间模式\' : \'夜间模式\'\" placement=\"bottom\">\n		<el-switch\n			v-model=\"appStore.isDark\"\n			size=\"default\"\n			:active-action-icon=\"Moon\"\n			:inactive-action-icon=\"Sunny\"\n			inline-prompt\n			@change=\"appStore.toggleDark\"\n		></el-switch>\n	</el-tooltip>\n</template>\n\n<script setup lang=\"ts\">\nimport { useAppStore } from \'@/store\'\nimport { Moon, Sunny } from \'@element-plus/icons-vue\'\n\ndefineOptions({\n	name: \'ThemeSwitch\'\n})\n\nconst appStore = useAppStore()\n</script>\n', '', NULL, '2025-09-25 14:43:58', '2025-11-24 16:13:45', 0);
INSERT INTO `gen_template` VALUES (1900, 30, 671, '', 'menu', 0, '', '', '', NULL, '2025-09-25 14:44:40', '2025-09-25 14:44:40', 0);
INSERT INTO `gen_template` VALUES (1901, 30, 1900, 'menu-index.ftl', 'menu-index.vue', 1, '菜单组件', '<template>\n	<el-scrollbar>\n		<el-menu\n			:default-active=\"userStore.activeMenuPath\"\n			background-color=\"transparent\"\n			mode=\"vertical\"\n			router\n			:unique-opened=\"systemSettingStore.isOpenMenuUniqueOpened\"\n			:collapse-transition=\"systemSettingStore.isOpenMenuCollapseAnimation\"\n			:collapse=\"appStore.isCollapse\"\n		>\n			<menu-item v-for=\"menu in userStore.menuList\" :key=\"menu.path\" :menu=\"menu\" :ref-map=\"menuRefs\"></menu-item>\n		</el-menu>\n	</el-scrollbar>\n</template>\n\n<script setup lang=\"ts\">\nimport MenuItem from \'@/layout/sidebar/components/menu/menu-item.vue\'\nimport { useRoute } from \'vue-router\'\nimport { nextTick, ref, watch } from \'vue\'\nimport { useAppStore, useSystemSettingStore, useUserStore } from \'@/store\'\n\ndefineOptions({\n	name: \'MenuIndex\'\n})\n\nconst appStore = useAppStore()\nconst userStore = useUserStore()\nconst systemSettingStore = useSystemSettingStore()\nconst route = useRoute()\n\n// 存储所有菜单项引用的Map，格式为 <path, ref>\nconst menuRefs = ref<Map<string, any>>(new Map())\n\n// 监听路由变化，菜单自动滚动\nwatch(\n	() => route.path,\n	newPath => {\n		nextTick(() => {\n			userStore.setActiveMenuPath(newPath)\n			scrollToMenu(newPath)\n		})\n	},\n	{ immediate: true }\n)\n\n// 激活的菜单滚动到可视区域中\nconst scrollToMenu = (path: string) => {\n	// 查找当前激活菜单的 DOM\n	const menuDom = menuRefs.value.get(path)?.$el\n\n	if (!menuDom) {\n		return\n	}\n\n	menuDom.scrollIntoView({\n		behavior: \'smooth\',\n		block: \'nearest\'\n	})\n}\n</script>\n', '', NULL, '2025-09-25 14:45:26', '2025-11-24 16:14:33', 0);
INSERT INTO `gen_template` VALUES (1902, 30, 1900, 'menu-item.ftl', 'menu-item.vue', 1, '菜单项组件', '<template>\n	<!-- 渲染目录 -->\n	<el-sub-menu v-if=\"menu.meta.type === 0\" ref=\"rootRef\" :key=\"\'sub-menu-\' + menu.path\" :index=\"menu.path\">\n		<template #title>\n			<menu-item-content :title=\"menu.meta.title\" :icon=\"menu.meta.icon\"></menu-item-content>\n		</template>\n		<!-- 递归渲染目录或者菜单 -->\n		<template v-if=\"menu.children && menu.children.length > 0\">\n			<menu-item v-for=\"sub in menu.children\" :key=\"\'sub-menu-\' + sub.path\" :menu=\"sub\" :ref-map=\"refMap\"></menu-item>\n		</template>\n	</el-sub-menu>\n	<!-- 渲染菜单、iframe、外链 -->\n	<el-menu-item v-else-if=\"menu.meta.type != 2 && !menu.meta.hidden\" ref=\"rootRef\" :key=\"\'menu-item-\' + menu.path\" :index=\"menu.path\">\n		<!-- 处理内联和外链（内嵌iframe和新窗口） -->\n		<menu-link :menu=\"menu\">\n			<menu-item-content :title=\"menu.meta.title\" :icon=\"menu.meta.icon\"></menu-item-content>\n		</menu-link>\n	</el-menu-item>\n</template>\n\n<script setup lang=\"ts\">\nimport { onMounted, PropType, ref } from \'vue\'\nimport MenuItemContent from \'@/layout/sidebar/components/menu/menu-item-content.vue\'\nimport MenuLink from \'@/layout/sidebar/components/menu/menu-link.vue\'\nimport { MenuInfo } from \'@/types\'\n\ndefineOptions({\n	name: \'MenuItem\'\n})\n\nconst props = defineProps({\n	menu: {\n		type: Object as PropType<MenuInfo>,\n		required: true\n	},\n	refMap: {\n		type: Map,\n		required: true\n	}\n})\nconst rootRef = ref()\n// 添加ref引用到refMap中\nonMounted(() => {\n	props.refMap.set(props.menu.path, rootRef.value)\n})\n</script>\n', '', NULL, '2025-09-25 14:46:05', '2025-11-24 16:14:48', 0);
INSERT INTO `gen_template` VALUES (1903, 30, 1900, 'menu-item-content.ftl', 'menu-item-content.vue', 1, '菜单项内容组件', '<template>\n	<div class=\"menu-item\">\n		<svg-icon v-if=\"icon\" :icon=\"icon\" is-pointer></svg-icon>\n		<el-tooltip :content=\"title\" :disabled=\"!isTitleOverflow\" placement=\"top\">\n			<el-text ref=\"titleRef\" class=\"menu-title\" :style=\"{ maxWidth: menuTitleMaxWidth }\">\n				{{ title }}\n			</el-text>\n		</el-tooltip>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, onMounted, ref } from \'vue\'\nimport SvgIcon from \'@/components/svg-icon/index.vue\'\nimport { useSystemSettingStore } from \'@/store\'\n\ndefineOptions({\n	name: \'MenuItemContent\'\n})\n\ndefineProps({\n	icon: {\n		type: String,\n		required: false,\n		default: \'\'\n	},\n	title: {\n		type: String,\n		required: true\n	}\n})\n\nconst titleRef = ref()\nconst isTitleOverflow = ref(false)\nconst systemSettingStore = useSystemSettingStore()\n\nconst menuTitleMaxWidth = computed(() => {\n	return systemSettingStore.menuExpandWidth - 100 + \'px\'\n})\n\n// 检查文本是否溢出\nonMounted(() => {\n	nextTick(() => {\n		const el = titleRef.value?.$el\n		if (!el) {\n			return\n		}\n\n		const check = () => {\n			isTitleOverflow.value = el.scrollWidth > el.offsetWidth\n		}\n		check()\n\n		const observer = new ResizeObserver(check)\n		observer.observe(el)\n	})\n})\n</script>\n\n<style scoped>\n.menu-item {\n	display: flex;\n	align-items: center; /* 图标+文字垂直居中 */\n}\n.menu-title {\n	display: inline-block;\n	overflow: hidden;\n	white-space: nowrap;\n	text-overflow: ellipsis;\n	vertical-align: middle;\n}\n</style>\n', '', NULL, '2025-09-25 14:46:35', '2025-11-24 16:14:42', 0);
INSERT INTO `gen_template` VALUES (1904, 30, 1900, 'menu-link.ftl', 'menu-link.vue', 1, '菜单链接组件', '<template>\n	<component :is=\"linkType\" v-bind=\"linkProps\" @click=\"handleClick\">\n		<slot></slot>\n	</component>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, PropType } from \'vue\'\nimport { useUserStore } from \'@/store\'\nimport { MenuInfo } from \'@/types\'\n\ndefineOptions({\n	name: \'MenuLink\'\n})\n\nconst props = defineProps({\n	menu: {\n		type: Object as PropType<MenuInfo>,\n		required: true\n	}\n})\n\nconst userStore = useUserStore()\n\n// 判断组件类型：<a> 或 <router-link>\nconst linkType = computed(() => {\n	if (props.menu.meta.type === 4) {\n		return \'a\'\n	}\n	return \'router-link\'\n})\n\nconst handleClick = (e: Event) => {\n	// 外链点击阻止 el-menu router 跳转\n	if (props.menu.meta.type === 4) {\n		e.stopPropagation() // 阻止事件冒泡\n	}\n	userStore.setActiveMenuPath(props.menu.path!)\n}\n\n// 计算绑定属性\nconst linkProps = computed(() => {\n	// 外链方式\n	if (props.menu.meta.type === 4) {\n		return { href: props.menu.meta.externalUrl, target: \'_blank\', rel: \'noopener\' }\n	} else if (props.menu.meta.type === 3) {\n		// iframe 内嵌\n		return { to: { path: props.menu.path } }\n	} else {\n		// 普通路由\n		return { to: { path: props.menu.path } }\n	}\n})\n</script>\n', '', NULL, '2025-09-25 14:47:35', '2025-11-24 16:14:55', 0);
INSERT INTO `gen_template` VALUES (1905, 30, 631, '', 'plugins', 0, '插件目录', '', '', NULL, '2025-09-25 14:49:15', '2025-09-25 14:49:15', 0);
INSERT INTO `gen_template` VALUES (1906, 30, 1905, 'dynamic-persist-plugin.ftl', 'dynamic-persist-plugin.ts', 1, '动态持久化pinia的key插件', 'import type { PiniaPluginContext } from \'pinia\'\n\n/**\n * 支持 pick/omit 可以写函数的增强版 persist 插件\n */\nexport const dynamicPersistPlugin = ({ store, options }: PiniaPluginContext) => {\n	const persist = (options as any)?.persist\n	if (!persist) {\n		return\n	}\n\n	const storage = persist.storage || localStorage\n	const key = persist.key || store.$id\n\n	// 解析 state 并根据 pick/omit 过滤\n	const resolvePaths = (state: Record<string, any>) => {\n		let pick: string[] | undefined\n		let omit: string[] | undefined\n\n		if (typeof persist.pick === \'function\') {\n			pick = persist.pick(store) // 运行时动态计算\n		} else {\n			pick = persist.pick\n		}\n\n		if (typeof persist.omit === \'function\') {\n			omit = persist.omit(store)\n		} else {\n			omit = persist.omit\n		}\n\n		const newState: Record<string, any> = { ...state }\n\n		if (pick && pick.length > 0) {\n			return pick.reduce(\n				(acc, key) => {\n					acc[key] = state[key]\n					return acc\n				},\n				{} as Record<string, any>\n			)\n		}\n\n		if (omit && omit.length > 0) {\n			omit.forEach(key => delete newState[key])\n			return newState\n		}\n\n		return newState\n	}\n\n	// 初始化恢复\n	const fromStorage = storage.getItem(key)\n	if (fromStorage) {\n		try {\n			store.$patch(JSON.parse(fromStorage))\n		} catch (err) {\n			console.error(`[dynamicPersistPlugin] Failed to parse storage for <#noparse>${key}</#noparse>`, err)\n		}\n	}\n\n	// 订阅变化时保存\n	store.$subscribe((_mutation, state) => {\n		const filtered = resolvePaths(state)\n		storage.setItem(key, JSON.stringify(filtered))\n	})\n}\n', '', NULL, '2025-09-25 14:49:49', '2025-09-25 15:18:57', 0);
INSERT INTO `gen_template` VALUES (1907, 30, 648, 'system-setting-store.ftl', 'system-setting-store.ts', 1, '', 'import { defineStore } from \'pinia\'\nimport { reactive, toRefs } from \'vue\'\nimport { cloneObject, resetReactiveObject } from \'@/utils/tool\'\nimport { PersistenceOptions } from \'pinia-plugin-persistedstate\'\nimport { SystemSetting } from \'@/types\'\n\n// 菜单展开宽度\nexport const menuExpandWidthList = [180, 210, 240]\n\n// 菜单折叠宽度\nexport const menuFoldWidthList = [50, 60, 70]\n\n// 默认配置\nconst defaultSystemSetting: SystemSetting = {\n	isOpenBreadcrumb: true,\n	isOpenBreadcrumbIcon: true,\n	isOpenTag: true,\n	isOpenTagIcon: true,\n	isOpenTagCache: true,\n	isOpenTagDragActivated: false,\n	isOpenDynamicTitle: true,\n	isOpenLogo: true,\n	isOpenProgress: true,\n	isOpenPageCache: true,\n	isOpenMenuSearch: true,\n	isOpenRefreshPage: true,\n	isOpenLayoutSetting: true,\n	isOpenFullscreen: true,\n	isOpenThemeSwitch: true,\n	isOpenMenuCollapseAnimation: true,\n	isOpenMenuUniqueOpened: false,\n	isOpenMenuCollapseButton: true,\n	menuExpandWidth: menuExpandWidthList.length >= 3 ? menuExpandWidthList[1] : menuExpandWidthList[0],\n	menuFoldWidth: menuFoldWidthList.length >= 3 ? menuFoldWidthList[1] : menuFoldWidthList[0],\n	menuDefault: \'/index\'\n}\n\n// 持久化配置\nconst getPersistConfig = () => {\n	const key = \'systemSettingStore\'\n	if (import.meta.env.PROD) {\n		return {\n			key,\n			storage: localStorage\n		} as PersistenceOptions\n	} else {\n		return false\n	}\n}\n\nexport const useSystemSettingStore = defineStore(\n	\'system-setting\',\n	() => {\n		const state = reactive<SystemSetting>(cloneObject(defaultSystemSetting))\n\n		// 恢复默认配置\n		const resetSettings = () => {\n			resetReactiveObject(state, defaultSystemSetting)\n		}\n\n		return {\n			// 注意这里要用 toRefs 保持响应式\n			...toRefs(state),\n			resetSettings\n		}\n	},\n	{\n		persist: getPersistConfig()\n	}\n)\n', '', NULL, '2025-09-25 14:51:28', '2025-11-24 16:17:45', 0);
INSERT INTO `gen_template` VALUES (1908, 30, 643, 'theme.scss', 'theme.scss', 1, '主题样式（日间和夜间）', 'html.light {\n  --el-color-primary: #409eff;\n  --el-color-success: #67c23a;\n  --el-color-warning: #e6a23c;\n  --el-color-danger: #f56c6c;\n  --el-color-info: #909399;\n\n  --el-tag-bg-color: #ffffff;\n  --el-tag-text-color: #606266;\n  --el-tag-border-color: #dcdfe6;\n\n  --theme-menu-bg-color: #ffffff;\n  --theme-menu-text-color: #303133;\n  --theme-main-bg-color: #f5f5f5;\n\n  /* Header 专用 */\n  --theme-header-bg-color: #ffffff;\n  --theme-header-text-color: #303133;\n}\n\nhtml.dark {\n  --el-color-primary: #4d8acc;\n  --el-color-success: #5daf3f;\n  --el-color-warning: #d49a45;\n  --el-color-danger: #e06262;\n  --el-color-info: #8a8c91;\n\n  --el-tag-bg-color: #2a2a2a;\n  --el-tag-text-color: #e0e0e0;\n  --el-tag-border-color: #3a3a3a;\n\n  --theme-menu-bg-color: #1e1e1e;\n  --theme-menu-text-color: #e0e0e0;\n  --theme-main-bg-color: #121212;\n\n  /* Header 专用 */\n  --theme-header-bg-color: #1a1a1a;\n  --theme-header-text-color: #e0e0e0;\n}\n', '', NULL, '2025-09-25 14:53:02', '2025-11-24 16:18:38', 0);
INSERT INTO `gen_template` VALUES (1909, 30, 653, '', 'error', 0, '', '', '', NULL, '2025-09-25 14:54:47', '2025-09-25 14:54:47', 0);
INSERT INTO `gen_template` VALUES (1910, 30, 655, 'iframe-page.ftl', 'iframe-page.vue', 1, 'iframe容器组件', '<template>\n	<div v-loading=\"currentLoading\" class=\"iframe-container\">\n		<iframe :src=\"iframeSrc\" width=\"100%\" height=\"100%\" style=\"min-height: calc(100vh - 84px)\" allow=\"accelerometer\" @load=\"handleLoad\"></iframe>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from \'vue\'\nimport NProgress from \'nprogress\'\nimport { useSystemSettingStore } from \'@/store/system-setting-store\'\n\ndefineOptions({\n	name: \'IframePage\'\n})\n\nconst props = defineProps({\n	// iframe地址\n	iframeSrc: {\n		type: String,\n		required: true\n	},\n	// 是否缓存\n	cache: {\n		type: Boolean,\n		required: false,\n		default: false\n	}\n})\n\nconst currentLoading = ref(true) // 是否在加载中\nconst systemSettingStore = useSystemSettingStore()\n\n// 只有在缓存模式下进行监控\nif (props.cache) {\n	// 如果src路径发生变化，进行loading加载，表示刷新\n	watch(\n		() => props.iframeSrc,\n		() => {\n			if (systemSettingStore.isOpenProgress) {\n				NProgress.start()\n			}\n			currentLoading.value = true\n		}\n	)\n}\n\n// iframe加载完成，关闭loading\nconst handleLoad = () => {\n	// 只有在启用缓存模式下才处理 NProgress\n	if (props.cache && NProgress.isStarted() && systemSettingStore.isOpenProgress) {\n		NProgress.done()\n	}\n	currentLoading.value = false\n}\n</script>\n\n<style scoped>\n.iframe-container {\n	height: 100%;\n	overflow: hidden;\n}\n</style>\n', '', NULL, '2025-09-25 14:56:08', '2025-11-24 16:23:06', 1);
INSERT INTO `gen_template` VALUES (1931, 76, 0, '', '${backendPath}', 0, '后端项目根路径', '', '', NULL, '2025-09-25 17:44:42', '2025-09-25 17:44:42', 0);
INSERT INTO `gen_template` VALUES (1932, 76, 1931, 'pom.xml.ftl', 'pom.xml', 1, 'pom文件模板', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<project xmlns=\"http://maven.apache.org/POM/4.0.0\"\n         xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n         xsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd\">\n    <modelVersion>4.0.0</modelVersion>\n\n    <groupId>${projectPackage}</groupId>\n    <artifactId>${projectName}</artifactId>\n    <version>${projectVersion}</version>\n    <description>${projectDesc}</description>\n    <packaging>war</packaging>\n\n    <properties>\n        <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>\n        <project.reporting.outputEncoding>UTF-8</project.reporting.outputEncoding>\n        <java.version>17</java.version>\n        <maven.compiler.source>17</maven.compiler.source>\n        <maven.compiler.target>17</maven.compiler.target>\n        <spring-boot.version>3.3.1</spring-boot.version>\n        <hutool.version>6.0.0-M20</hutool.version>\n        <lombok.version>1.18.36</lombok.version>\n        <mapstruct.version>1.6.3</mapstruct.version>\n        <lombok-mapstruct-binding.version>0.2.0</lombok-mapstruct-binding.version>\n        <mybatis-plus.version>3.5.10.1</mybatis-plus.version>\n    </properties>\n\n    <!-- 依赖版本管理 -->\n    <dependencyManagement>\n        <dependencies>\n            <dependency>\n                <groupId>org.springframework.boot</groupId>\n                <artifactId>spring-boot-dependencies</artifactId>\n                <version><#noparse>${spring-boot.version}</#noparse></version>\n                <type>pom</type>\n                <scope>import</scope>\n            </dependency>\n            <dependency>\n                <groupId>org.projectlombok</groupId>\n                <artifactId>lombok</artifactId>\n                <version><#noparse>${lombok.version}</#noparse></version>\n            </dependency>\n            <dependency>\n                <groupId>org.dromara.hutool</groupId>\n                <artifactId>hutool-all</artifactId>\n                <version><#noparse>${hutool.version}</#noparse></version>\n            </dependency>\n            <!--对象转换-->\n            <dependency>\n                <groupId>org.mapstruct</groupId>\n                <artifactId>mapstruct</artifactId>\n                <version><#noparse>${mapstruct.version}</#noparse></version>\n            </dependency>\n            <dependency>\n                <groupId>org.mapstruct</groupId>\n                <artifactId>mapstruct-processor</artifactId>\n                <version><#noparse>${mapstruct.version}</#noparse></version>\n            </dependency>\n            <dependency>\n                <groupId>com.baomidou</groupId>\n                <artifactId>mybatis-plus-jsqlparser</artifactId>\n                <version><#noparse>${mybatis-plus.version}</#noparse></version>\n            </dependency>\n            <dependency>\n                <groupId>com.baomidou</groupId>\n                <artifactId>mybatis-plus-spring-boot3-starter</artifactId>\n                <version><#noparse>${mybatis-plus.version}</#noparse></version>\n            </dependency>\n        </dependencies>\n    </dependencyManagement>\n\n    <dependencies>\n        <dependency>\n            <groupId>org.projectlombok</groupId>\n            <artifactId>lombok</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.dromara.hutool</groupId>\n            <artifactId>hutool-all</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-validation</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-web</artifactId>\n            <exclusions>\n                <exclusion>\n                    <groupId>org.springframework.boot</groupId>\n                    <artifactId>spring-boot-starter-tomcat</artifactId>\n                </exclusion>\n            </exclusions>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-tomcat</artifactId>\n            <scope>provided</scope>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-aop</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>jakarta.validation</groupId>\n            <artifactId>jakarta.validation-api</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.springframework.boot</groupId>\n            <artifactId>spring-boot-starter-test</artifactId>\n            <scope>test</scope>\n        </dependency>\n        <dependency>\n            <groupId>com.mysql</groupId>\n            <artifactId>mysql-connector-j</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>com.baomidou</groupId>\n            <artifactId>mybatis-plus-jsqlparser</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>com.baomidou</groupId>\n            <artifactId>mybatis-plus-spring-boot3-starter</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.mapstruct</groupId>\n            <artifactId>mapstruct</artifactId>\n        </dependency>\n        <dependency>\n            <groupId>org.mapstruct</groupId>\n            <artifactId>mapstruct-processor</artifactId>\n        </dependency>\n    </dependencies>\n\n    <build>\n        <finalName><#noparse>${project.artifactId}</#noparse></finalName>\n        <plugins>\n            <plugin>\n                <groupId>org.springframework.boot</groupId>\n                <artifactId>spring-boot-maven-plugin</artifactId>\n                <version><#noparse>${spring-boot.version}</#noparse></version>\n                <executions>\n                    <execution>\n                        <id>repackage</id>\n                        <goals>\n                            <goal>repackage</goal>\n                        </goals>\n                    </execution>\n                </executions>\n            </plugin>\n        </plugins>\n    </build>\n\n</project>', NULL, NULL, '2025-09-25 17:44:42', '2025-09-25 17:49:01', 0);
INSERT INTO `gen_template` VALUES (1933, 76, 1931, '.gitignore.ftl', '.gitignore', 1, 'gitignore配置文件', '!.mvn/wrapper/maven-wrapper.jar\n!**/src/main/**/target/\n!**/src/test/**/target/\n\n### IntelliJ IDEA ###\n.idea/**\n*.iws\n*.iml\n*.ipr\n\n### Eclipse ###\n.apt_generated\n.classpath\n.factorypath\n.project\n.settings\n.springBeans\n.sts4-cache\n\n### NetBeans ###\n/nbproject/private/\n/nbbuild/\n/dist/\n/nbdist/\n/.nb-gradle/\nbuild/\n!**/src/main/**/build/\n!**/src/test/**/build/\n\n### VS Code ###\n.vscode/\n\n### Mac OS ###\n.DS_Store\n\n/**/target/**\n/**/logs/**\n/**/log/**', NULL, NULL, '2025-09-25 17:44:42', '2025-09-25 17:44:42', 0);
