INSERT INTO `gen_template` VALUES (1953, 76, 1952, 'PageQuery.ftl', 'PageQuery.java', 1, '分页查询参数', 'package ${projectPackage}.${projectNameDot}.common.domain.query;\n\nimport com.baomidou.mybatisplus.core.metadata.IPage;\nimport com.baomidou.mybatisplus.core.metadata.OrderItem;\nimport lombok.AccessLevel;\nimport lombok.Data;\nimport lombok.Getter;\nimport lombok.Setter;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.List;\n\n/**\n * 分页查询参数基类，分页查询入参和返回基类\n *\n * @param <T> 必须是Entity或者是VO\n */\n@Data\npublic class PageQuery<T> implements IPage<T>, Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 2101820826443930585L;\n\n    /**\n     * 当前页码\n     */\n    private Long pageNum = 1L;\n\n    /**\n     * 每页大小\n     */\n    private Long pageSize = 10L;\n\n    /**\n     * 排序字段列表\n     */\n    private List<OrderItemQuery> orderItemList = OrderItemQuery.descs(\"updateTime\", \"id\");\n\n    /**\n     * 分页数据\n     */\n    private List<T> records;\n\n    /**\n     * 记录总数\n     */\n    private long total;\n\n    private Long size;\n\n    private Long current;\n\n    @Getter(AccessLevel.NONE)\n    @Setter(AccessLevel.NONE)\n    private Long pages;\n\n    @Override\n    public long getSize() {\n        return this.pageSize;\n    }\n\n    @Override\n    public IPage<T> setSize(long size) {\n        this.pageSize = size;\n        return this;\n    }\n\n    @Override\n    public long getCurrent() {\n        return pageNum;\n    }\n\n    @Override\n    public IPage<T> setCurrent(long current) {\n        this.pageSize = current;\n        return this;\n    }\n\n    @Override\n    public List<T> getRecords() {\n        return this.records;\n    }\n\n    @Override\n    public PageQuery<T> setRecords(List<T> records) {\n        this.records = records;\n        return this;\n    }\n\n    @Override\n    public long getTotal() {\n        return this.total;\n    }\n\n    @Override\n    public PageQuery<T> setTotal(long total) {\n        this.total = total;\n        return this;\n    }\n\n    @Override\n    public List<OrderItem> orders() {\n        //返回空数组，让框架不做排序处理\n        return List.of();\n    }\n\n}\n', '', NULL, '2025-09-25 17:44:43', '2025-09-25 17:49:01', 0);
INSERT INTO `gen_template` VALUES (1954, 76, 1952, 'OrderItemQuery.ftl', 'OrderItemQuery.java', 1, '排序参数', 'package ${projectPackage}.${projectNameDot}.common.domain.query;\n\nimport com.baomidou.mybatisplus.core.toolkit.StringUtils;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.stream.Collectors;\n\n/**\n * 排序字段查询参数\n */\n@Data\npublic class OrderItemQuery implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    /**\n     * 需要进行排序的字段\n     */\n    private String column;\n\n    /**\n     * 是否正序排列，默认 true\n     */\n    private Boolean asc = true;\n\n    public static OrderItemQuery asc(String column) {\n        return build(column, true);\n    }\n\n    public static OrderItemQuery desc(String column) {\n        return build(column, false);\n    }\n\n    public static List<OrderItemQuery> ascs(String... columns) {\n        return Arrays.stream(columns).map(OrderItemQuery::asc).collect(Collectors.toList());\n    }\n\n    public static List<OrderItemQuery> descs(String... columns) {\n        return Arrays.stream(columns).map(OrderItemQuery::desc).collect(Collectors.toList());\n    }\n\n    private static OrderItemQuery build(String column, boolean asc) {\n        return new OrderItemQuery().setColumn(column).setAsc(asc);\n    }\n\n    public OrderItemQuery setColumn(String column) {\n        this.column = StringUtils.replaceAllBlank(column);\n        return this;\n    }\n\n    public OrderItemQuery setAsc(boolean asc) {\n        this.asc = asc;\n        return this;\n    }\n\n}\n', '', NULL, '2025-09-25 17:44:43', '2025-09-25 17:49:01', 0);
INSERT INTO `gen_template` VALUES (1955, 76, 1948, '', 'vo', 0, NULL, NULL, NULL, NULL, '2025-09-25 17:44:43', '2025-09-25 17:44:43', 0);
INSERT INTO `gen_template` VALUES (1956, 76, 1955, 'BaseUserVO.ftl', 'BaseUserVO.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\n/**\n * Controller返回值数据基类（包含用户相关信息）\n * <p>自定义VO类继承该类即可</p>\n */\n@Data\npublic abstract class BaseUserVO extends BaseVO implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = -5814569213714989166L;\n\n    /**\n     * 创建人ID\n     */\n    private Long createUserId;\n\n    /**\n     * 创建人\n     */\n    private String createUser;\n\n    /**\n     * 修改人ID\n     */\n    private Long updateUserId;\n\n    /**\n     * 修改人\n     */\n    private String updateUser;\n\n}', NULL, NULL, '2025-09-25 17:44:43', '2025-09-25 17:52:20', 0);
INSERT INTO `gen_template` VALUES (1957, 76, 1955, 'BaseVO.ftl', 'BaseVO.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * Controller返回值数据基类\n * <p>自定义VO类继承该类即可</p>\n */\n@Data\npublic abstract class BaseVO implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = -5814569213714989166L;\n\n    /**\n     * 创建时间\n     */\n    private Date createTime;\n\n    /**\n     * 修改时间\n     */\n    private Date updateTime;\n\n    /**\n     * 是否删除（0正常, 1删除）\n     */\n    private Integer isDelete;\n\n}', NULL, NULL, '2025-09-25 17:44:43', '2025-09-25 17:49:01', 0);
INSERT INTO `gen_template` VALUES (1958, 76, 1955, 'PageVO.ftl', 'PageVO.java', 1, '分页响应参数', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport lombok.Data;\nimport lombok.NoArgsConstructor;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.List;\n\n/**\n * 分页数据封装\n *\n * @param <T> 必须是VO\n */\n@Data\n@NoArgsConstructor\npublic class PageVO<T> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 3563028771440196184L;\n\n    /**\n     * 当前页码\n     */\n    private Long pageNum;\n\n    /**\n     * 每页显示条数\n     */\n    private Long pageSize;\n\n    /**\n     * 分页数据\n     */\n    private List<T> records;\n\n    /**\n     * 总记录数\n     */\n    private Long total;\n\n    /**\n     * 将其余VO分页数据转换成PageVO分页数据\n     */\n    public PageVO(PageQuery<T> pageQuery) {\n        this.pageNum = pageQuery.getPageNum();\n        this.pageSize = pageQuery.getPageSize();\n        this.records = pageQuery.getRecords();\n        this.total = pageQuery.getTotal();\n    }\n\n    /**\n     * 转成成分页数据通过全量参数\n     *\n     * @param records 已经分页后的list\n     */\n    public PageVO(Long pageNum, Long pageSize, Long total, List<T> records) {\n        this.pageNum = pageNum;\n        this.pageSize = pageSize;\n        this.total = total;\n        this.records = records;\n    }\n\n    /**\n     * 转换成分页数据，手动分页\n     *\n     * @param records 分页前的数据\n     */\n    public PageVO(Long pageNum, Long pageSize, List<T> records) {\n        this.pageNum = pageNum;\n        this.pageSize = pageSize;\n        this.total = (long) records.size();\n        this.records = records.stream()\n                .skip((pageNum - 1) * pageSize)\n                .limit(pageSize)\n                .toList();\n    }\n\n}\n', '', NULL, '2025-09-25 17:44:43', '2025-09-25 17:49:01', 0);
