INSERT INTO `gen_template` VALUES (2016, 79, 2015, 'index.html.ftl', 'index.html', 1, '根文件', '<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.ico\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>%VITE_APP_TITLE%</title>\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script type=\"module\" src=\"/src/main.ts\"></script>\n  </body>\n</html>\n', NULL, NULL, '2025-09-28 18:08:43', '2025-09-28 18:08:43', 0);
INSERT INTO `gen_template` VALUES (2017, 79, 2015, 'vite.config.ts.ftl', 'vite.config.ts', 1, 'vite配置文件', 'import { resolve } from \'path\'\nimport { defineConfig } from \'vite\'\nimport vue from \'@vitejs/plugin-vue\'\nimport { createSvgIconsPlugin } from \'vite-plugin-svg-icons\'\n\n// 参考：https://cn.vitejs.dev/config/\nexport default defineConfig({\n	base: \'./\',\n	resolve: {\n		// 配置别名\n		alias: {\n			\'@\': resolve(__dirname, \'./src\'),\n			\'vue-i18n\': \'vue-i18n/dist/vue-i18n.cjs.js\'\n		}\n	},\n	plugins: [\n		vue(),\n		createSvgIconsPlugin({\n			iconDirs: [resolve(__dirname, \'src/icons/svg\')],\n			symbolId: \'icon-[dir]-[name]\'\n		})\n	],\n	server: {\n		host: \'0.0.0.0\',\n		port: 5000, // 端口号\n		open: false // 是否自动打开浏览器\n	}\n})\n', NULL, NULL, '2025-09-28 18:08:43', '2025-09-28 18:08:43', 0);
INSERT INTO `gen_template` VALUES (2018, 79, 2015, 'tsconfig.json.ftl', 'tsconfig.json', 1, 'ts配置文件', '{\n  \"compilerOptions\": {\n    \"baseUrl\": \".\",\n    \"target\": \"esnext\",\n    \"useDefineForClassFields\": true,\n    \"module\": \"esnext\",\n    \"moduleResolution\": \"node\",\n    \"strict\": true,\n    \"jsx\": \"preserve\",\n    \"skipLibCheck\": true,\n    \"allowJs\": true,\n    \"sourceMap\": true,\n    \"resolveJsonModule\": true,\n    \"esModuleInterop\": true,\n    \"allowSyntheticDefaultImports\": true,\n    \"lib\": [\"esnext\", \"dom\"],\n    \"types\": [\n      \"web-bluetooth\",\n      \"vite/client\"\n    ],\n    \"paths\": {\n      \"@/*\": [\"./src/*\"]\n    },\n    \"compilerOptions\": {\n      \"types\": [\"vite-plugin-svg-icons/client\"]\n    }\n  },\n  \"include\": [\"src/**/*.ts\", \"src/**/*.d.ts\", \"src/**/*.tsx\", \"src/**/*.vue\"],\n  \"exclude\": [\"node_modules\"]\n}\n', NULL, NULL, '2025-09-28 18:08:43', '2025-09-28 18:08:43', 0);
INSERT INTO `gen_template` VALUES (2019, 79, 2015, 'package.json.ftl', 'package.json', 1, '包管理', '{\n  \"name\": \"${projectName}\",\n  \"version\": \"${projectVersion}\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\",\n    \"lint\": \"eslint src/ --ext .ts,.vue --fix\"\n  },\n  \"dependencies\": {\n    \"@element-plus/icons-vue\": \"2.3.1\",\n    \"@vueuse/core\": \"^9.1.1\",\n    \"axios\": \"1.8.2\",\n    \"dayjs\": \"^1.11.15\",\n    \"element-plus\": \"2.9.3\",\n    \"nprogress\": \"^0.2.0\",\n    \"pinia\": \"^3.0.3\",\n    \"pinia-plugin-persistedstate\": \"^4.4.1\",\n    \"qs\": \"6.10.3\",\n    \"sortablejs\": \"^1.15.6\",\n    \"vue\": \"^3.5.17\",\n    \"vue-router\": \"4.2.5\",\n    \"xe-utils\": \"^3.5.4\"\n  },\n  \"devDependencies\": {\n    \"@babel/types\": \"7.24.0\",\n    \"@types/node\": \"20.11.28\",\n    \"@types/nprogress\": \"0.2.3\",\n    \"@types/qs\": \"6.9.12\",\n    \"@types/sortablejs\": \"1.15.8\",\n    \"@typescript-eslint/eslint-plugin\": \"^8.40.0\",\n    \"@typescript-eslint/parser\": \"^8.40.0\",\n    \"@vitejs/plugin-vue\": \"5.0.5\",\n    \"@vue/compiler-sfc\": \"3.4.30\",\n    \"@vue/eslint-config-prettier\": \"9.0.0\",\n    \"@vue/eslint-config-typescript\": \"13.0.0\",\n    \"@vue/tsconfig\": \"0.5.1\",\n    \"eslint\": \"8.57.0\",\n    \"eslint-plugin-prettier\": \"^5.5.4\",\n    \"eslint-plugin-unused-imports\": \"^4.2.0\",\n    \"eslint-plugin-vue\": \"9.23.0\",\n    \"prettier\": \"3.2.5\",\n    \"sass\": \"1.72.0\",\n    \"typescript\": \"5.4.2\",\n    \"vite\": \"6.3.4\",\n    \"vite-plugin-svg-icons\": \"2.0.1\",\n    \"vite-plugin-vue-setup-extend\": \"0.4.0\",\n    \"vue-eslint-parser\": \"^10.2.0\",\n    \"vue-tsc\": \"2.0.22\"\n  },\n  \"keywords\": [\n    \"vue\",\n    \"vue3\",\n    \"vuejs\",\n    \"vite\",\n    \"element-plus\",\n    \"${projectName}\"\n  ],\n  \"license\": \"MIT\"\n}\n', NULL, NULL, '2025-09-28 18:08:43', '2025-09-28 18:08:43', 0);
INSERT INTO `gen_template` VALUES (2020, 79, 2015, '.prettierrc.cjs.ftl', '.prettierrc.cjs', 1, '代码格式化配置文件', '// 参考：https://prettier.io/docs/en/options.html\nmodule.exports = {\n	// 超过指定值换行\n	printWidth: 150,\n	// 制表符宽度\n	tabWidth: 2,\n	// 使用制表符缩进\n	useTabs: true,\n	// 句尾不使用分号\n	semi: false,\n	// 使用单引号\n	singleQuote: true,\n	// 在 JSX 文件中使用单引号代替双引号\n	jsxSingleQuote: true,\n	// 在对象或数组最后一个元素后面是否加逗号，可选值\"[none：不追加 | es5：追加]\n	trailingComma: \'none\',\n	// 在对象，数组括号与代码之间加空格 \"{ foo: bar }\"\n	bracketSpacing: true,\n	// 将多行 JSX 元素的 > 放置于最后一行的末尾，而非换行\n	jsxBracketSameLine: true,\n	//(x) => {} 箭头函数参数只有一个时是否要有小括号，可选值\"[always：(x) => x | avoid：x => x]\n	arrowParens: \'avoid\',\n	// 使用默认的折行标准，可选值\"[always|never|preserve]\"\n	proseWrap: \'preserve\',\n	// 指定HTML文件的全局空格敏感度，可选值\"[css|strict|ignore]\"\n	htmlWhitespaceSensitivity: \'css\',\n	// 结尾时换行符，默认值lf，可选值\"[auto|lf|crlf|cr]\"\n	endOfLine: \'auto\'\n}\n', NULL, NULL, '2025-09-28 18:08:43', '2025-09-28 18:08:43', 0);
INSERT INTO `gen_template` VALUES (2021, 79, 2015, '.gitignore.ftl', '.gitignore', 1, 'git忽略配置文件', '# Logs\nlogs\n*.log\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\npnpm-debug.log*\nlerna-debug.log*\n\nnode_modules\ndist\ndist-ssr\n*.local\n\n# Editor directories and files\n.vscode/*\n!.vscode/extensions.json\n.idea\n.DS_Store\n*.suo\n*.ntvs*\n*.njsproj\n*.sln\n*.sw?\n', NULL, NULL, '2025-09-28 18:08:43', '2025-09-28 18:08:43', 0);
INSERT INTO `gen_template` VALUES (2022, 79, 2015, '.eslintrc.cjs.ftl', '.eslintrc.cjs', 1, '代码格式化配置文件', 'module.exports = {\n	root: true,\n	env: {\n		node: true\n	},\n	extends: [\n		\'plugin:vue/vue3-recommended\',\n		\'plugin:prettier/recommended\',\n		\'@vue/typescript/recommended\' // 添加 TypeScript 推荐规则\n	],\n	parser: \'vue-eslint-parser\',\n	parserOptions: {\n		parser: \'@typescript-eslint/parser\',\n		ecmaVersion: 2022,\n		ecmaFeatures: {\n			jsx: true\n		},\n		sourceType: \'module\' // 添加模块化支持\n	},\n	plugins: [\n		\'@typescript-eslint\',\n		\'unused-imports\' // 添加未使用导入检测插件\n	],\n	rules: {\n		curly: \'error\',\n		\'vue/multi-word-component-names\': \'off\',\n		// 添加未使用变量检测规则\n		\'no-unused-vars\': \'off\', // 禁用基础规则\n		\'@typescript-eslint/no-unused-vars\': [\n			\'error\',\n			{\n				args: \'all\',\n				argsIgnorePattern: \'^_\',\n				varsIgnorePattern: \'^_\',\n				caughtErrors: \'all\',\n				caughtErrorsIgnorePattern: \'^_\'\n			}\n		],\n		// 添加未使用导入检测规则\n		\'unused-imports/no-unused-imports\': \'error\',\n		\'unused-imports/no-unused-vars\': [\n			\'warn\',\n			{\n				vars: \'all\',\n				varsIgnorePattern: \'^_\',\n				args: \'after-used\',\n				argsIgnorePattern: \'^_\'\n			}\n		]\n	}\n}\n', NULL, NULL, '2025-09-28 18:08:43', '2025-09-28 18:08:43', 0);
