INSERT INTO `gen_template` VALUES (2093, 79, 2092, 'use-index-query.ts.ftl', 'use-index-query.ts', 1, '表格列表查询（分页）、批量删除hooks', 'import { onMounted, ref } from \'vue\'\nimport { ElMessage, ElMessageBox } from \'element-plus\'\n\ntype DataListApi<T = any> = (params: any) => Promise<T>\ntype DeleteListApi<T = any> = (params: any) => Promise<T>\n\nexport interface IHooksOptions {\n	// 否在创建页面时，调用数据列表接口\n	createdIsNeed?: boolean\n	// 是否需要分页\n	isPage?: boolean\n	// 数据列表接口\n	dataListApi?: DataListApi\n	// 删除接口\n	deleteListApi?: DeleteListApi\n	// 主键key，用于删除场景\n	primaryKey?: string\n	// 查询条件\n	queryForm?: any\n	// 数据列表\n	dataList?: any[]\n	// 排序字段\n	order?: string\n	// 是否升序\n	asc?: boolean\n	// 当前页码\n	pageNum?: number\n	// 每页数\n	pageSize?: number\n	// 总条数\n	total?: number\n	// 每页数选择项\n	pageSizes?: number[]\n	// 数据列表，loading状态\n	dataListLoading?: boolean\n	// 数据列表，多选项\n	dataListSelections?: any[]\n	// 删除时提示语\n	deleteMessage?: string\n}\n\nexport const useIndexQuery = (options: IHooksOptions) => {\n	// 表单查询引用\n	const queryRef = ref()\n\n	// 重置查询\n	const resetQueryHandle = () => {\n		if (queryRef.value) {\n			queryRef.value.resetFields()\n		}\n	}\n\n	const defaultOptions: IHooksOptions = {\n		dataListApi: () => Promise.resolve({ data: [] }),\n		deleteListApi: () => Promise.resolve(),\n		createdIsNeed: true,\n		isPage: true,\n		primaryKey: \'id\',\n		queryForm: {},\n		dataList: [],\n		order: \'\',\n		asc: false,\n		pageNum: 1,\n		pageSize: 10,\n		total: 0,\n		pageSizes: [10, 20, 50, 100, 200],\n		dataListLoading: false,\n		dataListSelections: [],\n		deleteMessage: \'确定进行删除操作?\'\n	}\n\n	const mergeDefaultOptions = (options: any, props: any): IHooksOptions => {\n		for (const key in options) {\n			if (!Object.getOwnPropertyDescriptor(props, key)) {\n				props[key] = options[key]\n			}\n		}\n		return props\n	}\n\n	// 覆盖默认值\n	const state = mergeDefaultOptions(defaultOptions, options)\n\n	// 创建完毕\n	onMounted(() => {\n		if (state.createdIsNeed) {\n			query()\n		}\n	})\n\n	// 执行实际的查询逻辑\n	const executeQuery = () => {\n		//解构查询条件\n		const queryForm = {\n			...state.queryForm\n		}\n		//如果queryForm包含dateRange\n		if (queryForm.hasOwnProperty(\'dateRange\')) {\n			if (queryForm.dateRange && queryForm.dateRange.length === 2) {\n				queryForm.startDate = queryForm.dateRange[0]\n				queryForm.endDate = queryForm.dateRange[1]\n			}\n			delete queryForm.dateRange\n		}\n\n		//如果queryForm包含dateTimeRange\n		if (queryForm.hasOwnProperty(\'dateTimeRange\')) {\n			if (queryForm.dateTimeRange && queryForm.dateTimeRange.length === 2) {\n				queryForm.startTime = queryForm.dateTimeRange[0]\n				queryForm.endTime = queryForm.dateTimeRange[1]\n			}\n			delete queryForm.dateTimeRange\n		}\n\n		//如果是分页，添加分页参数\n		if (state.isPage) {\n			queryForm.pageNum = state.pageNum\n			queryForm.pageSize = state.pageSize\n		}\n\n		//排序字段\n		if (state.order) {\n			queryForm.orderItemList = [{ column: state.order, asc: state.asc }]\n		}\n\n		state.dataListLoading = true\n\n		//调用接口\n		state.dataListApi!(queryForm)\n			.then((res: any) => {\n				if (state.isPage) {\n					state.dataList = res.data.records\n					state.total = res.data.total\n				} else {\n					state.dataList = res.data\n					state.total = res.data.length\n					state.pageNum = 1\n					state.pageSize = res.data.length\n				}\n			})\n			.finally(() => {\n				state.dataListLoading = false\n			})\n	}\n\n	// 异步验证表单\n	const validateQueryForm = (): Promise<boolean> => {\n		return new Promise(resolve => {\n			if (queryRef.value) {\n				queryRef.value.validate((valid: boolean) => {\n					resolve(valid)\n				})\n			} else {\n				resolve(true)\n			}\n		})\n	}\n\n	const query = () => {\n		// 先进行表单验证，验证通过后再执行查询\n		validateQueryForm().then(valid => {\n			if (!valid) {\n				return\n			}\n			executeQuery()\n		})\n	}\n\n	// 加载数据列表\n	const getDataList = () => {\n		state.pageNum = 1\n		query()\n	}\n\n	// pageNum发生变化\n	const currentChangeHandle = (pageNum: number) => {\n		state.pageNum = pageNum\n		query()\n	}\n\n	// pageSize发生变化\n	const sizeChangeHandle = (pageSize: number) => {\n		state.pageNum = 1\n		state.pageSize = pageSize\n		query()\n	}\n\n	// 多选\n	const selectionChangeHandle = (selections: any[]) => {\n		state.dataListSelections = selections.map((item: any) => state.primaryKey && item[state.primaryKey])\n	}\n\n	// 排序\n	const sortChangeHandle = ({ order, prop }: any) => {\n		if (order === \'ascending\') {\n			state.order = prop\n			state.asc = true\n		} else if (order === \'descending\') {\n			state.order = prop\n			state.asc = false\n		} else {\n			state.order = \'\'\n		}\n		getDataList()\n	}\n\n	// 批量删除\n	const deleteBatchHandle = (key?: number | string) => {\n		let data: any[] = []\n		if (key) {\n			data = [key]\n		} else {\n			data = state.dataListSelections ? state.dataListSelections : []\n\n			if (data.length === 0) {\n				ElMessage.warning(\'请选择删除记录\')\n				return\n			}\n		}\n\n		ElMessageBox.confirm(state.deleteMessage, \'提示\', {\n			confirmButtonText: \'确定\',\n			cancelButtonText: \'取消\',\n			type: \'warning\'\n		}).then(() => {\n			state.deleteListApi!(data).then(() => {\n				ElMessage.success(\'删除成功\')\n				query()\n			})\n		})\n	}\n\n	const tableIndex = (index: number) => {\n		return (state.pageNum! - 1) * state.pageSize! + index + 1\n	}\n\n	return {\n		getDataList,\n		sizeChangeHandle,\n		currentChangeHandle,\n		selectionChangeHandle,\n		sortChangeHandle,\n		deleteBatchHandle,\n		queryRef,\n		resetQueryHandle,\n		tableIndex\n	}\n}\n', NULL, NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2094, 79, 2092, 'use-init-form.ts.ftl', 'use-init-form.ts', 1, '初始化表单hooks', 'import { ref } from \'vue\'\n\nexport const useInitForm = () => {\n	const addOrUpdateRef = ref()\n	const addOrUpdateHandle = (id?: number) => {\n		addOrUpdateRef.value.init(id)\n	}\n\n	return {\n		addOrUpdateRef,\n		addOrUpdateHandle\n	}\n}\n', NULL, NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2095, 79, 2092, 'use-submit-form.ts.ftl', 'use-submit-form.ts', 1, '表单回显、提交hooks', 'import { ref } from \'vue\'\nimport { ElMessage } from \'element-plus\'\nimport { AxiosPromise } from \'axios\'\n\nexport interface FormOptions {\n	// 提交API\n	submitApi: (data: any) => AxiosPromise\n	// 详情API\n	detailApi: (id: number) => AxiosPromise\n	// 初始化之前调用\n	initBefore?: () => void\n	// 表单数据\n	dataForm: any\n	// 初始化之后调用\n	initAfter?: () => void\n	// 提交之前操作\n	submitBefore?: () => void\n	// 触发事件\n	emit: any\n	// 提示信息\n	message?: string\n	// 提示时长\n	duration?: number\n}\n\nexport const useSubmitForm = (options: FormOptions) => {\n	const visible = ref(false) // 弹窗可见性\n	const submitLoading = ref(false) // 提交按钮loading状态\n	const dataFormRef = ref() // 表单ref\n\n	// 初始化表单\n	const init = (id?: number) => {\n		visible.value = true\n		options.dataForm.id = null\n		// 重置表单状态\n		if (dataFormRef.value) {\n			dataFormRef.value.resetFields()\n		}\n\n		// 初始化之前调用\n		options.initBefore?.()\n\n		if (id) {\n			// 获取详情数据\n			options.detailApi(id).then(res => {\n				Object.assign(options.dataForm, res.data)\n\n				// 获取详情之后调用\n				options.initAfter?.()\n			})\n		} else {\n			options.initAfter?.()\n		}\n	}\n\n	// 表单验证并提交\n	const submitHandle = () => {\n		dataFormRef.value.validate((valid: boolean) => {\n			if (!valid) {\n				return false\n			}\n\n			// 提交之前操作\n			options.submitBefore?.()\n\n			submitLoading.value = true\n\n			// 提示消息\n			const message = options.message || (options.dataForm.id ? \'修改成功\' : \'新增成功\')\n			options\n				.submitApi(options.dataForm)\n				.then(resp => {\n					ElMessage.success({\n						message: message,\n						duration: options.duration || 500\n					})\n					visible.value = false\n					options.emit(\'refreshDataList\', resp.data)\n				})\n				.finally(() => {\n					submitLoading.value = false\n				})\n		})\n	}\n\n	return {\n		visible,\n		dataFormRef,\n		init,\n		submitHandle,\n		submitLoading\n	}\n}\n', NULL, NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2096, 79, 2092, 'refresh-hook.ftl', 'use-refresh-current-page.ts', 1, '刷新页面的hook（支持缓存和非缓存、iframe和非iframe）', 'import { useAppStore } from \'@/store/app-store\'\nimport { useRoute, useRouter } from \'vue-router\'\nimport { useSystemSettingStore } from \'@/store/system-setting-store\'\n\n// 刷新当前页面\nexport const usePageRefresher = () => {\n	const appStore = useAppStore()\n	const systemSettingStore = useSystemSettingStore()\n	const route = useRoute()\n	const router = useRouter()\n\n	const refreshPage = () => {\n		const { type, cache } = route.meta\n		const name = route.name as string\n\n		// 关闭了全局页面缓存，使用路由跳转实现刷新\n		if (!systemSettingStore.isOpenPageCache) {\n			// 使用路由跳转实现刷新\n			router.push({\n				path: \'/redirect\' + route.fullPath,\n				query: route.query\n			})\n		} else {\n			// 开启了全局页面缓存，使用组件缓存实现刷新\n			// 业务菜单\n			if (type === 1) {\n				// 如果是缓存，删除缓存\n				if (cache) {\n					appStore.removeCacheComponent(name)\n				}\n\n				// 使用路由跳转实现刷新\n				router.push({\n					path: \'/redirect\' + route.fullPath,\n					query: route.query\n				})\n			} else if (type === 3 && cache === false) {\n				// iframe菜单，非缓存\n				// 使用路由跳转实现刷新\n				router.push({\n					path: \'/redirect\' + route.fullPath,\n					query: route.query\n				})\n			} else {\n				// iframe菜单，缓存\n				const idx = appStore.iframeCacheList.findIndex(i => i.fullPath === route.fullPath)\n				if (idx !== -1) {\n					const old = appStore.iframeCacheList[idx]\n					// 修改src的值，会触发刷新\n					old.src = <#noparse>`${old.src.split(\'?\')[0]}?t=${Date.now()}`</#noparse>\n				}\n			}\n		}\n	}\n	return { refreshPage }\n}\n', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2097, 79, 2027, '', 'directive', 0, NULL, NULL, NULL, NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2098, 79, 2097, 'directive-index.ts.ftl', 'index.ts', 1, '自定义指令注册主文件', 'import { App } from \'vue\'\nimport { hasPermission } from \'@/directive/permission\'\n\nexport default function directive(app: App<Element>) {\n	app.directive(\'auth\', hasPermission)\n	//如果有其它的指令可以继续添加\n}\n', NULL, NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2099, 79, 2097, 'permission.ts.ftl', 'permission.ts', 1, '自定义权限文件', 'import { DirectiveBinding } from \'vue\'\nimport { useUserStore } from \'@/store/user-store\'\n\nexport function hasPermission(el: Element, binding: DirectiveBinding) {\n	const userStore = useUserStore()\n	const { value } = binding\n\n	if (!value) {\n		throw new Error(\'请传入权限标识\')\n	}\n	if (typeof value == \'string\') {\n		//没有权限就移除当前元素\n		if (!userStore.permissionList.includes(value)) {\n			el.parentNode?.removeChild(el)\n		}\n		return\n	}\n	if (Array.isArray(value)) {\n		//用户权限是否拥有数组中的任意一个权限\n		const hasPerm = value.some(item => userStore.permissionList.includes(item))\n		if (!hasPerm) {\n			el.parentNode?.removeChild(el)\n		}\n		return\n	}\n\n	throw new Error(\'权限标识格式不正确\')\n}\n', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
