INSERT INTO `gen_template` VALUES (2102, 79, 2101, 'svg-icon.ts.ftl', 'index.ts', 1, '自定义图标注册ts', 'import { withInstall } from \'@/utils/tool\'\nimport SvgIcon from \'@/components/svg-icon/index.vue\'\n\nexport default withInstall(SvgIcon)\n', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2103, 79, 2101, 'svg-icon.vue.ftl', 'index.vue', 1, '自定义图标组件', '<template>\n	<svg\n		class=\"svg-icon\"\n		:style=\"{\n			color,\n			width: size,\n			height: size,\n			...(isPointer !== undefined ? { cursor: isPointer ? \'pointer\' : \'default\' } : {})\n		}\"\n		aria-hidden=\"true\"\n	>\n		<use :xlink:href=\"`#<#noparse>${icon}</#noparse>`\"></use>\n	</svg>\n</template>\n<script setup lang=\"ts\">\ndefineProps({\n	// 图标名称（传入时需要带上前缀 icon-）\n	icon: {\n		type: String,\n		required: true\n	},\n	// 图标颜色\n	color: {\n		type: String,\n		default: \'\'\n	},\n	// 图标大小，支持 px / em / rem\n	size: {\n		type: String,\n		default: \'1em\'\n	},\n	// 是否为pointer\n	isPointer: {\n		type: Boolean,\n		required: false\n	}\n})\n</script>\n\n<style scoped>\n.svg-icon {\n	display: inline-block;\n	vertical-align: middle;\n	fill: currentColor; /* 保持与文字颜色同步 */\n}\n</style>\n', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2104, 79, 2100, '', 'dict-tag', 0, '', '', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2105, 79, 2104, 'dict-el-tag.ftl', 'index.vue', 1, '字典标签组件', '<template>\n	<el-tag :type=\"enumItem.type\" :color=\"enumItem.color\">{{ enumItem.label }}</el-tag>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, PropType } from \'vue\'\nimport { EnumItem, EnumValueType, getByValue } from \'@/utils/enum\'\n\nconst props = defineProps({\n	value: {\n		type: [String, Number, Boolean] as PropType<EnumValueType>,\n		required: true\n	},\n	enumItemList: {\n		type: Array as PropType<EnumItem[]>,\n		required: true\n	}\n})\n\nconst enumItem = computed(() => {\n	const byValue = getByValue(props.value, props.enumItemList)\n	if (byValue) {\n		return byValue\n	} else {\n		return {\n			label: \'未知\',\n			type: \'info\',\n			color: \'\'\n		}\n	}\n})\n</script>\n', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2106, 79, 2027, '', 'constant', 0, '常量目录', '', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
INSERT INTO `gen_template` VALUES (2107, 79, 2106, 'enum.ftl', 'enum.ts', 1, '枚举文件', 'import { EnumItem } from \'@/utils/enum\'\n\n<#list enumModelList as enumModel>\n// ${enumModel.enumDesc}枚举\nexport const ${enumModel.enumNameAllUpper}_ENUM: EnumItem[] = [\n<#list enumModel.enumItemList as item >\n    {  label: \'${item.enumItemDesc}\', value: <#if item.enumItemCode?is_string>\'${item.enumItemCode}\'<#else>${item.enumItemCode}</#if> }<#if item_has_next>,</#if>\n</#list>\n]\n\n</#list>', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:08:45', 0);
