INSERT INTO `gen_template` VALUES (2110, 79, 2109, 'common-crud-api.ftl', 'index.ts', 1, '通用CRUD的API代码', 'import service from \'@/utils/request\'\n\n// 所有可能的CRUD方法签名\ninterface CrudApi {\n    // 新增接口\n    add: (dataForm: any) => Promise<any>\n\n    // 修改接口\n    update: (dataForm: any) => Promise<any>\n\n    // 提交表单接口\n    submit: (dataForm: any) => Promise<any>\n\n    // 单个删除接口\n    delete: (id: number | string) => Promise<any>\n\n    // 批量删除接口\n    deleteList: (idList: number[] | string[]) => Promise<any>\n\n    // 详情接口\n    detail: (id: number | string) => Promise<any>\n\n    // 批量详情接口\n    detailList: (idList: number[] | string[]) => Promise<any>\n\n    /**\n     * 分页查询基础实体数据\n     * - 只返回表的原始字段，不包含关联表信息\n     * - 用于简单分页展示和列表查询\n     */\n    entityPage: (queryForm?: any) => Promise<any>\n\n    /**\n     * 分页查询复杂视图数据（VO）\n     * - 可能包含关联表 JOIN 的额外信息\n     * - 用于需要显示完整业务信息的场景\n     */\n    voPage: (queryForm?: any) => Promise<any>\n\n    /**\n     * 列表查询基础实体数据（无分页）\n     * - 只返回表原始字段\n     */\n    entityList: (queryForm?: any) => Promise<any>\n\n    /**\n     * 列表查询复杂视图数据（VO）（无分页）\n     * - 包含关联表 JOIN 的额外信息\n     */\n    voList: (queryForm?: any) => Promise<any>\n}\n\n// 配置接口，默认所有方法启用，禁用方法时显式设置false\nexport interface CrudConfig {\n    add?: boolean\n    update?: boolean\n    submit?: boolean\n    delete?: boolean\n    deleteList?: boolean\n    detail?: boolean\n    detailList?: boolean\n    entityPage?: boolean\n    entityList?: boolean\n    voPage?: boolean\n    voList?: boolean\n}\n\n// ----------------------------------------------------\n// 工具类型：根据 CrudConfig 过滤掉被显式设置为 false 的接口\n// C：传入的配置类型（每个键为 CrudApi 的方法名，可选值为 false 或省略）\n// CrudApi：完整的 CRUD API 方法集合\n// ----------------------------------------------------\ntype EnabledCrudApi<C extends CrudConfig> = Pick<\n    CrudApi,\n    Exclude<\n        keyof CrudApi,\n        // 找出配置中显式为 false 的方法名，并排除\n        {\n            [K in keyof C]: C[K] extends false ? K : never\n        }[keyof C]\n    >\n>\n\n// ----------------------------------------------------\n// 生成 CRUD API 工厂函数\n// - baseUrl：接口基础路径\n// - opts：可选配置，某些方法设为 false 表示禁用该方法\n// 返回值：自动排除了禁用方法的 CRUD API 对象\n// ----------------------------------------------------\nexport const createCrudApi = <C extends CrudConfig = CrudConfig>(baseUrl: string, opts?: C): EnabledCrudApi<C> => {\n    const api = {} as any\n    const defaultOpts = {\n        add: false,\n        update: false\n    } as C\n    const o = opts || defaultOpts\n\n    const add = <K extends keyof CrudApi>(key: K, fn: CrudApi[K]) => {\n        if (o[key] !== false) {\n            api[key] = fn\n        }\n    }\n\n    add(\'add\', dataForm => service.post(`<#noparse>${baseUrl}/add`</#noparse>, dataForm))\n\n    add(\'update\', dataForm => service.put(<#noparse>`${baseUrl}/update`</#noparse>, dataForm))\n\n    add(\'submit\', dataForm => (dataForm.id ? service.put(<#noparse>`${baseUrl}</#noparse>/update`, dataForm) : service.post(<#noparse>`${baseUrl}</#noparse>/add`, dataForm)))\n\n    add(\'delete\', id => service.delete(<#noparse>`${baseUrl}</#noparse>/delete`, { params: { id } }))\n\n    add(\'deleteList\', idList => service.delete(<#noparse>`${baseUrl}</#noparse>/deleteList`, { data: idList }))\n\n    add(\'detail\', id => service.get(<#noparse>`${baseUrl}</#noparse>/detail`, { params: { id } }))\n\n    add(\'detailList\', idList => service.post(<#noparse>`${baseUrl}</#noparse>/detailList`, idList))\n\n    add(\'entityPage\', queryForm => service.post(<#noparse>`${baseUrl}</#noparse>/entityPage`, queryForm || {}))\n\n    add(\'entityList\', queryForm => service.post(<#noparse>`${baseUrl}</#noparse>/entityList`, queryForm || {}))\n\n    add(\'voPage\', queryForm => service.post(<#noparse>`${baseUrl}</#noparse>/voPage`, queryForm || {}))\n\n    add(\'voList\', queryForm => service.post(<#noparse>`${baseUrl}</#noparse>/voList`, queryForm || {}))\n\n    return api\n}\n', '', NULL, '2025-09-28 18:08:45', '2025-09-28 18:09:00', 1);
