INSERT INTO `gen_template` VALUES (2280, 82, 2279, 'CorsConfig.ftl', 'CorsConfig.java', 1, '跨域文件配置类', 'package ${projectPackage}.${projectNameDot}.common.config;\n\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.web.cors.CorsConfiguration;\nimport org.springframework.web.cors.UrlBasedCorsConfigurationSource;\nimport org.springframework.web.filter.CorsFilter;\n\nimport java.util.List;\n\n/**\n * 跨域配置\n */\n@Configuration\n@ConditionalOnProperty(name = \"web.cors.enable\", havingValue = \"true\", matchIfMissing = true)\npublic class CorsConfig {\n\n    /**\n     * 跨域过期时间。单位：秒\n     */\n    @Value(\"<#noparse>${web.cors.max-age:3600}</#noparse>\")\n    private Long maxAge;\n\n    /**\n     * 跨域是否传递cookie\n     */\n    @Value(\"<#noparse>${web.cors.allow-credentials:true}</#noparse>\")\n    private Boolean allowCredentials;\n\n    /**\n     * 允许跨域的请求头\n     */\n    @Value(\"<#noparse>#{\'${web.cors.allowed-headers:*}\'.split(\',\')}</#noparse>\")\n    private List<String> allowedHeaders;\n\n    /**\n     * 允许跨域的方法\n     */\n    @Value(\"<#noparse>#{\'${web.cors.allowed-methods:*}\'.split(\',\')}</#noparse>\")\n    private List<String> allowedMethods;\n\n    /**\n     * 允许跨域的源\n     */\n    @Value(\"<#noparse>#{\'${web.cors.allowed-origins:*}\'.split(\',\')}</#noparse>\")\n    private List<String> allowedOrigins;\n\n    /**\n     * 允许跨域的响应头\n     */\n    @Value(\"<#noparse>#{\'${web.cors.expose-headers:Content-Disposition,Authorization,token,Cookie}\'.split(\',\')}</#noparse>\")\n    private List<String> exposedHeaders;\n\n    @Bean\n    public CorsFilter corsFilter() {\n        final UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();\n        final CorsConfiguration corsConfiguration = new CorsConfiguration();\n        corsConfiguration.setMaxAge(maxAge);\n        corsConfiguration.setAllowCredentials(allowCredentials);\n        corsConfiguration.setAllowedHeaders(allowedHeaders);\n        corsConfiguration.setAllowedMethods(allowedMethods);\n        corsConfiguration.setAllowedOriginPatterns(allowedOrigins);\n        corsConfiguration.setExposedHeaders(exposedHeaders);\n        source.registerCorsConfiguration(\"/**\", corsConfiguration);\n        return new CorsFilter(source);\n    }\n\n}\n', '', NULL, '2025-10-14 14:04:31', '2025-10-15 13:45:44', 1);
INSERT INTO `gen_template` VALUES (2281, 82, 2279, 'Knife4jConfig.ftl', 'Knife4jConfig.java', 1, 'Knife4j配置类', 'package ${projectPackage}.${projectNameDot}.common.config;\n\nimport com.github.xiaoymin.knife4j.spring.annotations.EnableKnife4j;\nimport io.swagger.v3.oas.models.OpenAPI;\nimport io.swagger.v3.oas.models.info.Info;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/**\n * 创建Knife4j配置\n */\n@Configuration\n@EnableKnife4j\npublic class Knife4jConfig {\n\n    @Value(\"<#noparse>${spring.application.name:}</#noparse>\")\n    private String applicationName;\n\n    @Value(\"<#noparse>${spring.application.version:}</#noparse>\")\n    private String version;\n\n    @Value(\"<#noparse>${spring.application.description:}</#noparse>\")\n    private String description;\n\n    @Bean\n    public OpenAPI customOpenAPI() {\n        return new OpenAPI()\n                .info(new Info()\n                        .title(applicationName)\n                        .version(version)\n                        .description(description)\n                );\n    }\n\n}\n', '', NULL, '2025-10-14 14:04:31', '2025-10-15 13:45:44', 1);
