INSERT INTO `gen_template` VALUES (2439, 84, 2437, 'BaseVO.ftl', 'BaseVO.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * Controller返回值数据基类\n * <p>自定义VO类继承该类即可</p>\n */\n@Data\n@Schema(description = \"数据VO基类\")\npublic abstract class BaseVO implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = -5814569213714989166L;\n\n    /**\n     * 创建时间\n     */\n    @Schema(description = \"创建时间\")\n    private Date createTime;\n\n    /**\n     * 修改时间\n     */\n    @Schema(description = \"修改时间\")\n    private Date updateTime;\n\n    /**\n     * 是否删除（0正常, 1删除）\n     */\n    @Schema(description = \"是否删除（0正常, 1删除）\")\n    private Integer isDelete;\n\n}', NULL, NULL, '2025-10-14 14:17:02', '2025-10-14 14:17:16', 1);
INSERT INTO `gen_template` VALUES (2440, 84, 2437, 'PageVO.ftl', 'PageVO.java', 1, '分页响应参数', 'package ${projectPackage}.${projectNameDot}.common.domain.vo;\n\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\nimport lombok.NoArgsConstructor;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.List;\n\n/**\n * 分页数据封装\n *\n * @param <T> 必须是VO\n */\n@Data\n@NoArgsConstructor\n@Schema(description = \"分页数据封装\")\npublic class PageVO<T> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 3563028771440196184L;\n\n    /**\n     * 当前页码\n     */\n    @Schema(description = \"当前页码\")\n    private Long pageNum;\n\n    /**\n     * 每页显示条数\n     */\n    @Schema(description = \"每页显示条数\")\n    private Long pageSize;\n\n    /**\n     * 分页数据\n     */\n    @Schema(description = \"分页数据\")\n    private List<T> records;\n\n    /**\n     * 总记录数\n     */\n    @Schema(description = \"总记录数\")\n    private Long total;\n\n    /**\n     * 将其余VO分页数据转换成PageVO分页数据\n     */\n    public PageVO(PageQuery<T> pageQuery) {\n        this.pageNum = pageQuery.getPageNum();\n        this.pageSize = pageQuery.getPageSize();\n        this.records = pageQuery.getRecords();\n        this.total = pageQuery.getTotal();\n    }\n\n    /**\n     * 转成成分页数据通过全量参数\n     *\n     * @param records 已经分页后的list\n     */\n    public PageVO(Long pageNum, Long pageSize, Long total, List<T> records) {\n        this.pageNum = pageNum;\n        this.pageSize = pageSize;\n        this.total = total;\n        this.records = records;\n    }\n\n    /**\n     * 转换成分页数据，手动分页\n     *\n     * @param records 分页前的数据\n     */\n    public PageVO(Long pageNum, Long pageSize, List<T> records) {\n        this.pageNum = pageNum;\n        this.pageSize = pageSize;\n        this.total = (long) records.size();\n        this.records = records.stream()\n                .skip((pageNum - 1) * pageSize)\n                .limit(pageSize)\n                .toList();\n    }\n\n}\n', '', NULL, '2025-10-14 14:17:02', '2025-10-14 14:17:16', 1);
