INSERT INTO `gen_template` VALUES (2458, 84, 2457, 'CommonMetaObjectHandler.ftl', 'CommonMetaObjectHandler.java', 1, 'mybatis-plus数据填充配置类', 'package ${projectPackage}.${projectNameDot}.common.mybatis.config;\n\nimport com.baomidou.mybatisplus.core.handlers.MetaObjectHandler;\nimport org.apache.ibatis.reflection.MetaObject;\n\nimport java.util.Date;\n\n/**\n * 填充公共字段\n */\npublic class CommonMetaObjectHandler implements MetaObjectHandler {\n\n    @Override\n    public void insertFill(MetaObject metaObject) {\n        //插入的时候设置添加和修改时间的值\n        this.setFieldValByName(\"createTime\", new Date(), metaObject);\n        this.setFieldValByName(\"updateTime\", new Date(), metaObject);\n        this.setFieldValByName(\"isDelete\", 0, metaObject);\n    }\n\n    @Override\n    public void updateFill(MetaObject metaObject) {\n        //更新的时候设置修改时间的值\n        this.setFieldValByName(\"updateTime\", new Date(), metaObject);\n    }\n\n}\n', '', NULL, '2025-10-14 14:17:03', '2025-10-14 14:17:16', 1);
INSERT INTO `gen_template` VALUES (2459, 84, 2457, 'MybatisPlusConfig.ftl', 'MybatisPlusConfig.java', 1, 'mybatis-plus配置类', 'package ${projectPackage}.${projectNameDot}.common.mybatis.config;\n\nimport com.baomidou.mybatisplus.annotation.DbType;\nimport com.baomidou.mybatisplus.core.handlers.MetaObjectHandler;\nimport com.baomidou.mybatisplus.extension.plugins.MybatisPlusInterceptor;\nimport com.baomidou.mybatisplus.extension.plugins.inner.PaginationInnerInterceptor;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/**\n * mybatis-plus配置类\n */\n@Configuration\npublic class MybatisPlusConfig {\n\n    /**\n     * 添加分页插件\n     */\n    @Bean\n    public MybatisPlusInterceptor mybatisPlusInterceptor() {\n        MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor();\n        //如果配置多个插件, 切记分页最后添加\n        interceptor.addInnerInterceptor(new PaginationInnerInterceptor(DbType.MYSQL));\n        return interceptor;\n    }\n\n    /**\n     * 自动填充部分数据（createTime、updateTime、isDelete）\n     */\n    @Bean\n    public MetaObjectHandler metaObjectHandler() {\n        return new CommonMetaObjectHandler();\n    }\n\n}\n', '', NULL, '2025-10-14 14:17:03', '2025-10-14 14:17:16', 1);
