INSERT INTO `gen_template` VALUES (2493, 85, 2492, 'application.ftl', 'application.yaml', 1, 'springboot项目配置文件', 'server:\n  port: 8080\n  servlet:\n    context-path: /${projectName}\n\nspring:\n  # 项目名配置\n  application:\n    name: ${projectName}\n    version: \'${projectVersion}\'\n    description: \'${projectDesc}\'\n\n  main:\n    # 允许循环依赖\n    allow-circular-references: true\n\n  # 配置策略\n  mvc:\n    pathmatch:\n      matching-strategy: ANT_PATH_MATCHER\n\n  # jackson配置\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8\n\n<#if databaseDriverClassName??>\n  # 数据源配置\n  datasource:\n    driver-class-name: ${databaseDriverClassName}\n    url: ${databaseUrl}\n    username: ${databaseUsername}\n    password: ${databasePassword}\n</#if>\n\n# mybatis-plus配置\nmybatis-plus:\n  # mapper配置文件\n  mapper-locations: classpath*:mapper/**/*.xml\n  configuration:\n    # 日志配置\n    log-impl: org.apache.ibatis.logging.slf4j.Slf4jImpl\n\nknife4j:\n  enable: true', '', NULL, '2025-10-16 15:05:54', '2025-10-16 15:06:03', 1);
INSERT INTO `gen_template` VALUES (2494, 85, 2492, 'logback-spring.ftl', 'logback-spring.xml', 1, 'logback文件日志配置', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<configuration>\n\n    <!-- 服务名称 -->\n    <springProperty name=\"APP_NAME\" source=\"spring.application.name\" defaultValue=\"app\" />\n    <!-- 日志格式 -->\n    <springProperty name=\"LOG_PATTERN\" source=\"logging.pattern.console\"\n                    defaultValue=\"%d{yyyy-MM-dd HH:mm:ss.SSS} [%thread] %-5level %logger{36}:%line - %msg%n\"/>\n    <!-- 指定日志输出路径 -->\n    <springProperty name=\"LOG_PATH\" source=\"logging.file.path\" defaultValue=\"./logs\" />\n    <!-- 日志文件最大大小 -->\n    <springProperty name=\"MAX_FILE_SIZE\" source=\"logging.max-file-size\" defaultValue=\"200MB\" />\n    <!-- 日志保留天数 -->\n    <springProperty name=\"MAX_HISTORY\" source=\"logging.max-history\" defaultValue=\"30\" />\n\n    <!-- 输出到控制台 -->\n    <appender name=\"CONSOLE\" class=\"ch.qos.logback.core.ConsoleAppender\">\n        <encoder>\n            <Pattern><#noparse>${LOG_PATTERN}</#noparse></Pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n    </appender>\n\n    <!-- 所有日志级别 -->\n    <appender name=\"ALL_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <!-- 正在记录的日志文档的路径及文档名 -->\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-all.log</#noparse></file>\n        <!--日志文档输出格式-->\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-all-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n    </appender>\n\n    <!-- DEBUG日志级别 -->\n    <appender name=\"DEBUG_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <!-- 正在记录的日志文档的路径及文档名 -->\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-debug.log</#noparse></file>\n        <!--日志文档输出格式-->\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-debug-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <!-- 此日志文档只记录debug级别的 -->\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>DEBUG</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- INFO日志级别 -->\n    <appender name=\"INFO_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-info.log</#noparse></file>\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-info-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>INFO</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- WARN日志级别 -->\n    <appender name=\"WARN_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-warn.log</#noparse></file>\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-warn-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>WARN</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- ERROR日志级别 -->\n    <appender name=\"ERROR_FILE\" class=\"ch.qos.logback.core.rolling.RollingFileAppender\">\n        <file><#noparse>${LOG_PATH}/${APP_NAME}-error.log</#noparse></file>\n        <encoder>\n            <pattern><#noparse>${LOG_PATTERN}</#noparse></pattern>\n            <charset>UTF-8</charset>\n        </encoder>\n        <rollingPolicy class=\"ch.qos.logback.core.rolling.SizeAndTimeBasedRollingPolicy\">\n            <fileNamePattern><#noparse>${LOG_PATH}/${APP_NAME}-error-%d{yyyy-MM-dd}-%i.log.gz</#noparse></fileNamePattern>\n            <maxFileSize><#noparse>${MAX_FILE_SIZE}</#noparse></maxFileSize>\n            <maxHistory><#noparse>${MAX_HISTORY}</#noparse></maxHistory>\n        </rollingPolicy>\n        <filter class=\"ch.qos.logback.classic.filter.LevelFilter\">\n            <level>ERROR</level>\n            <onMatch>ACCEPT</onMatch>\n            <onMismatch>DENY</onMismatch>\n        </filter>\n    </appender>\n\n    <!-- mapper接口日志配置 -->\n    <logger name=\"${projectPackage}.${projectNameDot}.mapper\" level=\"DEBUG\" />\n\n    <root level=\"INFO\">\n        <appender-ref ref=\"CONSOLE\" />\n        <appender-ref ref=\"DEBUG_FILE\" />\n        <appender-ref ref=\"ERROR_FILE\" />\n        <appender-ref ref=\"WARN_FILE\" />\n        <appender-ref ref=\"INFO_FILE\" />\n        <appender-ref ref=\"ALL_FILE\" />\n    </root>\n\n</configuration>', '', NULL, '2025-10-16 15:05:54', '2025-10-16 15:06:03', 1);
INSERT INTO `gen_template` VALUES (2495, 85, 2492, '', 'mapper', 0, NULL, NULL, '', NULL, '2025-10-16 15:05:54', '2025-10-16 15:06:03', 1);
INSERT INTO `gen_template` VALUES (2496, 85, 2495, 'BaseMapperPlus.xml.ftl', 'BaseMapperPlus.xml', 1, '通用mybatis的mapper的xml文件', '<?xml version=\"1.0\" encoding=\"UTF-8\" ?>\n<!DOCTYPE mapper\n        PUBLIC \"-//mybatis.org//DTD Mapper 3.0//EN\"\n        \"http://mybatis.org/dtd/mybatis-3-mapper.dtd\">\n<mapper namespace=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus\">\n\n    <!-- 排序SQL -->\n    <sql id=\"orderBySQL\">\n        <bind name=\"columnPrefix\" value=\"\'\'\"/>\n        <include refid=\"${projectPackage}.${projectNameDot}.common.mybatis.mapper.BaseMapperPlus.prefixOrderBySQL\"/>\n    </sql>\n\n    <!-- 排序SQL（带前缀） -->\n    <sql id=\"prefixOrderBySQL\">\n        <if test=\"@${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil@isNotEmpty(query, \'orderItemList\')\">\n            ORDER BY\n            <foreach collection=\"query.orderItemList\" item=\"order\" separator=\",\">\n                <if test=\"@${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil@isNotEmpty(columnPrefix)\">\n                    <#noparse>${columnPrefix}</#noparse>.\n                </if>\n                <#noparse>${columnPrefix}.${@</#noparse>${projectPackage}.${projectNameDot}.common.mybatis.util.MybatisUtil@toUnderlineCase(order.column)} <if test=\"order.asc\">ASC</if><if test=\"!order.asc\">DESC</if>\n            </foreach>\n        </if>\n    </sql>\n\n</mapper>\n', '', NULL, '2025-10-16 15:05:54', '2025-10-16 15:06:03', 1);
