INSERT INTO `gen_template` VALUES (2580, 86, 2579, 'BaseEntity.ftl', 'BaseEntity.java', 1, 'Entity基类', 'package ${projectPackage}.${projectNameDot}.common.domain.entity;\n\n\nimport com.baomidou.mybatisplus.annotation.FieldFill;\nimport com.baomidou.mybatisplus.annotation.TableField;\nimport com.baomidou.mybatisplus.annotation.TableLogic;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Date;\n\n/**\n * 数据库实体基类\n * <p>包含创建时间、修改时间、删除标识三个字段</p>\n */\n@Data\npublic abstract class BaseEntity implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 4784400802803080438L;\n\n    /**\n     * 创建时间\n     */\n    @TableField(value = \"create_time\", fill = FieldFill.INSERT)\n    private Date createTime;\n\n    /**\n     * 修改时间\n     */\n    @TableField(value = \"update_time\", fill = FieldFill.INSERT_UPDATE)\n    private Date updateTime;\n\n    /**\n     * 是否删除（0未删除, 1删除）\n     */\n    @TableField(\"is_delete\")\n    @TableLogic(value = \"0\", delval = \"1\")\n    private Integer isDelete;\n\n}', NULL, NULL, '2025-10-16 16:55:22', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2581, 86, 2579, 'BaseUserEntity.ftl', 'BaseUserEntity.java', 1, 'Entity用户基类', 'package ${projectPackage}.${projectNameDot}.common.domain.entity;\n\nimport com.baomidou.mybatisplus.annotation.FieldFill;\nimport com.baomidou.mybatisplus.annotation.TableField;\nimport lombok.Data;\nimport lombok.EqualsAndHashCode;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\n/**\n * 数据库实体类基类，适用于用户操作的数据表、增删改查\n */\n@Data\n@EqualsAndHashCode(callSuper = true)\npublic abstract class BaseUserEntity extends BaseEntity implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = -3534460034686573788L;\n\n    /**\n     * 创建人\n     */\n    @TableField(value = \"create_user_id\", fill = FieldFill.INSERT)\n    private Long createUserId;\n\n    /**\n     * 修改人\n     */\n    @TableField(value = \"update_user_id\", fill = FieldFill.INSERT_UPDATE)\n    private Long updateUserId;\n\n}\n', '', NULL, '2025-10-16 16:55:22', '2025-10-16 16:55:37', 1);
