INSERT INTO `gen_template` VALUES (2594, 86, 2593, 'BaseMapstruct.ftl', 'BaseMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\n/**\n * Mapstruct转换基类，提供Entity、VO、DTO之间基本的转换\n * <p>适用于Entity、VO、DTO都存在的情况</p>\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n */\npublic interface BaseMapstruct<E, V, D> extends DTOToEntityMapstruct<D, E>, PageEntityMapstruct<E, V>, PageVOMapstruct<V> {\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2595, 86, 2593, 'BaseNoDTOMapstruct.ftl', 'BaseNoDTOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\n/**\n * Mapstruct转换基类，提供Entity和VO之间基本的转换\n * <p>适用于DTO不存在的情况，但是有分页的情况</p>\n * <p>例如系统日志表，它的数据是程序内部自己生成的，并不是外界传入</p>\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface BaseNoDTOMapstruct<E, V> extends PageEntityMapstruct<E, V>, PageVOMapstruct<V> {\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2596, 86, 2593, 'BaseNoPageMapstruct.ftl', 'BaseNoPageMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\n/**\n * Mapstruct转换基类，提供Entity、VO、DTO之间基本的转换\n * <p>适用于Entity、VO、DTO都存在的情况，但是不需要分页</p>\n * <p>例如系统内置字典表。可能就10条数据</p>\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n */\npublic interface BaseNoPageMapstruct<E, V, D> extends DTOToEntityMapstruct<D, E>, EntityToVOMapstruct<E, V> {\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2597, 86, 2593, 'DTOToEntityMapstruct.ftl', 'DTOToEntityMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport org.dromara.hutool.core.collection.CollUtil;\n\nimport java.util.Collections;\nimport java.util.List;\n\n/**\n * 将DTO转换成Entity的通用接口\n *\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n * @param <E> entity实体类泛型（数据库实体类）\n */\npublic interface DTOToEntityMapstruct<D, E> {\n\n    /**\n     * 将DTO转换成Entity\n     */\n    E dtoToEntity(D dto);\n\n    /**\n     * 将DTO列表转换为Entity列表\n     */\n    default List<E> dtoToEntity(List<D> dtoList) {\n        if (CollUtil.isEmpty(dtoList)) {\n            return Collections.emptyList();\n        }\n        return dtoList.stream().map(this::dtoToEntity).toList();\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2598, 86, 2593, 'EntityToDTOMapstruct.ftl', 'EntityToDTOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport org.dromara.hutool.core.collection.CollUtil;\n\nimport java.util.Collections;\nimport java.util.List;\n\n/**\n * 将Entity转换成DTO的通用接口\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <D> dto实体类泛型（controller新增、修改请求参数）\n */\npublic interface EntityToDTOMapstruct<E, D> {\n\n    /**\n     * 将Entity转换成DTO\n     */\n    D entityToDTO(E entity);\n\n    /**\n     * 将DTO列表转换为Entity列表\n     */\n    default List<D> entityToDTO(List<E> entityList) {\n        if (CollUtil.isEmpty(entityList)) {\n            return Collections.emptyList();\n        }\n        return entityList.stream().map(this::entityToDTO).toList();\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2599, 86, 2593, 'EntityToVOMapstruct.ftl', 'EntityToVOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport org.dromara.hutool.core.collection.CollUtil;\n\nimport java.util.Collections;\nimport java.util.List;\n\n/**\n * 将Entity转换成VO的通用接口\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface EntityToVOMapstruct<E, V> {\n\n    /**\n     * 将Entity转换成VO\n     */\n    V entityToVO(E entity);\n\n    /**\n     * 将Entity列表转换成VO列表\n     */\n    default List<V> entityToVO(List<E> entityList) {\n        if (CollUtil.isEmpty(entityList)) {\n            return Collections.emptyList();\n        }\n        return entityList.stream().map(this::entityToVO).toList();\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2600, 86, 2593, 'PageEntityMapstruct.ftl', 'PageEntityMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\n\nimport java.util.List;\n\n/**\n * 将Entity分页数据转换为VO分页数据的通用接口\n *\n * @param <E> entity实体类泛型（数据库实体类）\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface PageEntityMapstruct<E, V> extends EntityToVOMapstruct<E, V> {\n\n    /**\n     * 将Entity分页数据转换为VO分页数据\n     */\n    default PageVO<V> entityToPageVO(PageQuery<E> entityPageQuery) {\n        Long pageNum = entityPageQuery.getPageNum();\n        Long pageSize = entityPageQuery.getPageSize();\n        long total = entityPageQuery.getTotal();\n        List<V> voList = this.entityToVO(entityPageQuery.getRecords());\n        return new PageVO<>(pageNum, pageSize, total, voList);\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2601, 86, 2593, 'PageVOMapstruct.ftl', 'PageVOMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\n\n/**\n * 将VO分页数据转换为VO分页数据的通用接口\n *\n * @param <V> vo实体类泛型（controller返回参数）\n */\npublic interface PageVOMapstruct<V> extends PageVOOtherMapstruct {\n\n    /**\n     * 将VO分页数据转换成PageVO分页数据\n     */\n    default PageVO<V> voToPageVO(PageQuery<V> voPageQuery) {\n        return toPageVO(voPageQuery);\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2602, 86, 2593, 'PageVOOtherMapstruct.ftl', 'PageVOOtherMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport ${projectPackage}.${projectNameDot}.common.domain.query.PageQuery;\nimport ${projectPackage}.${projectNameDot}.common.domain.vo.PageVO;\n\nimport java.util.List;\n\n/**\n * 其余情况下的分页数据转换\n */\npublic interface PageVOOtherMapstruct {\n\n    /**\n     * 将其余VO分页数据转换成PageVO分页数据\n     *\n     * @param <T> 其余VO对象\n     */\n    default <T> PageVO<T> toPageVO(PageQuery<T> voPageQuery) {\n        return new PageVO<>(voPageQuery);\n    }\n\n    /**\n     * 转成成分页数据通过全量参数\n     *\n     * @param records 已经分页后的list\n     */\n    default <T> PageVO<T> toPageVOWithFullParams(Long pageNum, Long pageSize, Long total, List<T> records) {\n        return new PageVO<>(pageNum, pageSize, total, records);\n    }\n\n    /**\n     * 转换成分页数据，手动分页\n     *\n     * @param records 分页前的数据\n     */\n    default <T> PageVO<T> toPageVOWithPagination(Long pageNum, Long pageSize, List<T> records) {\n        return new PageVO<>(pageNum, pageSize, records);\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2603, 86, 2593, 'VOToEntityMapstruct.ftl', 'VOToEntityMapstruct.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mapstruct;\n\nimport org.dromara.hutool.core.collection.CollUtil;\n\nimport java.util.Collections;\nimport java.util.List;\n\n/**\n * 将VO转换成Entity的通用接口\n *\n * @param <V> vo实体类泛型（controller返回参数）\n * @param <E> entity实体类泛型（数据库实体类）\n */\npublic interface VOToEntityMapstruct<V, E> {\n\n    /**\n     * 将VO转换成Entity\n     */\n    E voToEntity(V vo);\n\n    /**\n     * 将Entity列表转换成VO列表\n     */\n    default List<E> voToEntity(List<V> voList) {\n        if (CollUtil.isEmpty(voList)) {\n            return Collections.emptyList();\n        }\n        return voList.stream().map(this::voToEntity).toList();\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
