INSERT INTO `gen_template` VALUES (2609, 86, 2608, 'BaseMapperPlus.ftl', 'BaseMapperPlus.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.mybatis.mapper;\n\nimport com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;\nimport com.baomidou.mybatisplus.core.mapper.BaseMapper;\nimport com.baomidou.mybatisplus.extension.toolkit.Db;\n\nimport java.util.Collection;\nimport java.util.List;\n\n/**\n * 自定义Mapper接口, 实现自定义扩展\n *\n * @param <T> Entity泛型\n */\npublic interface BaseMapperPlus<T> extends BaseMapper<T> {\n\n    /**\n     * 使用默认的查询条件查询并返回结果列表\n     *\n     * @return 返回查询结果的列表\n     */\n    default List<T> selectList() {\n        return this.selectList(new QueryWrapper<>());\n    }\n\n    /**\n     * 批量插入实体对象集合\n     *\n     * @param entityList 实体对象集合\n     * @return 插入操作是否成功的布尔值\n     */\n    default boolean insertBatch(Collection<T> entityList) {\n        return Db.saveBatch(entityList);\n    }\n\n    /**\n     * 批量插入实体对象集合并指定批处理大小\n     *\n     * @param entityList 实体对象集合\n     * @param batchSize  批处理大小\n     * @return 插入操作是否成功的布尔值\n     */\n    default boolean insertBatch(Collection<T> entityList, int batchSize) {\n        return Db.saveBatch(entityList, batchSize);\n    }\n\n    /**\n     * 批量根据ID更新实体对象集合\n     *\n     * @param entityList 实体对象集合\n     * @return 更新操作是否成功的布尔值\n     */\n    default boolean updateBatchById(Collection<T> entityList) {\n        return Db.updateBatchById(entityList);\n    }\n\n    /**\n     * 批量根据ID更新实体对象集合并指定批处理大小\n     *\n     * @param entityList 实体对象集合\n     * @param batchSize  批处理大小\n     * @return 更新操作是否成功的布尔值\n     */\n    default boolean updateBatchById(Collection<T> entityList, int batchSize) {\n        return Db.updateBatchById(entityList, batchSize);\n    }\n\n    /**\n     * 批量插入或更新实体对象集合\n     *\n     * @param entityList 实体对象集合\n     * @return 插入或更新操作是否成功的布尔值\n     */\n    default boolean insertOrUpdateBatch(Collection<T> entityList) {\n        return Db.saveOrUpdateBatch(entityList);\n    }\n\n    /**\n     * 批量插入或更新实体对象集合并指定批处理大小\n     *\n     * @param entityList 实体对象集合\n     * @param batchSize  批处理大小\n     * @return 插入或更新操作是否成功的布尔值\n     */\n    default boolean insertOrUpdateBatch(Collection<T> entityList, int batchSize) {\n        return Db.saveOrUpdateBatch(entityList, batchSize);\n    }\n\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
