INSERT INTO `gen_template` VALUES (2613, 86, 2612, 'IgnoreResult.ftl', 'IgnoreResult.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport java.lang.annotation.*;\n\n/**\n * 方法加上这个注解代表无需自动封装 {@link Result} 返回值\n */\n@Documented\n@Target({ElementType.METHOD, ElementType.TYPE})\n@Retention(RetentionPolicy.RUNTIME)\npublic @interface IgnoreResult {\n}', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2614, 86, 2612, 'IResultError.ftl', 'IResultError.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\n/**\n * 自定义枚举继承该接口\n */\npublic interface IResultError {\n\n    /**\n     * 错误码\n     */\n    Integer getCode();\n\n    /**\n     * 错误信息\n     */\n    String getMessage();\n\n}\n', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2615, 86, 2612, 'Result.ftl', 'Result.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport ${projectPackage}.${projectNameDot}.common.exception.BusinessException;\nimport ${projectPackage}.${projectNameDot}.common.exception.IException;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.INTERNAL_SERVER_ERROR;\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.SUCCESS;\n\n/**\n * 统一返回的响应封装结果\n */\n@Data\npublic class Result<T> implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 3782047511903624813L;\n\n    /**\n     * 返回状态码\n     */\n    private Integer code;\n\n    /**\n     * 返回信息\n     */\n    private String message;\n\n    /**\n     * 返回的数据\n     */\n    private T data;\n\n    /**\n     * 无参\n     */\n    public static <T> Result<T> success() {\n        Result<T> result = new Result<>();\n        result.setCode(SUCCESS.getCode());\n        result.setMessage(SUCCESS.getMessage());\n        return result;\n    }\n\n    /**\n     * 一个参数\n     */\n    public static <T> Result<T> success(T data) {\n        Result<T> result = success();\n        result.setData(data);\n        return result;\n    }\n\n    /**\n     * 两个参数\n     *\n     * @param message\n     * @param data\n     * @param <T>\n     * @return\n     */\n    public static <T> Result<T> success(String message, T data) {\n        Result<T> result = success(data);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 服务稳定-两个参数\n     *\n     * @param code\n     * @param message\n     * @param <T>\n     * @return\n     */\n    public static <T> Result<T> build(Integer code, String message) {\n        Result<T> result = new Result<>();\n        result.setCode(code);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 三个参数\n     *\n     * @param code\n     * @param message\n     * @param data\n     * @param <T>\n     * @return\n     */\n    public static <T> Result<T> build(Integer code, String message, T data) {\n        Result<T> result = build(code, message);\n        result.setData(data);\n        return result;\n    }\n\n\n    /**\n     * 服务异常时的响应 -无参\n     */\n    public static <T> Result<T> fail() {\n        Result<T> result = new Result<>();\n        result.setCode(INTERNAL_SERVER_ERROR.getCode());\n        result.setMessage(INTERNAL_SERVER_ERROR.getMessage());\n        return result;\n    }\n\n    /**\n     * 服务异常时的响应 -一个参数\n     */\n    public static <T> Result<T> fail(T data) {\n        Result<T> result = fail();\n        result.setData(data);\n        return result;\n    }\n\n    /**\n     * 服务异常时的响应 -两个参数\n     */\n    public static <T> Result<T> fail(String message, T data) {\n        Result<T> result = fail(data);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 异常信息处理\n     */\n    public static <T> Result<T> fail(String message) {\n        Result<T> result = fail();\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 服务异常时的响应 -两个参数\n     */\n    public static <T> Result<T> fail(Integer code, String message) {\n        Result<T> result = fail();\n        result.setCode(code);\n        result.setMessage(message);\n        return result;\n    }\n\n    /**\n     * 返回异常\n     */\n    public static <T> Result<T> fail(BusinessException businessException) {\n        return fail(businessException.getCode(), businessException.getMessage());\n    }\n\n    /**\n     * 返回异常\n     */\n    public static <T> Result<T> fail(IException exception) {\n        Result<T> result = new Result<>();\n        result.setCode(exception.getCode());\n        result.setMessage(exception.getMessage());\n        return result;\n    }\n\n    /**\n     * 返回异常枚举\n     */\n    public static <T> Result<T> fail(IResultError error) {\n        return fail(error.getCode(), error.getMessage());\n    }\n\n    /**\n     * 服务异常时的响应 -三个参数\n     */\n    public static <T> Result<T> fail(Integer code, String message, T data) {\n        Result<T> result = fail(message, data);\n        result.setCode(code);\n        return result;\n    }\n\n}\n', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2616, 86, 2612, 'ResultAdvice.ftl', 'ResultAdvice.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport lombok.SneakyThrows;\nimport org.dromara.hutool.core.collection.CollUtil;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.core.MethodParameter;\nimport org.springframework.core.annotation.AnnotationUtils;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.converter.HttpMessageConverter;\nimport org.springframework.http.server.ServerHttpRequest;\nimport org.springframework.http.server.ServerHttpResponse;\nimport org.springframework.web.bind.annotation.RestController;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\nimport org.springframework.web.servlet.mvc.method.annotation.ResponseBodyAdvice;\n\nimport java.lang.reflect.Method;\nimport java.util.List;\n\n/**\n * 对RestController返回值统一处理\n */\n@RestControllerAdvice(annotations = RestController.class)\n@ConditionalOnProperty(name = \"web.response.enable\", havingValue = \"true\", matchIfMissing = true)\npublic class ResultAdvice implements ResponseBodyAdvice<Object> {\n\n    @Autowired\n    private ObjectMapper objectMapper;\n\n    /**\n     * 不需要增强的类名，有默认值，主要是swagger等的类\n     */\n    @Value(\"<#noparse>#{\'${web.response.exclude-list:swagger,springfox,springdoc}\'.split(\',\')}</#noparse>\")\n    private List<String> excludeNameList;\n\n    @Override\n    public boolean supports(MethodParameter returnType, Class<? extends HttpMessageConverter<?>> converterType) {\n        //类上有IgnoreResult注解的，不增强\n        IgnoreResult annotation = AnnotationUtils.findAnnotation(returnType.getDeclaringClass(), IgnoreResult.class);\n        if (annotation != null) {\n            return false;\n        }\n\n        //方法上有IgnoreResult注解的，不增强\n        annotation = AnnotationUtils.findAnnotation(returnType.getAnnotatedElement(), IgnoreResult.class);\n        if (annotation != null) {\n            return false;\n        }\n        Method method = returnType.getMethod();\n        //如果类名包含swagger等，不处理\n        if (method != null && CollUtil.isNotEmpty(excludeNameList)) {\n            String name = method.getDeclaringClass().getName();\n            for (String excludeName : excludeNameList) {\n                if (name.contains(excludeName)) {\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\n\n    @Override\n    @SneakyThrows\n    public Object beforeBodyWrite(Object body,\n                                  MethodParameter returnType,\n                                  MediaType selectedContentType,\n                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,\n                                  ServerHttpRequest request,\n                                  ServerHttpResponse response) {\n        //如果返回类型已经是Result则直接返回，否则需要用Result进行返回值包装\n        if (body instanceof Result) {\n            return body;\n        } else if (body instanceof byte[]) {\n            return body;\n        } else {\n            Result<Object> result = Result.success(body);\n            //如果返回值是字符串, 需要特殊处理, 手动变成JSON字符串\n            if (returnType.getParameterType().equals(String.class)) {\n                return objectMapper.writeValueAsString(result);\n            }\n            return result;\n        }\n    }\n\n}\n', NULL, NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
INSERT INTO `gen_template` VALUES (2617, 86, 2612, 'ResultEnum.ftl', 'ResultEnum.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.response;\n\nimport lombok.AllArgsConstructor;\nimport lombok.Getter;\n\n/**\n * 响应结果枚举\n */\n@Getter\n@AllArgsConstructor\npublic enum ResultEnum implements IResultError {\n\n    /**\n     * 请求成功\n     */\n    SUCCESS(200, \"success\"),\n\n    /**\n     * 请求参数错误\n     */\n    PARAM_ERR(300, \"request param error\"),\n\n    /**\n     * 请求参数丢失\n     */\n    PARAM_LOST(301, \"request param lost\"),\n\n    /**\n     * 请求头参数丢失\n     */\n    HEADER_LOST(302, \"request header lost\"),\n\n    /**\n     * 路径参数丢失\n     */\n    PATH_LOST(303, \"request path lost\"),\n\n    /**\n     * cookie值丢失\n     */\n    COOKIE_LOST(304, \"request cookie lost\"),\n\n    /**\n     * 客户端错误\n     */\n    REQUEST_ERR(400, \"request error\"),\n\n    /**\n     * 资源不存在\n     */\n    NOT_FOUND(404, \"not found\"),\n\n    /**\n     * 请求方法不支持\n     */\n    METHOD_NOT_ALLOWED(405, \"this method is not supported\"),\n\n    /**\n     * 服务器错误\n     */\n    INTERNAL_SERVER_ERROR(500, \"internal server error\"),\n\n    /**\n     * 文件太大\n     */\n    FILE_TOO_LARGE(501, \"file too large\"),\n\n    /**\n     * 数据不存在\n     */\n    DATA_NOT_EXIST(1000, \"{}数据{}字段的值已存在\"),\n\n    /**\n     * 数据已经存在\n     */\n    DATA_ALREADY_EXIST(1001, \"{}数据{}字段的值已存在\"),\n\n    /**\n     * 数据不能为空\n     */\n    DATA_NOT_NULL(1002, \"数据不能为空\"),\n    ;\n\n    /**\n     * 请求结果状态码\n     */\n    private final Integer code;\n\n    /**\n     * 请求结果描述信息\n     */\n    private final String message;\n\n}\n', '', NULL, '2025-10-16 16:55:23', '2025-10-16 16:55:37', 1);
