INSERT INTO `gen_template` VALUES (2699, 88, 2698, 'AbstractEnumCodeValidator.ftl', 'AbstractEnumCodeValidator.java', 1, NULL, 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\nimport jakarta.validation.ConstraintValidator;\nimport jakarta.validation.ConstraintValidatorContext;\nimport lombok.SneakyThrows;\nimport org.dromara.hutool.core.array.ArrayUtil;\nimport org.dromara.hutool.core.convert.ConvertUtil;\nimport org.dromara.hutool.core.reflect.FieldUtil;\nimport org.dromara.hutool.core.util.EnumUtil;\n\nimport java.lang.reflect.Field;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Objects;\n\npublic abstract class AbstractEnumCodeValidator<T> implements ConstraintValidator<EnumCode, T> {\n\n    protected String enumName;\n\n    protected String enumFieldName;\n\n    protected List<?> values;\n\n    @Override\n    @SneakyThrows\n    public void initialize(EnumCode annotation) {\n        Class<? extends Enum<?>> value = annotation.value();\n        this.enumName = value.getName();\n        this.enumFieldName = annotation.fieldName();\n        if (!FieldUtil.hasField(value, this.enumFieldName)) {\n            throw new IllegalArgumentException(\"枚举属性名称: \" + enumName + \", 枚举属性名称: \" + enumFieldName + \" 不存在\");\n        }\n        List<Object> fieldValues = EnumUtil.getFieldValues(value, this.enumFieldName);\n        String[] valueList = annotation.valueList();\n        if (ArrayUtil.isNotEmpty(valueList)) {\n            Field declaredField = value.getDeclaredField(this.enumFieldName);\n            List<?> list = ConvertUtil.toList(declaredField.getType(), valueList);\n            //判断是否包含所有值\n            if (new HashSet<>(fieldValues).containsAll(list)) {\n                this.values = list;\n            } else {\n                throw new IllegalArgumentException(\"枚举属性名称: \" + enumName + \", 属性名称: \" + enumFieldName + \", 值: \"\n                        + list + \" 不在枚举属性值范围内: \" + fieldValues);\n            }\n        } else {\n            this.values = fieldValues;\n        }\n    }\n\n    /**\n     * 子类实现校验逻辑\n     */\n    public abstract boolean isValid(T value);\n\n    @Override\n    public boolean isValid(T value, ConstraintValidatorContext context) {\n        //进行校验\n        boolean valid = isValid(value);\n        //如果校验不通过，则设置错误提示语句\n        if (!valid) {\n            setMessageTemplate(value, context);\n        }\n        return valid;\n    }\n\n    protected void setMessageTemplate(Object value, ConstraintValidatorContext context) {\n        //校验不通过，自定义提示语句\n        context.disableDefaultConstraintViolation();\n        //禁用默认的message 的值\n        String messageTemplate = context.getDefaultConstraintMessageTemplate()\n                //重新添加错误提示语句\n                .replace(\"{enumName}\", enumName)\n                .replace(\"{enumFieldName}\", enumFieldName)\n                .replace(\"{enumValue}\", Objects.toString(value))\n                .replace(\"{valueList}\", values.toString());\n        context.buildConstraintViolationWithTemplate(messageTemplate)\n                .addConstraintViolation();\n    }\n\n}\n', NULL, NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2700, 88, 2698, 'EnumCode.ftl', 'EnumCode.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\n\nimport jakarta.validation.Constraint;\nimport jakarta.validation.Payload;\n\nimport java.lang.annotation.Documented;\nimport java.lang.annotation.Retention;\nimport java.lang.annotation.RetentionPolicy;\nimport java.lang.annotation.Target;\n\nimport static java.lang.annotation.ElementType.*;\n\n/**\n * 枚举校验注解。字段的值需要在枚举的指定字段的指定值范围内\n */\n@Documented\n@Retention(RetentionPolicy.RUNTIME)\n@Target({METHOD, FIELD, ANNOTATION_TYPE, CONSTRUCTOR, PARAMETER, TYPE_USE})\n@Constraint(validatedBy = {EnumCodeValidator.class, EnumCodeCollectionValidator.class})\npublic @interface EnumCode {\n\n    /**\n     * 需要校验的枚举类型\n     */\n    Class<? extends Enum<?>> value();\n\n    /**\n     * 枚举类型校验值字段名称\n     */\n    String fieldName() default \"code\";\n\n    /**\n     * 枚举类型校验值列表。为空代表全部\n     */\n    String[] valueList() default {};\n\n    /**\n     * 异常信息，支持{enumName}、{enumFieldName}、{enumValue}和{valueList}占位替换\n     */\n    String message() default \"枚举属性名称: {enumName}.{enumFieldName}, 传入的枚举属性枚举值: {enumValue}, 必须在指定范围: {valueList}\";\n\n    Class<?>[] groups() default {};\n\n    Class<? extends Payload>[] payload() default {};\n\n}\n', NULL, NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2701, 88, 2698, 'EnumCodeCollectionValidator.ftl', 'EnumCodeCollectionValidator.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\n\nimport org.dromara.hutool.core.collection.CollUtil;\n\nimport java.util.Collection;\n\npublic class EnumCodeCollectionValidator extends AbstractEnumCodeValidator<Collection<?>> {\n\n    @Override\n    public boolean isValid(Collection<?> value) {\n        return CollUtil.containsAll(values, value);\n    }\n\n}\n', NULL, NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2702, 88, 2698, 'EnumCodeValidator.ftl', 'EnumCodeValidator.java', 1, '', 'package ${projectPackage}.${projectNameDot}.common.validation.code;\n\npublic class EnumCodeValidator extends AbstractEnumCodeValidator<Object> {\n\n    @Override\n    public boolean isValid(Object value) {\n        //为空时，默认不校验，即认为通过\n        if (value == null) {\n            return true;\n        }\n        for (Object item : values) {\n            if (item.equals(value)) {\n                return true;\n            }\n        }\n        return false;\n    }\n\n}\n', NULL, NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2703, 88, 2648, '', 'requestresponselog', 0, 'controller请求和响应切面包', '', '', NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2704, 88, 2703, 'Controller请求日志切面类', 'RequestResponseLogAspect.java', 1, 'Controller请求日志切面类', 'package ${projectPackage}.${projectNameDot}.common.requestresponselog;\n\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport ${projectPackage}.${projectNameDot}.common.util.AopDataUtil;\nimport jakarta.servlet.http.HttpServletRequest;\nimport lombok.extern.slf4j.Slf4j;\nimport org.aspectj.lang.ProceedingJoinPoint;\nimport org.aspectj.lang.Signature;\nimport org.aspectj.lang.annotation.Around;\nimport org.aspectj.lang.annotation.Aspect;\nimport org.aspectj.lang.reflect.MethodSignature;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.stereotype.Component;\n\nimport java.lang.reflect.Method;\n\n/**\n * 请求和响应日志切面\n */\n@Slf4j\n@Aspect\n@Component\n@ConditionalOnProperty(name = \"web.log.enable\", havingValue = \"true\", matchIfMissing = true)\npublic class RequestResponseLogAspect {\n\n    @Autowired\n    private HttpServletRequest request;\n\n    @Autowired\n    private ObjectMapper objectMapper;\n\n    /**\n     * 对RestController进行增强, 打印方法的入参、出参和执行时间\n     */\n    @Around(\"execution(\"\n            + \"public * *..controller..*(..))\"\n            + \" && @within(org.springframework.web.bind.annotation.RestController)\"\n            + \" && (@annotation(org.springframework.web.bind.annotation.RequestMapping)\"\n            + \" || @annotation(org.springframework.web.bind.annotation.GetMapping)\"\n            + \" || @annotation(org.springframework.web.bind.annotation.PostMapping)\"\n            + \" || @annotation(org.springframework.web.bind.annotation.PutMapping)\"\n            + \" || @annotation(org.springframework.web.bind.annotation.DeleteMapping))\"\n    )\n    public Object around(final ProceedingJoinPoint joinPoint) throws Throwable {\n        String url = request.getRequestURI();\n        Signature signature = joinPoint.getSignature();\n\n        //获取日志参数，默认请求日志和响应日志都日志记录\n        LogParam logParam = getLogParam(joinPoint);\n\n        //记录请求日志\n        if (logParam.isLogRequestData()) {\n            //获取请求参数\n            String requestData = AopDataUtil.buildRequestData(joinPoint, logParam.excludeRequestParamNames(), objectMapper);\n            //打印请求参数\n            log.info(\"[请求日志记录] 请求的url: {}, 执行的方法名: {}, 请求的参数: {}\", url, signature, requestData);\n        }\n\n        long current = System.currentTimeMillis();\n        //执行方法, 这里不进行异常处理, 在通用异常处理统一进行处理\n        Object result = joinPoint.proceed();\n\n        //记录响应日志\n        if (logParam.isLogResponseData()) {\n            //打印响应参数\n            long executeTime = System.currentTimeMillis() - current;\n            String responseData = AopDataUtil.buildResponseData(result, logParam.excludeResponseFieldNames(), objectMapper);\n            log.info(\"[响应日志记录] 请求的url: {}, 执行的方法名: {}, 执行时间: {}毫秒, 响应的参数: {}\", url, signature, executeTime, responseData);\n        }\n        return result;\n    }\n\n    /**\n     * 获取日志参数\n     */\n    private LogParam getLogParam(ProceedingJoinPoint joinPoint) {\n        boolean isLogRequestData = true;\n        boolean isLogResponseData = true;\n        String[] excludeRequestParamNames = {};\n        String[] excludeResponseFieldNames = {};\n        //优先从方法上尝试获取\n        Method method = ((MethodSignature) joinPoint.getSignature()).getMethod();\n        RequestResponseLog annotation = method.getAnnotation(RequestResponseLog.class);\n        //获取不到从类上尝试获取\n        if (annotation == null) {\n            annotation = joinPoint.getTarget().getClass().getAnnotation(RequestResponseLog.class);\n        }\n        //如果有注解才获取\n        if (annotation != null) {\n            excludeRequestParamNames = annotation.excludeRequestParamNames();\n            excludeResponseFieldNames = annotation.excludeResponseFieldNames();\n            //如果不记录日志\n            if (annotation.isIgnoreLog()) {\n                isLogRequestData = false;\n                isLogResponseData = false;\n            } else {\n                isLogRequestData = annotation.isLogRequestData();\n                isLogResponseData = annotation.isLogResponseData();\n            }\n        }\n        return new LogParam(isLogRequestData, isLogResponseData, excludeRequestParamNames, excludeResponseFieldNames);\n    }\n\n    private record LogParam(boolean isLogRequestData,\n                            boolean isLogResponseData,\n                            String[] excludeRequestParamNames,\n                            String[] excludeResponseFieldNames) {\n    }\n\n}', '', NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2705, 88, 2703, 'Controller日志切面注解', 'RequestResponseLog.java', 1, 'Controller日志切面注解', 'package ${projectPackage}.${projectNameDot}.common.requestresponselog;\n\n\nimport java.lang.annotation.*;\n\n/**\n * controller日志注解\n */\n@Documented\n@Target({ElementType.METHOD})\n@Retention(RetentionPolicy.RUNTIME)\npublic @interface RequestResponseLog {\n\n    /**\n     * 是否忽略日志记录\n     */\n    boolean isIgnoreLog() default false;\n\n    /**\n     * 是否日志记录请求的参数\n     */\n    boolean isLogRequestData() default true;\n\n    /**\n     * 是否日志记录响应的参数\n     */\n    boolean isLogResponseData() default true;\n\n    /**\n     * 排除指定的请求参数。支持beanPath的方式，删除属性。例如person.friend[5].name\n     */\n    String[] excludeRequestParamNames() default {};\n\n    /**\n     * 排除指定的响应参数。支持beanPath的方式，删除属性。例如person.friend[5].name\n     */\n    String[] excludeResponseFieldNames() default {};\n\n}\n', '', NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2706, 88, 2648, '', 'util', 0, '工具包', '', '', NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2707, 88, 2706, 'AOP数据处理工具类', 'AopDataUtil.java', 1, 'AOP数据处理工具类', 'package ${projectPackage}.${projectNameDot}.common.util;\n\n\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.fasterxml.jackson.databind.node.ArrayNode;\nimport com.fasterxml.jackson.databind.node.ObjectNode;\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport lombok.experimental.UtilityClass;\nimport lombok.extern.slf4j.Slf4j;\nimport org.aspectj.lang.JoinPoint;\nimport org.aspectj.lang.Signature;\nimport org.aspectj.lang.reflect.MethodSignature;\nimport org.dromara.hutool.core.array.ArrayUtil;\nimport org.dromara.hutool.core.map.MapUtil;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.multipart.MultipartFile;\n\nimport java.lang.reflect.Method;\nimport java.util.*;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\n\n/**\n * AOP数据处理工具类\n */\n@Slf4j\n@UtilityClass\npublic class AopDataUtil {\n\n    private static final List<Class<?>> REQUEST_PARAM_FILTER_CLASS_LIST = List.of(\n            MultipartFile.class,\n            MultipartFile[].class,\n            HttpServletRequest.class,\n            HttpServletResponse.class\n    );\n\n    private static final List<Class<?>> RESPONSE_FILTER_CLASS_LIST = List.of(\n            ResponseEntity.class\n    );\n\n    /**\n     * 预编译正则表达式提升解析性能\n     */\n    private static final Pattern PATH_PATTERN = Pattern.compile(\"^([a-zA-Z_$][\\\\w$]*)(?:\\\\[(\\\\d+)])?$\");\n\n    /**\n     * 构建请求参数数据\n     */\n    public static String buildRequestData(JoinPoint joinPoint,\n                                          String[] excludeRequestParamNames,\n                                          ObjectMapper objectMapper) throws Exception {\n        Signature signature = joinPoint.getSignature();\n        Class<?>[] args = ((MethodSignature) signature).getParameterTypes();\n        Method method = joinPoint.getTarget().getClass().getMethod(signature.getName(), args);\n\n        Object[] params = joinPoint.getArgs();\n        //key是参数名, value是参数值\n        Map<String, Object> paramMap = new HashMap<>();\n        if (ArrayUtil.isEmpty(params)) {\n            return objectMapper.writeValueAsString(paramMap);\n        }\n        for (int i = 0; i < params.length; i++) {\n            Object param = params[i];\n            //判断参数是否需要过滤\n            boolean anyMatch = REQUEST_PARAM_FILTER_CLASS_LIST.stream().anyMatch(type -> type.isInstance(param));\n            if (anyMatch) {\n                continue;\n            }\n            paramMap.put(method.getParameters()[i].getName(), param);\n        }\n        if (MapUtil.isEmpty(paramMap)) {\n            return objectMapper.writeValueAsString(paramMap);\n        } else {\n            //去除指定的参数\n            //转换为JsonNode树结构\n            JsonNode rootNode = objectMapper.valueToTree(paramMap);\n            //遍历所有需要排除的路径\n            for (String path : excludeRequestParamNames) {\n                AopDataUtil.deleteByBeanPath(rootNode, path);\n            }\n            return objectMapper.writeValueAsString(rootNode);\n        }\n    }\n\n    /**\n     * 构建响应参数数据\n     */\n    public static String buildResponseData(Object result, String[] excludeResponseFieldNames, ObjectMapper objectMapper) throws Exception {\n        //判断响应参数是否需要过滤\n        boolean anyMatch = RESPONSE_FILTER_CLASS_LIST.stream().anyMatch(type -> type.isInstance(result));\n        if (anyMatch) {\n            return \"响应参数已过滤\";\n        }\n        String responseJsonString;\n        //过滤部分字段\n        if (ArrayUtil.isNotEmpty(excludeResponseFieldNames)) {\n            //去除指定的参数\n            //转换为JsonNode树结构\n            JsonNode rootNode = objectMapper.valueToTree(result);\n            //遍历所有需要排除的路径\n            for (String path : excludeResponseFieldNames) {\n                AopDataUtil.deleteByBeanPath(rootNode, path);\n            }\n            responseJsonString = objectMapper.writeValueAsString(rootNode);\n        } else {\n            responseJsonString = objectMapper.writeValueAsString(result);\n        }\n        return responseJsonString;\n    }\n\n    /**\n     * 支持bean-path方式删除字段数据\n     */\n    public static void deleteByBeanPath(JsonNode rootNode, String beanPath) {\n        try {\n            List<PathSegment> pathSegments = parseBeanPath(beanPath);\n            if (pathSegments.isEmpty()) {\n                return;\n            }\n\n            JsonNode currentNode = rootNode;\n            for (int i = 0; i < pathSegments.size() - 1; i++) {\n                PathSegment segment = pathSegments.get(i);\n                currentNode = traverseToChild(currentNode, segment);\n                if (currentNode == null || currentNode.isNull()) {\n                    return;\n                }\n            }\n\n            PathSegment lastSegment = pathSegments.get(pathSegments.size() - 1);\n            performSafeDelete(currentNode, lastSegment);\n        } catch (Exception e) {\n            log.error(\"Error processing path: {}\", beanPath, e);\n        }\n    }\n\n    /**\n     * 增强版路径解析（带格式校验）\n     */\n    private static List<PathSegment> parseBeanPath(String beanPath) {\n        List<PathSegment> segments = new ArrayList<>();\n        if (beanPath == null || beanPath.isEmpty()) {\n            return segments;\n        }\n\n        String[] parts = beanPath.split(\"\\\\.\");\n        for (String part : parts) {\n            Matcher matcher = PATH_PATTERN.matcher(part);\n            if (!matcher.matches()) {\n                log.warn(\"Invalid path segment: {}\", part);\n                return Collections.emptyList();\n            }\n\n            String field = matcher.group(1);\n            String indexStr = matcher.group(2);\n            // 新增索引校验方法\n            int index = parseIndex(indexStr);\n\n            segments.add(new PathSegment(field, index));\n        }\n        return segments;\n    }\n\n    // 新增索引校验逻辑\n    private static int parseIndex(String indexStr) {\n        try {\n            return indexStr != null ? Integer.parseInt(indexStr) : -1;\n        } catch (NumberFormatException e) {\n            log.warn(\"Invalid array index format: {}\", indexStr);\n            return -1;\n        }\n    }\n\n    /**\n     * 增强型节点遍历方法（支持对象和数组类型）\n     */\n    private static JsonNode traverseToChild(JsonNode currentNode, PathSegment segment) {\n        if (currentNode.isObject()) {\n            return handleObjectTraversal(currentNode, segment);\n        } else if (currentNode.isArray()) {\n            return handleArrayTraversal(currentNode, segment);\n        }\n        throw new IllegalStateException(\"Unsupported node type at path segment: \" + segment.field());\n    }\n\n    /**\n     * 处理对象类型节点遍历\n     */\n    private static JsonNode handleObjectTraversal(JsonNode node, PathSegment segment) {\n        JsonNode child = node.get(segment.field());\n        if (child == null) {\n            return null;\n        }\n\n        // 检查数组索引需求\n        if (segment.index() >= 0) {\n            return getArrayElement(child, segment.index());\n        }\n        return child;\n    }\n\n    /**\n     * 处理数组类型节点遍历\n     */\n    private static JsonNode handleArrayTraversal(JsonNode node, PathSegment segment) {\n        if (segment.index() >= 0 && segment.index() < node.size()) {\n            return node.get(segment.index());\n        }\n        return null;\n    }\n\n    /**\n     * 安全获取数组元素（带边界检查）\n     */\n    private static JsonNode getArrayElement(JsonNode node, int index) {\n        if (!node.isArray() || index < 0 || index >= node.size()) {\n            return null;\n        }\n        return node.get(index);\n    }\n\n    /**\n     * 安全删除操作\n     */\n    private static void performSafeDelete(JsonNode node, PathSegment segment) {\n        try {\n            if (node.isObject()) {\n                ObjectNode objectNode = (ObjectNode) node;\n                if (objectNode.has(segment.field())) {\n                    JsonNode jsonNode = objectNode.get(segment.field());\n                    if (jsonNode.isArray() && segment.index() >= 0) {\n                        ArrayNode arrayNode = (ArrayNode) jsonNode;\n                        if (segment.index() < arrayNode.size()) {\n                            arrayNode.remove(segment.index());\n                        }\n                    } else {\n                        objectNode.remove(segment.field());\n                    }\n                }\n            } else if (node.isArray() && segment.index() >= 0) {\n                ArrayNode arrayNode = (ArrayNode) node;\n                if (segment.index() < arrayNode.size()) {\n                    arrayNode.remove(segment.index());\n                }\n            }\n        } catch (ClassCastException e) {\n            log.warn(\"Type mismatch at path segment: {}\", segment);\n        }\n    }\n\n    /**\n     * 更新 PathSegment 记录类\n     *\n     * @param field\n     * @param index\n     */\n    private record PathSegment(String field, int index) {\n\n        @Override\n        public String toString() {\n            return index >= 0 ? field + \"[\" + index + \"]\" : field;\n        }\n\n    }\n\n}\n', '', NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
INSERT INTO `gen_template` VALUES (2708, 88, 2647, 'SpringbootApplication.ftl', '${projectNamePascal}Application.java', 1, '项目主启动类', 'package ${projectPackage}.${projectNameDot};\n\nimport org.mybatis.spring.annotation.MapperScan;\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\n\n/**\n * ${projectNamePascal}主启动类\n */\n@SpringBootApplication\n@MapperScan(\"${projectPackage}.${projectNameDot}.mapper\")\npublic class ${projectNamePascal}Application {\n\n    public static void main(String[] args) {\n        SpringApplication.run(${projectNamePascal}Application.class, args);\n    }\n\n}\n', '', NULL, '2025-10-17 17:23:23', '2025-10-17 17:23:34', 1);
