INSERT INTO `gen_template` VALUES (2720, 30, 2719, 'auth.ts.ftl', 'index.ts', 1, '权限api接口', 'import { service } from \'@/utils/request\'\n\nconst baseUrl: string = \'/auth\'\n\n// 登录、权限API\nexport const authApi = {\n	// 登录\n	<#noparse>login: (dataForm: any) => service.post(`${baseUrl}/login`, dataForm),\n\n	// 注册\n	register: (dataForm: any) => service.post(`${baseUrl}/register`, dataForm),\n\n	// 刷新token\n	refreshToken: (refreshToken: string) => service.get(`${baseUrl}/refreshToken`, { params: { refreshToken } }),\n\n	// 退出登录\n	logout: () => service.post(`${baseUrl}/logout`)</#noparse>\n}\n', '', NULL, '2025-11-05 14:30:00', '2025-11-07 17:33:16', 0);
INSERT INTO `gen_template` VALUES (2721, 30, 1805, 'type.ts.ftl', 'type.ts', 1, 'API统一类型', '// 统一返回数据\nexport interface Result<T> {\n	// 状态码 200为正常\n	code: number\n	// 提示信息 正常为success\n	message: string\n	// 数据\n	data: T\n}\n\n// 排序查询参数\nexport interface OrderItemQuery {\n	// 排序字段\n	column: string\n	// 是否正序排列，默认 true\n	asc: boolean\n}\n\n// 统一分页查询参数\nexport interface PageQuery {\n	// 当前页码\n	pageNum?: number\n	// 每页条数\n	pageSize?: number\n	// 排序字段\n	orderItemList?: OrderItemQuery[]\n	// 开始时间\n	startTime?: string\n	// 结束时间\n	endTime?: string\n	// 开始日期\n	startDate?: string\n	// 结束日期\n	endDate?: string\n	// 时间范围\n	dateRange?: string[]\n	// 日期范围\n	dateTimeRange?: string[]\n}\n\n// 分页数据\nexport interface PageVO<T> {\n	// 当前页码\n	pageNum: number\n	// 每页条数\n	pageSize: number\n	// 总记录数\n	total: number\n	// 分页数据\n	records: T[]\n}\n', '', NULL, '2025-11-05 14:31:09', '2025-11-24 15:55:15', 1);
INSERT INTO `gen_template` VALUES (2722, 30, 687, '', 'icon-text-tooltip', 0, '', '', '', NULL, '2025-11-05 14:32:18', '2025-11-05 14:32:18', 0);
INSERT INTO `gen_template` VALUES (2723, 30, 2722, 'icon-text-tooltip页面', 'index.vue', 1, '图标、文字、提示组件', '<template>\n	<div class=\"icon-text-tooltip\">\n		<svg-icon v-if=\"enableIcon && icon\" :icon=\"icon\" :size=\"iconSize\" :is-pointer=\"isPointer\"></svg-icon>\n		<text-tooltip :title=\"title\" :max-width=\"maxWidth\" :placement=\"placement\"></text-tooltip>\n	</div>\n</template>\n<script setup lang=\"ts\">\nimport TextTooltip from \'@/components/text-tooltip/index.vue\'\nimport SvgIcon from \'@/components/svg-icon/index.vue\'\n\ndefineOptions({\n	name: \'IconTextTooltip\'\n})\n\ndefineProps({\n	enableIcon: {\n		type: Boolean,\n		default: true\n	},\n	icon: {\n		type: String,\n		required: true\n	},\n	iconSize: {\n		type: String,\n		required: false,\n		default: \'1em\'\n	},\n	isPointer: {\n		type: Boolean,\n		default: false\n	},\n	title: {\n		type: String,\n		required: true\n	},\n	maxWidth: {\n		type: String,\n		required: false,\n		default: \'100px\'\n	},\n	placement: {\n		type: String,\n		required: false,\n		default: \'top\'\n	}\n})\n</script>\n<style scoped>\n.icon-text-tooltip {\n	display: flex;\n	align-items: center;\n	gap: 5px;\n}\n</style>\n', '', NULL, '2025-11-05 14:33:00', '2025-11-24 15:59:53', 0);
INSERT INTO `gen_template` VALUES (2724, 30, 687, '', 'text-tooltip', 0, '', '', '', NULL, '2025-11-05 14:34:00', '2025-11-05 14:34:00', 0);
INSERT INTO `gen_template` VALUES (2725, 30, 2724, 'text-tooltip.vue', 'index.vue', 1, '文字、提示组件', '<template>\n	<el-tooltip :content=\"title\" :disabled=\"!isTitleOverflow\" :placement=\"placement\">\n		<el-text ref=\"textRef\" class=\"text-tooltip-title\" :style=\"{ maxWidth }\">\n			{{ title }}\n		</el-text>\n	</el-tooltip>\n</template>\n\n<script setup lang=\"ts\">\nimport { nextTick, onMounted, ref, watch } from \'vue\'\nimport { useResizeObserver } from \'@vueuse/core\'\n\ndefineOptions({\n	name: \'TextTooltip\'\n})\n\nconst props = defineProps({\n	title: {\n		type: String,\n		required: true\n	},\n	maxWidth: {\n		type: String,\n		default: \'100px\' // 如果是el-row和el-col的title，则maxWidth为100%\n	},\n	placement: {\n		type: String,\n		default: \'top\'\n	}\n})\n\nconst textRef = ref()\nconst isTitleOverflow = ref(false)\n\n// 检查文本是否溢出\nconst checkOverflow = () => {\n	nextTick(() => {\n		if (textRef.value?.$el) {\n			const element = textRef.value.$el\n			isTitleOverflow.value = element.scrollWidth > element.offsetWidth\n		}\n	})\n}\n\n// 监听 title 和 maxWidth 的变化\nwatch(() => [props.title, props.maxWidth], checkOverflow)\n\nonMounted(checkOverflow)\n\n// 使用 VueUse 的 useResizeObserver 自动监听尺寸变化\nuseResizeObserver(textRef, checkOverflow)\n</script>\n<style scoped lang=\"scss\">\n.text-tooltip-title {\n	display: inline-block;\n	overflow: hidden;\n	white-space: nowrap;\n	text-overflow: ellipsis;\n	vertical-align: middle;\n	color: inherit;\n}\n</style>\n', '', NULL, '2025-11-05 14:34:35', '2025-11-24 16:04:30', 0);
INSERT INTO `gen_template` VALUES (2726, 30, 663, 'user-dropdown.vue.ftl', 'user-dropdown.vue', 1, '个人中心下拉页面', '<template>\n	<el-dropdown>\n		<div style=\"display: flex; align-items: center; cursor: pointer; gap: 5px\">\n			<template v-if=\"userStore.userInfo.avatar\">\n				<el-avatar :src=\"userStore.userInfo.avatar\" :size=\"16\"></el-avatar>\n			</template>\n			<template v-else>\n				<el-icon size=\"16px\">\n					<Avatar></Avatar>\n				</el-icon>\n			</template>\n			<el-text>{{ userStore.userInfo.nickname || userStore.userInfo.username }}</el-text>\n		</div>\n		<template #dropdown>\n			<el-dropdown-menu>\n				<router-link to=\"/user/profile\">\n					<el-dropdown-item :icon=\"User\">个人信息</el-dropdown-item>\n				</router-link>\n				<el-dropdown-item :icon=\"SwitchButton\" @click=\"logout()\">退出登录</el-dropdown-item>\n			</el-dropdown-menu>\n		</template>\n	</el-dropdown>\n</template>\n\n<script setup lang=\"ts\">\nimport { useUserStore } from \'@/store\'\nimport { authApi } from \'@/api\'\nimport { ElMessageBox } from \'element-plus\'\nimport { useRoute, useRouter } from \'vue-router\'\nimport { Avatar, SwitchButton, User } from \'@element-plus/icons-vue\'\n\ndefineOptions({\n	name: \'UserDropdown\'\n})\n\nconst userStore = useUserStore()\nconst route = useRoute()\nconst router = useRouter()\n\n// 退出登录\nconst logout = () => {\n	ElMessageBox.confirm(\'确定注销并退出系统吗？\', \'系统提示\', {\n		confirmButtonText: \'确定\',\n		cancelButtonText: \'取消\',\n		type: \'warning\'\n	}).then(() => {\n		authApi.logout().then(() => {\n			userStore.clearAll()\n			router.push({\n				path: \'/auth/login\',\n				query: {\n					redirect: encodeURIComponent(route.fullPath || \'/\')\n				}\n			})\n		})\n	})\n}\n</script>\n<style scoped lang=\"scss\"></style>\n', '', NULL, '2025-11-05 14:42:46', '2025-11-24 16:14:01', 0);
INSERT INTO `gen_template` VALUES (2727, 30, 651, 'router-constant.ts.ftl', 'constant.ts', 1, '常量路由文件', 'import { RouteRecordRaw } from \'vue-router\'\n\n// 常量路由\nexport const constantRoutes: RouteRecordRaw[] = [\n	{\n		path: \'/\',\n		name: \'Layout\',\n		component: () => import(\'@/layout/index.vue\')\n	},\n	{\n		path: \'/auth\',\n		name: \'Auth\',\n		children: [\n			{\n				path: \'/auth/login\',\n				name: \'AuthLogin\',\n				component: () => import(\'@/views/auth/login.vue\'),\n				meta: {\n					title: \'登录\',\n					cache: false,\n					type: 1\n				}\n			},\n			{\n				path: \'/auth/register\',\n				name: \'AuthRegister\',\n				component: () => import(\'@/views/auth/register.vue\'),\n				meta: {\n					title: \'注册\',\n					cache: false,\n					type: 1\n				}\n			}\n		]\n	},\n	{\n		path: \'/user\',\n		name: \'User\',\n		component: () => import(\'@/layout/index.vue\'),\n		meta: {\n			title: \'个人中心\',\n			icon: \'icon-user\',\n			type: 0\n		},\n		children: [\n			{\n				path: \'/user/profile\',\n				name: \'UserProfile\',\n				component: () => import(\'@/views/user/profile.vue\'),\n				meta: {\n					title: \'个人信息\',\n					icon: \'icon-user-profile\',\n					hidden: true,\n					cache: false,\n					type: 1\n				}\n			}\n		]\n	},\n	{\n		path: \'/redirect\',\n		name: \'Redirect\',\n		component: () => import(\'@/layout/index.vue\'),\n		children: [\n			{\n				path: \'/redirect/:path(.*)\',\n				component: () => import(\'@/components/router/redirect.vue\'),\n				meta: {\n					title: \'重定向\',\n					cache: false,\n					type: 1\n				}\n			}\n		]\n	},\n	{\n		path: \'/error\',\n		name: \'Error\',\n		component: () => import(\'@/layout/index.vue\'),\n		meta: {\n			title: \'错误页\',\n			icon: \'icon-error\',\n			type: 0\n		},\n		children: [\n			{\n				path: \'/error/400\',\n				name: \'Error400\',\n				component: () => import(\'@/views/error/400.vue\'),\n				meta: {\n					title: \'400\',\n					icon: \'icon-error-400\',\n					cache: false,\n					type: 1\n				}\n			},\n			{\n				path: \'/error/401\',\n				name: \'Error401\',\n				component: () => import(\'@/views/error/401.vue\'),\n				meta: {\n					title: \'401\',\n					icon: \'icon-error-401\',\n					cache: false,\n					type: 1\n				}\n			},\n			{\n				path: \'/error/403\',\n				name: \'Error403\',\n				component: () => import(\'@/views/error/403.vue\'),\n				meta: {\n					title: \'403\',\n					icon: \'icon-error-403\',\n					cache: false,\n					type: 1\n				}\n			},\n			{\n				path: \'/error/404\',\n				name: \'Error404\',\n				component: () => import(\'@/views/error/404.vue\'),\n				meta: {\n					title: \'404\',\n					icon: \'icon-error-404\',\n					cache: false,\n					type: 1\n				}\n			},\n			{\n				path: \'/error/500\',\n				name: \'Error500\',\n				component: () => import(\'@/views/error/500.vue\'),\n				meta: {\n					title: \'500\',\n					icon: \'icon-error-500\',\n					cache: false,\n					type: 1\n				}\n			}\n		]\n	},\n	{\n		path: \'/:pathMatch(.*)*\',\n		component: () => import(\'@/layout/index.vue\'),\n		children: [\n			{\n				path: \'\',\n				component: () => import(\'@/views/error/404.vue\'),\n				meta: {\n					title: \'404\',\n					icon: \'icon-error-404\',\n					cache: false,\n					type: 1\n				}\n			}\n		]\n	}\n]\n', '', NULL, '2025-11-05 14:45:36', '2025-11-24 16:16:00', 0);
INSERT INTO `gen_template` VALUES (2728, 30, 640, 'axios.d.ts.ftl', 'axios.d.ts', 1, '', 'import \'axios\'\n\ndeclare module \'axios\' {\n	export interface AxiosRequestConfig {\n		/**\n		 * 是否禁止全局错误提示\n		 * - 不设置 或 false：显示错误提示（默认行为）\n		 * - true：不显示错误提示。自行处理错误\n		 */\n		noErrorMessage?: boolean\n\n		/**\n		 * 是否返回完整后端响应\n		 * - 不设置 或 true：返回 res.data（默认行为）\n		 * - false：返回完整 res\n		 */\n		rawResponse?: boolean\n	}\n}\n', '', NULL, '2025-11-05 14:48:13', '2025-11-05 14:48:19', 0);
INSERT INTO `gen_template` VALUES (2729, 30, 640, 'common.ts.ftl', 'common.ts', 1, '', '// 主键类型\nexport type Key = string | number | null | undefined\n\n// 主键数组类型\nexport type KeyArray = number[] | string[]\n\n// 标签数据\nexport interface LabelData {\n	// 标签\n	label: string\n	// 值\n	value: string | number | boolean | null\n}\n', '', NULL, '2025-11-05 14:48:55', '2025-11-24 16:34:21', 1);
