INSERT INTO `gen_template` VALUES (2731, 30, 2730, 'login.vue.ftl', 'login.vue', 1, '登录页面', '<template>\n	<el-card class=\"login\">\n		<el-form ref=\"loginRef\" :model=\"form\" :rules=\"dataRules\" class=\"login-form\" @keyup.enter=\"loginHandle()\">\n			<el-form-item prop=\"username\">\n				<el-input v-model=\"form.username\" :prefix-icon=\"User\" clearable placeholder=\"用户名\"></el-input>\n			</el-form-item>\n			<el-form-item prop=\"password\">\n				<el-input v-model=\"form.password\" :prefix-icon=\"Lock\" clearable placeholder=\"密码\" type=\"password\"></el-input>\n			</el-form-item>\n			<el-form-item style=\"width: 100%\">\n				<el-button type=\"primary\" @click=\"loginHandle()\">登录</el-button>\n			</el-form-item>\n		</el-form>\n	</el-card>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive, ref, watch } from \'vue\'\nimport { authApi } from \'@/api\'\nimport { ElMessage } from \'element-plus\'\nimport { useUserStore } from \'@/store\'\nimport { useRoute, useRouter } from \'vue-router\'\nimport { Lock, User } from \'@element-plus/icons-vue\'\n\ndefineOptions({\n	name: \'AuthLogin\'\n})\n\nconst redirect = ref(\'/\')\nconst route = useRoute()\nconst router = useRouter()\nconst loginRef = ref()\n\nwatch(\n	() => route,\n	() => {\n		if (route.query?.redirect) {\n			const redirectPath = route.query?.redirect as string\n			redirect.value = decodeURIComponent(redirectPath)\n		}\n	},\n	{ immediate: true }\n)\n\nconst userStore = useUserStore()\n\nconst appTitle = import.meta.env.VITE_APP_TITLE\nconst form = reactive({\n	username: \'\',\n	password: \'\'\n})\n\nconst dataRules = reactive({\n	username: [{ required: true, message: \'用户名不能为空\', trigger: \'blur\' }],\n	password: [{ required: true, message: \'密码不能为空\', trigger: \'blur\' }]\n})\n\nconst loginHandle = () => {\n	loginRef.value.validate((valid: boolean) => {\n		if (!valid) {\n			return false\n		}\n		authApi.login(form).then(data => {\n			userStore.setData(data)\n			ElMessage.success(\'登录成功\')\n			router.push(redirect.value)\n		})\n	})\n}\n</script>\n\n<style lang=\"scss\" scoped>\n.login {\n	display: flex;\n	justify-content: center;\n	align-items: center;\n	height: 100%;\n	background-size: cover;\n}\n.login-form {\n	border-radius: 6px;\n	background: #ffffff;\n	width: 400px;\n	padding: 25px 25px 5px 25px;\n	z-index: 1;\n	.el-input {\n		height: 40px;\n		input {\n			height: 40px;\n		}\n	}\n\n	.input-icon {\n		height: 39px;\n		width: 14px;\n		margin-left: 0px;\n	}\n}\n</style>\n', '', NULL, '2025-11-05 14:50:36', '2025-11-24 16:20:25', 0);
INSERT INTO `gen_template` VALUES (2732, 30, 2730, 'register.vue.ftl', 'register.vue', 1, '注册页面', '<template>\n	<el-card class=\"login\">\n		<el-form ref=\"loginRef\" :model=\"form\" :rules=\"dataRules\" class=\"login-form\" @keyup.enter=\"loginHandle()\">\n			<el-form-item prop=\"username\">\n				<el-input v-model=\"form.username\" :prefix-icon=\"User\" clearable placeholder=\"用户名\"></el-input>\n			</el-form-item>\n			<el-form-item prop=\"password\">\n				<el-input v-model=\"form.password\" :prefix-icon=\"Lock\" clearable placeholder=\"密码\" type=\"password\"></el-input>\n			</el-form-item>\n			<el-form-item style=\"width: 100%\">\n				<el-button type=\"primary\" @click=\"loginHandle()\">登录</el-button>\n			</el-form-item>\n		</el-form>\n	</el-card>\n</template>\n\n<script setup lang=\"ts\">\nimport { reactive, ref, watch } from \'vue\'\nimport { authApi } from \'@/api\'\nimport { ElMessage } from \'element-plus\'\nimport { useUserStore } from \'@/store\'\nimport { useRoute, useRouter } from \'vue-router\'\nimport { Lock, User } from \'@element-plus/icons-vue\'\n\ndefineOptions({\n	name: \'AuthRegister\'\n})\n\nconst redirect = ref(\'/\')\nconst route = useRoute()\nconst router = useRouter()\nconst loginRef = ref()\n\nwatch(\n	() => route.query,\n	newRouteQuery => {\n		if (newRouteQuery.redirect && typeof newRouteQuery.redirect === \'string\') {\n			redirect.value = decodeURIComponent(newRouteQuery.redirect)\n		}\n	},\n	{ immediate: true }\n)\n\nconst userStore = useUserStore()\n\nconst appTitle = import.meta.env.VITE_APP_TITLE\nconst form = reactive({\n	username: \'\',\n	password: \'\'\n})\n\nconst dataRules = reactive({\n	username: [{ required: true, message: \'用户名不能为空\', trigger: \'blur\' }],\n	password: [{ required: true, message: \'密码不能为空\', trigger: \'blur\' }]\n})\n\nconst loginHandle = () => {\n	authApi.login(form).then(data => {\n		userStore.setData(data)\n		ElMessage.success(\'登录成功\')\n		router.replace(redirect.value)\n	})\n}\n</script>\n\n<style lang=\"scss\" scoped>\n.login {\n	display: flex;\n	justify-content: center;\n	align-items: center;\n	height: 100%;\n	background-size: cover;\n}\n.login-form {\n	border-radius: 6px;\n	background: #ffffff;\n	width: 400px;\n	padding: 25px 25px 5px 25px;\n	z-index: 1;\n	.el-input {\n		height: 40px;\n		input {\n			height: 40px;\n		}\n	}\n\n	.input-icon {\n		height: 39px;\n		width: 14px;\n		margin-left: 0px;\n	}\n}\n</style>\n', '', NULL, '2025-11-05 14:51:15', '2025-11-24 16:20:31', 0);
INSERT INTO `gen_template` VALUES (2733, 30, 653, '', 'user', 0, '', '', '', NULL, '2025-11-05 14:52:20', '2025-11-05 14:52:20', 0);
INSERT INTO `gen_template` VALUES (2734, 30, 2733, 'user-profile.vue.ftl', 'profile.vue', 1, '个人中心页面', '<template>\n	<h1>用户个人中心</h1>\n</template>\n<script setup lang=\"ts\">\ndefineOptions({\n	name: \'UserProfile\'\n})\n</script>\n\n<style scoped></style>\n', '', NULL, '2025-11-05 14:52:51', '2025-11-24 16:23:21', 0);
INSERT INTO `gen_template` VALUES (2735, 29, 561, '', 'satoken', 0, '权限框架', '', '', 'projectTemplatePropertyData[\'enableSaToken\']', '2025-11-14 14:07:33', '2025-12-29 15:31:40', 0);
INSERT INTO `gen_template` VALUES (2736, 29, 2735, 'RolePermissionInteface.ftl', 'RolePermissionInteface.java', 1, '角色、权限查询接口，实现类需要注入Spring容器，方便Spring调用', 'package ${projectPackage}.${projectNameDot}.common.satoken;\n\nimport java.util.List;\n\n/**\n * 角色、权限查询接口\n * 实现类需要注入Spring容器，方便Spring调用\n */\npublic interface RolePermissionInteface {\n\n    /**\n     * 返回一个账号所拥有的角色标识集合\n     *\n     * @param loginId   账号id\n     * @param loginType 账号类型\n     */\n    List<String> getRoleList(Object loginId, String loginType);\n\n    /**\n     * 返回一个账号所拥有的权限码集合\n     *\n     * @param loginId   账号id\n     * @param loginType 账号类型\n     */\n    List<String> getPermissionList(Object loginId, String loginType);\n\n}\n', '', 'projectTemplatePropertyData[\'enableSaToken\']', '2025-11-14 14:08:05', '2025-12-29 15:30:18', 0);
INSERT INTO `gen_template` VALUES (2737, 29, 2735, 'LoginHelper.ftl', 'LoginHelper.java', 1, '登录鉴权助手', 'package ${projectPackage}.${projectNameDot}.common.satoken;\n\nimport cn.dev33.satoken.session.SaSession;\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.hutool.v7.core.util.ObjUtil;\nimport ${projectPackage}.${projectNameDot}.common.domain.model.LoginUser;\nimport lombok.experimental.UtilityClass;\n\n\n/**\n * 登录鉴权助手\n * <p>\n * user_type 为 用户类型 同一个用户表 可以有多种用户类型 例如 pc,app\n * deivce 为 设备类型 同一个用户类型 可以有 多种设备类型 例如 web,ios\n * 可以组成 用户类型与设备类型多对多的 权限灵活控制\n * <p>\n * 多用户体系 针对 多种用户类型 但权限控制不一致\n * 可以组成 多用户类型表与多设备类型 分别控制权限\n */\n@UtilityClass\npublic class LoginHelper {\n\n    public static final String LOGIN_USER_KEY = \"loginUser\";\n\n    public static final String USER_KEY = \"userId\";\n\n    public static final String USER_NAME_KEY = \"userName\";\n\n    /**\n     * 登录方法\n     *\n     * @param loginUser 登录用户信息\n     */\n    public static <T extends LoginUser> void login(T loginUser) {\n        // 登录\n        StpUtil.login(loginUser.getUserId());\n        // 用户信息放入缓存中\n        StpUtil.getTokenSession().set(LOGIN_USER_KEY, loginUser);\n    }\n\n    /**\n     * 获取用户\n     */\n    public static <T extends LoginUser> T getLoginUser() {\n        SaSession session = StpUtil.getTokenSession();\n        if (ObjUtil.isNull(session)) {\n            return null;\n        }\n        return (T) session.get(LOGIN_USER_KEY);\n    }\n\n    /**\n     * 获取用户ID\n     */\n    public static Long getUserId() {\n        return ((LoginUser) StpUtil.getTokenSession().get(LOGIN_USER_KEY)).getUserId();\n    }\n\n}\n', '', 'projectTemplatePropertyData[\'enableSaToken\']', '2025-11-14 14:08:58', '2025-12-29 15:30:09', 0);
INSERT INTO `gen_template` VALUES (2738, 29, 2735, 'SaPermissionImpl.ftl', 'SaPermissionImpl.java', 1, 'sa-token 权限管理实现类', 'package ${projectPackage}.${projectNameDot}.common.satoken;\n\nimport cn.dev33.satoken.SaManager;\nimport cn.dev33.satoken.stp.StpInterface;\nimport cn.hutool.v7.core.collection.CollUtil;\nimport cn.hutool.v7.core.text.StrUtil;\nimport cn.hutool.v7.extra.spring.SpringUtil;\nimport cn.hutool.v7.json.JSONUtil;\nimport org.springframework.beans.factory.annotation.Value;\n\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.Set;\n\n/**\n * sa-token 权限管理实现类\n */\npublic class SaPermissionImpl implements StpInterface {\n\n    @Value(\"<#noparse>${sa-token.token-name}</#noparse>\")\n    private String tokenName;\n\n    @Value(\"<#noparse>${sa-token.role-permission-bean-name:}</#noparse>\")\n    private String rolePermissionBeanName;\n\n    /**\n     * 返回一个账号所拥有的权限码集合\n     *\n     * @param loginId   账号id\n     * @param loginType 账号类型\n     */\n    @Override\n    public List<String> getPermissionList(Object loginId, String loginType) {\n\n        // 1. 声明权限码集合\n        Set<String> set = new HashSet<>();\n\n        // 2. 遍历角色列表，查询拥有的权限码\n        for (String roleId : getRoleList(loginId, loginType)) {\n            String key = getPermissionKey(roleId);\n            List<String> permissionList = Optional.ofNullable(SaManager.getSaTokenDao().get(key))\n                    .filter(StrUtil::isNotEmpty)\n                    .map(jsonArray -> JSONUtil.toList(jsonArray, String.class)\n                            .stream()\n                            .distinct()\n                            .toList())\n                    .orElse(List.of());\n            if (CollUtil.isEmpty(permissionList)) {\n                // 从数据库查询这个角色 id 所拥有的权限列表\n                RolePermissionInteface bean = getRolePermissionInteface();\n                permissionList = bean.getPermissionList(loginId, roleId);\n                // 查好后，set 到缓存中\n                SaManager.getSaTokenDao().setObject(key, permissionList, 60 * 60 * 24);\n            }\n            if (CollUtil.isNotEmpty(permissionList)) {\n                set.addAll(permissionList);\n            }\n        }\n\n        // 3. 返回权限码集合\n        return set.stream().toList();\n    }\n\n    /**\n     * 返回一个账号所拥有的角色标识集合\n     *\n     * @param loginId   账号id\n     * @param loginType 账号类型\n     */\n    @Override\n    public List<String> getRoleList(Object loginId, String loginType) {\n        String key = getRoleKey(loginId.toString());\n        List<String> roleList = Optional.ofNullable(SaManager.getSaTokenDao().get(key))\n                .filter(StrUtil::isNotEmpty)\n                .map(jsonArray -> JSONUtil.toList(jsonArray, String.class)\n                        .stream()\n                        .distinct()\n                        .toList())\n                .orElse(List.of());\n        if (CollUtil.isEmpty(roleList)) {\n            // 从数据库查询这个账号id拥有的角色列表\n            RolePermissionInteface bean = getRolePermissionInteface();\n            roleList = bean.getRoleList(loginId, loginType);\n            // 查好后，set 到缓存中\n            SaManager.getSaTokenDao().setObject(key, roleList, 60 * 60 * 24);\n        }\n        return roleList;\n    }\n\n    private String getPermissionKey(String roleId) {\n        return tokenName + \":permission:\" + roleId;\n    }\n\n    private String getRoleKey(String loginId) {\n        return tokenName + \":role:\" + loginId;\n    }\n\n    // 获取角色权限接口\n    private RolePermissionInteface getRolePermissionInteface() {\n        if (StrUtil.isNotEmpty(rolePermissionBeanName)) {\n            return SpringUtil.getBean(rolePermissionBeanName, RolePermissionInteface.class);\n        }\n        return SpringUtil.getBean(RolePermissionInteface.class);\n    }\n\n}\n', '', 'projectTemplatePropertyData[\'enableSaToken\']', '2025-11-14 14:11:20', '2025-12-29 15:30:22', 0);
INSERT INTO `gen_template` VALUES (2739, 29, 2735, 'SaTokenConfig.ftl', 'SaTokenConfig.java', 1, 'sa-token配置类', 'package ${projectPackage}.${projectNameDot}.common.satoken;\n\nimport cn.dev33.satoken.stp.StpInterface;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/**\n * sa-token配置类\n */\n@Configuration\npublic class SaTokenConfig {\n\n    /**\n     * 拦截器\n     */\n    @Bean\n    public SaTokenInterceptor getSaTokenInterceptor() {\n        return new SaTokenInterceptor();\n    }\n\n    /**\n     * 权限接口实现(使用bean注入方便用户替换)\n     */\n    @Bean\n    public StpInterface stpInterface() {\n        return new SaPermissionImpl();\n    }\n\n    /**\n     * 异常处理器\n     */\n    @Bean\n    public SaTokenExceptionHandler saTokenExceptionHandler() {\n        return new SaTokenExceptionHandler();\n    }\n\n}\n', '', 'projectTemplatePropertyData[\'enableSaToken\']', '2025-11-14 14:12:20', '2025-12-29 15:30:27', 0);
INSERT INTO `gen_template` VALUES (2740, 29, 2735, 'SaTokenExceptionHandler.ftl', 'SaTokenExceptionHandler.java', 1, 'SaToken异常处理器', 'package ${projectPackage}.${projectNameDot}.common.satoken;\n\nimport cn.dev33.satoken.exception.NotLoginException;\nimport cn.dev33.satoken.exception.NotPermissionException;\nimport cn.dev33.satoken.exception.NotRoleException;\nimport ${projectPackage}.${projectNameDot}.common.response.Result;\nimport jakarta.servlet.http.HttpServletRequest;\nimport lombok.extern.slf4j.Slf4j;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.core.annotation.Order;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\nimport static ${projectPackage}.${projectNameDot}.common.response.Result.fail;\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.FORBIDDEN;\nimport static ${projectPackage}.${projectNameDot}.common.response.ResultEnum.UNAUTHORIZED;\nimport static org.springframework.core.Ordered.HIGHEST_PRECEDENCE;\n\n\n/**\n * SaToken异常处理器\n *\n */\n@Slf4j\n@RestControllerAdvice\n// 最高优先级处理\n@Order(HIGHEST_PRECEDENCE)\npublic class SaTokenExceptionHandler {\n\n    @Autowired\n    private HttpServletRequest request;\n\n    /**\n     * 认证失败\n     */\n    @ExceptionHandler(NotLoginException.class)\n    public Result<Void> handleNotLoginException(NotLoginException exception) {\n        log.error(\"认证失败, 请求方式: {}, 请求uri: {}, 异常message: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(UNAUTHORIZED);\n    }\n\n    /**\n     * 角色权限异常\n     */\n    @ExceptionHandler(NotRoleException.class)\n    public Result<Void> handleNotRoleException(NotRoleException exception) {\n        log.error(\"角色权限异常, 请求方式: {}, 请求uri: {}, 异常message: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(FORBIDDEN);\n    }\n\n    /**\n     * 权限码异常\n     */\n    @ExceptionHandler(NotPermissionException.class)\n    public Result<Void> handleNotPermissionException(NotPermissionException exception) {\n        log.error(\"权限码异常, 请求方式: {}, 请求uri: {}, 异常message: {}\",\n                request.getMethod(), request.getRequestURI(), exception.getMessage(), exception);\n        return fail(FORBIDDEN);\n    }\n\n}\n', '', 'projectTemplatePropertyData[\'enableSaToken\']', '2025-11-14 14:13:03', '2025-12-29 15:30:34', 0);
INSERT INTO `gen_template` VALUES (2741, 29, 2735, 'SaTokenInterceptor.ftl', 'SaTokenInterceptor.java', 1, '登录和权限拦截器', 'package ${projectPackage}.${projectNameDot}.common.satoken;\n\nimport cn.dev33.satoken.interceptor.SaInterceptor;\nimport cn.dev33.satoken.stp.StpUtil;\nimport cn.dev33.satoken.strategy.SaAnnotationStrategy;\nimport jakarta.annotation.PostConstruct;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.core.annotation.AnnotatedElementUtils;\nimport org.springframework.web.servlet.config.annotation.InterceptorRegistry;\nimport org.springframework.web.servlet.config.annotation.WebMvcConfigurer;\n\nimport java.util.List;\n\n/**\n * 登录和权限拦截器\n */\npublic class SaTokenInterceptor implements WebMvcConfigurer {\n\n    /**\n     * 忽略的url\n     */\n    @Value(\"<#noparse>#{\'${sa-token.interceptor.exclude-url:/auth/login}\'.split(\',\')}</#noparse>\")\n    private List<String> excludeUrlList;\n\n    @PostConstruct\n    public void init() {\n        // 重写Sa-Token的注解处理器，增加注解合并功能\n        SaAnnotationStrategy.instance.getAnnotation = AnnotatedElementUtils::getMergedAnnotation;\n    }\n\n    @Override\n    public void addInterceptors(InterceptorRegistry registry) {\n        // 注册 Sa-Token 拦截器，打开注解式鉴权功能\n        // 校验是否登录，自动校验controller方法上的sa-token注解\n        registry.addInterceptor(new SaInterceptor(handle -> StpUtil.checkLogin()))\n                .addPathPatterns(\"/**\")\n                .excludePathPatterns(excludeUrlList.toArray(new String[0]));\n    }\n\n}\n', '', 'projectTemplatePropertyData[\'enableSaToken\']', '2025-11-14 14:13:59', '2025-12-29 15:30:39', 0);
