INSERT INTO `gen_template` VALUES (2743, 29, 2742, 'LoginUser.ftl', 'LoginUser.java', 1, '登录用户身份权限', 'package ${projectPackage}.${projectNameDot}.common.domain.model;\n\nimport lombok.Data;\nimport lombok.NoArgsConstructor;\n\nimport java.io.Serial;\nimport java.io.Serializable;\n\n/**\n * 登录用户身份权限\n */\n@Data\n@NoArgsConstructor\npublic class LoginUser implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    /**\n     * 用户ID\n     */\n    private Long userId;\n\n    /**\n     * 用户名\n     */\n    private String username;\n\n    /**\n     * 用户昵称\n     */\n    private String nickname;\n\n    /**\n     * 设备类型\n     */\n    private String deviceType;\n\n}\n', '', NULL, '2025-11-14 14:16:00', '2025-11-14 14:16:13', 0);
INSERT INTO `gen_template` VALUES (2744, 30, 1804, 'api-index.ts', 'index.ts', 1, 'api统一导出', '/**\n * API 统一导出\n *\n * 使用方式：\n * import { authApi } from \'@/api\'\n */\n\n// 认证模块\nexport { authApi } from \'@/api/auth\'\n\n<#list tableModelList as tableModel>\n// ${tableModel.functionNameKebabCase}类型\nexport * from \'@/api/${tableModel.moduleName}/${tableModel.functionNameKebabCase}\'   \n</#list>', '', NULL, '2025-11-24 15:56:01', '2025-11-24 17:47:38', 0);
