INSERT INTO `gen_template` VALUES (2747, 30, 2746, 'form-divider.vue', 'index.vue', 1, '表单分隔符组件', '<template>\n	<div class=\"form-divider-content\">\n		<div class=\"form-blue-indicator\"></div>\n		<el-text class=\"form-section-title\">{{ title }}</el-text>\n	</div>\n</template>\n<script setup lang=\"ts\">\ndefineOptions({\n	name: \'FormDivider\'\n})\n\ndefineProps({\n	title: {\n		type: String,\n		required: true\n	}\n})\n</script>\n\n<style scoped>\n.form-divider-content {\n	display: flex;\n	align-items: center;\n	gap: 10px; /* 蓝条与文字的间距，可选 */\n	margin: 16px 0 20px;\n}\n/* 当上一个元素是 el-row 时，减少顶边距 */\n.el-row + .form-divider-content {\n	margin-top: 8px !important;\n}\n.form-divider-content:first-child {\n	margin-top: 0;\n}\n.form-blue-indicator {\n	display: flex;\n	width: 4px;\n	height: 1.2em;\n	background-color: var(--el-color-primary);\n	border-radius: 2px;\n}\n.form-section-title {\n	color: var(--el-text-color-primary);\n	font-size: 15px;\n	font-weight: 600;\n}\n</style>\n', '', NULL, '2025-11-24 15:59:13', '2025-11-24 15:59:28', 0);
INSERT INTO `gen_template` VALUES (2748, 30, 687, '', 'router', 0, '路由组件', '', '', NULL, '2025-11-24 16:00:17', '2025-11-24 16:00:17', 0);
INSERT INTO `gen_template` VALUES (2749, 30, 2748, 'router-iframe-page.vue', 'iframe-page.vue', 1, 'iframe页面', '<template>\n	<div v-loading=\"currentLoading\" class=\"iframe-container\">\n		<iframe :src=\"iframeSrc\" width=\"100%\" height=\"100%\" style=\"min-height: calc(100vh - 84px)\" allow=\"accelerometer\" @load=\"handleLoad\"></iframe>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from \'vue\'\nimport NProgress from \'nprogress\'\nimport { useSystemSettingStore } from \'@/store\'\n\ndefineOptions({\n	name: \'RouterIframePage\'\n})\n\nconst props = defineProps({\n	// iframe地址\n	iframeSrc: {\n		type: String,\n		required: true\n	},\n	// 是否缓存\n	cache: {\n		type: Boolean,\n		required: false,\n		default: false\n	}\n})\n\nconst currentLoading = ref(true) // 是否在加载中\nconst systemSettingStore = useSystemSettingStore()\n\n// 只有在缓存模式下进行监控\nif (props.cache) {\n	// 如果src路径发生变化，进行loading加载，表示刷新\n	watch(\n		() => props.iframeSrc,\n		() => {\n			if (systemSettingStore.isOpenProgress) {\n				NProgress.start()\n			}\n			currentLoading.value = true\n		}\n	)\n}\n\n// iframe加载完成，关闭loading\nconst handleLoad = () => {\n	// 只有在启用缓存模式下才处理 NProgress\n	if (props.cache && NProgress.isStarted() && systemSettingStore.isOpenProgress) {\n		NProgress.done()\n	}\n	currentLoading.value = false\n}\n</script>\n\n<style scoped>\n.iframe-container {\n	height: 100%;\n	overflow: hidden;\n}\n</style>\n', '', NULL, '2025-11-24 16:01:10', '2025-11-24 16:01:16', 0);
INSERT INTO `gen_template` VALUES (2750, 30, 2748, 'router-redirect.vue', 'redirect.vue', 1, '重定向组件', '<template>\n	<div></div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useRoute, useRouter } from \'vue-router\'\n\ndefineOptions({\n	name: \'RouterRedirect\'\n})\n\nconst route = useRoute()\nconst router = useRouter()\nconst { params, query } = route\nconst { path } = params\n\nrouter.replace({ path: \'/\' + path, query })\n</script>\n', '', NULL, '2025-11-24 16:01:45', '2025-11-24 16:02:01', 0);
