INSERT INTO `gen_template` VALUES (2752, 30, 2751, '', 'tool-bar', 0, '表格工具栏', '', '', NULL, '2025-11-24 16:03:33', '2025-11-24 16:03:33', 0);
INSERT INTO `gen_template` VALUES (2753, 30, 2752, 'table-tool-bar.vue', 'index.vue', 1, '表格工具栏组件', '<template>\n	<div class=\"table-tool-bar\">\n		<!-- 左插槽：父组件传入 -->\n		<div class=\"table-tool-bar-left\">\n			<slot name=\"left\"></slot>\n		</div>\n\n		<!-- 右侧：通用工具 -->\n		<div class=\"table-tool-bar-right\">\n			<el-space>\n				<!-- 搜索 -->\n				<el-tooltip v-if=\"useSearch && !isFullscreen\" :content=\"showSearch ? \'隐藏搜索\' : \'显示搜索\'\" placement=\"top\" :teleported=\"teleported\">\n					<el-button circle :icon=\"Search\" @click=\"toggleSearch()\"></el-button>\n				</el-tooltip>\n\n				<!-- 刷新 -->\n				<el-tooltip v-if=\"useRefresh\" content=\"刷新表格\" placement=\"top\" :teleported=\"teleported\">\n					<el-button circle :icon=\"Refresh\" :loading-icon=\"Refresh\" :loading=\"queryLoading\" @click=\"emit(\'getDataList\')\"></el-button>\n				</el-tooltip>\n\n				<!-- 全屏 -->\n				<el-tooltip\n					v-if=\"useFullscreenButton && tableCardRef\"\n					:content=\"isFullscreen ? \'退出全屏\' : \'开启全屏\'\"\n					placement=\"top\"\n					:teleported=\"teleported\"\n				>\n					<el-button circle @click=\"toggle()\">\n						<svg-icon :icon=\"isFullscreen ? \'icon-fullscreen-exit\' : \'icon-fullscreen\'\" is-pointer></svg-icon>\n					</el-button>\n				</el-tooltip>\n			</el-space>\n		</div>\n	</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { Refresh, Search } from \'@element-plus/icons-vue\'\nimport { useFullscreen, useToggle } from \'@vueuse/core\'\nimport SvgIcon from \'@/components/svg-icon\'\nimport { computed, PropType, Ref } from \'vue\'\n\ndefineOptions({\n	name: \'TableToolBar\'\n})\n\nconst showSearch = defineModel(\'showSearch\', {\n	type: Boolean,\n	default: true\n})\n\nconst queryLoading = defineModel(\'queryLoading\', {\n	type: Boolean,\n	default: false\n})\n\nconst props = defineProps({\n	tableCardRef: {\n		type: Object as PropType<Ref<HTMLElement>>,\n		required: true\n	},\n	useSearch: {\n		type: Boolean,\n		default: true\n	},\n	useRefresh: {\n		type: Boolean,\n		default: true\n	},\n	useFullscreenButton: {\n		type: Boolean,\n		default: true\n	}\n})\n\nconst emit = defineEmits([\'getDataList\'])\n\nconst teleported = computed(() => !isFullscreen.value)\n\nconst toggleSearch = useToggle(showSearch)\n\nconst { isFullscreen, toggle } = useFullscreen(props.tableCardRef)\n</script>\n\n<style scoped>\n.table-tool-bar {\n	display: flex;\n	align-items: center;\n	justify-content: space-between;\n}\n.table-tool-bar-left,\n.table-tool-bar-right {\n	display: flex;\n	align-items: center;\n}\n</style>\n', '', NULL, '2025-11-24 16:04:02', '2025-11-24 16:04:12', 0);
INSERT INTO `gen_template` VALUES (2754, 30, 678, 'hooks-index.ts', 'index.ts', 1, 'hooks统一导出', '/**\n * hooks统一导出\n */\nexport * from \'@/hooks/use-init-form\'\nexport * from \'@/hooks/use-refresh-current-page\'\nexport * from \'@/hooks/use-submit-form\'\nexport * from \'@/hooks/use-submit-handler\'\nexport * from \'@/hooks/use-switch-change-handler\'\nexport * from \'@/hooks/use-table-action\'\n', '', NULL, '2025-11-24 16:06:38', '2025-11-24 16:06:44', 0);
INSERT INTO `gen_template` VALUES (2755, 30, 678, 'use-submit-handler.ts', 'use-submit-handler.ts', 1, '提交hooks', 'import { ref } from \'vue\'\nimport { ElMessage } from \'element-plus\'\nimport { SubmitOptions } from \'@/types\'\n\n// 提交处理\nexport const useSubmitHandler = (options: SubmitOptions) => {\n	const submitLoading = ref(false)\n\n	const defaultOptions: SubmitOptions = {\n		message: \'提交成功\',\n		duration: 500\n	}\n\n	// 合并默认值\n	Object.assign(defaultOptions, Object.fromEntries(Object.entries(defaultOptions).filter(([key]) => !Object.hasOwn(options, key))))\n\n	// 提交方法\n	const submitHandle = async (dataForm?: any) => {\n		if (submitLoading.value) {\n			ElMessage.warning(\'请勿重复提交\')\n			return\n		}\n\n		if (!options.submitApi) {\n			ElMessage.warning(\'未配置提交接口\')\n			return\n		}\n\n		submitLoading.value = true\n		try {\n			const res = await options.submitApi(dataForm)\n\n			ElMessage.success({\n				message: options.message,\n				duration: options.duration,\n				onClose: () => {\n					// 关闭弹窗\n					if (options.visible) {\n						options.visible.value = false\n					}\n					// 执行成功回调函数\n					if (options.onSuccess) {\n						options.onSuccess?.(res)\n					} else {\n						// 默认刷新数据列表\n						options.emit?.(\'refreshDataList\', res)\n					}\n				}\n			})\n		} catch (err) {\n			// 用户自定义错误处理\n			if (options.onError) {\n				options.onError?.(err)\n			} else {\n				// 默认错误处理\n				ElMessage.error({\n					message: \'提交失败，请稍后重试\',\n					duration: 1000\n				})\n			}\n		} finally {\n			submitLoading.value = false\n		}\n	}\n\n	return {\n		submitLoading,\n		submitHandle\n	}\n}\n', '', NULL, '2025-11-24 16:08:36', '2025-11-24 16:08:49', 0);
INSERT INTO `gen_template` VALUES (2756, 30, 678, 'use-switch-change-handler.ts', 'use-switch-change-handler.ts', 1, '开关切换hooks', 'import { ElMessage, ElMessageBox } from \'element-plus\'\nimport { SwitchState } from \'@/types\'\n\n// 开关状态切换\nexport const useSwitchState = (options: SwitchState) => {\n	const { field, states } = options\n	if (options.states.length !== 2) {\n		throw new Error(\'Switch options must contain exactly two items\')\n	}\n\n	const activeState = states.find(s => s.isActive)!\n	const inactiveState = states.find(s => !s.isActive)!\n\n	const textMap = Object.fromEntries(states.map(s => [s.value, s.text]))\n\n	const confirmMessage = options.confirmText ?? ((newText: string) => <#noparse>`确定要修改为【${newText}】吗？`</#noparse>)\n\n	const successMessage = options.successText ?? ((_: string, newText: string) => <#noparse>`修改为【${newText}】成功`</#noparse>)\n\n	const getOldValue = (newValue: any) => {\n		return newValue === activeState.value ? inactiveState.value : activeState.value\n	}\n\n	return {\n		field,\n		activeValue: activeState.value,\n		inactiveValue: inactiveState.value,\n		activeText: activeState.text,\n		inactiveText: inactiveState.text,\n		text: textMap,\n		getOldValue,\n		confirmMessage,\n		successMessage\n	}\n}\n\nexport const useSwitchChangeHandler = (\n	switchState: ReturnType<typeof useSwitchState>,\n	apiFn: (newValue: any, row: any) => Promise<any>,\n	afterSuccess?: () => void\n) => {\n	return async (newValue: any, row: any) => {\n		const { field, text, getOldValue } = switchState\n\n		const oldValue = getOldValue(newValue)\n		const oldText = text[oldValue]\n		const newText = text[newValue]\n\n		try {\n			await ElMessageBox.confirm(switchState.confirmMessage(newText), \'提示\', {\n				confirmButtonText: \'确定\',\n				cancelButtonText: \'取消\',\n				type: \'warning\'\n			})\n\n			await apiFn(newValue, row)\n\n			if (afterSuccess) {\n				afterSuccess()\n			} else {\n				ElMessage.success(switchState.successMessage(oldText, newText))\n			}\n			afterSuccess?.()\n		} catch {\n			row[field] = oldValue\n		}\n	}\n}\n', '', NULL, '2025-11-24 16:09:30', '2025-11-24 16:10:07', 0);
INSERT INTO `gen_template` VALUES (2757, 30, 663, 'menu-tree-node.vue', 'menu-tree-node.vue', 1, '菜单树节点', '<template>\n	<div class=\"tree-node\" @click.stop=\"handleClick\">\n		<span class=\"tree-prefix\" v-html=\"getTreePrefix(level, !!node.children)\"></span>\n		<icon-text-tooltip :icon=\"node.icon\" :title=\"node.title\" :max-width=\"\'300px\'\"></icon-text-tooltip>\n	</div>\n\n	<div v-if=\"node.children && node.children.length\" class=\"tree-children\">\n		<MenuTreeNode v-for=\"child in node.children\" :key=\"child.title\" :node=\"child\" :level=\"level + 1\" :on-select=\"onSelect\"></MenuTreeNode>\n	</div>\n</template>\n<script setup lang=\"ts\">\nimport IconTextTooltip from \'@/components/icon-text-tooltip/index.vue\'\n\ndefineOptions({\n	name: \'MenuTreeNode\'\n})\n\nexport interface TreeNode {\n	title: string\n	icon: string\n	path?: string\n	type: number\n	externalUrl?: string\n	children?: TreeNode[]\n}\n\nconst props = defineProps<{\n	node: TreeNode\n	level: number\n	onSelect: (node: TreeNode) => void\n}>()\n\nconst handleClick = (_: Event) => {\n	if (!props.node.children || props.node.children.length === 0) {\n		props.onSelect(props.node)\n	}\n}\nconst getTreePrefix = (level: number, hasChildren: boolean): string => {\n	const indent = \'&nbsp;&nbsp;\'.repeat(level)\n	const prefix = hasChildren ? \'├─\' : \'│&nbsp;&nbsp;\'\n	return indent + prefix\n}\n</script>\n<style scoped>\n/* 树节点样式 */\n.tree-node {\n	display: flex;\n	align-items: center;\n	gap: 6px;\n	padding: 5px 5px 10px 10px;\n	cursor: pointer;\n}\n.tree-node:hover {\n	background-color: var(--theme-menu-hover-bg-color);\n	color: var(--theme-menu-hover-color);\n}\n.tree-prefix {\n	font-family: monospace;\n	white-space: pre;\n}\n.tree-children {\n	margin-left: 16px;\n}\n</style>\n', '', NULL, '2025-11-24 16:12:39', '2025-11-24 16:12:44', 0);
INSERT INTO `gen_template` VALUES (2758, 30, 648, 'store-index.ts', 'index.ts', 1, 'store统一导出', '/**\n * Store 统一导出\n *\n * 使用方式：\n * import { useUserStore, useAppStore, useSystemSettingStore } from \'@/store\'\n */\n\nexport { useUserStore } from \'@/store/user-store\'\nexport { useAppStore } from \'@/store/app-store\'\nexport { useSystemSettingStore } from \'@/store/system-setting-store\'\n\n// 如果需要，也可以导出常量\nexport { menuExpandWidthList, menuFoldWidthList } from \'@/store/system-setting-store\'\n', '', NULL, '2025-11-24 16:17:32', '2025-11-24 16:17:37', 0);
