INSERT INTO `gen_template` VALUES (2765, 30, 2764, 'api-common-index.ts', 'index.ts', 1, '', '/**\n * 统一返回数据结构\n */\nexport interface Result<T = any> {\n	// 状态码 200为正常\n	code: number\n	// 提示信息 正常为success\n	message: string\n	// 数据\n	data: T\n}\n\n/**\n * 排序查询参数\n */\nexport interface OrderItemQuery {\n	// 排序字段\n	column: string\n	// 是否正序排列，默认 true\n	asc: boolean\n}\n\n/**\n * 分页查询参数基类\n */\nexport interface PageQuery {\n	// 当前页码\n	pageNum?: number\n	// 每页条数\n	pageSize?: number\n	// 排序字段\n	orderItemList?: OrderItemQuery[]\n	// 开始时间\n	startTime?: string\n	// 结束时间\n	endTime?: string\n	// 开始日期\n	startDate?: string\n	// 结束日期\n	endDate?: string\n	// 时间范围\n	dateRange?: string[]\n	// 日期范围\n	dateTimeRange?: string[]\n}\n\n/**\n * 分页返回数据\n */\nexport interface PageVO<T = any> {\n	// 当前页码\n	pageNum: number\n	// 每页条数\n	pageSize: number\n	// 总记录数\n	total: number\n	// 分页数据\n	records: T[]\n}\n', '', NULL, '2025-11-24 16:25:34', '2025-11-24 16:25:40', 0);
INSERT INTO `gen_template` VALUES (2766, 30, 2763, 'api-index.ts', 'index.ts', 1, '', '/**\n * API 类型统一导出\n */\n// common 模块类型\nexport * from \'@/types/api/common\'\n\n<#list tableModelList as tableModel>\n// ${tableModel.functionNameKebabCase}类型\nexport * from \'@/types/api/${tableModel.moduleName}/${tableModel.functionNameKebabCase}\'   \n</#list>', '', NULL, '2025-11-24 16:25:56', '2025-11-24 17:44:55', 0);
