INSERT INTO `gen_template` VALUES (2768, 30, 2767, 'common-index.ts', 'index.ts', 1, '', '// 主键类型\nexport type Key = string | number | null | undefined\n\n// 主键数组类型\nexport type KeyArray = number[] | string[]\n\n// 标签数据\nexport interface LabelData {\n	// 标签\n	label: string\n	// 值\n	value: string | number | boolean | null\n}\n', '', NULL, '2025-11-24 16:27:09', '2025-11-24 16:27:14', 0);
