INSERT INTO `gen_template` VALUES (2770, 30, 2769, 'types-hooks-index.ts', 'index.ts', 1, '', '/**\n * API 类型统一导出\n */\nexport * from \'@/types/hooks/use-submit-form\'\nexport * from \'@/types/hooks/use-submit-handler\'\nexport * from \'@/types/hooks/use-switch-change-handler\'\nexport * from \'@/types/hooks/use-table-action\'\n', '', NULL, '2025-11-24 16:28:07', '2025-11-24 16:28:15', 0);
INSERT INTO `gen_template` VALUES (2771, 30, 2769, 'types-hooks-use-submit-form.ts', 'use-submit-form.ts', 1, '', 'import { Key } from \'@/types\'\n\n// 表单模式：新增、修改、复制\nexport type FormType = \'add\' | \'update\' | \'copy\'\n\nexport interface FormOptions<VO> {\n	// 提交API\n	submitApi: (data: VO) => Promise<any>\n	// 详情API\n	detailApi: (id: Key) => Promise<VO>\n	// 初始化之前调用\n	initBefore?: () => void\n	// 表单数据\n	dataForm: VO & { id?: Key }\n	// 初始化之后调用\n	initAfter?: () => void\n	// 提交之前操作\n	submitBefore?: () => void\n	// 触发事件\n	emit?: any\n	// 提示信息\n	message?: string\n	// 提示时长\n	duration?: number\n}\n', '', NULL, '2025-11-24 16:29:04', '2025-11-24 16:29:09', 0);
INSERT INTO `gen_template` VALUES (2772, 30, 2769, 'types-hooks-ubse-submit-handler.ts', 'use-submit-handler.ts', 1, '', 'import { Ref } from \'vue\'\n\nexport interface SubmitOptions {\n	// 控制 dialog 显示\n	visible?: Ref<boolean, boolean>\n	// 提交方法\n	submitApi?: (dataForm: any) => Promise<any>\n	// 触发事件\n	emit?: any\n	// 成功提示\n	message?: string\n	// 提示时长\n	duration?: number\n	// 成功回调\n	onSuccess?: (res: any) => void\n	// 错误回调\n	onError?: (err: any) => void\n}\n', '', NULL, '2025-11-24 16:29:39', '2025-11-24 16:29:45', 0);
INSERT INTO `gen_template` VALUES (2773, 30, 2769, 'types-hooks-use-switch-change-handler.ts', 'use-switch-change-handler.ts', 1, '', '/**\n * 开关数据\n */\nexport interface SwitchOption<T = any> {\n	// 值\n	value: T\n	// 文本\n	text: string\n	// 是否激活\n	isActive: boolean\n}\n/**\n * 开关状态切换数据\n */\nexport interface SwitchState {\n	// 字段\n	field: string\n	// 数据列表\n	states: SwitchOption[]\n	// 确认提示\n	confirmText?: (newText: string) => string\n	// 成功提示\n	successText?: (oldText: string, newText: string) => string\n}\n', '', NULL, '2025-11-24 16:30:09', '2025-11-24 16:30:17', 0);
INSERT INTO `gen_template` VALUES (2774, 30, 2769, 'types-hooks-use-table-action.ts', 'use-table-action.ts', 1, '', 'import { KeyArray, PageQuery, PageVO } from \'@/types\'\n\n// 数据列表接口\ntype DataListApi<Query, VO> = (queryForm?: Query) => Promise<PageVO<VO> | VO[]>\n// 批量删除接口\ntype DeleteListApi = (idList: KeyArray) => Promise<void>\n// 导出接口\ntype ExportApi = (idList: KeyArray) => Promise<void>\n// 导入接口\ntype ImportApi = (formData: FormData) => Promise<void>\n\n// 表格操作\nexport interface IHooksOptions<Query extends PageQuery = PageQuery, VO = any> {\n	// 否在创建页面时，调用数据列表接口\n	mountedGetData?: boolean\n	// 重置后是否查询\n	resetQueryGetData?: boolean\n	// 是否需要分页\n	isPage?: boolean\n	// 数据列表接口\n	dataListApi?: DataListApi<Query, VO>\n	// 删除接口\n	deleteListApi?: DeleteListApi\n	// 导出接口\n	exportApi?: ExportApi\n	// 导入接口\n	importApi?: ImportApi\n	// 主键key，用于删除场景\n	primaryKey?: string\n	// 查询条件\n	queryForm: Query\n	// 数据列表\n	dataList?: VO[]\n	// 排序字段\n	order?: string\n	// 是否升序\n	asc?: boolean\n	// 当前页码\n	pageNum?: number\n	// 每页数\n	pageSize?: number\n	// 总条数\n	total?: number\n	// 每页数选择项\n	pageSizes?: number[]\n	// 数据列表，loading状态\n	dataListLoading?: boolean\n	// 删除loading状态\n	deleteLoading?: boolean\n	// 导出loading状态\n	exportLoading?: boolean\n	// 数据列表，多选项\n	dataListSelections?: KeyArray\n	// 删除时提示语\n	deleteConfirmMessage?: string\n	// 导出时提示语\n	exportSuccessMessage?: string\n	// 导入成功提示语\n	importSuccessMessage?: string\n}\n', '', NULL, '2025-11-24 16:30:46', '2025-11-24 16:30:50', 0);
INSERT INTO `gen_template` VALUES (2775, 30, 640, '', 'router', 0, '', '', '', NULL, '2025-11-24 16:31:02', '2025-11-24 16:31:02', 0);
INSERT INTO `gen_template` VALUES (2776, 30, 2775, 'types-router-index.ts', 'index.ts', 1, '', '/**\n * 路由相关类型定义\n */\n\n/**\n * 路由元数据类型\n * 用于标签栏、面包屑、缓存等功能\n */\nexport interface RouteMetaData {\n	/** 路径 */\n	path: string\n	/** 完整路径 */\n	fullPath: string\n	/** 组件名称 */\n	name: string\n	/** 标题 */\n	title: string\n	/** 图标 */\n	icon: string\n	/** 缓存 */\n	cache: boolean\n	/** 隐藏 */\n	hidden: boolean\n	/** 类型 */\n	type: RouteType\n	/** 外链地址 */\n	externalUrl?: string\n}\n\n/**\n * 路由类型枚举\n */\nexport enum RouteType {\n	/** 目录 */\n	DIRECTORY = 0,\n	/** 菜单 */\n	MENU = 1,\n	/** 按钮 */\n	BUTTON = 2,\n	/** iframe */\n	IFRAME = 3,\n	/** 外链 */\n	EXTERNAL = 4\n}\n', '', NULL, '2025-11-24 16:31:21', '2025-11-24 16:31:27', 0);
INSERT INTO `gen_template` VALUES (2777, 30, 640, '', 'store', 0, '', '', '', NULL, '2025-11-24 16:31:44', '2025-11-24 16:31:44', 0);
INSERT INTO `gen_template` VALUES (2778, 30, 2777, 'types-store-app-store.ts', 'app-store.ts', 1, '', '// 标签数据\nexport interface NavbarTag {\n	// 完整路径\n	fullPath: string\n	// 组件名称\n	name: string\n	// 标题\n	title: string\n	// 图标\n	icon: string\n}\n\n// iframe数据\nexport interface IframeInfo {\n	// 路由名称\n	name: string\n	// 路由地址\n	src: string\n	// 全路径\n	fullPath: string\n}\n\n// 布局大小\nexport type LayOutSize = \'large\' | \'default\' | \'small\'\n', '', NULL, '2025-11-24 16:32:16', '2025-11-24 16:32:21', 0);
INSERT INTO `gen_template` VALUES (2779, 30, 2777, 'types-store-index.ts', 'index.ts', 1, '', '/**\n * Store 类型统一导出\n */\nexport * from \'@/types/store/app-store\'\nexport * from \'@/types/store/user-store\'\nexport * from \'@/types/store/system-setting-store\'\n', '', NULL, '2025-11-24 16:32:38', '2025-11-24 16:32:43', 0);
INSERT INTO `gen_template` VALUES (2780, 30, 2777, 'types-store-system-setting-store.ts', 'system-setting-store.ts', 1, '', 'export interface SystemSetting {\n	// 是否开启面包屑\n	isOpenBreadcrumb: boolean\n	// 面包屑是否设置图标\n	isOpenBreadcrumbIcon: boolean\n	// 是否开启标签页\n	isOpenTag: boolean\n	// 是否开启标签页图标\n	isOpenTagIcon: boolean\n	// 是否开启tag持久化\n	isOpenTagCache: boolean\n	// 是否开启被激活拖拽标签\n	isOpenTagDragActivated: boolean\n	// 是否设置动态标题\n	isOpenDynamicTitle: boolean\n	// 是否开启logo\n	isOpenLogo: boolean\n	// 是否开启载入进度条\n	isOpenProgress: boolean\n	// 是否开启页面缓存\n	isOpenPageCache: boolean\n	// 是否开启菜单搜索\n	isOpenMenuSearch: boolean\n	// 是否开启刷新页面\n	isOpenRefreshPage: boolean\n	// 布局大小\n	isOpenLayoutSetting: boolean\n	// 切换全屏\n	isOpenFullscreen: boolean\n	// 主题切换\n	isOpenThemeSwitch: boolean\n	// 是否开启菜单折叠动画\n	isOpenMenuCollapseAnimation: boolean\n	// 是否开启菜单只打开一个菜单\n	isOpenMenuUniqueOpened: boolean\n	// 菜单展开/折叠按钮\n	isOpenMenuCollapseButton: boolean\n	// 菜单展开宽度\n	menuExpandWidth: number\n	// 菜单折叠宽度\n	menuFoldWidth: number\n	// 默认菜单\n	menuDefault: string\n}\n', '', NULL, '2025-11-24 16:33:02', '2025-11-24 16:33:06', 0);
INSERT INTO `gen_template` VALUES (2781, 30, 2777, 'types-store-user-store.ts', 'user-store.ts', 1, '', 'export interface UserInfo {\n	username: string\n\n	nickname: string\n\n	avatar: string\n\n	email: string\n\n	mobile: string\n}\n\nexport interface TokenInfo {\n	// token名称\n	tokenName: string\n	// 访问令牌\n	accessToken: string\n	// 刷新令牌\n	refreshToken: string\n	// 过期时间\n	expire: number\n}\n\nexport interface MenuInfo {\n	// 名称\n	name: string\n	// 路由\n	path: string\n	// 组件路径\n	component?: string\n	// 元数据\n	meta: {\n		// 标题\n		title: string\n		// 图标\n		icon: string\n		// 类型 0-目录、1-菜单、2-按钮、3-iframe、4-外链\n		type: number\n		// 外链地址\n		externalUrl?: string\n		// 缓存\n		cache?: boolean\n		// 隐藏\n		hidden?: boolean\n	}\n	// 子菜单\n	children?: MenuInfo[]\n}\n', '', NULL, '2025-11-24 16:33:25', '2025-11-24 16:33:29', 0);
INSERT INTO `gen_template` VALUES (2782, 30, 640, '', 'utils', 0, '', '', '', NULL, '2025-11-24 16:33:46', '2025-11-24 16:33:46', 0);
INSERT INTO `gen_template` VALUES (2783, 30, 2782, 'types-utils-index.ts', 'index.ts', 1, '', '/**\n * 工具类型定义\n */\n\n/**\n * 枚举值类型\n */\nexport type EnumValueType = string | number | boolean | null\n\n/**\n * 枚举标签类型值（Element Plus tag 组件类型）\n */\nexport type EnumTagTypeValue = \'primary\' | \'success\' | \'warning\' | \'danger\' | \'info\'\n\n/**\n * 枚举项接口\n * 用于构建选择器、单选框、多选框等组件的数据源\n */\nexport interface EnumItem {\n	/** 枚举值 */\n	value: EnumValueType\n	/** 枚举标签 */\n	label: string\n	/** Element Plus 的 type 类型（用于标签组件） */\n	type?: EnumTagTypeValue\n	/** 颜色 */\n	color?: string\n}\n', '', NULL, '2025-11-24 16:34:03', '2025-11-24 16:34:09', 0);
INSERT INTO `gen_template` VALUES (2784, 30, 640, 'types-index.ts', 'index.ts', 1, '', '/**\n * 类型定义统一导出\n */\n\n// API 相关类型\nexport * from \'@/types/api\'\n\n// 通用类型\nexport * from \'@/types/common\'\n\n// hooks\nexport * from \'@/types/hooks\'\n\n// 路由类型\nexport * from \'@/types/router\'\n\n// Store 相关类型\nexport * from \'@/types/store\'\n\n// 工具类型\nexport * from \'@/types/utils\'\n', '', NULL, '2025-11-24 16:34:43', '2025-11-24 16:34:49', 0);
