INSERT INTO `gen_template` VALUES (2811, 89, 2810, 'PageQuery.ftl', 'PageQuery.java', 1, '分页查询参数', 'package ${projectPackage}.${projectNameDot}.common.domain.query;\n\nimport com.baomidou.mybatisplus.core.metadata.IPage;\nimport com.baomidou.mybatisplus.core.metadata.OrderItem;\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.AccessLevel;\nimport lombok.Data;\nimport lombok.Getter;\nimport lombok.Setter;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.List;\n\n/**\n * 分页查询参数基类，分页查询入参和返回基类\n *\n * @param <T> 必须是Entity或者是VO\n */\n@Data\n@Schema(description = \"分页查询参数基类\")\npublic class PageQuery<T> implements IPage<T>, Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 2101820826443930585L;\n\n    /**\n     * 当前页码\n     */\n    @Schema(description = \"当前页码\", defaultValue = \"1\")\n    private Long pageNum = 1L;\n\n    /**\n     * 每页大小\n     */\n    @Schema(description = \"每页大小\", defaultValue = \"10\")\n    private Long pageSize = 10L;\n\n    /**\n     * 排序字段列表\n     */\n    @Schema(description = \"排序字段列表\")\n    private List<OrderItemQuery> orderItemList = OrderItemQuery.descs(\"updateTime\", \"id\");\n\n    /**\n     * 分页数据\n     */\n    @Schema(description = \"分页数据\", hidden = true)\n    private List<T> records;\n\n    /**\n     * 记录总数\n     */\n    @Schema(description = \"记录总数\", hidden = true)\n    private long total;\n\n    @Schema(hidden = true)\n    private Long size;\n\n    @Schema(hidden = true)\n    private Long current;\n\n    @Schema(hidden = true)\n    @Getter(AccessLevel.NONE)\n    @Setter(AccessLevel.NONE)\n    private Long pages;\n\n    @Override\n    public long getSize() {\n        return this.pageSize;\n    }\n\n    @Override\n    public IPage<T> setSize(long size) {\n        this.pageSize = size;\n        return this;\n    }\n\n    @Override\n    public long getCurrent() {\n        return pageNum;\n    }\n\n    @Override\n    public IPage<T> setCurrent(long current) {\n        this.pageSize = current;\n        return this;\n    }\n\n    @Override\n    public List<T> getRecords() {\n        return this.records;\n    }\n\n    @Override\n    public PageQuery<T> setRecords(List<T> records) {\n        this.records = records;\n        return this;\n    }\n\n    @Override\n    public long getTotal() {\n        return this.total;\n    }\n\n    @Override\n    public PageQuery<T> setTotal(long total) {\n        this.total = total;\n        return this;\n    }\n\n    @Override\n    public List<OrderItem> orders() {\n        //返回空数组，让框架不做排序处理\n        return List.of();\n    }\n\n}\n', '', NULL, '2025-12-05 14:34:53', '2025-12-05 14:35:43', 1);
INSERT INTO `gen_template` VALUES (2812, 89, 2810, 'OrderItemQuery.ftl', 'OrderItemQuery.java', 1, '排序参数', 'package ${projectPackage}.${projectNameDot}.common.domain.query;\n\nimport com.baomidou.mybatisplus.core.toolkit.StringUtils;\nimport io.swagger.v3.oas.annotations.media.Schema;\nimport lombok.Data;\n\nimport java.io.Serial;\nimport java.io.Serializable;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.stream.Collectors;\n\n/**\n * 排序字段查询参数\n */\n@Data\n@Schema(description = \"排序字段查询参数\")\npublic class OrderItemQuery implements Serializable {\n\n    @Serial\n    private static final long serialVersionUID = 1L;\n\n    /**\n     * 需要进行排序的字段\n     */\n    @Schema(description = \"需要进行排序的字段\")\n    private String column;\n\n    /**\n     * 是否正序排列，默认 true\n     */\n    @Schema(description = \"是否正序排列，默认 true\")\n    private Boolean asc = true;\n\n    public static OrderItemQuery asc(String column) {\n        return build(column, true);\n    }\n\n    public static OrderItemQuery desc(String column) {\n        return build(column, false);\n    }\n\n    public static List<OrderItemQuery> ascs(String... columns) {\n        return Arrays.stream(columns).map(OrderItemQuery::asc).collect(Collectors.toList());\n    }\n\n    public static List<OrderItemQuery> descs(String... columns) {\n        return Arrays.stream(columns).map(OrderItemQuery::desc).collect(Collectors.toList());\n    }\n\n    private static OrderItemQuery build(String column, boolean asc) {\n        return new OrderItemQuery().setColumn(column).setAsc(asc);\n    }\n\n    public OrderItemQuery setColumn(String column) {\n        this.column = StringUtils.replaceAllBlank(column);\n        return this;\n    }\n\n    public OrderItemQuery setAsc(boolean asc) {\n        this.asc = asc;\n        return this;\n    }\n\n}\n', '', NULL, '2025-12-05 14:34:53', '2025-12-05 14:35:43', 1);
